    /// <param name="result">The value object, or null when the value was absent or could not be created.</param>
    /// <param name="errors">The violations, empty when the call succeeded.</param>
    public static bool TryCreateFrom(
        object? raw,
        IFormatProvider? provider,
        out TSelf? result,
        out IReadOnlyList<string> errors
    )
    {
        // A blank cell means "not filled in", which is the caller's business rather than a violation: a nullable column keeps
        // the property null, and a required one is reported by the edit model's own required check.
        if (raw is null or DBNull || (raw is string empty && empty.Length == 0))
        {
            result = null;
            errors = Array.Empty<string>();
            return true;
        }

        // A shape the type accepts of its own (a name for an enumeration-like type, say) wins over the ordinary conversion.
        if (TSelf.TryConvertCustomInput(raw, provider, out var custom) && custom is not null)
        {
            result = custom;
            errors = Array.Empty<string>();
            return true;
        }

        object converted;

        try
        {
            converted = RawValueConverter.ConvertInput(raw, typeof(TValue), provider);
        }
        catch (Exception ex)
            when (ex is InvalidCastException
                or FormatException
                or OverflowException
                or ArgumentException
            )
        {
            result = null;
            errors = new[] { ValueObjectValidationMessages.InputNotConvertible(TSelf.DisplayName, raw) };
            return false;
        }

        return TSelf.TryCreate((TValue)converted, out result, out errors);
    }

    /// <summary>Converts a value from outside the model and creates the value object from it, using the invariant culture.</summary>
    public static bool TryCreateFrom(object? raw, out TSelf? result, out IReadOnlyList<string> errors) =>
        TSelf.TryCreateFrom(raw, null, out result, out errors);

    /// <summary>Converts a value from outside the model and creates the value object from it (throws ValueObjectValidationException on violation; an absent value returns null).</summary>
    /// <param name="raw">The value read from the source.</param>
    /// <param name="provider">The culture the text is written in; <c>null</c> uses the invariant culture.</param>
    /// <exception cref="ValueObjectValidationException">The value could not be converted, or failed validation.</exception>
    public static TSelf? CreateFrom(object? raw, IFormatProvider? provider)
    {
        if (TSelf.TryCreateFrom(raw, provider, out var result, out var errors))
        {
            return result;
        }

        throw new ValueObjectValidationException(typeof(TSelf), errors);
    }

    /// <summary>Converts a value from outside the model and creates the value object from it, using the invariant culture.</summary>
    public static TSelf? CreateFrom(object? raw) => TSelf.CreateFrom(raw, null);

    /// <summary>Gets the underlying value as an object (opens the raw value for SQL binding and similar).</summary>
    object? IValueObjectCore.UnderlyingValue => Value;

    /// <summary>Gets the string used for display (defaults to ToString()). A concrete value object's partial class can override it to change the format.</summary>
    public virtual string DisplayValue => ToString();

    /// <summary>Value-based equality with another instance of the same value object type (compared through <see cref="EqualityComparer{T}.Default"/>, so a struct value is not boxed).</summary>
    /// <remarks>
    /// Implementing <see cref="IEquatable{T}"/> is what lets <see cref="EqualityComparer{T}.Default"/> compare value objects
    /// by value directly. Without it the default comparer falls back to the object-based one, which reaches equality only
    /// through <see cref="Equals(object?)"/> and boxes a struct-valued argument on the way; every dictionary and hash-set
    /// lookup keyed by a value object goes through that comparer. A value object whose value is an array needs
    /// element-by-element comparison and overrides this — the binary value object base does, through
    /// <see cref="ValueObjectBinaryOperations"/>.
    /// </remarks>
    public virtual bool Equals(TSelf? other) =>
        other is not null && EqualityComparer<TValue>.Default.Equals(Value, other.Value);

    /// <summary>Value-based equality (delegates to the typed overload; anything that is not this value object type is unequal).</summary>
    public override bool Equals(object? obj) => obj is TSelf other && Equals(other);

    /// <summary>Value-based hash code (computed through <see cref="EqualityComparer{T}.Default"/>, so a struct value is not boxed).</summary>
    public override int GetHashCode() =>
        Value is null ? 0 : EqualityComparer<TValue>.Default.GetHashCode(Value);

    /// <summary>Value-based equality operator.</summary>
    public static bool operator ==(
        ValueObjectBaseCore<TSelf, TValue>? left,
        ValueObjectBaseCore<TSelf, TValue>? right
    ) => left is null ? right is null : left.Equals(right);

    /// <summary>Value-based inequality operator.</summary>
    public static bool operator !=(
        ValueObjectBaseCore<TSelf, TValue>? left,
        ValueObjectBaseCore<TSelf, TValue>? right
    ) => !(left == right);

    /// <summary>Returns the string representation of the underlying value.</summary>
    public override string ToString() => Value?.ToString() ?? string.Empty;

    /// <summary>Formats the underlying value with the given format string, using the current culture.</summary>
    /// <param name="format">The format string for the underlying value (for example "N2" on a decimal, "yyyy/MM/dd" on a date).</param>
    public string ToString(string? format) => ToString(format, null);

    /// <summary>Formats the underlying value with the given format string and culture.</summary>
    /// <remarks>
    /// Because the value object implements <see cref="IFormattable"/>, a format specifier in string interpolation,
    /// <see cref="string.Format(string, object?)"/>, or a WPF binding's StringFormat reaches the underlying value through
    /// this method. Without a format string the result is always <see cref="ToString()"/> (so an override of
    /// <see cref="ToString()"/> also governs unformatted interpolation and composite formatting, and the format provider
    /// is not consulted). The same applies when the underlying value does not implement <see cref="IFormattable"/>
    /// (a string, a byte array, a bool): the format is ignored, which is what composite formatting does for any such value.
    /// <see cref="DisplayValue"/> is the type's own display form; this method renders the format the caller asks for.
    /// </remarks>
    /// <param name="format">The format string for the underlying value.</param>
    /// <param name="formatProvider">The culture to format with; null uses the current culture.</param>
    public string ToString(string? format, IFormatProvider? formatProvider) =>
        !string.IsNullOrEmpty(format) && Value is IFormattable formattable
            ? formattable.ToString(format, formatProvider)
            : ToString();
}

/// <summary>Comparison bodies shared by the ordered, string and GUID-key value object bases.</summary>
public static class ValueObjectComparisons
{
    /// <summary>Compares a value object with an arbitrary object, for the non-generic <see cref="IComparable"/> surface.</summary>
    /// <remarks>
    /// A null object sorts first, an object of the same value object type is handed to the typed comparison, and anything
    /// else is a programming error rather than an ordering: sorting a list that mixes value object types would otherwise
    /// produce an arbitrary order instead of failing.
    /// </remarks>
    /// <param name="self">The value object the comparison starts from.</param>
    /// <param name="obj">The object to compare with.</param>
    /// <exception cref="ArgumentException"><paramref name="obj"/> is not of type <typeparamref name="TSelf"/>.</exception>
    public static int CompareToObject<TSelf>(IComparable<TSelf> self, object? obj)
        where TSelf : class =>
        obj is null ? 1
        : obj is TSelf other ? self.CompareTo(other)
        : throw new ArgumentException(
            $"{obj.GetType().Name} cannot be compared with {typeof(TSelf).Name}.",
            nameof(obj)
        );

    /// <summary>Orders two operands by their underlying values, treating null as the smallest value (two nulls are equal).</summary>
    /// <remarks>
    /// This is the body behind the ordering operators, which - unlike <see cref="IComparable{T}.CompareTo"/> - can be
    /// handed a null on either side.
    /// </remarks>
    public static int CompareOrdered<TSelf, TValue>(
        ValueObjectBaseCore<TSelf, TValue>? left,
        ValueObjectBaseCore<TSelf, TValue>? right
    )
        where TSelf : ValueObjectBaseCore<TSelf, TValue>, IValueObject<TSelf, TValue>
        where TValue : IComparable<TValue> =>
        left is null ? (right is null ? 0 : -1)
        : right is null ? 1
        : left.Value.CompareTo(right.Value);
}

/// <summary>Equality and hashing over a byte array, as a binary value object defines them.</summary>
public static class ValueObjectBinaryOperations
{
    /// <summary>Compares two arrays element by element (reference equality would make two equal blobs differ); two nulls are equal.</summary>
    /// <remarks>The comparison runs over spans, which compares whole machine words at a time instead of one element at a time — worth having on values that are blob-sized by definition.</remarks>
    public static bool AreEqual(byte[]? left, byte[]? right)
    {
        if (left is null || right is null)
        {
            return left is null && right is null;
        }

        return left.AsSpan().SequenceEqual(right);
    }

    /// <summary>Computes a hash code from every byte, matching <see cref="AreEqual"/>.</summary>
    /// <remarks>
    /// <see cref="HashCode.AddBytes(ReadOnlySpan{byte})"/> mixes in the whole array. The structural comparer used before it
    /// hashes only the last eight elements, so two blobs sharing a tail landed in the same bucket however much of their
    /// content differed — exactly the shape a binary value object tends to have when it wraps a versioned or padded payload.
    /// </remarks>
    public static int ComputeHashCode(byte[]? value)
    {
        if (value is null)
        {
            return 0;
        }

        var hash = new HashCode();
        hash.AddBytes(value);
        return hash.ToHashCode();
    }
}

/// <summary>Converter that reads and writes a value object as its underlying (raw) value in JSON.</summary>
public sealed class ValueObjectJsonConverter<TVo, TValue> : JsonConverter<TVo>
    where TVo : class, IValueObject<TVo, TValue>
{
    /// <summary>Reads the raw value and restores the value object via Create.</summary>
    public override TVo? Read(
        ref Utf8JsonReader reader,
        Type typeToConvert,
        JsonSerializerOptions options
    )
    {
        var value = JsonSerializer.Deserialize<TValue>(ref reader, options);
        return value is null ? null : TVo.Create(value);
    }

    /// <summary>Writes the underlying (raw) value.</summary>
    public override void Write(Utf8JsonWriter writer, TVo value, JsonSerializerOptions options) =>
        JsonSerializer.Serialize(writer, value.Value, options);
}

/// <summary>Factory that applies the generic converter to types implementing IValueObject&lt;,&gt;.</summary>
public sealed class ValueObjectJsonConverterFactory : JsonConverterFactory
{
    /// <summary>Returns whether the type is a value object type.</summary>
    public override bool CanConvert(Type typeToConvert) =>
        Array.Exists(
            typeToConvert.GetInterfaces(),
            i => i.IsGenericType && i.GetGenericTypeDefinition() == typeof(IValueObject<,>)
        );

    /// <summary>Resolves the target type's TValue and creates a closed converter.</summary>
    public override JsonConverter CreateConverter(Type typeToConvert, JsonSerializerOptions options)
    {
        var iface = Array.Find(
            typeToConvert.GetInterfaces(),
            i => i.IsGenericType && i.GetGenericTypeDefinition() == typeof(IValueObject<,>)
        )!;
        var valueType = iface.GetGenericArguments()[1];
        var converterType = typeof(ValueObjectJsonConverter<,>).MakeGenericType(
            typeToConvert,
            valueType
        );
        return (JsonConverter)Activator.CreateInstance(converterType)!;
    }
}

/// <summary>Automatic validation messages for value objects (defaults shared by all VOs). Replacing them at app startup applies to every VO.</summary>
/// <remarks>
/// <para>
/// Every message takes the value object's display name as its first argument, so one replacement covers both the wording
/// for every type and the wording for one type in particular - compare against that type's own <c>DisplayName</c> and let
/// the rest fall through:
/// <c>ValueObjectValidationMessages.ValueRequired = name =&gt; name == NameValue.DisplayName ? "..." : "...";</c>.
/// Naming the type keeps the comparison compiling against the generated code, so a column that is renamed away shows up as
/// a build error rather than as a message that quietly stops matching.
/// </para>
/// <para>
/// The default wording does not spell the display name out, because a value object's violation is normally shown next to
/// the field it belongs to; a replacement that needs the name has it in hand.
/// </para>
/// </remarks>
public static class ValueObjectValidationMessages
{
    /// <summary>Message for exceeding the maximum length (arguments: display name, maximum length, current character count).</summary>
    public static Func<string, int, int, string> MaxLengthExceeded { get; set; } =
        (_, maxLength, actualLength) =>
            $"Enter at most {maxLength} characters. (currently {actualLength} characters)";

    /// <summary>Message for exceeding the number of decimal places (arguments: display name, allowed scale).</summary>
    public static Func<string, int, string> ScaleExceeded { get; set; } =
        (_, scale) => $"Enter at most {scale} digits after the decimal point.";

    /// <summary>Message for exceeding the number of integer digits (arguments: display name, allowed integer digits).</summary>
    public static Func<string, int, string> PrecisionExceeded { get; set; } =
        (_, maxIntegralDigits) => $"Enter at most {maxIntegralDigits} digits in the integer part.";

    /// <summary>Message for a null value passed to Create/TryCreate (argument: display name). A value object never wraps null; keep the property itself null for nullable columns.</summary>
    public static Func<string, string> ValueRequired { get; set; } = _ => "A value is required.";

    /// <summary>Message for exceeding the number of digits of an integer (arguments: display name, allowed digit count).</summary>
    public static Func<string, int, string> DigitsExceeded { get; set; } =
        (_, maxDigits) => $"Enter at most {maxDigits} digits.";

    /// <summary>Message for a value outside the allowed range (arguments: display name, minimum, maximum; both bounds are allowed).</summary>
    public static Func<string, object, object, string> OutOfRange { get; set; } =
        (_, minimum, maximum) => $"Enter a value between {minimum} and {maximum}.";

    /// <summary>Message for a character outside the allowed set (arguments: display name, the extra symbols allowed, empty when none are).</summary>
    public static Func<string, string, string> InvalidCharacters { get; set; } =
        (_, allowedSymbols) =>
            allowedSymbols.Length == 0
                ? "Enter ASCII letters and digits only."
                : $"Enter ASCII letters, digits, and any of \"{allowedSymbols}\" only.";

    /// <summary>Message for a value that is not shaped like an email address (argument: display name).</summary>
    public static Func<string, string> InvalidEmailAddress { get; set; } =
        _ => "Enter a valid email address.";

    /// <summary>Message for a value from outside the model that could not be converted to the underlying type (arguments: display name, the value as read).</summary>
    public static Func<string, object, string> InputNotConvertible { get; set; } =
        (displayName, raw) => $"'{raw}' is not a valid {displayName}.";
}

/// <summary>The rule every value object over a reference-typed value runs before the rest.</summary>
public static class ValueObjectRules
{
    /// <summary>Reports a null value as a violation, and tells the caller whether the rules that follow can run at all.</summary>
    /// <remarks>
    /// A value object never wraps null - a nullable column keeps the property itself null - so a null input is reported as
    /// a validation error rather than as an exception thrown out of the next rule. A false result means "stop here":
    /// every rule after this one dereferences the value.
    /// </remarks>
    /// <param name="value">The value being validated.</param>
    /// <param name="displayName">The value object's display name, handed to the message resolver.</param>
    /// <param name="errors">The violations so far, allocated on the first one.</param>
    /// <returns>True when the value is present; false when it was null and the violation was added.</returns>
    public static bool ValidateRequired<TValue>(
        TValue? value,
        string displayName,
        ref List<string>? errors
    )
        where TValue : class
    {
        if (value is not null)
        {
            return true;
        }

        (errors ??= new List<string>()).Add(
            ValueObjectValidationMessages.ValueRequired(displayName)
        );
        return false;
    }
}

/// <summary>Validation rules for string values: the maximum length a generated value object enforces, plus rules to call from <c>OnValidate</c>.</summary>
/// <remarks>
/// Each rule takes the error list by reference and possibly unallocated, and allocates it only when it has a violation to
/// add, so a value that passes every rule allocates nothing at all.
/// </remarks>
public static class ValueObjectStringRules
{
    /// <summary>Rejects a value longer than <paramref name="maxLength"/> characters.</summary>
    /// <param name="value">The value being validated.</param>
    /// <param name="maxLength">The greatest number of characters allowed.</param>
    /// <param name="displayName">The value object's display name, handed to the message resolver.</param>
    /// <param name="errors">The violations so far, allocated on the first one.</param>
    public static void ValidateMaxLength(
        string value,
        int maxLength,
        string displayName,
        ref List<string>? errors
    )
    {
        if (value.Length > maxLength)
        {
            (errors ??= new List<string>()).Add(
                ValueObjectValidationMessages.MaxLengthExceeded(
                    displayName,
                    maxLength,
                    value.Length
                )
            );
        }
    }

    /// <summary>Rejects any character that is neither an ASCII letter or digit nor one of <paramref name="allowedSymbols"/>.</summary>
    /// <remarks>
    /// The set is ASCII on purpose: a full-width letter or digit is rejected, which is what a code or an identifier column
    /// normally wants. At most one violation is added however many characters offend, because the message names the rule
    /// rather than the character.
    /// </remarks>
    /// <param name="value">The value being validated.</param>
    /// <param name="allowedSymbols">Extra characters to allow; an empty string allows no symbols at all.</param>
    /// <param name="displayName">The value object's display name, handed to the message resolver.</param>
    /// <param name="errors">The violations so far, allocated on the first one.</param>
    public static void ValidateAsciiAlphanumeric(
        string value,
        string allowedSymbols,
        string displayName,
        ref List<string>? errors
    )
    {
        foreach (var character in value)
        {
            if (char.IsAsciiLetterOrDigit(character) || allowedSymbols.Contains(character))
            {
                continue;
            }

            (errors ??= new List<string>()).Add(
                ValueObjectValidationMessages.InvalidCharacters(displayName, allowedSymbols)
            );
            return;
        }
    }

    /// <summary>Rejects a value that is not shaped like an email address: exactly one '@', a non-empty part on each side of it, and no whitespace anywhere.</summary>
    /// <remarks>
    /// This is a practical minimum rather than RFC 5322. The full grammar accepts quoted local parts, comments and address
    /// literals that no application wants stored in a column, and turning an address away is worse than letting an odd one
    /// through - deliverability is settled by sending mail, not by a pattern. <see cref="System.Net.Mail.MailAddress"/> is
    /// not used for the same reason it looks tempting: it also parses the display-name form ("Name &lt;a@b&gt;"), so a
    /// whole header line would pass as an address.
    /// </remarks>
    /// <param name="value">The value being validated.</param>
    /// <param name="displayName">The value object's display name, handed to the message resolver.</param>
    /// <param name="errors">The violations so far, allocated on the first one.</param>
    public static void ValidateEmailAddress(
        string value,
        string displayName,
        ref List<string>? errors
    )
    {
        if (!IsEmailAddress(value))
        {
            (errors ??= new List<string>()).Add(
                ValueObjectValidationMessages.InvalidEmailAddress(displayName)
            );
        }
    }

    /// <summary>Returns whether the text has the shape <see cref="ValidateEmailAddress"/> accepts.</summary>
    private static bool IsEmailAddress(string value)
    {
        var at = value.IndexOf('@');

        if (at <= 0 || at == value.Length - 1 || at != value.LastIndexOf('@'))
        {
            return false;
        }

        foreach (var character in value)
        {
            if (char.IsWhiteSpace(character))
            {
                return false;
            }
        }

        return true;
    }
}

/// <summary>Validation rules for numeric values, to call from a value object's <c>OnValidate</c>.</summary>
/// <remarks>
/// Each rule takes the error list by reference and possibly unallocated, and allocates it only when it has a violation to
/// add, so a value that passes every rule allocates nothing at all.
/// </remarks>
public static class ValueObjectNumberRules
{
    /// <summary>Rejects an integer written with more than <paramref name="maxDigits"/> digits.</summary>
    /// <remarks>The sign does not count, and neither do leading zeros, which an integer does not carry; zero is one digit.</remarks>
    /// <param name="value">The value being validated (a narrower integer type widens to it).</param>
    /// <param name="maxDigits">The greatest number of digits allowed.</param>
    /// <param name="displayName">The value object's display name, handed to the message resolver.</param>
    /// <param name="errors">The violations so far, allocated on the first one.</param>
    public static void ValidateMaxDigits(
        long value,
        int maxDigits,
        string displayName,
        ref List<string>? errors
    )
    {
        if (CountDigits(value) > maxDigits)
        {
            (errors ??= new List<string>()).Add(
                ValueObjectValidationMessages.DigitsExceeded(displayName, maxDigits)
            );
        }
    }

    /// <summary>Rejects a value outside the closed interval from <paramref name="minimum"/> to <paramref name="maximum"/> (both bounds are allowed).</summary>
    /// <param name="value">The value being validated.</param>
    /// <param name="minimum">The smallest value allowed.</param>
    /// <param name="maximum">The greatest value allowed.</param>
    /// <param name="displayName">The value object's display name, handed to the message resolver.</param>
    /// <param name="errors">The violations so far, allocated on the first one.</param>
    public static void ValidateRange<T>(
        T value,
        T minimum,
        T maximum,
        string displayName,
        ref List<string>? errors
    )
        where T : IComparable<T>
    {
        if (value.CompareTo(minimum) < 0 || value.CompareTo(maximum) > 0)
        {
            (errors ??= new List<string>()).Add(
                ValueObjectValidationMessages.OutOfRange(displayName, minimum, maximum)
            );
        }
    }

    /// <summary>Counts the digits an integer is written with, ignoring the sign.</summary>
    private static int CountDigits(long value)
    {
        // long.MinValue has no positive counterpart, so negating it would overflow; its digit count is a constant.
        if (value == long.MinValue)
        {
            return 19;
        }

        var remaining = value < 0 ? -value : value;
        var digits = 1;

        while (remaining >= 10)
        {
            remaining /= 10;
            digits++;
        }

        return digits;
    }
}

/// <summary>Validation rules for decimal values: the digit counts a generated value object enforces from the column's precision and scale.</summary>
/// <remarks>
/// Each rule takes the error list by reference and possibly unallocated, and allocates it only when it has a violation to
/// add, so a value that passes every rule allocates nothing at all.
/// </remarks>
public static class ValueObjectDecimalRules
{
    /// <summary>Powers of ten, so the integer part is checked with one comparison instead of a division per digit.</summary>
    /// <remarks>
    /// A decimal holds at most 29 significant digits, so the table ends at 10^28 and a limit at least that wide can never
    /// be exceeded.
    /// </remarks>
    private static readonly decimal[] PowersOfTen =
    {
        1m,
        1e1m,
        1e2m,
        1e3m,
        1e4m,
        1e5m,
        1e6m,
        1e7m,
        1e8m,
        1e9m,
        1e10m,
        1e11m,
        1e12m,
        1e13m,
        1e14m,
        1e15m,
        1e16m,
        1e17m,
        1e18m,
        1e19m,
        1e20m,
        1e21m,
        1e22m,
        1e23m,
        1e24m,
        1e25m,
        1e26m,
        1e27m,
        1e28m,
    };

    /// <summary>Validates the digit counts of a decimal (does not round; rejects overflow). Trailing zeros count toward the scale.</summary>
    /// <param name="value">The value being validated.</param>
    /// <param name="precision">The column's total number of digits.</param>
    /// <param name="scale">The column's number of decimal places; the integer part may hold <c>precision - scale</c> digits.</param>
    /// <param name="displayName">The value object's display name, handed to the message resolver.</param>
    /// <param name="errors">The violations so far, allocated on the first one.</param>
    public static void Validate(
        decimal value,
        int precision,
        int scale,
        string displayName,
        ref List<string>? errors
    )
    {
        // decimal.Scale states the number of decimal places directly; reading it out of decimal.GetBits meant
        // allocating a four-element int array on every single validation just to shift one of the words.
        if (value.Scale > scale)
        {
            (errors ??= new List<string>()).Add(
                ValueObjectValidationMessages.ScaleExceeded(displayName, scale)
            );
        }

        var maxIntegralDigits = precision - scale;
        var integral = Math.Truncate(Math.Abs(value));

        if (
            maxIntegralDigits < 0
            || (
                maxIntegralDigits < PowersOfTen.Length
                && integral >= PowersOfTen[maxIntegralDigits]
            )
        )
        {
            (errors ??= new List<string>()).Add(
                ValueObjectValidationMessages.PrecisionExceeded(displayName, maxIntegralDigits)
            );
        }
    }
}

/// <summary>Marker implemented by every value object. Adding an interface or a member to a partial declaration of this type reaches all of them at once.</summary>
public partial interface IValueObject : IValueObjectCore { }

/// <summary>Base of every value object, and the extension point that reaches all of them: a member added to a partial declaration of this class is available on every value object whatever its value shape. The shaped bases below all derive from it, and a value object whose underlying type has no shaped base of its own (a Guid or an sbyte, say) derives from it directly.</summary>
/// <typeparam name="TSelf">The concrete value object type deriving from this class.</typeparam>
/// <typeparam name="TValue">The underlying value type.</typeparam>
public abstract partial class ValueObjectBase<TSelf, TValue>
    : ValueObjectBaseCore<TSelf, TValue>,
        IValueObject
    where TSelf : ValueObjectBase<TSelf, TValue>, IValueObject<TSelf, TValue>
{
    /// <summary>Initializes with an already-validated value.</summary>
    protected ValueObjectBase(TValue value)
        : base(value) { }
}

/// <summary>Base of every orderable value object (numeric and date/time types), and the extension point for them. Provides comparison operators and CompareTo.</summary>
/// <typeparam name="TSelf">The concrete value object type deriving from this class.</typeparam>
/// <typeparam name="TValue">The underlying value type.</typeparam>
public abstract partial class ValueObjectOrderedBase<TSelf, TValue>
    : ValueObjectBase<TSelf, TValue>,
