/// <summary>A single UNIQUE constraint violation reported by a uniqueness pre-check.</summary>
/// <param name="ConstraintName">Name of the violated constraint (the synthesized name when the diagram does not set one; a caller-defined name for user-defined checks).</param>
/// <param name="PropertyNames">Entity property names that make up the constraint, in declaration order (empty for a check that is not tied to specific properties).</param>
/// <param name="Message">Message that replaces the default one built by the caller (null to use the default).</param>
public sealed record UniquenessViolation(
    string ConstraintName,
    IReadOnlyList<string> PropertyNames,
    string? Message = null
);

/// <summary>A user-defined uniqueness check that participates in <c>CheckUniquenessAsync</c> (returns null when the entity is unique).</summary>
/// <typeparam name="TEntity">The entity type being checked.</typeparam>
/// <param name="entity">The entity to check.</param>
/// <param name="cancellationToken">The cancellation token.</param>
public delegate Task<UniquenessViolation?> UniquenessCheck<TEntity>(
    TEntity entity,
    CancellationToken cancellationToken
);

/// <summary>One UNIQUE-constraint check as data: the guard that skips tuples containing null, the equality filter over the constraint members, and the names the violation reports.</summary>
/// <typeparam name="TEntity">The entity type being checked.</typeparam>
/// <param name="ConstraintName">Name of the constraint (the synthesized name when the diagram does not set one).</param>
/// <param name="PropertyNames">Entity property names that make up the constraint, in declaration order.</param>
/// <param name="HasAllValues">Returns whether every constraint member holds a value (tuples containing null are skipped; NULL collision semantics differ per dialect).</param>
/// <param name="ApplyFilter">Adds the equality filter for the constraint members to a candidate query (one Where per member, AND-combined).</param>
public sealed record UniquenessConstraintCheck<TEntity>(
    string ConstraintName,
    IReadOnlyList<string> PropertyNames,
    Func<TEntity, bool> HasAllValues,
    Func<SqlQuery<TEntity>, TEntity, SqlQuery<TEntity>> ApplyFilter
)
    where TEntity : class;

/// <summary>The UNIQUE constraints of one entity type as a single value: the constraint table and the self-exclusion that belongs with it.</summary>
/// <remarks>
/// The generated repository hands this to its base class through a single override, which is what lets one implementation
/// of the pre-check serve every entity type. An entity type that declares no constraint leaves <see cref="Empty"/> in
/// place, so the walk finds nothing and only the user-defined checks run.
/// </remarks>
/// <typeparam name="TEntity">The entity type being checked.</typeparam>
/// <param name="Constraints">The constraint checks, in declaration order.</param>
/// <param name="ExcludeSelf">Excludes the entity's own row from a candidate query (a row that has no primary key yet excludes nothing).</param>
public sealed record UniquenessConstraintSet<TEntity>(
    IReadOnlyList<UniquenessConstraintCheck<TEntity>> Constraints,
    Func<SqlQuery<TEntity>, TEntity, SqlQuery<TEntity>> ExcludeSelf
)
    where TEntity : class
{
    /// <summary>The set an entity type that declares no UNIQUE constraint uses (nothing to walk, no row to exclude).</summary>
    public static UniquenessConstraintSet<TEntity> Empty { get; } =
        new(Array.Empty<UniquenessConstraintCheck<TEntity>>(), static (query, _) => query);
}

/// <summary>Shared engine of the uniqueness pre-check: walks the constraint table, excludes the entity's own row, asks the store for existence, and runs the user-defined checks.</summary>
/// <remarks>
/// Everything type-specific stays with the generated code, either as data (the constraint table and the self-exclusion,
/// whose expression trees must be built over the concrete entity type) or as code (the partial hook that collects the
/// user-defined checks, which a shared engine cannot call). The checks run through <c>Query()</c>, so every
/// implementation target - the dialect repositories, in-memory, and EF Core - answers with the same semantics.
/// </remarks>
public static class UniquenessChecker
{
    /// <summary>Checks the declared UNIQUE constraints and returns the violations (an empty list when there are none).</summary>
    /// <param name="entity">The entity whose constraint member values are checked.</param>
    /// <param name="query">Creates a fresh candidate query (called once per constraint).</param>
    /// <param name="excludeSelf">Excludes the entity's own row from a candidate query (a row that has no primary key yet excludes nothing).</param>
    /// <param name="constraints">The constraint table, in declaration order.</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    public static async Task<List<UniquenessViolation>> CheckAsync<TEntity>(
        TEntity entity,
        Func<SqlQuery<TEntity>> query,
        Func<SqlQuery<TEntity>, TEntity, SqlQuery<TEntity>> excludeSelf,
        IReadOnlyList<UniquenessConstraintCheck<TEntity>> constraints,
        CancellationToken cancellationToken
    )
        where TEntity : class
    {
        ArgumentNullException.ThrowIfNull(entity);
        var violations = new List<UniquenessViolation>();

        foreach (var constraint in constraints)
        {
            // Tuples whose member values contain null are not checked (NULL collision semantics differ per dialect)
            if (!constraint.HasAllValues(entity))
            {
                continue;
            }

            var duplicated = await excludeSelf(constraint.ApplyFilter(query(), entity), entity)
                .AnyAsync(cancellationToken)
                .ConfigureAwait(false);

            if (duplicated)
            {
                violations.Add(
                    new UniquenessViolation(constraint.ConstraintName, constraint.PropertyNames)
                );
            }
        }

        return violations;
    }

    /// <summary>Runs the user-defined checks collected by the generated hook, adding every reported violation (a null list - the hook unimplemented, or nothing added - is a no-op).</summary>
    /// <param name="entity">The entity to check.</param>
    /// <param name="checks">The user-defined checks, or null when there are none.</param>
    /// <param name="violations">The list the reported violations are added to.</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    public static async Task RunCustomChecksAsync<TEntity>(
        TEntity entity,
        List<UniquenessCheck<TEntity>>? checks,
        List<UniquenessViolation> violations,
        CancellationToken cancellationToken
    )
        where TEntity : class
    {
        if (checks is null)
        {
            return;
        }

        foreach (var check in checks)
        {
            if (await check(entity, cancellationToken).ConfigureAwait(false) is { } violation)
            {
                violations.Add(violation);
            }
        }
    }
}

/// <summary>Common repository interface limited to operations that can be provided across a network boundary (the remote surface).</summary>
/// <remarks>
/// <para>
/// Holds only CRUD and save operations for single entities and entity graphs; it excludes members that take arguments
/// that cannot be carried out of process, such as expression trees (<see cref="IRepositoryCore{TEntity, TKey}.Query"/>) or
/// raw SQL. Because every member's arguments and return values are pure data (entities, primary keys, counts), code that
/// depends only on this surface stays compile-time safe even if the implementation is later swapped for a remote
/// implementation (over a web service).
/// </para>
/// <para>
/// <see cref="IRepositoryCore{TEntity, TKey}"/> inherits this interface and provides all of its methods, so existing consuming
/// code is unchanged. With remote contract generation (GenerateRemoteContracts), an I{Entity}RemoteRepository that has only
/// this surface (plus the named queries) is additionally generated, and I{Entity}Repository inherits it.
/// </para>
/// </remarks>
public interface IRemoteRepositoryCore<TEntity, TKey>
    where TEntity : EntityBaseCore, new()
{
    /// <summary>Gets a single entity by primary key (null when not found).</summary>
    Task<TEntity?> GetByIdAsync(TKey id, CancellationToken cancellationToken = default);

    /// <summary>Gets all entities.</summary>
    Task<IReadOnlyList<TEntity>> GetAllAsync(CancellationToken cancellationToken = default);

    /// <summary>Inserts an entity.</summary>
    Task InsertAsync(TEntity entity, CancellationToken cancellationToken = default);

    /// <summary>Updates an entity (true when a matching row was updated).</summary>
    /// <param name="entity">The entity to update.</param>
    /// <param name="mode">How a concurrent modification is handled when the table has a rowversion column (no effect otherwise). Not every engine behind this contract honours it: an engine whose database does not assign that column's value writes the column as an ordinary one, so it has no version to compare and ignores this argument. An undefined value throws <see cref="ArgumentOutOfRangeException"/>.</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    Task<bool> UpdateAsync(
        TEntity entity,
        ConcurrencyMode mode = ConcurrencyMode.Optimistic,
        CancellationToken cancellationToken = default
    );

    /// <summary>Deletes an entity by primary key (true when a matching row was deleted).</summary>
    /// <remarks>
    /// The delete is unconditional: a primary key is all this call is given, so there is no version to compare it against
    /// and <see cref="ConcurrencyMode"/> plays no part even when the table has a rowversion column. To delete under the
    /// protection of the version that was read, call <c>MarkRemoved()</c> on the entity and hand it to <c>SaveAsync</c>,
    /// which fails with <see cref="SaveConflictException"/> when someone else has changed the row meanwhile.
    /// </remarks>
    /// <param name="id">The primary key of the row to delete.</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    Task<bool> DeleteAsync(TKey id, CancellationToken cancellationToken = default);

    /// <summary>Saves inserts, updates, and deletes in a single transaction according to RowState (children cascade by default).</summary>
    /// <param name="entity">The entity to save (the aggregate root).</param>
    /// <param name="cascadeSave">Whether to cascade the save to child objects.</param>
    /// <param name="cascadeDelete">Whether to cascade deletes to child objects.</param>
    /// <param name="insertWhenUpdateMissing">Whether to switch to INSERT when no row exists to update (throws by default).</param>
    /// <param name="mode">How a concurrent modification is handled for entities whose table has a rowversion column (no effect otherwise). Not every engine behind this contract honours it: an engine whose database does not assign that column's value writes the column as an ordinary one, so it has no version to compare and ignores this argument. An undefined value throws <see cref="ArgumentOutOfRangeException"/>.</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    /// <returns>The number of records saved.</returns>
    Task<int> SaveAsync(
        TEntity entity,
        bool cascadeSave = true,
        bool cascadeDelete = true,
        bool insertWhenUpdateMissing = false,
        ConcurrencyMode mode = ConcurrencyMode.Optimistic,
        CancellationToken cancellationToken = default
    );

    /// <summary>Saves multiple aggregate roots together in a single transaction (an atomic all-succeed-or-all-rollback operation).</summary>
    /// <param name="entities">The list of entities to save (the aggregate roots).</param>
    /// <param name="cascadeSave">Whether to cascade the save to child objects.</param>
    /// <param name="cascadeDelete">Whether to cascade deletes to child objects.</param>
    /// <param name="insertWhenUpdateMissing">Whether to switch to INSERT when no row exists to update (throws by default).</param>
    /// <param name="mode">How a concurrent modification is handled for entities whose table has a rowversion column (no effect otherwise). Not every engine behind this contract honours it: an engine whose database does not assign that column's value writes the column as an ordinary one, so it has no version to compare and ignores this argument. An undefined value throws <see cref="ArgumentOutOfRangeException"/>.</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    /// <returns>The number of records saved.</returns>
    Task<int> SaveAsync(
        IEnumerable<TEntity> entities,
        bool cascadeSave = true,
        bool cascadeDelete = true,
        bool insertWhenUpdateMissing = false,
        ConcurrencyMode mode = ConcurrencyMode.Optimistic,
        CancellationToken cancellationToken = default
    );

    /// <summary>Checks the entity's declared UNIQUE constraints against the store and returns the violations (an empty list when there are none).</summary>
    /// <remarks>
    /// Rows that share the entity's primary key are excluded, so the same call is correct for both insert and update (an
    /// entity whose key is not set yet excludes nothing). Constraint member values that contain a null are skipped (NULL
    /// collision semantics differ per dialect). The result is advisory only: the definitive guarantee is the database's
    /// own UNIQUE constraint, and a concurrent insert between this check and the save can still make the save fail
    /// (TOCTOU). The checks a repository adds through its <c>CollectCustomUniquenessChecks</c> hook run as part of it,
    /// and over a remote implementation the whole check, those hooks included, runs in the server-side repository.
    /// </remarks>
    /// <param name="entity">The entity whose constraint member values are checked.</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    Task<IReadOnlyList<UniquenessViolation>> CheckUniquenessAsync(
        TEntity entity,
        CancellationToken cancellationToken = default
    );
}

/// <summary>Common repository interface that provides CRUD operations for entities.</summary>
/// <remarks>
/// The full-featured surface that, in addition to the remote surface (<see cref="IRemoteRepositoryCore{TEntity, TKey}"/>), adds
/// members that assume local execution (a direct DB connection): expression-tree queries, raw SQL, and bulk insert.
/// I{Entity}Repository always provides this full-featured surface.
/// </remarks>
public interface IRepositoryCore<TEntity, TKey> : IRemoteRepositoryCore<TEntity, TKey>
    where TEntity : EntityBaseCore, new()
{
    /// <summary>Bulk inserts a collection of entities.</summary>
    /// <remarks>
    /// The contract every backend keeps to:
    /// <list type="bullet">
    /// <item><description>A <c>null</c> element is skipped rather than rejected (the same treatment the graph save gives a null in its list).</description></item>
    /// <item><description>The return value counts the rows actually inserted, so skipped elements are not part of it.</description></item>
    /// <item><description>An empty collection inserts nothing and returns 0 without opening a connection.</description></item>
    /// <item><description>A cancellation already requested on entry throws before anything is written.</description></item>
    /// </list>
    /// The insert itself is one unit of work per backend (SqlBulkCopy, a single transaction, one SaveChanges, or one staged
    /// batch), but only the in-memory backend validates the whole batch for duplicate primary keys up front.
    /// </remarks>
    /// <param name="entities">The list of entities to insert (null elements are skipped).</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    /// <returns>The number of rows inserted.</returns>
    Task<int> BulkInsertAsync(
        IEnumerable<TEntity> entities,
        CancellationToken cancellationToken = default
    );

    /// <summary>Starts a query where filters, ordering, and Include can be specified via a fluent chain.</summary>
    SqlQuery<TEntity> Query();

    /// <summary>Executes a raw SQL SELECT and maps the result rows to {TEntity}.</summary>
    /// <remarks>
    /// <para>
    /// The SELECT must return all columns of {TEntity} (<c>SELECT *</c> or all columns listed). A partial SELECT (missing
    /// columns) is not allowed; if any column is missing, an exception is thrown that names the missing column.
    /// </para>
    /// <para>
    /// <paramref name="parameters"/> enumerates the public instance properties of an anonymous object (or similar) and binds
    /// property name <c>Foo</c> as SQL parameter <c>@Foo</c> (null means no parameters). Because raw SQL has no column context,
    /// values are bound without an explicit type via <c>AddWithValue</c>.
    /// <b>Always pass values as parameters (concatenating them into the SQL string risks injection).</b>
    /// </para>
    /// </remarks>
    /// <param name="sql">A SELECT statement that returns all columns.</param>
    /// <param name="parameters">An anonymous object bound to @name parameters (null for no parameters).</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    Task<IReadOnlyList<TEntity>> QueryBySqlAsync(
        string sql,
        object? parameters = null,
        CancellationToken cancellationToken = default
    );

    /// <summary>Executes raw SQL (UPDATE/DELETE/any DML) and returns the number of affected rows.</summary>
    /// <remarks>
    /// <para>
    /// <paramref name="parameters"/> is bound the same way as <see cref="QueryBySqlAsync"/> (property name <c>Foo</c> → <c>@Foo</c>,
    /// <c>AddWithValue</c> without an explicit type, null for no parameters).
    /// <b>Always pass values as parameters (string concatenation risks injection).</b>
    /// </para>
    /// <para>
    /// The connection is opened and closed per call (no transaction argument). To execute multiple statements atomically,
    /// write <c>BEGIN TRAN ... COMMIT</c> inside a single <see cref="ExecuteSqlAsync"/> call.
    /// </para>
    /// </remarks>
    /// <param name="sql">The DML statement to execute.</param>
    /// <param name="parameters">An anonymous object bound to @name parameters (null for no parameters).</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    Task<int> ExecuteSqlAsync(
        string sql,
        object? parameters = null,
        CancellationToken cancellationToken = default
    );

    /// <summary>Executes raw SQL and returns a single scalar value (<c>default</c> when there is no match or DBNull).</summary>
    /// <remarks>
    /// <para>
    /// <paramref name="parameters"/> is bound the same way as <see cref="QueryBySqlAsync"/>.
    /// <b>Always pass values as parameters (string concatenation risks injection).</b>
    /// </para>
    /// <para>
    /// When the result is <c>null</c> / <see cref="DBNull"/>, returns <c>default(TResult)</c>. When the type does not match
    /// <typeparamref name="TResult"/>, it performs a best-effort conversion with
    /// <see cref="System.Convert.ChangeType(object, System.Type, System.IFormatProvider)"/>
    /// (<see cref="System.Globalization.CultureInfo.InvariantCulture"/>), throwing a descriptive exception when it cannot convert.
    /// </para>
    /// </remarks>
    /// <param name="sql">A SELECT statement that returns a single value (for example, <c>SELECT COUNT(*) ...</c>).</param>
    /// <param name="parameters">An anonymous object bound to @name parameters (null for no parameters).</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    Task<TResult?> ExecuteScalarSqlAsync<TResult>(
        string sql,
        object? parameters = null,
        CancellationToken cancellationToken = default
    );
}

/// <summary>A raw SQL executor not bound to a specific entity (executes arbitrary SQL and maps to entities, projection DTOs, or single values).</summary>
/// <remarks>
/// <para>
/// Unlike the raw SQL methods on <see cref="IRepositoryCore{TEntity, TKey}"/>, the caller specifies the type via a type argument,
/// so cross-entity JOIN and aggregate queries can be projected onto any DTO. The repository's raw SQL methods delegate to
/// this executor internally.
/// </para>
/// <para>
/// <c>parameters</c> is bound the same way as the repository's raw SQL methods (property name <c>Foo</c> of an anonymous
/// object is bound as <c>@Foo</c> without an explicit type; null for no parameters).
/// <b>Always pass values as parameters (concatenating them into the SQL string risks injection).</b>
/// </para>
/// </remarks>
public partial interface ISqlExecutor
{
    /// <summary>Executes a raw SQL SELECT and maps the result rows strictly (all columns required) to {TEntity}.</summary>
    /// <remarks>
    /// The SELECT must return all columns of {TEntity} (<c>SELECT *</c> or all columns listed); if any column is missing, a
    /// descriptive exception is thrown. Mapping and the RowState=Unchanged treatment are identical to
    /// <see cref="IRepositoryCore{TEntity, TKey}.QueryBySqlAsync"/>.
    /// </remarks>
    /// <param name="sql">A SELECT statement that returns all columns.</param>
    /// <param name="parameters">An anonymous object bound to @name parameters (null for no parameters).</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    Task<IReadOnlyList<TEntity>> QueryBySqlAsync<TEntity>(
        string sql,
        object? parameters = null,
        CancellationToken cancellationToken = default
    )
        where TEntity : EntityBaseCore, new();

    /// <summary>Executes a raw SQL SELECT and leniently projects the result rows onto an arbitrary <typeparamref name="TResult"/>.</summary>
    /// <remarks>
    /// <para>
    /// <b>Single-value mode</b>: when <typeparamref name="TResult"/> (Nullable is judged by its underlying type) is primitive / enum /
    /// string / decimal / DateTime / DateTimeOffset / TimeSpan / Guid / byte[] / a value object (IValueObjectCore implementation),
    /// the <b>first column</b> of each row is converted and returned (DBNull becomes <c>default</c>). Conversion uses the same
    /// Nullable-aware <see cref="System.Convert.ChangeType(object, System.Type, System.IFormatProvider)"/> as the scalar methods.
    /// </para>
    /// <para>
    /// <b>DTO mode</b>: any other type requires a public parameterless constructor (positional records are not supported). Result
    /// set column names are matched <b>case-insensitively</b> against the writable properties (set/init) of
    /// <typeparamref name="TResult"/>, and only matching columns are assigned. Extra columns are ignored and missing columns keep
    /// their defaults. When no column matches at all, an exception listing the column names and property names is thrown (typo guard).
    /// </para>
    /// <para>
    /// Projection DTOs have no save path, so a partial map carries no data-corruption risk; unlike entities, they are mapped <b>leniently</b>.
    /// </para>
    /// </remarks>
    /// <param name="sql">The SELECT statement to project.</param>
    /// <param name="parameters">An anonymous object bound to @name parameters (null for no parameters).</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    Task<IReadOnlyList<TResult>> QueryProjectionBySqlAsync<TResult>(
        string sql,
        object? parameters = null,
        CancellationToken cancellationToken = default
    );

    /// <summary>Executes raw SQL (UPDATE/DELETE/any DML) and returns the number of affected rows.</summary>
    /// <remarks>
    /// The connection is opened and closed per call (no transaction argument). To execute multiple statements atomically,
    /// write <c>BEGIN TRAN ... COMMIT</c> in the SQL within a single call.
    /// </remarks>
    /// <param name="sql">The DML statement to execute.</param>
    /// <param name="parameters">An anonymous object bound to @name parameters (null for no parameters).</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    Task<int> ExecuteSqlAsync(
        string sql,
        object? parameters = null,
        CancellationToken cancellationToken = default
    );

    /// <summary>Executes raw SQL and returns a single scalar value (<c>default</c> when there is no match or DBNull).</summary>
    /// <remarks>
    /// When the result is <c>null</c> / <see cref="DBNull"/>, returns <c>default(TResult)</c>. When the type does not match,
    /// it performs a best-effort conversion with
    /// <see cref="System.Convert.ChangeType(object, System.Type, System.IFormatProvider)"/> (<see cref="System.Globalization.CultureInfo.InvariantCulture"/>),
    /// throwing a descriptive exception when it cannot convert.
    /// </remarks>
    /// <param name="sql">A SELECT statement that returns a single value (for example, <c>SELECT COUNT(*) ...</c>).</param>
    /// <param name="parameters">An anonymous object bound to @name parameters (null for no parameters).</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    Task<TResult?> ExecuteScalarSqlAsync<TResult>(
        string sql,
        object? parameters = null,
        CancellationToken cancellationToken = default
    );
}

/// <summary>The kind of DB operation performed for a single entity during a graph save (Save).</summary>
public enum SaveOperation
{
    /// <summary>Insert (INSERT).</summary>
    Insert,

    /// <summary>Update (UPDATE).</summary>
    Update,

    /// <summary>Delete (DELETE).</summary>
    Delete,
}

/// <summary>Selects how concurrent modifications are handled when saving an entity whose table has a rowversion column (no effect otherwise).</summary>
/// <remarks>
/// Not every engine generated from this diagram honours it: an engine whose database does not assign that column's value writes the
/// column as an ordinary one, so it has no version to compare and neither member changes what a save against it does.
/// </remarks>
public enum ConcurrencyMode
{
    /// <summary>Rejects the save with a SaveConflictException when the row was modified by someone else after it was read (the default).</summary>
    Optimistic,

    /// <summary>Overwrites the row unconditionally, ignoring the version check (an explicit last-write-wins).</summary>
    ForceOverwrite,
}

/// <summary>Validates a ConcurrencyMode argument (an undefined value must fail fast instead of silently disabling the version check).</summary>
internal static class ConcurrencyModes
{
    /// <summary>Returns the mode unchanged, or throws ArgumentOutOfRangeException when it is not a defined member.</summary>
    public static ConcurrencyMode Validated(ConcurrencyMode mode) =>
        mode is ConcurrencyMode.Optimistic or ConcurrencyMode.ForceOverwrite
            ? mode
            : throw new ArgumentOutOfRangeException(
                nameof(mode),
                "The concurrency mode must be Optimistic or ForceOverwrite."
            );
}

/// <summary>Transaction handling shared by the failure paths of the generated repositories.</summary>
internal static class SqlTransactions
{
    /// <summary>Rolls a transaction back from a catch block, never letting the rollback replace the failure being propagated.</summary>
    /// <remarks>
    /// <para>
    /// A rollback attempted on a transaction that has already completed - most notably one whose commit went through
    /// before the failure occurred - throws <see cref="InvalidOperationException"/>, and an exception thrown from a
    /// catch block replaces the one being propagated. The original failure is the one that explains what went wrong,
    /// so the completed case is skipped and anything the rollback itself raises is swallowed.
    /// </para>
    /// <para>
    /// Nothing is leaked by swallowing: the caller disposes the connection on the way out, which ends an uncommitted
    /// transaction regardless. The rollback also runs with <see cref="CancellationToken.None"/>, because a canceled
    /// token must not be able to interrupt it.
    /// </para>
    /// </remarks>
    /// <param name="transaction">The transaction to roll back.</param>
    public static async Task RollbackQuietlyAsync(DbTransaction transaction)
    {
        // A completed transaction no longer holds its connection, which is the portable way to tell that there is
        // nothing left to roll back.
        if (transaction.Connection is null)
        {
            return;
        }

        try
        {
            await transaction.RollbackAsync(CancellationToken.None).ConfigureAwait(false);
        }
        catch (Exception)
        {
            // Deliberately ignored: reporting it would hide the failure that is on its way to the caller.
        }
    }
}

/// <summary>
/// A hook that injects logic before and after a graph save (<c>SaveAsync</c>). Zero or more can be registered in DI and are
/// resolved per target entity type.
/// </summary>
/// <remarks>
/// <para>
/// Both methods have default implementations, so implement only the one you need. <see cref="BeforeSaveAsync"/> is called
/// immediately before each entity's operation (Insert/Update/Delete); returning <c>false</c> skips just that single
/// operation (other rows continue). <see cref="AfterSaveAsync"/> is called immediately after the operation, before commit,
/// together with an <see cref="ISaveHookContext"/> that participates in the same transaction (throwing an exception rolls
/// back the entire save).
/// </para>
/// <para>
/// Hooks fire only for <c>SaveAsync</c> (graph save, both overloads); direct calls to <c>InsertAsync</c> / <c>UpdateAsync</c> /
/// <c>DeleteAsync</c> and <c>BulkInsertAsync</c> are not covered (they pass through). Consistency across skips (for example,
/// if you block a new parent, also block its new children) is the hook implementer's responsibility; contradictions fail
/// safe via a DB constraint error followed by a full rollback.
/// </para>
/// </remarks>
/// <typeparam name="TEntity">The entity type the hook targets.</typeparam>
public interface ISaveHook<TEntity>
    where TEntity : EntityBaseCore
{
    /// <summary>Called immediately before the operation (<c>false</c> skips that single operation; the default does not skip).</summary>
    /// <param name="entity">The entity being saved.</param>
    /// <param name="operation">
    /// The operation about to be performed (Insert/Update/Delete), decided from the entity's RowState before the hook is
    /// called. Rewriting that RowState from inside the hook is not a supported way to redirect the save: whether the change
    /// is picked up is not guaranteed and differs between the backends. Returning <c>false</c> is the supported way to stop
    /// an operation - it is what <see cref="AfterSaveAsync"/> reflects, since that one reports the operation actually
    /// performed.
    /// </param>
    /// <param name="cancellationToken">The cancellation token.</param>
    /// <returns><c>true</c> to proceed with the operation, <c>false</c> to skip it.</returns>
    Task<bool> BeforeSaveAsync(
        TEntity entity,
        SaveOperation operation,
        CancellationToken cancellationToken = default
    ) => Task.FromResult(true);

    /// <summary>Called immediately after the operation, before commit (the default does nothing; <paramref name="context"/> participates in the same transaction).</summary>
    /// <remarks>
    /// Because this runs before the commit, a rowversion (concurrency token) property still holds the value the entity was
    /// read with: the version the database assigned during this save is written back only after the commit succeeds.
    /// </remarks>
    /// <param name="entity">The entity that was saved.</param>
    /// <param name="operation">The operation actually performed (Insert when switched via <c>insertWhenUpdateMissing</c>).</param>
    /// <param name="context">A context for performing DB operations within the same transaction.</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    Task AfterSaveAsync(
        TEntity entity,
        SaveOperation operation,
        ISaveHookContext context,
        CancellationToken cancellationToken = default
    ) => Task.CompletedTask;
}

/// <summary>
/// The context passed to <see cref="ISaveHook{TEntity}.AfterSaveAsync"/> for performing DB operations while participating in
/// the in-progress save transaction.
/// </summary>
/// <remarks>
/// <para>
/// Calling the repository's regular API from inside a hook would use a separate connection and contend for locks, so this
/// contract provides operations that complete within the same transaction. Raw handles (connection, transaction) are not
/// exposed; only typed operations (writing excluded binary columns and raw SQL) are provided (dialect-neutral, misuse-proof).
/// </para>
/// <para>
/// <see cref="WriteBinaryColumnAsync"/> works only for diagrams generated with <c>ExcludeUnboundedBinaryColumns</c> enabled.
/// For diagrams without it, a <see cref="NotSupportedException"/> is thrown (use raw SQL via <see cref="ExecuteSqlAsync"/>,
/// or enable the option).
/// </para>
/// </remarks>
public interface ISaveHookContext
{
    /// <summary>Executes raw SQL (any DML) within the same transaction and returns the number of affected rows.</summary>
    /// <remarks>
    /// Parameter binding is the same as the repository's raw SQL methods (public property name <c>Foo</c> of an anonymous
    /// object is bound as <c>@Foo</c>).
    /// <b>Always pass values as parameters (string concatenation risks injection).</b>
    /// </remarks>
    /// <param name="sql">The DML statement to execute.</param>
    /// <param name="parameters">An anonymous object bound to @name parameters (null for no parameters).</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    Task<int> ExecuteSqlAsync(
        string sql,
        object? parameters = null,
        CancellationToken cancellationToken = default
    );

    /// <summary>
    /// Writes an unbounded binary (excluded) column from a stream, addressed by primary key, within the same transaction
    /// (O(chunk) streaming). When <paramref name="source"/> is <c>null</c>, sets the column to NULL. Returns <c>true</c>
    /// when a row was updated, <c>false</c> when no row matched.
    /// </summary>
    /// <param name="propertyName">The C# property name of the target column (use <c>nameof</c>).</param>
    /// <param name="key">The primary key value of the target row.</param>
    /// <param name="source">The stream to write (<c>null</c> for SET NULL).</param>
    /// <param name="length">The length, required when <c>source.CanSeek</c> is false (omitting it throws <see cref="ArgumentException"/>).</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    Task<bool> WriteBinaryColumnAsync(
        string propertyName,
        object key,
        Stream? source,
        long? length = null,
        CancellationToken cancellationToken = default
    );

    /// <summary>File convenience method that writes a file's contents to an unbounded binary (excluded) column (delegates to <see cref="WriteBinaryColumnAsync"/>).</summary>
    /// <param name="propertyName">The C# property name of the target column (use <c>nameof</c>).</param>
    /// <param name="key">The primary key value of the target row.</param>
    /// <param name="path">The path of the file to read.</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    async Task<bool> WriteBinaryColumnFromFileAsync(
        string propertyName,
        object key,
        string path,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(path);

        await using var stream = File.OpenRead(path);
        return await WriteBinaryColumnAsync(
            propertyName,
            key,
            stream,
            stream.Length,
            cancellationToken
        ).ConfigureAwait(false);
    }
}

/// <summary>A non-generic surface for invoking the save hooks of a specific entity type (across the mixed types of a graph).</summary>
/// <remarks>Calls Before in registration order, short-circuiting on the first <c>false</c>; calls After sequentially in registration order. Built once per type.</remarks>
public interface ISaveHookInvoker
{
    /// <summary>Calls Before in registration order, short-circuiting on the first <c>false</c> (returns false when any hook returns false).</summary>
    Task<bool> InvokeBeforeAsync(
        EntityBaseCore entity,
        SaveOperation operation,
        CancellationToken cancellationToken
    );

    /// <summary>Calls After sequentially in registration order.</summary>
    Task InvokeAfterAsync(
        EntityBaseCore entity,
        SaveOperation operation,
        ISaveHookContext context,
        CancellationToken cancellationToken
    );
}

/// <summary>A registry that resolves the save hook invoker surface (<see cref="ISaveHookInvoker"/>) for an entity type.</summary>
/// <remarks>Returns <c>null</c> for a type with no hooks at all (a complete no-op). Implementations cache resolution results.</remarks>
public interface ISaveHookRegistry
{
    /// <summary>Returns the hook invoker surface for the given entity type (<c>null</c> when there are no hooks).</summary>
    ISaveHookInvoker? GetInvoker(Type entityType);
}

/// <summary>
/// The default <see cref="ISaveHookRegistry"/> implementation, which resolves <c>IEnumerable&lt;ISaveHook&lt;TEntity&gt;&gt;</c>
/// from an <see cref="IServiceProvider"/> and builds the invoker surface (depends only on the BCL <see cref="IServiceProvider"/>).
/// </summary>
/// <remarks>
/// Caches the type-to-invoker mapping <b>per registry instance (Scoped)</b> — not process-static, because hooks may be
/// Scoped services. The invoker surface is created exactly once via <see cref="Type.MakeGenericType"/> on
/// <see cref="SaveHookInvoker{TEntity}"/> plus <see cref="Activator"/> (subsequent calls involve no reflection).
/// </remarks>
internal sealed class ServiceProviderSaveHookRegistry(IServiceProvider serviceProvider)
    : ISaveHookRegistry
{
    private readonly IServiceProvider _serviceProvider = serviceProvider;
    private readonly ConcurrentDictionary<Type, ISaveHookInvoker?> _invokers = new();

    /// <summary>Resolves and caches the invoker surface for the given type (<c>null</c> when there are no hooks).</summary>
    public ISaveHookInvoker? GetInvoker(Type entityType) =>
        _invokers.GetOrAdd(entityType, BuildInvoker);

    /// <summary>Resolves <c>IEnumerable&lt;ISaveHook&lt;entityType&gt;&gt;</c> and builds the invoker surface when at least one hook exists (null otherwise).</summary>
    private ISaveHookInvoker? BuildInvoker(Type entityType)
    {
        var hookType = typeof(ISaveHook<>).MakeGenericType(entityType);
        var enumerableType = typeof(IEnumerable<>).MakeGenericType(hookType);
        var resolved = (System.Collections.IEnumerable?)_serviceProvider.GetService(enumerableType);

        if (resolved is null)
        {
            return null;
        }

        // Null when nothing is registered (a complete no-op even with a registry present). Materialize to fix the count
        var hooks = resolved.Cast<object>().ToList();

        if (hooks.Count == 0)
        {
            return null;
        }

        var invokerType = typeof(SaveHookInvoker<>).MakeGenericType(entityType);
        return (ISaveHookInvoker)Activator.CreateInstance(invokerType, resolved)!;
    }
}

/// <summary>An <see cref="ISaveHookRegistry"/> built from hooks added explicitly, for use without a DI container.</summary>
/// <remarks>
/// The generated repositories take an <see cref="ISaveHookRegistry"/> as a constructor argument, so a repository created
/// with <c>new</c> can be given its hooks without standing up a service provider:
/// <c>new {Entity}Repository(connectionFactory, new SaveHookRegistry().Add(hook))</c>. Hooks run in the order they
/// were added, exactly as with the DI-backed <see cref="ServiceProviderSaveHookRegistry"/>. Building the registry is not
/// thread-safe (add every hook before handing it to a repository); resolution afterwards is read-only.
/// </remarks>
internal sealed class SaveHookRegistry : ISaveHookRegistry
{
    // The value is the List<ISaveHook<TEntity>> for the key type. Add is generic, so the typed list and its invoker are
    // built without reflection; only the storage is type-erased
    private readonly Dictionary<Type, object> _hooks = new();
    private readonly Dictionary<Type, ISaveHookInvoker> _invokers = new();

    /// <summary>Adds a hook for <typeparamref name="TEntity"/> and returns this registry so that calls can be chained.</summary>
    /// <typeparam name="TEntity">The entity type the hook targets.</typeparam>
    /// <param name="hook">The hook to add (hooks for the same type fire in the order they were added).</param>
    public SaveHookRegistry Add<TEntity>(ISaveHook<TEntity> hook)
        where TEntity : EntityBaseCore
    {
        ArgumentNullException.ThrowIfNull(hook);

        if (!_hooks.TryGetValue(typeof(TEntity), out var registered))
        {
            registered = new List<ISaveHook<TEntity>>();
            _hooks[typeof(TEntity)] = registered;
        }

        var hooks = (List<ISaveHook<TEntity>>)registered;
        hooks.Add(hook);

        // Rebuild the invoker so that a hook added after the registry was already used still takes effect
        _invokers[typeof(TEntity)] = new SaveHookInvoker<TEntity>(hooks);
        return this;
    }

    /// <summary>Returns the invoker surface for the given type (<c>null</c> when no hook was added for it).</summary>
    public ISaveHookInvoker? GetInvoker(Type entityType) =>
        _invokers.TryGetValue(entityType, out var invoker) ? invoker : null;
}

/// <summary>Typed implementation that invokes the hooks for <typeparamref name="TEntity"/> in registration order (the concrete <see cref="ISaveHookInvoker"/>).</summary>
/// <typeparam name="TEntity">The entity type the hooks target.</typeparam>
internal sealed class SaveHookInvoker<TEntity>(IEnumerable<ISaveHook<TEntity>> hooks)
    : ISaveHookInvoker
    where TEntity : EntityBaseCore
{
    private readonly IReadOnlyList<ISaveHook<TEntity>> _hooks =
        hooks as IReadOnlyList<ISaveHook<TEntity>> ?? hooks.ToList();

    /// <summary>Calls Before in registration order, short-circuiting on the first <c>false</c>.</summary>
    public async Task<bool> InvokeBeforeAsync(
        EntityBaseCore entity,
        SaveOperation operation,
        CancellationToken cancellationToken
    )
    {
        var typed = (TEntity)entity;

        foreach (var hook in _hooks)
        {
            if (!await hook.BeforeSaveAsync(typed, operation, cancellationToken).ConfigureAwait(false))
            {
                return false;
            }
        }

        return true;
    }

    /// <summary>Calls After sequentially in registration order.</summary>
    public async Task InvokeAfterAsync(
        EntityBaseCore entity,
        SaveOperation operation,
        ISaveHookContext context,
        CancellationToken cancellationToken
    )
    {
        var typed = (TEntity)entity;

        foreach (var hook in _hooks)
        {
            await hook.AfterSaveAsync(typed, operation, context, cancellationToken).ConfigureAwait(false);
        }
    }
}

/// <summary>Helper that unwraps values passed to SQL parameters into raw values (converts value objects to their underlying values, into types SqlClient can handle).</summary>
internal static class SqlParameterValue
{
    /// <summary>Returns the underlying value for a value object; returns anything else as is.</summary>
    public static object? Unwrap(object? value) =>
        value is IValueObjectCore valueObject ? valueObject.UnderlyingValue : value;
}

/// <summary>Reverse-conversion helper that rewraps raw values read from the DB via Create when the target property is a value object type (the counterpart of Unwrap).</summary>
internal static class SqlValueObjectActivator
{
    /// <summary>Caches the raw-value-to-value-object converter resolved per property type (null for non-VO types).</summary>
    private static readonly ConcurrentDictionary<Type, Func<object, object>?> _factoryCache = new();

    /// <summary>Wraps the raw value via Create when the target type is a value object; returns anything else as is.</summary>
    public static object? Wrap(object? value, Type targetType)
    {
        if (value is null)
        {
            return null;
        }

        var factory = _factoryCache.GetOrAdd(targetType, ResolveFactory);
        return factory is null ? value : factory(value);
    }

    /// <summary>Resolves TValue and Create(TValue) from the target type's IValueObject&lt;,&gt; and builds the converter (null when not a VO).</summary>
    private static Func<object, object>? ResolveFactory(Type targetType)
    {
        var iface = Array.Find(
            targetType.GetInterfaces(),
            i => i.IsGenericType && i.GetGenericTypeDefinition() == typeof(IValueObject<,>)
        );
        if (iface is null)
        {
            return null;
        }

        var valueType = iface.GetGenericArguments()[1];

        // FlattenHierarchy: without it reflection never returns a static member declared on a base class, and Create
        // lives on ValueObjectBaseCore (a hand-written value object inheriting it included). A same-signature Create declared
        // on the type itself still wins (hide-by-signature), with no AmbiguousMatchException.
        var createMethod = targetType.GetMethod(
            "Create",
            BindingFlags.Public | BindingFlags.Static | BindingFlags.FlattenHierarchy,
            binder: null,
            new[] { valueType },
            modifiers: null
        );
        if (createMethod is null)
        {
            return null;
        }

        // Compile the call to Create once per target type. Invoking it reflectively instead would re-dispatch and allocate a
        // one-element object[] for every value read out of every row; the compiled delegate does neither. A validation
        // failure inside Create surfaces as itself here as well - an expression-tree call never wraps anything in a
        // TargetInvocationException - so the caller can still add the column context and keep the original as the inner one.
        var rawParameter = Expression.Parameter(typeof(object), "raw");
        var invoker = Expression
            .Lambda<Func<object, object>>(
                Expression.Convert(
                    Expression.Call(createMethod, Expression.Convert(rawParameter, valueType)),
                    typeof(object)
                ),
                rawParameter
            )
            .Compile();

        return raw =>
        {
            // Convert only when the raw type returned by the DB differs from TValue. The shared converter also covers the
            // underlying types Convert.ChangeType cannot reach (TimeSpan/Guid/DateTimeOffset and friends), which a driver
            // that returns them as text - SQLite - would otherwise fail on for every row
            var converted = RawValueConverter.ConvertRaw(raw, valueType);

            return invoker(converted);
        };
    }
}

/// <summary>
/// Shared helper responsible for raw SQL binding, scalar conversion, and projection mapping (a single implementation shared
/// by QuickER's SQL Server implementation and the EF Core executor).
/// </summary>
/// <remarks>
/// Works only with the provider-agnostic <see cref="DbCommand"/> / <see cref="DbDataReader"/> and does not depend on any
/// specific DB client. Even in EF Core-only output (configurations without QuickER's SQL Server implementation), this class
/// is emitted as a shared contract and the EF Core executor calls it.
/// </remarks>
internal static class RawSqlMapper
{
    /// <summary>Caches the reflected properties of raw SQL parameter objects per type (the single binding implementation).</summary>
    private static readonly ConcurrentDictionary<Type, PropertyInfo[]> _parameterPropertyCache =
        new();

    /// <summary>Resolves the bindable properties (public instance, readable, non-indexer) of an anonymous object or similar (cached per type).</summary>
    internal static PropertyInfo[] GetBindableProperties(Type type) =>
        _parameterPropertyCache.GetOrAdd(
            type,
            static t =>
                t.GetProperties(BindingFlags.Public | BindingFlags.Instance)
                    .Where(property => property.CanRead && property.GetIndexParameters().Length == 0)
                    .ToArray()
        );

    /// <summary>
    /// Provider-agnostic <see cref="DbCommand"/> parameter binding. Binds public property name <c>Foo</c> of an anonymous
    /// object as SQL parameter <c>@Foo</c> without an explicit type (raw SQL has no column context). Does nothing when null.
    /// </summary>
    internal static void BindParameters(DbCommand command, object? parameters)
    {
        if (parameters is null)
        {
            return;
        }

        foreach (var property in GetBindableProperties(parameters.GetType()))
        {
            var value =
                SqlParameterValue.Unwrap(property.GetValue(parameters));

            // Collection values (for IN) are expanded and bound as @name0, @name1, ... (the @name in the SQL is rewritten too)
            if (IsCollectionParameter(value))
            {
                BindCollectionParameter(command, property.Name, (System.Collections.IEnumerable)value!);
                continue;
            }

            var parameter = command.CreateParameter();
            parameter.ParameterName = $"@{property.Name}";
            parameter.Value = value ?? DBNull.Value;
            command.Parameters.Add(parameter);
        }
    }

    /// <summary>Whether the value is a collection subject to IN expansion (string / byte[] are treated as single values).</summary>
    internal static bool IsCollectionParameter(object? value) =>
        value is System.Collections.IEnumerable && value is not string && value is not byte[];

    /// <summary>
    /// Expands and binds a collection-valued parameter for IN. Rewrites <c>@name</c> in the SQL to per-element
    /// <c>@name0, @name1, ...</c> and adds each element as an individual parameter.
    /// </summary>
    /// <remarks>
    /// <para>
    /// Reference it inside parentheses in the SQL, as in <c>IN (@name)</c>. An empty collection expands to a single
    /// <c>NULL</c> (<c>IN (NULL)</c>) and matches no rows (following SQL's three-valued logic). That is the right answer
    /// for <c>IN</c>, but <c>NOT IN (NULL)</c> is UNKNOWN for every row and therefore matches nothing either - branch to a
    /// different statement when the collection can be empty and the negated form is what you need.
    /// </para>
    /// <para>
    /// The rewrite is textual, so it replaces <c>@name</c> anywhere in the command text - including inside a string
    /// literal or a comment. Do not write the parameter's own name in those places. Names that merely start the same
    /// (<c>@nameSuffix</c>, <c>@name0</c>) and system variables that merely end the same (<c>@@name</c>) are left alone.
    /// </para>
    /// </remarks>
    internal static void BindCollectionParameter(
        DbCommand command,
        string name,
        System.Collections.IEnumerable values
    )
    {
        var names = new List<string>();

        foreach (var item in values)
        {
            var value = SqlParameterValue.Unwrap(item);
            var parameter = command.CreateParameter();
            parameter.ParameterName = $"@{name}{names.Count}";
            parameter.Value = value ?? DBNull.Value;
            command.Parameters.Add(parameter);
            names.Add(parameter.ParameterName);
        }

        // When an identifier character follows @name (as in @name0 or @nameX) it is a different parameter, so do not rewrite it.
        // The same holds on the left: an identifier character or a second @ in front (@@name, a system variable) means a different token
        command.CommandText = Regex.Replace(
            command.CommandText,
            $"(?<![@0-9A-Za-z_])@{Regex.Escape(name)}(?![0-9A-Za-z_])",
            names.Count == 0 ? "NULL" : string.Join(", ", names)
        );
    }

    /// <summary>
    /// Reads the full result set, leniently projecting it onto <typeparamref name="TResult"/> (the single implementation of
    /// single-value mode and DTO mode). Takes a provider-agnostic <see cref="DbDataReader"/>, so the QuickER and EF Core
    /// executors share the mapping implementation.
    /// </summary>
    internal static async Task<IReadOnlyList<TResult>> ReadProjectionRowsAsync<TResult>(
        DbDataReader reader,
        CancellationToken cancellationToken
    )
    {
        var resultType = typeof(TResult);
        var items = new List<TResult>();

        // Single-value mode (primitive/enum/string/decimal/date-time/Guid/byte[]/value object) converts and returns the first column of each row
        if (IsSingleValueType(resultType))
        {
            while (await reader.ReadAsync(cancellationToken).ConfigureAwait(false))
            {
                var raw = reader.IsDBNull(0) ? null : reader.GetValue(0);
                // Single-value mode allows DBNull → default (may be null for reference types, but projections carry no corruption risk)
                items.Add(ConvertSingleValue<TResult>(raw)!);
            }

            return items;
        }

        // DTO mode: cache the per-type resolver (column name → property setter) and match by column name per result set
        var accessor = _projectionAccessorCache.GetOrAdd(resultType, BuildProjectionAccessor);

        // Match result set column names to setters (matching properties only). If no column matches, throw via the typo guard
        var setters = new Action<object, object?>?[reader.FieldCount];
        var matched = false;
        for (var i = 0; i < reader.FieldCount; i++)
        {
            if (accessor.SettersByColumn.TryGetValue(reader.GetName(i), out var setter))
            {
                setters[i] = setter;
                matched = true;
            }
        }

        if (!matched)
        {
            var columnNames = new string[reader.FieldCount];
            for (var i = 0; i < reader.FieldCount; i++)
            {
                columnNames[i] = reader.GetName(i);
            }

            throw new InvalidOperationException(
                $"No column in the result set matches a writable property of projection target {resultType.Name}. "
                    + $"Result set columns: [{string.Join(", ", columnNames)}]. "
                    + $"Properties of {resultType.Name}: [{string.Join(", ", accessor.SettersByColumn.Keys)}]. "
                    + "Check the SELECT aliases (AS) and property name spellings (matching is case-insensitive)."
            );
        }

        while (await reader.ReadAsync(cancellationToken).ConfigureAwait(false))
        {
            var result = accessor.Create();
            for (var i = 0; i < setters.Length; i++)
            {
                var setter = setters[i];
                if (setter is null)
                {
                    continue;
                }

                var raw = reader.IsDBNull(i) ? null : reader.GetValue(i);
                setter(result!, raw);
            }

            items.Add((TResult)result!);
        }

        return items;
    }

    /// <summary>Value conversion shared by the scalar and single-value modes (DBNull/null becomes default; best-effort conversion via Nullable-aware ChangeType).</summary>
    internal static TResult? ConvertSingleValue<TResult>(object? raw)
    {
        if (raw is null)
        {
            return default;
        }

        if (raw is TResult typed)
        {
            return typed;
        }

        // Wrap the raw value via Create for value objects. When TResult is Nullable<T>, convert to the underlying type (ChangeType cannot handle Nullable directly)
        var targetType = Nullable.GetUnderlyingType(typeof(TResult)) ?? typeof(TResult);
        if (typeof(IValueObjectCore).IsAssignableFrom(targetType))
        {
            try
            {
                return (TResult?)SqlValueObjectActivator.Wrap(raw, targetType);
            }
            catch (Exception ex) when (ex is not OperationCanceledException)
            {
                // Name the target value object: without it the failure only says the value was rejected, not what it was being read into
                throw new InvalidOperationException(
                    $"The raw SQL result value (of type {raw.GetType().Name}) could not be converted to the value object {targetType.Name}: {ex.Message}",
                    ex
                );
            }
        }

        try
        {
            return (TResult)RawValueConverter.ConvertRaw(raw, targetType);
        }
        catch (Exception ex)
            when (ex is InvalidCastException or FormatException or OverflowException)
        {
            throw new InvalidOperationException(
                $"Could not convert the raw SQL result value (of type {raw.GetType().Name}) to {typeof(TResult).Name}.",
                ex
            );
        }
    }

    /// <summary>Whether the type is handled in single-value mode (primitive/enum/string/decimal/date-time/Guid/byte[]/value object; Nullable is judged by its underlying type).</summary>
    private static bool IsSingleValueType(Type type)
    {
        var actual = Nullable.GetUnderlyingType(type) ?? type;
        if (typeof(IValueObjectCore).IsAssignableFrom(actual))
        {
            return true;
        }

        return actual.IsPrimitive
            || actual.IsEnum
            || actual == typeof(string)
            || actual == typeof(decimal)
            || actual == typeof(DateTime)
            || actual == typeof(DateTimeOffset)
            || actual == typeof(TimeSpan)
            || actual == typeof(Guid)
            || actual == typeof(byte[]);
    }

    /// <summary>Resolver holding a projection DTO's factory function and its column-name (case-insensitive) to property-setter map.</summary>
    private sealed record ProjectionAccessor(
        Func<object> Create,
        IReadOnlyDictionary<string, Action<object, object?>> SettersByColumn
    );

    /// <summary>Caches the resolver per projection target type (the column-to-property matching itself happens per result set).</summary>
    private static readonly ConcurrentDictionary<Type, ProjectionAccessor> _projectionAccessorCache =
        new();

    /// <summary>Builds the factory function and the property-name-to-setter map from the projection target type (parameterless constructor required; writable properties only).</summary>
    private static ProjectionAccessor BuildProjectionAccessor(Type resultType)
    {
        var constructor = resultType.GetConstructor(Type.EmptyTypes);
        if (constructor is null)
        {
            throw new InvalidOperationException(
                $"Projection target {resultType.Name} cannot be used with QueryProjectionBySqlAsync. "
                    + "Specify a type with a public parameterless constructor (positional records are not supported)."
            );
        }

        // Init-only properties can also be set via PropertyInfo.SetValue, so include any property with a SetMethod, whether set or init
        var setters = new Dictionary<string, Action<object, object?>>(StringComparer.OrdinalIgnoreCase);
        foreach (
            var property in resultType.GetProperties(BindingFlags.Public | BindingFlags.Instance)
        )
        {
            if (
                property.SetMethod is null
                || property.GetIndexParameters().Length != 0
            )
            {
                continue;
            }

            // The raw type returned by the driver differs by dialect (e.g. SQLite's INTEGER is long),
            // so coerce to the property's underlying type (Nullable uses its underlying type) before setting
            var underlyingType =
                Nullable.GetUnderlyingType(property.PropertyType) ?? property.PropertyType;
            var propertyName = property.Name;
            setters[property.Name] = (target, raw) =>
                property.SetValue(
                    target,
                    raw is null ? null : CoerceProjectionValue(raw, underlyingType, propertyName)
                );
        }

        return new ProjectionAccessor(() => constructor.Invoke(null), setters);
    }

    /// <summary>Coerces a value being assigned to a projection DTO property to the underlying type (same semantics as the scalar conversion ConvertSingleValue).</summary>
    /// <remarks>
    /// The failures name the property being filled: a projection has as many of them as it has columns, and without the name the
    /// message says only that some value of some type was rejected, leaving the reader to guess which column it came from.
    /// </remarks>
    /// <param name="raw">The value the driver returned.</param>
    /// <param name="underlyingType">The property's type (a nullable property's underlying type).</param>
    /// <param name="propertyName">The projection property being filled (used in the failure messages).</param>
    private static object CoerceProjectionValue(
        object raw,
        Type underlyingType,
        string propertyName
    )
    {
        // Wrap the raw value via Create for value objects
        if (typeof(IValueObjectCore).IsAssignableFrom(underlyingType))
        {
            try
            {
                return SqlValueObjectActivator.Wrap(raw, underlyingType)!;
            }
            catch (Exception ex) when (ex is not OperationCanceledException)
            {
                throw new InvalidOperationException(
                    $"The raw SQL projection value for '{propertyName}' (of type {raw.GetType().Name}) could not be converted to the value object {underlyingType.Name}: {ex.Message}",
                    ex
                );
            }
        }

        try
        {
            return RawValueConverter.ConvertRaw(raw, underlyingType);
        }
        catch (Exception ex)
            when (ex is InvalidCastException or FormatException or OverflowException)
        {
            throw new InvalidOperationException(
                $"Could not convert the raw SQL projection value for '{propertyName}' (of type {raw.GetType().Name}) to {underlyingType.Name}.",
                ex
            );
        }
    }
}

/// <summary>A single ordering for SqlQuery (a key selector and a descending flag). Captured as an expression tree and translated to a column name / SQL by the executor.</summary>
/// <param name="KeySelector">The key-selecting lambda expression (may include boxing to object?; the executor strips it).</param>
/// <param name="Descending">Whether the ordering is descending.</param>
internal readonly record struct SqlQueryOrdering(LambdaExpression KeySelector, bool Descending);

/// <summary>
/// A dialect-neutral snapshot (composed only of BCL types) that hands what a SqlQuery has accumulated
/// (Where expressions, orderings, Include tree, paging) to an executor.
/// </summary>
/// <remarks>
/// Predicates and orderings are kept as expression trees; translation to SQL (dialect differences such as
/// identifier quoting, date parts, and LIKE) and execution are the responsibility of each backend's
/// <see cref="ISqlQueryExecutor{TEntity}"/> implementation (the per-dialect ADO executor and the EF Core executor).
/// </remarks>
/// <param name="Predicates">The predicate expressions captured by Where (combined with AND).</param>
/// <param name="Orderings">The orderings captured by OrderBy / OrderByDescending (in the specified order).</param>
/// <param name="Includes">The navigation tree from Include / ThenInclude.</param>
/// <param name="Take">The maximum number of rows to fetch (null when unspecified).</param>
/// <param name="Skip">The number of rows to skip (null when unspecified).</param>
/// <param name="WithUnboundedBinary">Whether to fetch including unbounded binary columns (true means an all-column plain SELECT; cannot be combined with Include).</param>
internal sealed record SqlQueryPlan<TEntity>(
    IReadOnlyList<LambdaExpression> Predicates,
    IReadOnlyList<SqlQueryOrdering> Orderings,
    IReadOnlyList<IncludeNode> Includes,
    int? Take,
    int? Skip,
    bool WithUnboundedBinary
);

/// <summary>
/// The internal abstraction that swaps out execution of SqlQuery's terminal methods. Each backend
/// (the per-dialect ADO executor and the EF Core variant) implements it and is injected into SqlQuery
/// via the constructor. SqlQuery itself holds no dialect SQL and delegates the captured plan
/// (expression trees, Include, paging) to this executor.
/// </summary>
internal interface ISqlQueryExecutor<TEntity>
    where TEntity : class
{
    /// <summary>Fetches the entities matching the conditions (together with the requested Includes) as a list.</summary>
    Task<IReadOnlyList<TEntity>> ToListAsync(
        SqlQueryPlan<TEntity> plan,
        CancellationToken cancellationToken
    );

    /// <summary>Fetches the entities matching the conditions with a projection (pruning columns server-side when the backend supports it).</summary>
    Task<IReadOnlyList<TResult>> ToProjectionListAsync<TResult>(
        SqlQueryPlan<TEntity> plan,
        Expression<Func<TEntity, TResult>> selector,
        CancellationToken cancellationToken
    );

    /// <summary>Fetches the first entity matching the conditions (together with the requested Includes); returns null when there is no match.</summary>
    Task<TEntity?> FirstOrDefaultAsync(
        SqlQueryPlan<TEntity> plan,
        CancellationToken cancellationToken
    );

    /// <summary>Returns the count of rows matching the conditions (orderings, paging, and Include are not involved).</summary>
    Task<int> CountAsync(SqlQueryPlan<TEntity> plan, CancellationToken cancellationToken);

    /// <summary>Returns whether any record matching the conditions exists (orderings, paging, and Include are not involved).</summary>
    Task<bool> AnyAsync(SqlQueryPlan<TEntity> plan, CancellationToken cancellationToken);

    /// <summary>Bulk-deletes the rows matching the conditions. When cascadeDelete=true, descendants are also deleted along FK chains.</summary>
    Task<int> ExecuteDeleteAsync(
        SqlQueryPlan<TEntity> plan,
        bool cascadeDelete,
        CancellationToken cancellationToken
    );
}

/// <summary>
/// An expression-tree visitor that walks a projection selector (<c>v =&gt; new Dto { ... v.Prop ... }</c>) and determines
/// both "the set of referenced column property names" and "whether the projection can be safely reconstructed from that
/// set alone (i.e. whether server-side column pruning is possible)".
/// </summary>
/// <remarks>
/// If the lambda parameter (the target entity) appears anywhere other than a "direct member reference (<c>v.Prop</c>)",
/// extraction is treated as impossible (referencing <c>v</c> as a whole, a method call that takes the entity as an argument
/// or receiver, a multi-hop navigation reference, and so on). Whether each collected name is actually a column property
/// (rather than a navigation) is reconciled by the caller (each executor) via <c>EntitySaveMetadata.ResolveProjectionColumns</c>
/// (not referenced with cref because EntitySaveMetadata is not co-located in configurations that include only this class).
/// When extraction is impossible, the executor falls back to fetching all columns and projecting in memory.
/// </remarks>
internal sealed class ProjectionColumnCollector : ExpressionVisitor
{
    private readonly ParameterExpression _parameter;
    private readonly HashSet<string> _members = new(StringComparer.Ordinal);
    private bool _extractable = true;

    private ProjectionColumnCollector(ParameterExpression parameter) => _parameter = parameter;

    /// <summary>
    /// Collects the direct member names referenced by the selector. Returns true plus the set of referenced names when
    /// extraction succeeded from column references alone, and false when extraction is impossible (whole reference, method call, etc.).
    /// </summary>
    public static bool TryCollect<TEntity, TResult>(
        Expression<Func<TEntity, TResult>> selector,
        out IReadOnlyCollection<string> referencedProperties
    )
    {
        // Only handle lambdas with a single parameter (one target entity)
        if (selector.Parameters.Count != 1)
        {
            referencedProperties = Array.Empty<string>();
            return false;
        }

        var collector = new ProjectionColumnCollector(selector.Parameters[0]);
        collector.Visit(selector.Body);
        referencedProperties = collector._members;
        return collector._extractable;
    }

    /// <summary>Visits a member reference. When the receiver is directly the lambda parameter (<c>v.Prop</c>), collects the name and does not descend inside.</summary>
    protected override Expression VisitMember(MemberExpression node)
    {
        if (node.Expression == _parameter && node.Member is PropertyInfo property)
        {
            // The v.Prop shape. Collect only the name as a column-reference candidate and avoid visiting the inner parameter (which would count as a whole reference).
            _members.Add(property.Name);
            return node;
        }

        return base.VisitMember(node);
    }

    /// <summary>Visits the lambda parameter. Appearing anywhere other than directly above a member reference means a whole reference, so extraction is treated as impossible.</summary>
    protected override Expression VisitParameter(ParameterExpression node)
    {
        if (node == _parameter)
        {
            _extractable = false;
        }

        return node;
    }
}

/// <summary>Validates the string-matching calls (Contains / StartsWith / EndsWith) inside a query predicate and rejects a null pattern argument up front.</summary>
/// <remarks>
/// Dialects and backends disagreed on what a null pattern means (match-all, no-match, or an exception), so the guard unifies
/// them to fail fast. Every backend (the per-dialect ADO executor, EF Core, and the in-memory store) and every generated
/// named query builds its predicates through <see cref="SqlQuery{TEntity}.Where"/>, which makes this the single enforcement point.
/// </remarks>
internal static class QueryStringMatchGuard
{
    /// <summary>Walks a predicate body and throws when a column-side string match is given a null pattern.</summary>
    public static void Validate(Expression predicateBody) =>
        new NullPatternVisitor().Visit(predicateBody);

    /// <summary>The visitor that inspects every method call in the predicate body.</summary>
    private sealed class NullPatternVisitor : ExpressionVisitor
    {
        /// <summary>Checks a string-matching call whose receiver is a column and whose argument is a value, then descends as usual.</summary>
        protected override Expression VisitMethodCall(MethodCallExpression node)
        {
            if (
                IsStringMatch(node)
                // The receiver must be the column side (it references the lambda parameter) and the argument the value side (it does not)
                && ReferencesParameter(node.Object!)
                && !ReferencesParameter(node.Arguments[0])
                && Evaluate(node.Arguments[0]) is null
            )
            {
                throw new ArgumentNullException(
                    "value",
                    "The pattern argument of Contains/StartsWith/EndsWith in a query predicate must not be null."
                );
            }

            return base.VisitMethodCall(node);
        }
    }

    /// <summary>Determines whether the call is a single-argument string match on string or on a string value object.</summary>
    private static bool IsStringMatch(MethodCallExpression call) =>
        call.Object is not null
        && call.Arguments.Count == 1
        && call.Method.Name is "Contains" or "StartsWith" or "EndsWith"
        && (
            call.Method.DeclaringType == typeof(string)
            || IsValueObjectStringMethod(call.Method)
        );

    /// <summary>Whether the method is one of the substring matches a string value object declares.</summary>
    /// <remarks>
    /// The judgement goes through the interface map of <see cref="IStringMatchValueObject{TSelf}"/>, so only the type that
    /// actually implements those members qualifies. Testing the name against a type that merely implements the interface
    /// would also claim a <c>Contains</c> a concrete value object declares for itself, which is an ordinary method call
    /// rather than a column-side match.
    /// </remarks>
    private static bool IsValueObjectStringMethod(MethodInfo method) =>
        StringMatchMethodCache.GetOrAdd(
            method,
            static m =>
            {
                if (m.DeclaringType is not { IsInterface: false } declaring)
                {
                    return false;
                }

                var contract = Array.Find(
                    declaring.GetInterfaces(),
                    i =>
                        i.IsGenericType
                        && i.GetGenericTypeDefinition() == typeof(IStringMatchValueObject<>)
                );

                return contract is not null
                    && Array.IndexOf(declaring.GetInterfaceMap(contract).TargetMethods, m) >= 0;
            }
        );

    /// <summary>Cache of the judgement per method: the interface probe allocates, and expression translation asks for the same methods repeatedly.</summary>
    private static readonly ConcurrentDictionary<MethodInfo, bool> StringMatchMethodCache = new();

    /// <summary>Walks the expression tree to determine whether it references a lambda parameter (i.e. an entity column).</summary>
    private static bool ReferencesParameter(Expression expression)
    {
        var finder = new ParameterFinder();
        finder.Visit(expression);
        return finder.Found;
    }

    /// <summary>
    /// Evaluates a value-side argument (a constant or a captured variable) to obtain the actual value. Constants and closure
    /// field / property references are read directly, avoiding (expensive) expression-tree compilation; anything else falls back to compiling.
    /// </summary>
    private static object? Evaluate(Expression expression)
    {
        switch (expression)
        {
            case ConstantExpression constant:
                return constant.Value;

            case MemberExpression member:
                var instance = member.Expression is null ? null : Evaluate(member.Expression);

                return member.Member switch
                {
                    FieldInfo field => field.GetValue(instance),
                    PropertyInfo property => property.GetValue(instance),
                    _ => CompileAndInvoke(expression),
                };

            default:
                return CompileAndInvoke(expression);
        }
    }

    /// <summary>Compiles an expression as a <c>Func&lt;object&gt;</c> and invokes it (avoiding the reflection-based DynamicInvoke and its exception wrapping).</summary>
    private static object? CompileAndInvoke(Expression expression) =>
        Expression.Lambda<Func<object?>>(Expression.Convert(expression, typeof(object)))
            .Compile()();

    /// <summary>A lightweight visitor that merely raises a flag when it finds a lambda-parameter reference.</summary>
    private sealed class ParameterFinder : ExpressionVisitor
    {
        public bool Found { get; private set; }

        protected override Expression VisitParameter(ParameterExpression node)
        {
            Found = true;
            return node;
        }
    }
}

/// <summary>A query built up by chaining conditions, orderings, and Includes, then executed by a terminal method (ToListAsync, etc.).</summary>
/// <remarks>
/// Predicates, orderings, and Includes are captured as lambda expressions (expression trees); translation to SQL and
/// execution are delegated to the injected <see cref="ISqlQueryExecutor{TEntity}"/> implementation (the per-dialect ADO
/// executor or the EF Core executor). SqlQuery itself holds no dialect SQL at all (dialect differences stay inside the executor).
/// </remarks>
public sealed class SqlQuery<TEntity>
    where TEntity : class
{
    private readonly List<IncludeNode> _includes = new();
    private int? _take;
    private int? _skip;

    /// <summary>The WithUnboundedBinary flag (true fetches all columns including unbounded binary columns; cannot be combined with Include).</summary>
    private bool _withUnboundedBinary;

    /// <summary>The backend executor that runs the terminal methods (per-dialect ADO or EF Core).</summary>
    private readonly ISqlQueryExecutor<TEntity> _executor;

    /// <summary>The captured Where expressions (kept as expression trees without translating; the executor translates them to SQL / LINQ).</summary>
    private readonly List<LambdaExpression> _predicates = new();

    /// <summary>The captured orderings (a key selector and a descending flag).</summary>
    private readonly List<SqlQueryOrdering> _orderSelectors = new();

    /// <summary>Internal constructor that injects the backend executor.</summary>
    internal SqlQuery(ISqlQueryExecutor<TEntity> executor) => _executor = executor;

    /// <summary>Adds a search condition (multiple conditions are combined with AND).</summary>
    public SqlQuery<TEntity> Where(Expression<Func<TEntity, bool>> predicate)
    {
        ArgumentNullException.ThrowIfNull(predicate);
        // Reject a null Contains/StartsWith/EndsWith pattern here so that every backend behaves the same way
        QueryStringMatchGuard.Validate(predicate.Body);
        // Capture as an expression tree and leave translation to SQL / LINQ to the executor
        _predicates.Add(predicate);
        return this;
    }

    /// <summary>Adds an ascending ordering.</summary>
    public SqlQuery<TEntity> OrderBy(Expression<Func<TEntity, object?>> keySelector)
    {
        _orderSelectors.Add(new SqlQueryOrdering(keySelector, Descending: false));
        return this;
    }

    /// <summary>Adds a descending ordering.</summary>
    public SqlQuery<TEntity> OrderByDescending(Expression<Func<TEntity, object?>> keySelector)
    {
        _orderSelectors.Add(new SqlQueryOrdering(keySelector, Descending: true));
        return this;
    }

    /// <summary>Sets the maximum number of rows to fetch (must be greater than zero).</summary>
    public SqlQuery<TEntity> Take(int count)
    {
        // Zero and negative values are rejected up front: dialects disagree on what they mean (SQL Server requires a fetch count greater than zero
        // while SQLite treats a negative LIMIT as "no limit"), and fetching zero rows has no meaningful use (skip the query instead).
        if (count <= 0)
        {
            throw new ArgumentOutOfRangeException(
                nameof(count),
                "The number of rows to fetch must be greater than zero."
            );
        }

        _take = count;
        return this;
    }

    /// <summary>Sets the number of leading rows to skip.</summary>
    public SqlQuery<TEntity> Skip(int count)
    {
        // Negative values are rejected up front: dialects disagree on what they mean (SQL Server raises an error, SQLite clamps a negative OFFSET to zero).
        if (count < 0)
        {
            throw new ArgumentOutOfRangeException(
                nameof(count),
                "The number of rows to skip must not be negative."
            );
        }

        _skip = count;
        return this;
    }

    /// <summary>
    /// Fetches entities including unbounded binary columns (those marked with <c>UnboundedBinaryColumnAttribute</c>). Use it when you want to
    /// fetch, for this call only, the columns that ExcludeUnboundedBinaryColumns has dropped from the default SELECT (a no-op when there are no excluded columns).
    /// </summary>
    /// <remarks>
    /// Cannot be combined with Include (an <see cref="InvalidOperationException"/> is thrown when the terminal method runs). When unbounded binary
    /// columns are needed, fetch them with a separate query that has no Include. On SQL Server this uses a plain SELECT (not the default JSON path),
    /// avoiding the Base64 inflation of large blobs (5-6x peak memory). It takes effect on the entity-shaped fetches (ToListAsync /
    /// FirstOrDefaultAsync) and on the fallback path of a projection, where the entity is materialized in full before the selector runs
    /// (it does not affect counts, existence checks, or a projection whose columns are pruned). The fetched entities are equivalent to a normal fetch (RowState=Unchanged), but
    /// because excluded columns remain outside the UPDATE set, calling UpdateAsync on them as-is throws via the existing guard (perform updates with raw SQL).
    /// </remarks>
    public SqlQuery<TEntity> WithUnboundedBinary()
    {
        _withUnboundedBinary = true;
        return this;
    }

    /// <summary>Eagerly fetches a single-reference navigation (ThenInclude allows specifying multiple levels).</summary>
    /// <remarks>Including a navigation that is already there returns the node it already has, so Include(A).ThenInclude(B) followed by Include(A).ThenInclude(C) branches one node instead of adding a second one.</remarks>
    public IncludableSqlQuery<TEntity, TProperty> Include<TProperty>(
        Expression<Func<TEntity, TProperty>> navigationSelector
    )
    {
        var node = MergeInclude(_includes, IncludeNode.GetProperty(navigationSelector));
        return new IncludableSqlQuery<TEntity, TProperty>(this, node);
    }

    /// <summary>Eagerly fetches a collection navigation (ThenInclude allows specifying multiple levels).</summary>
    /// <remarks>Including a navigation that is already there returns the node it already has, so Include(A).ThenInclude(B) followed by Include(A).ThenInclude(C) branches one node instead of adding a second one.</remarks>
    public IncludableSqlQuery<TEntity, TElement> Include<TElement>(
        Expression<Func<TEntity, ICollection<TElement>>> navigationSelector
    )
    {
        var node = MergeInclude(_includes, IncludeNode.GetProperty(navigationSelector));
        return new IncludableSqlQuery<TEntity, TElement>(this, node);
    }

    /// <summary>Adds an already built Include tree (the entry point the generated IncludeGraph extensions use).</summary>
    /// <remarks>
    /// The nodes are copied, so the tree handed over here is never modified: the generated extensions build one tree
    /// per entity type and share it across every query, and a ThenInclude written after IncludeGraph must not reach
    /// back into that shared tree. A navigation that is already there is merged into the node it already has instead
    /// of being added twice. Write Include/ThenInclude instead when composing an Include tree by hand.
    /// </remarks>
    internal SqlQuery<TEntity> AddIncludeNodes(IReadOnlyList<IncludeNode> nodes)
    {
        ArgumentNullException.ThrowIfNull(nodes);
        CopyIncludeNodes(nodes, _includes);
        return this;
    }

    /// <summary>Returns the node for the navigation in the given list, adding a new one only when the navigation is not there yet.</summary>
    /// <remarks>
    /// Include / ThenInclude keep one node per navigation because every backend binds a fetched child by replacing the
    /// navigation's value: a second node for the same navigation would silently overwrite what the first one loaded
    /// (and on SQL Server the two would collide as identically named JSON properties).
    /// </remarks>
    internal static IncludeNode MergeInclude(List<IncludeNode> nodes, PropertyInfo property)
    {
        foreach (var existing in nodes)
        {
            if (IsSameNavigation(existing.Property, property))
            {
                return existing;
            }
        }

        var node = new IncludeNode(property);
        nodes.Add(node);
        return node;
    }

    /// <summary>Copies an Include tree into the destination list, merging every navigation into the node it already has.</summary>
    private static void CopyIncludeNodes(
        IReadOnlyList<IncludeNode> source,
        List<IncludeNode> destination
    )
    {
        foreach (var node in source)
        {
            CopyIncludeNodes(node.Children, MergeInclude(destination, node.Property).Children);
        }
    }

    /// <summary>Whether two properties denote the same navigation (reflection may hand back different PropertyInfo instances for one property).</summary>
    private static bool IsSameNavigation(PropertyInfo left, PropertyInfo right) =>
        left == right || (left.Name == right.Name && left.DeclaringType == right.DeclaringType);

    /// <summary>Fetches the entities matching the conditions (together with the requested Includes) as a list.</summary>
    public async Task<IReadOnlyList<TEntity>> ToListAsync(
        CancellationToken cancellationToken = default
    ) => await _executor.ToListAsync(BuildPlan(), cancellationToken).ConfigureAwait(false);

    /// <summary>Fetches the first entity matching the conditions (together with the requested Includes); returns null when there is no match.</summary>
    public async Task<TEntity?> FirstOrDefaultAsync(CancellationToken cancellationToken = default) =>
        await _executor.FirstOrDefaultAsync(BuildPlan(), cancellationToken).ConfigureAwait(false);

    /// <summary>Returns the count of rows matching the conditions.</summary>
    public async Task<int> CountAsync(CancellationToken cancellationToken = default) =>
        await _executor.CountAsync(BuildPlan(), cancellationToken).ConfigureAwait(false);

    /// <summary>Returns whether any record matching the conditions exists.</summary>
    public async Task<bool> AnyAsync(CancellationToken cancellationToken = default) =>
        await _executor.AnyAsync(BuildPlan(), cancellationToken).ConfigureAwait(false);

    /// <summary>Fetches the entities matching the conditions and returns them as a list transformed by the given projection (for named-query projections).</summary>
    /// <remarks>
    /// Conditions, orderings, and paging are applied on the backend side (dialect SQL / EF Core / in-memory).
    /// The projected columns are pruned server-side when the selector references only column properties (with no Include) and the backend supports it
    /// (narrowing the SELECTed columns, the EF Core projection, and the in-memory copy to the referenced columns). When Include is combined or column
    /// references cannot be safely extracted from the selector, all columns are fetched and the projection is applied in memory.
    /// </remarks>
    /// <param name="selector">The expression that transforms an entity into a projection DTO.</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    public async Task<IReadOnlyList<TResult>> ToProjectionListAsync<TResult>(
        Expression<Func<TEntity, TResult>> selector,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(selector);

        return await _executor.ToProjectionListAsync(BuildPlan(), selector, cancellationToken).ConfigureAwait(false);
    }

    /// <summary>Bulk-deletes the rows matching the conditions. When cascadeDelete=true, descendants are also deleted along FK chains.</summary>
    public async Task<int> ExecuteDeleteAsync(
        bool cascadeDelete = false,
        CancellationToken cancellationToken = default
    ) => await _executor.ExecuteDeleteAsync(BuildPlan(), cascadeDelete, cancellationToken).ConfigureAwait(false);

    /// <summary>Freezes the captured expressions, Include tree, and paging into a snapshot to pass to the executor.</summary>
    private SqlQueryPlan<TEntity> BuildPlan()
    {
        // WithUnboundedBinary cannot be combined with Include (both orderings, Include->With and With->Include, are detected here).
        // The SQL Server Include path goes through the default JSON (Base64), which inflates memory for large blobs, so it is
        // incompatible with the goal of "including unbounded binary columns". The combination itself is always rejected regardless of the terminal method.
        if (_withUnboundedBinary && _includes.Count > 0)
        {
            throw new InvalidOperationException(
                "WithUnboundedBinary cannot be combined with Include. When unbounded binary columns are needed, fetch them with a separate query that has no Include."
            );
        }

        // The captured lists are copied, so a query that carries on being built after a terminal method cannot add to a plan
        // that has already been handed over. Their elements are shared as they are: the expressions are immutable, and
        // rebuilding them would defeat EF Core's query plan cache.
        return new(
            _predicates.ToArray(),
            _orderSelectors.ToArray(),
            _includes.ToArray(),
            _take,
            _skip,
            _withUnboundedBinary
        );
    }
}

/// <summary>The target navigation of an Include and the tree of its descendants (ThenInclude).</summary>
internal sealed class IncludeNode
{
    /// <summary>Creates an Include node for the specified target navigation property.</summary>
    public IncludeNode(PropertyInfo property) => Property = property;

    /// <summary>The navigation property to fetch.</summary>
    public PropertyInfo Property { get; }

    /// <summary>The descendant navigations specified via ThenInclude.</summary>
    public List<IncludeNode> Children { get; } = new();

    /// <summary>Extracts the navigation property from a lambda expression (x => x.Nav).</summary>
    public static PropertyInfo GetProperty(LambdaExpression selector)
    {
        var expression = selector.Body;
        if (
            expression is UnaryExpression
            {
                NodeType: ExpressionType.Convert or ExpressionType.ConvertChecked
            } unary
        )
        {
            expression = unary.Operand;
        }

        if (expression is MemberExpression { Member: PropertyInfo property })
        {
            return property;
        }

        throw new ArgumentException(
            $"Include/ThenInclude requires a navigation property: {selector}"
        );
    }
}

/// <summary>A query that lets you specify ThenInclude (fetching descendants) after an Include.</summary>
public sealed class IncludableSqlQuery<TEntity, TProperty>
    where TEntity : class
{
    private readonly SqlQuery<TEntity> _query;
    private readonly IncludeNode _node;

    internal IncludableSqlQuery(SqlQuery<TEntity> query, IncludeNode node)
    {
        _query = query;
        _node = node;
    }

    /// <summary>Further fetches the descendants of the single-reference navigation Included just before.</summary>
    /// <remarks>A navigation that is already a child of this node is reused, so repeating an Include / ThenInclude path merges it instead of duplicating it.</remarks>
    public IncludableSqlQuery<TEntity, TNext> ThenInclude<TNext>(
        Expression<Func<TProperty, TNext>> navigationSelector
    )
    {
        var child = SqlQuery<TEntity>.MergeInclude(
            _node.Children,
            IncludeNode.GetProperty(navigationSelector)
        );
        return new IncludableSqlQuery<TEntity, TNext>(_query, child);
    }

    /// <summary>Further fetches the descendants of the collection navigation Included just before.</summary>
    /// <remarks>A navigation that is already a child of this node is reused, so repeating an Include / ThenInclude path merges it instead of duplicating it.</remarks>
    public IncludableSqlQuery<TEntity, TNext> ThenInclude<TNext>(
        Expression<Func<TProperty, ICollection<TNext>>> navigationSelector
    )
    {
        var child = SqlQuery<TEntity>.MergeInclude(
            _node.Children,
            IncludeNode.GetProperty(navigationSelector)
        );
        return new IncludableSqlQuery<TEntity, TNext>(_query, child);
    }

    /// <summary>Additionally Includes another root navigation.</summary>
    public IncludableSqlQuery<TEntity, TNext> Include<TNext>(
        Expression<Func<TEntity, TNext>> navigationSelector
    ) => _query.Include(navigationSelector);

    /// <summary>Additionally Includes another root collection.</summary>
    public IncludableSqlQuery<TEntity, TNext> Include<TNext>(
        Expression<Func<TEntity, ICollection<TNext>>> navigationSelector
    ) => _query.Include(navigationSelector);

    /// <summary>Adds a search condition.</summary>
    public SqlQuery<TEntity> Where(Expression<Func<TEntity, bool>> predicate) =>
        _query.Where(predicate);

    /// <summary>Adds an ascending ordering.</summary>
    public SqlQuery<TEntity> OrderBy(Expression<Func<TEntity, object?>> keySelector) =>
        _query.OrderBy(keySelector);

    /// <summary>Adds a descending ordering.</summary>
    public SqlQuery<TEntity> OrderByDescending(Expression<Func<TEntity, object?>> keySelector) =>
        _query.OrderByDescending(keySelector);

    /// <summary>Sets the maximum number of rows to fetch.</summary>
    public SqlQuery<TEntity> Take(int count) => _query.Take(count);

    /// <summary>Sets the number of leading rows to skip.</summary>
    public SqlQuery<TEntity> Skip(int count) => _query.Skip(count);

    /// <summary>Fetches including unbounded binary columns (combining with Include throws when the terminal method runs).</summary>
    public SqlQuery<TEntity> WithUnboundedBinary() => _query.WithUnboundedBinary();

    /// <summary>Fetches the entities matching the conditions as a list.</summary>
    public Task<IReadOnlyList<TEntity>> ToListAsync(
        CancellationToken cancellationToken = default
    ) => _query.ToListAsync(cancellationToken);

    /// <summary>Fetches the first entity matching the conditions (returns null when there is no match).</summary>
    public Task<TEntity?> FirstOrDefaultAsync(CancellationToken cancellationToken = default) =>
        _query.FirstOrDefaultAsync(cancellationToken);

    /// <summary>Returns the count of rows matching the conditions.</summary>
    public Task<int> CountAsync(CancellationToken cancellationToken = default) =>
        _query.CountAsync(cancellationToken);

    /// <summary>Returns whether any record matching the conditions exists.</summary>
    public Task<bool> AnyAsync(CancellationToken cancellationToken = default) =>
        _query.AnyAsync(cancellationToken);
}

/// <summary>Why a save was rejected as a conflict (the classification carried by <see cref="SaveConflictException"/>).</summary>
public enum SaveConflictReason
{
    /// <summary>The reason was not reported (the exception was constructed directly rather than through a factory).</summary>
    Unknown,

    /// <summary>The row the save targeted no longer exists (it was deleted by someone else).</summary>
    NotFound,

    /// <summary>The row still exists, but its version moved on after the entity was read.</summary>
    Modified,
}

/// <summary>Represents an exception indicating that a record could not be saved because another party changed it first (it was deleted, or its version moved on).</summary>
/// <remarks>
/// <see cref="Reason"/>, <see cref="EntityTypeName"/>, and <see cref="Key"/> carry the material a reload-and-retry loop
/// needs, so the message does not have to be parsed. They are filled in by the factory methods; an instance built with the
/// message-only constructor reports <see cref="SaveConflictReason.Unknown"/> and nulls. The same details survive the remote
/// transport (HTTP 409), so a caller behaves identically against a direct and a remote repository.
/// </remarks>
public sealed class SaveConflictException : Exception
{
    /// <summary>Initializes a new instance with the specified message (no details: the reason stays <see cref="SaveConflictReason.Unknown"/>).</summary>
    public SaveConflictException(string message)
        : base(message) { }

    /// <summary>Initializes a new instance with the specified message and the failure it was classified from (no details: the reason stays <see cref="SaveConflictReason.Unknown"/>).</summary>
    /// <remarks>
    /// This is the constructor for a backend that recognizes a conflict in a provider's exception but cannot say which
    /// kind it is - the generated EF Core repositories take it when a <c>DbUpdateConcurrencyException</c> names no entry
    /// at all, leaving nothing to look the stored row up by. A conflict reported this way therefore carries
    /// <see cref="SaveConflictReason.Unknown"/> and no key, and the provider's exception is kept as the inner one because
    /// that is all the detail there is.
    /// </remarks>
    /// <param name="message">The message describing the conflict.</param>
    /// <param name="innerException">The failure this conflict was classified from, kept so that the original error is still available for diagnosis.</param>
    public SaveConflictException(string message, Exception? innerException)
        : base(message, innerException) { }

    /// <summary>Initializes a new instance with the specified message and the details of the rejected save.</summary>
    /// <param name="message">The message describing the conflict.</param>
    /// <param name="reason">Why the save was rejected.</param>
    /// <param name="entityTypeName">The CLR type name (<c>Type.Name</c>) of the entity whose save was rejected, or <c>null</c> when unknown.</param>
    /// <param name="key">The primary key the save targeted, formatted for display, or <c>null</c> when unknown.</param>
    public SaveConflictException(
        string message,
        SaveConflictReason reason,
        string? entityTypeName,
        string? key
    )
        : base(message)
    {
        Reason = reason;
        EntityTypeName = entityTypeName;
        Key = key;
    }

    /// <summary>Gets why the save was rejected (<see cref="SaveConflictReason.Unknown"/> when the exception carries no details).</summary>
    public SaveConflictReason Reason { get; }

    /// <summary>Gets the CLR type name of the entity whose save was rejected (<c>null</c> when unknown).</summary>
    public string? EntityTypeName { get; }

    /// <summary>Gets the primary key the rejected save targeted, formatted for display (<c>null</c> when unknown).</summary>
    public string? Key { get; }

    /// <summary>Creates the conflict reported when the row an update targeted no longer exists.</summary>
    /// <param name="entityType">The type of the entity whose save was rejected.</param>
    /// <param name="key">The primary key value the save targeted.</param>
    public static SaveConflictException NotFound(Type entityType, object? key) =>
        new(
            $"The record to update was not found ({entityType.Name}, key {key}). It may have been deleted by another user.",
            SaveConflictReason.NotFound,
            entityType.Name,
            key?.ToString()
        );

    /// <summary>Creates the conflict reported when the row still exists but was changed by someone else after the entity was read.</summary>
    /// <param name="entityType">The type of the entity whose save was rejected.</param>
    /// <param name="key">The primary key value the save targeted.</param>
    /// <param name="operation">The lowercase verb of the rejected operation ("update" or "delete").</param>
    public static SaveConflictException Modified(
        Type entityType,
        object? key,
        string operation
    ) =>
        new(
            $"The record to {operation} was modified by another user ({entityType.Name}, key {key}). Reload the entity and try again.",
            SaveConflictReason.Modified,
            entityType.Name,
            key?.ToString()
        );
}

/// <summary>A child navigation targeted by cascading (property, collection kind, child type, and FK information).</summary>
internal sealed record CascadeNavigation(
    PropertyInfo Property,
    bool IsCollection,
    Type ChildType,
    string PrincipalColumn,
    string DependentColumn
);

/// <summary>Extensions that register save hooks (<c>ISaveHook&lt;TEntity&gt;</c>) with the DI container.</summary>
/// <remarks>
/// The default registry (<c>ServiceProviderSaveHookRegistry</c>, registered by every <c>AddGenerated*Repositories</c>
/// overload) resolves <c>IEnumerable&lt;ISaveHook&lt;TEntity&gt;&gt;</c>, so a hook must be registered under each closed
/// interface it implements. This extension derives those from the instance itself, which keeps registration code free of
/// per-entity-type branching (and free of the maintenance it needs whenever a table is added).
/// </remarks>
public static class SaveHookServiceCollectionExtensions
{
    /// <summary>Registers a save hook instance as a singleton under every <c>ISaveHook&lt;TEntity&gt;</c> it implements.</summary>
    /// <param name="services">The service collection to register with.</param>
    /// <param name="hook">The hook instance (one object may implement the hook interface for several entity types).</param>
    /// <returns>The same service collection, so that calls can be chained.</returns>
    /// <exception cref="ArgumentException">The object implements no <c>ISaveHook&lt;TEntity&gt;</c> interface, so registering it would silently do nothing.</exception>
    public static IServiceCollection AddSaveHook(this IServiceCollection services, object hook)
    {
        ArgumentNullException.ThrowIfNull(services);
        ArgumentNullException.ThrowIfNull(hook);

        var registered = false;

        foreach (var contract in hook.GetType().GetInterfaces())
        {
            if (
                !contract.IsGenericType
                || contract.GetGenericTypeDefinition() != typeof(ISaveHook<>)
            )
            {
                continue;
            }

            services.AddSingleton(contract, hook);
            registered = true;
        }

        return registered
            ? services
            : throw new ArgumentException(
                $"The object of type '{hook.GetType().Name}' implements no ISaveHook<TEntity> interface.",
                nameof(hook)
            );
    }
}

/// <summary>Remote surface every generated repository contract inherits, and the extension point for it. A member with a default implementation added to a partial declaration of this interface is callable through any repository reference, whatever the entity or the backend behind it.</summary>
/// <typeparam name="TEntity">The entity type.</typeparam>
/// <typeparam name="TKey">The primary key type.</typeparam>
public partial interface IRemoteRepository<TEntity, TKey> : IRemoteRepositoryCore<TEntity, TKey>
    where TEntity : EntityBaseCore, new() { }

/// <summary>Full-featured surface every generated repository contract inherits, and the extension point for it. It inherits the remote surface as well, so a member added there is reachable through this one too.</summary>
/// <typeparam name="TEntity">The entity type.</typeparam>
/// <typeparam name="TKey">The primary key type.</typeparam>
public partial interface IRepository<TEntity, TKey>
    : IRepositoryCore<TEntity, TKey>,
        IRemoteRepository<TEntity, TKey>
    where TEntity : EntityBaseCore, new() { }

/// <summary>Repository interface for SyncvoOrderEntity.</summary>
public partial interface ISyncvoOrderRepository : IRepository<SyncvoOrderEntity, OrderIdValue> { }

/// <summary>Repository interface for SyncvoLineEntity.</summary>
public partial interface ISyncvoLineRepository : IRepository<SyncvoLineEntity, LineIdValue> { }

/// <summary>Query extensions: including the whole cascade graph of an entity with a single method call (the read-side counterpart of the graph save - combine it with Where or GetByIdAsync to bound what is fetched), and fetching a single entity by its key.</summary>
/// <remarks>
/// The Include tree of each entity is built once and shared by every query, so it must stay unmodified after construction.
/// </remarks>
public static class SqlQueryExtensions
{
    /// <summary>The Include tree of SyncvoOrderEntity (built once and shared by every query; never modify it).</summary>
    private static readonly Lazy<IReadOnlyList<IncludeNode>> _syncvoOrderEntityGraph = new(() =>
    {
        var n0 = new IncludeNode(typeof(SyncvoOrderEntity).GetProperty(nameof(SyncvoOrderEntity.SyncvoLines))!);
        return new IncludeNode[] { n0 };
    });

    /// <summary>Includes the cascade graph of SyncvoOrderEntity - the same child-direction navigations a graph save walks. A navigation pointing back to a table already on the path from the root is not followed.</summary>
    public static SqlQuery<SyncvoOrderEntity> IncludeGraph(this SqlQuery<SyncvoOrderEntity> query) =>
        query.AddIncludeNodes(_syncvoOrderEntityGraph.Value);

    /// <summary>Fetches the single entity with the given key - the same key the repository contract's GetByIdAsync takes - and returns null when no row matches.</summary>
    /// <remarks>Combine it with Include or IncludeGraph to fetch that entity together with its graph in one call.</remarks>
    public static Task<SyncvoOrderEntity?> GetByIdAsync(
        this SqlQuery<SyncvoOrderEntity> query,
        OrderIdValue id,
        CancellationToken cancellationToken = default
    ) => query.Where(entity => entity.OrderId == id).FirstOrDefaultAsync(cancellationToken);

    /// <summary>Fetches the single entity with the given key, keeping the Include chain written just before it (returns null when no row matches).</summary>
    public static Task<SyncvoOrderEntity?> GetByIdAsync<TProperty>(
        this IncludableSqlQuery<SyncvoOrderEntity, TProperty> query,
        OrderIdValue id,
        CancellationToken cancellationToken = default
    ) => query.Where(entity => entity.OrderId == id).FirstOrDefaultAsync(cancellationToken);

    /// <summary>Includes the cascade graph of SyncvoLineEntity (it has no child-direction navigation, so the query is returned unchanged).</summary>
    public static SqlQuery<SyncvoLineEntity> IncludeGraph(this SqlQuery<SyncvoLineEntity> query) => query;

    /// <summary>Fetches the single entity with the given key - the same key the repository contract's GetByIdAsync takes - and returns null when no row matches.</summary>
    /// <remarks>Combine it with Include or IncludeGraph to fetch that entity together with its graph in one call.</remarks>
    public static Task<SyncvoLineEntity?> GetByIdAsync(
        this SqlQuery<SyncvoLineEntity> query,
        LineIdValue id,
        CancellationToken cancellationToken = default
    ) => query.Where(entity => entity.LineId == id).FirstOrDefaultAsync(cancellationToken);

    /// <summary>Fetches the single entity with the given key, keeping the Include chain written just before it (returns null when no row matches).</summary>
    public static Task<SyncvoLineEntity?> GetByIdAsync<TProperty>(
        this IncludableSqlQuery<SyncvoLineEntity, TProperty> query,
        LineIdValue id,
        CancellationToken cancellationToken = default
    ) => query.Where(entity => entity.LineId == id).FirstOrDefaultAsync(cancellationToken);
}

/// <summary>The kind of local change recorded in the sync journal.</summary>
public enum SyncJournalOperation
{
    /// <summary>An insert or an update. The row's current local content is what gets uploaded.</summary>
    Upsert,

    /// <summary>A delete. The key and the mirrored version the row carried when it was deleted are what get uploaded.</summary>
    Delete,
}

/// <summary>Why a journal entry could not be replayed against the server.</summary>
public enum SyncConflictReason
{
    /// <summary>Someone else changed the server row after the local copy was taken.</summary>
    ModifiedOnServer,

    /// <summary>The server row the local change was meant to update no longer exists.</summary>
    MissingOnServer,

    /// <summary>The row was created locally, but a row with the same key already exists on the server.</summary>
    DuplicateOnServer,
}

/// <summary>How the engine treats a local change that collides with the server.</summary>
public enum SyncConflictPolicy
{
    /// <summary>Leaves the entry in the journal and reports it (the default: nothing is resolved silently).</summary>
    Collect,

    /// <summary>Discards the local change and makes the row match the server's state: the server's row is read back over the local one when the server has the key, and delete propagation removes the row when it does not (a local insert the server never received).</summary>
    ServerWins,

    /// <summary>Resends the local change with <see cref="ConcurrencyMode.ForceOverwrite"/>, overwriting the server row - and inserting it again when the server has no such row, so a row deleted on the server is resurrected by a local edit.</summary>
    LocalWins,
}

/// <summary>One local change that could not be replayed against the server.</summary>
/// <param name="TableName">The table the row belongs to.</param>
/// <param name="KeyText">The primary key, in the same text form the journal stores.</param>
/// <param name="Operation">The local operation that was being replayed.</param>
/// <param name="Reason">Why the replay did not go through.</param>
/// <param name="LocalEntity">The local row as it stands (null for a delete, whose row is already gone locally).</param>
/// <param name="ServerEntity">The server row as it stands (null when the server has no such row).</param>
public sealed record SyncConflict(
    string TableName,
    string KeyText,
    SyncJournalOperation Operation,
    SyncConflictReason Reason,
    object? LocalEntity,
    object? ServerEntity
);

/// <summary>What replaying one journal entry did.</summary>
/// <param name="Sent">Whether the change actually reached the server.</param>
/// <param name="Conflict">The disagreement that stopped it, or null when nothing stood in the way.</param>
/// <remarks>
/// "Not sent" and "conflicted" are different outcomes and must not be folded together: an entry whose row no longer
/// exists locally has nothing left to send and is simply dropped, which is neither an upload nor a conflict.
/// </remarks>
public readonly record struct SyncUploadOutcome(bool Sent, SyncConflict? Conflict)
{
    /// <summary>The version the server stamped the row with, or null when there is none to report.</summary>
    /// <remarks>
    /// The run remembers this stamp for the download that follows, which recognises a row carrying it as the echo of
    /// what this very run sent. Null for a delete, for a discard, for a conflict, and for a table without a version
    /// column.
    /// </remarks>
    public byte[]? ServerRowVersion { get; init; }

    /// <summary>The change reached the server; the journal entry is settled.</summary>
    public static SyncUploadOutcome Uploaded { get; } = new(true, null);

    /// <summary>There was nothing to send (a stale intent); the journal entry is settled without a round trip.</summary>
    public static SyncUploadOutcome Discarded { get; } = new(false, null);

    /// <summary>The server disagreed; the journal entry stays put.</summary>
    public static SyncUploadOutcome Conflicted(SyncConflict conflict) => new(false, conflict);

    /// <summary>The change reached the server, which stamped the row with the given version.</summary>
    /// <param name="serverRowVersion">The version the server now holds for the row, or null when it holds none.</param>
    public static SyncUploadOutcome UploadedWith(byte[]? serverRowVersion) =>
        new(true, null) { ServerRowVersion = serverRowVersion };
}

/// <summary>How one run treats versions and conflicts.</summary>
public enum SyncMode
{
    /// <summary>
    /// Versioned differential sync (the default): tables with a version column sync incrementally under version
    /// guards, and tables without one take no part in the run. This is the pre-existing behaviour, unchanged.
    /// </summary>
    Versioned,

    /// <summary>
    /// Last-write-wins: every table takes part. Uploads overwrite the server unconditionally - an update that finds
    /// no row inserts it, a delete needs no version - so nothing is ever reported as a conflict, and
    /// <see cref="SyncOptions.ConflictPolicy"/> is ignored. Tables without a version column download as a full
    /// key-ordered scan on every run; tables with one still download incrementally, because the result is the same
    /// and the transfer is smaller. The winner is whoever <i>uploads</i> last, not whoever edited last, and a lost
    /// update is neither detected nor reported - that is the trade this mode names.
    /// </summary>
    LastWriteWins,
}

/// <summary>Knobs for one sync run.</summary>
public sealed class SyncOptions
{
    /// <summary>How versions and conflicts are treated in this run (default <see cref="SyncMode.Versioned"/>).</summary>
    public SyncMode Mode { get; init; } = SyncMode.Versioned;

    /// <summary>The entity types this run leaves out entirely (upload, download, and delete propagation alike).</summary>
    /// <remarks>
    /// This is a per-run scope, not a way to keep a table local: the journaling decorators keep recording the
    /// excluded tables' writes, and the next run that includes them replays what accumulated. A table that should
    /// never sync is excluded where the engine is put together instead (the <c>excludeFromSync</c> argument of
    /// <c>AddGeneratedSyncEngine</c>), which also stops the recording. A type the engine does not synchronise -
    /// including one excluded at construction - is rejected with <see cref="ArgumentException"/> rather than
    /// silently skipped.
    /// </remarks>
    public IReadOnlyCollection<Type> ExcludedEntityTypes { get; init; } = [];

    /// <summary>How many rows one download batch fetches and applies in a single local transaction (default 500).</summary>
    public int DownloadBatchSize { get; init; } = 500;

    /// <summary>Whether to delete local rows whose key no longer exists on the server (default true).</summary>
    /// <remarks>
    /// <para>
    /// The check compares the full key set of each table, which costs one key-only pass over the server table. Turn it
    /// off (and run it on a slower schedule) when the tables are large enough for that pass to matter.
    /// </para>
    /// <para>
    /// A key the journal still holds an unsent entry for is spared, so a local edit awaiting upload - including one this
    /// run reported as a conflict - is not removed underneath the caller. That protection reaches exactly as far as the
    /// journal does: <b>a row written into a synchronised table without going through the generated repositories - raw
    /// SQL above all - has no entry, and while this is on it is deleted on the next run</b>, because from the key set's
    /// point of view it is a row the server does not have. Rows the local database is meant to keep to itself belong in
    /// a table that is not synchronised (one excluded where the engine is put together - the <c>excludeFromSync</c>
    /// argument of <c>AddGeneratedSyncEngine</c>).
    /// </para>
    /// </remarks>
    public bool PropagateDeletes { get; init; } = true;

    /// <summary>How a local change that collides with the server is treated (default <see cref="SyncConflictPolicy.Collect"/>).</summary>
    public SyncConflictPolicy ConflictPolicy { get; init; } = SyncConflictPolicy.Collect;

    /// <summary>Whether to carry the unbounded binary columns the row transfer leaves out (default false).</summary>
    /// <remarks>
    /// <para>
    /// Only tables generated with the unbounded binary columns excluded have any (<c>ISyncTable.UnboundedBinaryColumnNames</c>
    /// names them); for every other table this changes nothing. Those columns are not part of the row a run reads or
    /// writes, so with this off a downloaded row arrives without its blob and an uploaded row is sent without it. What is
    /// already stored on the receiving side stays there - an update never touches an excluded column - but a row that is
    /// new to that side has nothing to keep, and arrives with the column empty.
    /// </para>
    /// <para>
    /// With it on, each such column is copied separately after the row itself has been transferred, streamed through a
    /// temporary file so neither side has to hold the blob in memory. That is one round trip per column per changed row,
    /// which is why it is not the default: a table of large blobs whose rows change often pays for it on every run.
    /// </para>
    /// <para>
    /// That file is created in the operating system's temporary folder (<c>Path.GetTempPath()</c>) and deleted when the
    /// column has been written, so a blob whose contents are sensitive passes through the file system unencrypted for the
    /// duration of its copy - on a machine where that matters, point the temporary folder somewhere it does not.
    /// </para>
    /// </remarks>
    public bool IncludeUnboundedBinary { get; init; }
}

/// <summary>One table whose download stopped before the end of the server's changes.</summary>
/// <remarks>
/// Exactly one of the two reasons is given. A table stops at its own unsent local change, and every table after it in
/// foreign-key order stops with it - a child row whose parent was not downloaded would violate a foreign key, and the
/// engine cannot tell which children of the parents it skipped are in the batches it did not read.
/// </remarks>
/// <param name="TableName">The table whose download stopped early.</param>
/// <param name="PendingKeyText">The key of the unsent local change the download stopped at, or null when another table's truncation stopped this one.</param>
/// <param name="TruncatedByTableName">The table whose truncation stopped this one, or null when this table stopped at its own key.</param>
public sealed record SyncDownloadTruncation(
    string TableName,
    string? PendingKeyText,
    string? TruncatedByTableName
);

/// <summary>What one sync run did.</summary>
/// <param name="Uploaded">The number of local changes replayed against the server.</param>
/// <param name="Downloaded">The number of server rows applied locally.</param>
/// <param name="DeletedLocally">The number of local rows removed because the server no longer has that key.</param>
/// <param name="Discarded">The number of journal entries dropped without being sent (a stale intent, or ServerWins).</param>
/// <param name="Conflicts">The local changes that could not be replayed; they stay in the journal.</param>
public sealed record SyncResult(
    int Uploaded,
    int Downloaded,
    int DeletedLocally,
    int Discarded,
    IReadOnlyList<SyncConflict> Conflicts
)
{
    /// <summary>The tables whose download stopped early, empty when every table was drained.</summary>
    /// <remarks>
    /// A run that reports a conflict usually reports a truncation as well: the conflicted row's own table stops at it,
    /// and the tables after it stop with it. The rows behind the stopping point are still on the server and come down
    /// once the entry that stopped them is settled, which is the caller's to decide and re-run.
    /// </remarks>
    public IReadOnlyList<SyncDownloadTruncation> Truncations { get; init; } = [];

    /// <summary>Whether any local change was left unsent.</summary>
    public bool HasConflicts => Conflicts.Count > 0;

    /// <summary>Whether any table's download stopped early.</summary>
    public bool HasTruncations => Truncations.Count > 0;
}

/// <summary>Knobs for one refresh run.</summary>
public sealed class SyncRefreshOptions
{
    /// <summary>Which tables the refresh covers (default <see cref="SyncMode.LastWriteWins"/> = every synchronised table).</summary>
    /// <remarks>
    /// <para>
    /// A refresh has no upload, so the mode is purely a scope here - and unlike an ordinary run, the default takes
    /// everything: a refresh rebuilds the local database as a copy of the server's, and leaving the versionless
    /// tables out of that rebuild would keep stale rows pointing at parents the wipe is about to remove (a foreign
    /// key failure whenever a versionless table references a versioned one). On a diagram whose tables all carry a
    /// version column the two defaults cover the same set, so nothing changes there.
    /// </para>
    /// <para>
    /// <see cref="SyncMode.Versioned"/> narrows the refresh to the versioned tables. That is sound only while no
    /// versionless row references a versioned table being rebuilt - the scope is the caller's to choose soundly.
    /// The unsent-changes refusal and the forced discard follow the scope either way: entries of tables outside
    /// this refresh are neither counted nor dropped.
    /// </para>
    /// </remarks>
    public SyncMode Mode { get; init; } = SyncMode.LastWriteWins;

    /// <summary>The entity types this refresh leaves out (neither emptied nor reloaded).</summary>
    /// <remarks>
    /// The same per-run scope as <see cref="SyncOptions.ExcludedEntityTypes"/>, with the same rejection of a type the
    /// engine does not synchronise. Leaving a parent table out while reloading its children can break a foreign key
    /// mid-run; the scope is the caller's to choose soundly.
    /// </remarks>
    public IReadOnlyCollection<Type> ExcludedEntityTypes { get; init; } = [];

    /// <summary>How many rows one batch fetches from the server and writes locally (default 2000).</summary>
    /// <remarks>
    /// <para>
    /// Each batch is one local transaction, and on a local database that commit costs more than the inserts it commits.
    /// The default is therefore several times the one an ordinary run downloads with: a refresh writes whole tables and
    /// gains most of its speed here, while a run interrupted part way is repaired by running it again, so the finer
    /// resume granularity a small batch buys is worth less.
    /// </para>
    /// <para>
    /// The cost of raising it is memory - a batch is held in full - and, when the server is reached over HTTP, the size
    /// of one response body. A table with large binary columns is the case that wants a smaller value than the default,
    /// not a larger one.
    /// </para>
    /// </remarks>
    public int BatchSize { get; init; } = 2000;

    /// <summary>Whether to discard the unsent local changes instead of refusing to run (default false).</summary>
    /// <remarks>
    /// A refresh replaces the local rows wholesale, so an offline edit that has not reached the server yet goes with
    /// them. Leaving this off makes the run throw <see cref="SyncPendingChangesException"/> before it touches
    /// anything, which leaves the caller free to send those changes first - an ordinary
    /// <see cref="SyncEngine.SyncAsync"/> is what sends them - and refresh afterwards. Turning it on says the loss is
    /// intended.
    /// </remarks>
    public bool Force { get; init; }

    /// <summary>Whether to reload the unbounded binary columns as well (default false).</summary>
    /// <remarks>
    /// A refresh deletes the local rows, and an excluded column goes with the row that held it. Turning this on copies
    /// each such column back down after its row has been written, which makes the rebuilt local database a complete copy
    /// at the cost of one round trip per column per row. Leaving it off means the reloaded rows carry no blobs at all -
    /// which is why a table that has such columns refuses to be refreshed until one of this and
    /// <see cref="DiscardLocalUnboundedBinaries"/> says which of the two was meant.
    /// </remarks>
    public bool IncludeUnboundedBinary { get; init; }

    /// <summary>Whether to accept losing the local unbounded binary columns instead of refusing to run (default false).</summary>
    /// <remarks>
    /// This is the other answer to the same question <see cref="IncludeUnboundedBinary"/> answers, for the case where the
    /// blobs are not worth transferring - a local cache of thumbnails that can be rebuilt, say. It says the loss is
    /// intended; it does not make the rows arrive with their blobs. Setting both is not a contradiction, because
    /// carrying the columns means nothing is lost for the flag to permit.
    /// </remarks>
    public bool DiscardLocalUnboundedBinaries { get; init; }
}

/// <summary>The unbounded binary columns one table would lose in a refresh.</summary>
/// <param name="TableName">The table.</param>
/// <param name="ColumnNames">The columns the ordinary row transfer leaves out.</param>
public sealed record SyncUnboundedBinaryColumns(
    string TableName,
    IReadOnlyList<string> ColumnNames
);

/// <summary>Thrown when a refresh would drop local blobs without having been told which of the two outcomes was meant.</summary>
/// <remarks>
/// The run throws before it deletes anything. Set <see cref="SyncRefreshOptions.IncludeUnboundedBinary"/> to reload the
/// columns with the rows, or <see cref="SyncRefreshOptions.DiscardLocalUnboundedBinaries"/> to say the loss is intended.
/// </remarks>
public sealed class SyncUnboundedBinaryLossException : InvalidOperationException
{
    /// <summary>Creates the exception from the per-table breakdown of the columns at stake.</summary>
    /// <param name="columns">The unbounded binary columns, grouped by table.</param>
    public SyncUnboundedBinaryLossException(IReadOnlyList<SyncUnboundedBinaryColumns> columns)
        : base(BuildMessage(columns))
    {
        ArgumentNullException.ThrowIfNull(columns);
        Columns = columns;
    }

    /// <summary>The unbounded binary columns the refresh would have dropped, grouped by table.</summary>
    public IReadOnlyList<SyncUnboundedBinaryColumns> Columns { get; }

    /// <summary>Builds the message, which names the columns so the caller does not have to read the property to act.</summary>
    private static string BuildMessage(IReadOnlyList<SyncUnboundedBinaryColumns> columns)
    {
        ArgumentNullException.ThrowIfNull(columns);
        var breakdown = string.Join(
            ", ",
            columns.Select(table =>
                $"{table.TableName}: {string.Join('/', table.ColumnNames)}"
            )
        );

        return "A refresh replaces the local rows, and the unbounded binary columns of these tables go with them "
            + $"({breakdown}). Set SyncRefreshOptions.IncludeUnboundedBinary to reload them as well, or "
            + "SyncRefreshOptions.DiscardLocalUnboundedBinaries to say the loss is intended.";
    }
}

/// <summary>How many unsent local changes one table has.</summary>
/// <param name="TableName">The table the changes belong to.</param>
/// <param name="Count">The number of journal entries, which counts edits rather than rows: a row edited twice offline has two.</param>
public sealed record SyncPendingChange(string TableName, int Count);

/// <summary>Thrown when a refresh is asked for while the journal still holds unsent local changes.</summary>
/// <remarks>
/// The run throws before it deletes anything, so the local database is exactly as it was and the changes are still
/// there to be uploaded.
/// </remarks>
public sealed class SyncPendingChangesException : InvalidOperationException
{
    /// <summary>Creates the exception from the per-table breakdown of what the refresh would have discarded.</summary>
    /// <param name="pendingChanges">The unsent local changes, grouped by table.</param>
    public SyncPendingChangesException(IReadOnlyList<SyncPendingChange> pendingChanges)
        : base(BuildMessage(pendingChanges))
    {
        ArgumentNullException.ThrowIfNull(pendingChanges);
        PendingChanges = pendingChanges;
        PendingCount = pendingChanges.Sum(change => change.Count);
    }

    /// <summary>The unsent local changes the refresh would have discarded, grouped by table.</summary>
    public IReadOnlyList<SyncPendingChange> PendingChanges { get; }

    /// <summary>The total number of unsent local changes.</summary>
    public int PendingCount { get; }

    /// <summary>Builds the message, which names the tables so the caller does not have to read the property to act.</summary>
    private static string BuildMessage(IReadOnlyList<SyncPendingChange> pendingChanges)
    {
        ArgumentNullException.ThrowIfNull(pendingChanges);
        var breakdown = string.Join(
            ", ",
            pendingChanges.Select(change => $"{change.TableName}: {change.Count}")
        );

        return $"A refresh would discard {pendingChanges.Sum(change => change.Count)} unsent local "
            + $"change(s) ({breakdown}). Upload them with SyncAsync first, or set "
            + "SyncRefreshOptions.Force to discard them.";
    }
}

/// <summary>What a refresh did to one table.</summary>
/// <param name="TableName">The table.</param>
/// <param name="Deleted">How many local rows were removed to make room.</param>
/// <param name="Inserted">How many server rows were written in their place.</param>
public sealed record SyncRefreshTableResult(string TableName, int Deleted, int Inserted);

/// <summary>What one refresh run did.</summary>
/// <param name="Tables">The per-table counts, in the order the rows were written (parents first).</param>
/// <param name="DiscardedChanges">The number of journal entries dropped, which is zero unless <see cref="SyncRefreshOptions.Force"/> was set.</param>
/// <param name="Elapsed">How long the whole run took, measured around it rather than accumulated per table.</param>
public sealed record SyncRefreshResult(
    IReadOnlyList<SyncRefreshTableResult> Tables,
    int DiscardedChanges,
    TimeSpan Elapsed
)
{
    /// <summary>The total number of local rows removed.</summary>
    public int Deleted => Tables.Sum(table => table.Deleted);

    /// <summary>The total number of server rows written locally.</summary>
    public int Inserted => Tables.Sum(table => table.Inserted);
}

/// <summary>Marks the writes the sync engine itself performs so the journaling decorators skip them.</summary>
/// <remarks>
/// <para>
/// Applying a downloaded row and cleaning the journal both go through the ordinary local repository, which is wrapped by
/// the journaling decorator. Without this flag every downloaded row would immediately be recorded as a local change and
/// uploaded back on the next run - the same row would bounce between the two databases forever.
/// </para>
/// <para>
/// The flag is <see cref="AsyncLocal{T}"/>, so it follows the async control flow of the sync run and does not leak into
/// concurrent work on other tasks. It is a counter rather than a bool so nested scopes restore the outer state.
/// </para>
/// </remarks>
public static class SyncSession
{
    private static readonly AsyncLocal<int> _depth = new();

    /// <summary>Whether the current async flow is inside a sync-engine write.</summary>
    public static bool IsSuppressed => _depth.Value > 0;

    /// <summary>Suppresses journaling until the returned scope is disposed.</summary>
    public static IDisposable Suppress()
    {
        _depth.Value++;
        return new Scope();
    }

    private sealed class Scope : IDisposable
    {
        private bool _disposed;

        public void Dispose()
        {
            if (_disposed)
            {
                return;
            }

            _disposed = true;
            _depth.Value--;
        }
    }
}

/// <summary>The size every IN clause the sync engine builds is chunked to.</summary>
/// <remarks>
/// A collection parameter is expanded into one bind variable per value, so a single statement is bounded by the
/// database's parameter limit: one run settles every table's journal entries together, and a download batch looks up
/// every key it is about to apply, so a long offline stretch or a large batch size can push either past that limit.
/// Chunking keeps the statement within it whatever the list holds. The size matches the one the dialect engines use
/// for their own IN clauses.
/// </remarks>
internal static class SyncInClause
{
    /// <summary>The maximum number of values one statement binds.</summary>
    internal const int ChunkSize = 500;
}

/// <summary>One row of the journal table, as the lenient projection mapper reads it.</summary>
public sealed class SyncJournalRow
{
    /// <summary>The autoincrement id (also the replay order).</summary>
    public long Id { get; set; }

    /// <summary>The table the change belongs to.</summary>
    public string TableName { get; set; } = string.Empty;

    /// <summary>The primary key in text form.</summary>
    public string KeyText { get; set; } = string.Empty;

    /// <summary>The operation name (the <see cref="SyncJournalOperation"/> member name).</summary>
    public string Operation { get; set; } = string.Empty;

    /// <summary>The version the row carried when it was deleted (null for an upsert).</summary>
    public byte[]? OriginalRowVersion { get; set; }
}

/// <summary>One row of the acknowledgement table, as the lenient projection mapper reads it.</summary>
public sealed class SyncAckRow
{
    /// <summary>The primary key in text form.</summary>
    public string KeyText { get; set; } = string.Empty;

    /// <summary>The version the server stamped on the row when it took this device's upload.</summary>
    public byte[] ServerRowVersion { get; set; } = [];
}

/// <summary>
/// The local record of offline edits (<c>quicker_sync_journal</c>) and of the uploads the server has taken
/// (<c>quicker_sync_ack</c>), kept in two shared tables in the local database.
/// </summary>
/// <remarks>
/// <para>
/// The server gets no extra schema at all; only the local database - which the application owns - gets these two
/// tables, created on first use with <c>CREATE TABLE IF NOT EXISTS</c>.
/// </para>
/// <para>
/// <b>The acknowledgement table is a per-row receipt, not a resume point.</b> It holds, for a row this device has
/// uploaded, the version the server stamped on it - which the upload may not write into the mirror, because the
/// mirrored version is what the download derives its resume point from and only the download may move it. Until the
/// row comes back down and the mirror catches up, the receipt is the only record that the local row has already been
/// accepted at a newer version, and the replay of a further edit needs it to guard against the right original.
/// </para>
/// <para>
/// <b>Recording happens before the business write ("journal-first").</b> The generated repositories manage their own
/// connection, so a decorator cannot enlist its INSERT in the transaction of the write it wraps; something has to go
/// first. Recording the <i>intent</i> first is the safe order: if the business write then fails or is rolled back, the
/// journal holds an entry for a row that was never written, and the upload discards it - it re-reads the current local
/// row and finds nothing (an upsert entry), or sends a delete for a key the server does not have (a no-op). The
/// opposite order would lose changes outright: a write that succeeded and a journal entry that never landed is an edit
/// no later run can find. The entry also carries only the key, never a snapshot, so a stale intent still uploads the
/// row's current content.
/// </para>
/// </remarks>
public sealed class SyncJournal
{
    /// <summary>The statement that creates the journal table when it is missing.</summary>
    private const string CreateTableSql =
        "CREATE TABLE IF NOT EXISTS quicker_sync_journal ("
        + "id INTEGER PRIMARY KEY AUTOINCREMENT, "
        + "table_name TEXT NOT NULL, "
        + "key_text TEXT NOT NULL, "
        + "operation TEXT NOT NULL, "
        + "original_row_version BLOB NULL, "
        + "recorded_at TEXT NOT NULL)";

    /// <summary>The statement that creates the acknowledgement table when it is missing.</summary>
    private const string CreateAckTableSql =
        "CREATE TABLE IF NOT EXISTS quicker_sync_ack ("
        + "table_name TEXT NOT NULL, "
        + "key_text TEXT NOT NULL, "
        + "server_row_version BLOB NOT NULL, "
        + "PRIMARY KEY (table_name, key_text))";

    /// <summary>Reads every pending entry in replay order, aliasing the columns onto the DTO's property names.</summary>
    private const string SelectAllSql =
        "SELECT id AS Id, table_name AS TableName, key_text AS KeyText, operation AS Operation, "
        + "original_row_version AS OriginalRowVersion FROM quicker_sync_journal ORDER BY id";

    /// <summary>Reads one table's acknowledgements, aliasing the columns onto the DTO's property names.</summary>
    private const string SelectAcksSql =
        "SELECT key_text AS KeyText, server_row_version AS ServerRowVersion FROM quicker_sync_ack "
        + "WHERE table_name = @tableName";

    private readonly ISqlExecutor _localSqlExecutor;
    private volatile bool _ensured;

    /// <summary>Creates a journal over the local database's raw SQL executor.</summary>
    /// <param name="localSqlExecutor">The raw SQL executor bound to the local (SQLite) database.</param>
    public SyncJournal(ISqlExecutor localSqlExecutor)
    {
        ArgumentNullException.ThrowIfNull(localSqlExecutor);
        _localSqlExecutor = localSqlExecutor;
    }

    /// <summary>Creates the two tables when they do not exist yet (idempotent, and only issued once per instance).</summary>
    public async Task EnsureCreatedAsync(CancellationToken cancellationToken = default)
    {
        if (_ensured)
        {
            return;
        }

        await _localSqlExecutor
            .ExecuteSqlAsync(CreateTableSql, null, cancellationToken)
            .ConfigureAwait(false);
        await _localSqlExecutor
            .ExecuteSqlAsync(CreateAckTableSql, null, cancellationToken)
            .ConfigureAwait(false);
        _ensured = true;
    }

    /// <summary>Records one local change (a no-op while the sync engine's own writes are running).</summary>
    /// <param name="tableName">The table the changed row belongs to.</param>
    /// <param name="keyText">The primary key in the text form the table's descriptor produces.</param>
    /// <param name="operation">Whether the row was written or deleted.</param>
    /// <param name="originalRowVersion">For a delete, the mirrored server version the row carried; otherwise null.</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    public async Task RecordAsync(
        string tableName,
        string keyText,
        SyncJournalOperation operation,
        byte[]? originalRowVersion,
        CancellationToken cancellationToken = default
    )
    {
        if (SyncSession.IsSuppressed)
        {
            return;
        }

        await EnsureCreatedAsync(cancellationToken).ConfigureAwait(false);
        await _localSqlExecutor
            .ExecuteSqlAsync(
                "INSERT INTO quicker_sync_journal "
                    + "(table_name, key_text, operation, original_row_version, recorded_at) "
                    + "VALUES (@tableName, @keyText, @operation, @originalRowVersion, @recordedAt)",
                new
                {
                    tableName,
                    keyText,
                    operation = operation.ToString(),
                    originalRowVersion,
                    recordedAt = DateTime.UtcNow.ToString(
                        "o",
                        System.Globalization.CultureInfo.InvariantCulture
                    ),
                },
                cancellationToken
            )
            .ConfigureAwait(false);
    }

    /// <summary>Reads every pending entry in the order it was recorded.</summary>
    public async Task<IReadOnlyList<SyncJournalRow>> ReadAllAsync(
        CancellationToken cancellationToken = default
    )
    {
        await EnsureCreatedAsync(cancellationToken).ConfigureAwait(false);

        return await _localSqlExecutor
            .QueryProjectionBySqlAsync<SyncJournalRow>(SelectAllSql, null, cancellationToken)
            .ConfigureAwait(false);
    }

    /// <summary>Removes the given entries (called once the change they describe has reached the server).</summary>
    /// <remarks>The removal is chunked to <see cref="SyncInClause.ChunkSize"/> ids per statement.</remarks>
    public async Task RemoveAsync(
        IReadOnlyList<long> ids,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(ids);

        for (var offset = 0; offset < ids.Count; offset += SyncInClause.ChunkSize)
        {
            var count = Math.Min(SyncInClause.ChunkSize, ids.Count - offset);
            var chunk = new List<long>(count);

            for (var index = 0; index < count; index++)
            {
                chunk.Add(ids[offset + index]);
            }

            await _localSqlExecutor
                .ExecuteSqlAsync(
                    "DELETE FROM quicker_sync_journal WHERE id IN (@ids)",
                    new { ids = chunk },
                    cancellationToken
                )
                .ConfigureAwait(false);
        }
    }

    /// <summary>Removes every entry of one table, discarding the unsent local changes it held.</summary>
    /// <remarks>
    /// <para>
    /// This is journal maintenance for a table that is no longer synchronised - one excluded where the engine is put
    /// together after entries had already accumulated. Such entries can never be replayed (no run knows the table),
    /// yet they count as unsent changes and block <see cref="SyncEngine.RefreshAsync"/> for ever. Removing them is
    /// the deliberate statement that those local edits will never reach the server.
    /// </para>
    /// <para>
    /// Do not call it while a sync run is in flight: the run reads the journal once at its start and settles entries
    /// by id, and removing rows underneath it makes the two views disagree.
    /// </para>
    /// </remarks>
    /// <param name="tableName">The table whose entries are dropped.</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    public async Task RemoveTableAsync(
        string tableName,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(tableName);
        await EnsureCreatedAsync(cancellationToken).ConfigureAwait(false);
        await _localSqlExecutor
            .ExecuteSqlAsync(
                "DELETE FROM quicker_sync_journal WHERE table_name = @tableName",
                new { tableName },
                cancellationToken
            )
            .ConfigureAwait(false);
    }

    /// <summary>Removes every entry of every table, discarding all unsent local changes.</summary>
    /// <remarks>
    /// The whole-journal counterpart of <see cref="RemoveTableAsync"/>, with the same warnings: it is the journal half
    /// of what <see cref="SyncConflictPolicy.ServerWins"/> does at upload time, done without a run. What it leaves out
    /// is the other half - reading the server's rows back over the local ones - so an edit to a row the server has not
    /// changed since it was mirrored stays where it is, with nothing left to say it is there.
    /// </remarks>
    /// <param name="cancellationToken">The cancellation token.</param>
    public async Task RemoveAllAsync(CancellationToken cancellationToken = default)
    {
        await EnsureCreatedAsync(cancellationToken).ConfigureAwait(false);
        await _localSqlExecutor
            .ExecuteSqlAsync("DELETE FROM quicker_sync_journal", null, cancellationToken)
            .ConfigureAwait(false);
    }

    /// <summary>Records the version the server stamped on a row this device uploaded (one receipt per key, replaced on repeat).</summary>
    /// <remarks>
    /// <para>
    /// Written <i>before</i> the journal entry it settles is removed. Both surviving a crash costs nothing: the next
    /// run replays the same local content with the acknowledged version as its original, and the server takes it
    /// again. The opposite order leaves the row with a mirrored version behind the server's and nothing left to say
    /// so, which is the very state the receipt exists to prevent.
    /// </para>
    /// <para>
    /// The one window nothing can close is between the server accepting the upload and this write: a crash in
    /// between leaves an entry whose change the server already holds, and the next run's version-guarded replay
    /// reports it as a conflict against a row this device itself wrote.
    /// </para>
    /// </remarks>
    /// <param name="tableName">The table the row belongs to.</param>
    /// <param name="keyText">The primary key in the text form the table's descriptor produces.</param>
    /// <param name="serverRowVersion">The version the server stamped on the row it accepted.</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    public async Task RecordAckAsync(
        string tableName,
        string keyText,
        byte[] serverRowVersion,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(tableName);
        ArgumentNullException.ThrowIfNull(keyText);
        ArgumentNullException.ThrowIfNull(serverRowVersion);
        await EnsureCreatedAsync(cancellationToken).ConfigureAwait(false);
        await _localSqlExecutor
            .ExecuteSqlAsync(
                "INSERT OR REPLACE INTO quicker_sync_ack "
                    + "(table_name, key_text, server_row_version) "
                    + "VALUES (@tableName, @keyText, @serverRowVersion)",
                new
                {
                    tableName,
                    keyText,
                    serverRowVersion,
                },
                cancellationToken
            )
            .ConfigureAwait(false);
    }

    /// <summary>Reads every acknowledgement of one table, by the key's journal text form.</summary>
    /// <param name="tableName">The table whose receipts are read.</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    public async Task<IReadOnlyDictionary<string, byte[]>> ReadAcksAsync(
        string tableName,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(tableName);
        await EnsureCreatedAsync(cancellationToken).ConfigureAwait(false);
        var rows = await _localSqlExecutor
            .QueryProjectionBySqlAsync<SyncAckRow>(
                SelectAcksSql,
                new { tableName },
                cancellationToken
            )
            .ConfigureAwait(false);
        var byKeyText = new Dictionary<string, byte[]>(StringComparer.Ordinal);

        foreach (var row in rows)
        {
            byKeyText[row.KeyText] = row.ServerRowVersion;
        }

        return byKeyText;
    }

    /// <summary>Removes the acknowledgements of the given keys (the receipt has served its purpose, or has gone stale).</summary>
    /// <remarks>The removal is chunked to <see cref="SyncInClause.ChunkSize"/> keys per statement.</remarks>
    /// <param name="tableName">The table the keys belong to.</param>
    /// <param name="keyTexts">The keys whose receipts go.</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    public async Task RemoveAcksAsync(
        string tableName,
        IReadOnlyList<string> keyTexts,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(tableName);
        ArgumentNullException.ThrowIfNull(keyTexts);

        for (var offset = 0; offset < keyTexts.Count; offset += SyncInClause.ChunkSize)
        {
            var count = Math.Min(SyncInClause.ChunkSize, keyTexts.Count - offset);
            var chunk = new List<string>(count);

            for (var index = 0; index < count; index++)
            {
                chunk.Add(keyTexts[offset + index]);
            }

            await _localSqlExecutor
                .ExecuteSqlAsync(
                    "DELETE FROM quicker_sync_ack WHERE table_name = @tableName "
                        + "AND key_text IN (@keyTexts)",
                    new { tableName, keyTexts = chunk },
                    cancellationToken
                )
                .ConfigureAwait(false);
        }
    }

    /// <summary>Removes every acknowledgement of one table (what a refresh does, having rebuilt its rows outright).</summary>
    /// <param name="tableName">The table whose receipts go.</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    public async Task RemoveTableAcksAsync(
        string tableName,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(tableName);
        await EnsureCreatedAsync(cancellationToken).ConfigureAwait(false);
        await _localSqlExecutor
            .ExecuteSqlAsync(
                "DELETE FROM quicker_sync_ack WHERE table_name = @tableName",
                new { tableName },
                cancellationToken
            )
            .ConfigureAwait(false);
    }

    /// <summary>Counts the entries still waiting to be uploaded.</summary>
    public async Task<int> CountPendingAsync(CancellationToken cancellationToken = default)
    {
        await EnsureCreatedAsync(cancellationToken).ConfigureAwait(false);

        return await _localSqlExecutor
            .ExecuteScalarSqlAsync<int>(
                "SELECT COUNT(*) FROM quicker_sync_journal",
                null,
                cancellationToken
            )
            .ConfigureAwait(false);
    }
}

/// <summary>One batch of server changes, together with whether the stream it came from has more behind it.</summary>
/// <param name="Rows">The changed rows, in ascending version order.</param>
/// <param name="HasMore">Whether asking again - from the version the last row carries - can still return something.</param>
/// <remarks>
/// The flag is the source's own answer rather than something inferred from the row count. A full batch is the usual way
/// a source says "there is more", but only the source knows: one that trims a batch to fit a transfer limit returns
/// fewer rows and still has more behind them, and inferring from the count alone would stop the download early and
/// leave the rest for a later run without saying so.
/// </remarks>
/// <typeparam name="TEntity">The entity type.</typeparam>
public sealed record SyncChangeBatch<TEntity>(IReadOnlyList<TEntity> Rows, bool HasMore)
    where TEntity : EntityBaseCore, new();

/// <summary>
/// One side's unbounded binary columns, reachable by column name so the engine can copy them without knowing the entity.
/// </summary>
/// <remarks>
/// <para>
/// The generated accessors are named after their column (<c>ReadPayloadAsync</c> and so on), which an engine written
/// against <c>TEntity</c> cannot call. Both sides expose the same narrow surface instead, and the engine copies through
/// it - which is also what lets a direct database connection and an HTTP client stand in the same place, as they do for
/// every other part of a sync run.
/// </para>
/// <para>
/// A column name outside <see cref="UnboundedBinaryColumnNames"/> is rejected rather than ignored: silently doing
/// nothing would leave the destination as it was and report the copy as done.
/// </para>
/// </remarks>
/// <typeparam name="TKey">The primary key type.</typeparam>
public interface ISyncBinaryColumns<TKey>
{
    /// <summary>The names of the columns the ordinary row transfer leaves out.</summary>
    IReadOnlyList<string> UnboundedBinaryColumnNames { get; }

    /// <summary>Reads one column into the destination stream (false = no row, or the column is NULL).</summary>
    /// <param name="columnName">One of <see cref="UnboundedBinaryColumnNames"/>.</param>
    /// <param name="id">The primary key of the row.</param>
    /// <param name="destination">The stream the column's bytes are written to.</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    Task<bool> ReadUnboundedBinaryAsync(
        string columnName,
        TKey id,
        Stream destination,
        CancellationToken cancellationToken = default
    );

    /// <summary>Writes one column from a stream, or sets it to NULL (false = no row).</summary>
    /// <param name="columnName">One of <see cref="UnboundedBinaryColumnNames"/>.</param>
    /// <param name="id">The primary key of the row.</param>
    /// <param name="source">The bytes to store, or null to set the column to NULL.</param>
    /// <param name="length">The number of bytes, required when the stream cannot report its own length.</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    Task<bool> WriteUnboundedBinaryAsync(
        string columnName,
        TKey id,
        Stream? source,
        long? length,
        CancellationToken cancellationToken = default
    );
}

/// <summary>How one unbounded binary column is read from and written to a repository that owns it.</summary>
/// <remarks>
/// The repository arrives untyped because these accessors are declared on the concrete generated contract
/// (<c>ISyncOrderRepository</c> and the like), which the fixed engine has no way to name. The generated lambda is the
/// only place that knows the type, and it casts back to it there.
/// </remarks>
/// <param name="Read">Reads the column into the destination stream (false = no row, or the column is NULL).</param>
/// <param name="Write">Writes the column from a stream, or sets it to NULL when the stream is null (false = no row).</param>
/// <typeparam name="TKey">The primary key type.</typeparam>
public sealed record SyncBinaryColumnAccessor<TKey>(
    Func<object, TKey, Stream, CancellationToken, Task<bool>> Read,
    Func<object, TKey, Stream?, long?, CancellationToken, Task<bool>> Write
);

/// <summary>Everything about one synchronised table that the journal recorder needs, with the entity's types erased.</summary>
/// <remarks>
/// The recorder walks a graph of <see cref="EntityBaseCore"/> without knowing any entity type, so it looks a node's table up
/// by its CLR type and asks the descriptor it finds for the two things a journal entry carries.
/// </remarks>
public interface ISyncTableDescriptor
{
    /// <summary>The table name, as it appears in the journal.</summary>
    string TableName { get; }

    /// <summary>The CLR entity type the table synchronises.</summary>
    Type EntityType { get; }

    /// <summary>Renders the entity's primary key into the text form the journal stores.</summary>
    /// <param name="entity">An entity of <see cref="EntityType"/>.</param>
    string FormatEntityKey(EntityBaseCore entity);

    /// <summary>Reads the mirrored server version off the entity (null for a table without a version column).</summary>
    /// <param name="entity">An entity of <see cref="EntityType"/>.</param>
    byte[]? ReadEntityRowVersion(EntityBaseCore entity);
}

/// <summary>
/// Everything about one synchronised table that depends on the diagram: its name, the SQL that carries its identity, and
/// how the key and the mirrored version are read off an entity and written back.
/// </summary>
/// <remarks>
/// <para>
/// This is the whole of what the generator emits per table. The behaviour - batching, anchor derivation, delete
/// propagation, the replay of a journal entry - lives once in the fixed classes that take a descriptor
/// (<see cref="SyncTable{TEntity, TKey}"/>, <see cref="VersionlessSyncTable{TEntity, TKey}"/>,
/// <see cref="DirectSyncSource{TEntity, TKey}"/> and its versionless counterpart), so a table contributes data rather
/// than a class of its own.
/// </para>
/// <para>
/// The SQL is text baked in at generation time rather than assembled at run time: the two dialects a sync setup spans
/// (SQL Server for the server, SQLite for the local database) quote differently, and the generator is where both are
/// known.
/// </para>
/// </remarks>
/// <typeparam name="TEntity">The entity type.</typeparam>
/// <typeparam name="TKey">The primary key type.</typeparam>
public sealed class SyncTableDescriptor<TEntity, TKey> : ISyncTableDescriptor
    where TEntity : EntityBaseCore, new()
{
    /// <inheritdoc />
    public required string TableName { get; init; }

    /// <summary>The remote endpoint route of the entity (for example "SyncOrder").</summary>
    public required string RemoteRouteName { get; init; }

    /// <summary>
    /// Whether the table has no version column - synchronised only by <see cref="SyncMode.LastWriteWins"/> runs,
    /// downloaded as a full key-ordered scan, and uploaded without version guards.
    /// </summary>
    public required bool IsVersionless { get; init; }

    /// <inheritdoc />
    public Type EntityType => typeof(TEntity);

    /// <summary>Reads the entity's primary key.</summary>
    public required Func<TEntity, TKey> ReadKey { get; init; }

    /// <summary>Writes the entity's primary key (used to build the stub a version-guarded delete is sent as).</summary>
    public required Action<TEntity, TKey> WriteKey { get; init; }

    /// <summary>Renders a primary key into the text form the journal stores.</summary>
    public required Func<TKey, string> FormatKey { get; init; }

    /// <summary>Parses a primary key back out of the journal's text form.</summary>
    public required Func<string, TKey> ParseKey { get; init; }

    /// <summary>Reads the mirrored server version off the entity.</summary>
    /// <remarks>
    /// The default answers null, which is what a table without a version column has to say: the delete entries it
    /// records carry no version, and nothing else ever asks.
    /// </remarks>
    public Func<TEntity, byte[]?> ReadRowVersion { get; init; } = static _ => null;

    /// <summary>Writes the mirrored server version onto the entity.</summary>
    /// <remarks>The default does nothing, and is never reached: only a versioned table writes a mirrored version.</remarks>
    public Action<TEntity, byte[]?> WriteRowVersion { get; init; } = static (_, _) => { };

    /// <summary>SELECT that returns every primary key of the server table (SQL Server quoting).</summary>
    public required string ServerKeysSql { get; init; }

    /// <summary>SELECT that returns one ascending batch of server rows above the anchor and below the ceiling (versioned tables).</summary>
    public string ServerChangesSql { get; init; } = string.Empty;

    /// <summary>SELECT that returns the first ascending batch of server rows by primary key (versionless tables).</summary>
    public string ServerPageFirstSql { get; init; } = string.Empty;

    /// <summary>SELECT that returns the next ascending batch of server rows above a key (versionless tables).</summary>
    public string ServerPageAfterSql { get; init; } = string.Empty;

    /// <summary>SELECT that returns the highest mirrored version among the local rows (the derived resume point).</summary>
    public string LocalAnchorSql { get; init; } = string.Empty;

    /// <summary>SELECT that returns every local primary key.</summary>
    public required string LocalKeysSql { get; init; }

    /// <summary>SELECT that returns the local primary keys within a given set (bound as the collection parameter <c>@keys</c>).</summary>
    public required string LocalExistingKeysSql { get; init; }

    /// <summary>DELETE that empties the local table (the first half of a refresh).</summary>
    public required string LocalDeleteAllSql { get; init; }

    /// <summary>The unbounded binary columns the ordinary row transfer leaves out (empty when the table has none).</summary>
    public IReadOnlyList<string> UnboundedBinaryColumnNames { get; init; } = [];

    /// <summary>The repository accessors for those columns, by column name (empty when the table has none).</summary>
    public IReadOnlyDictionary<string, SyncBinaryColumnAccessor<TKey>> UnboundedBinaryAccessors
    {
        get;
        init;
    } = new Dictionary<string, SyncBinaryColumnAccessor<TKey>>(StringComparer.Ordinal);

    /// <inheritdoc />
    public string FormatEntityKey(EntityBaseCore entity)
    {
        ArgumentNullException.ThrowIfNull(entity);

        return FormatKey(ReadKey((TEntity)entity));
    }

    /// <inheritdoc />
    public byte[]? ReadEntityRowVersion(EntityBaseCore entity)
    {
        ArgumentNullException.ThrowIfNull(entity);

        return ReadRowVersion((TEntity)entity);
    }
}

/// <summary>
/// One side's unbounded binary columns, reached by column name through the repository that owns them.
/// </summary>
/// <remarks>
/// The same class serves the local database and a directly connected server, because both are reached through a
/// generated repository; only the instance differs. A column outside the descriptor's list is rejected rather than
/// ignored, for the reason <see cref="ISyncBinaryColumns{TKey}"/> gives.
/// </remarks>
/// <typeparam name="TEntity">The entity type.</typeparam>
/// <typeparam name="TKey">The primary key type.</typeparam>
public sealed class SyncRepositoryBinaryColumns<TEntity, TKey> : ISyncBinaryColumns<TKey>
    where TEntity : EntityBaseCore, new()
{
    private readonly SyncTableDescriptor<TEntity, TKey> _descriptor;
    private readonly object _repository;

    /// <summary>Creates the surface over the table's descriptor and the repository the columns are stored in.</summary>
    /// <param name="descriptor">The table's descriptor, which names the columns and holds their accessors.</param>
    /// <param name="repository">The generated repository instance the accessors are invoked on.</param>
    public SyncRepositoryBinaryColumns(
        SyncTableDescriptor<TEntity, TKey> descriptor,
        object repository
    )
    {
        ArgumentNullException.ThrowIfNull(descriptor);
        ArgumentNullException.ThrowIfNull(repository);
        _descriptor = descriptor;
        _repository = repository;
    }

    /// <inheritdoc />
    public IReadOnlyList<string> UnboundedBinaryColumnNames =>
        _descriptor.UnboundedBinaryColumnNames;

    /// <inheritdoc />
    public Task<bool> ReadUnboundedBinaryAsync(
        string columnName,
        TKey id,
        Stream destination,
        CancellationToken cancellationToken = default
    ) => Accessor(columnName).Read(_repository, id, destination, cancellationToken);

    /// <inheritdoc />
    public Task<bool> WriteUnboundedBinaryAsync(
        string columnName,
        TKey id,
        Stream? source,
        long? length,
        CancellationToken cancellationToken = default
    ) => Accessor(columnName).Write(_repository, id, source, length, cancellationToken);

    /// <summary>Looks the accessors of one column up, refusing a name the table does not have.</summary>
    private SyncBinaryColumnAccessor<TKey> Accessor(string columnName) =>
        _descriptor.UnboundedBinaryAccessors.TryGetValue(columnName, out var accessor)
            ? accessor
            : throw new ArgumentOutOfRangeException(
                nameof(columnName),
                columnName,
                "The column is not an unbounded binary column of this table."
            );
}

/// <summary>
/// The server side of the differential source for one entity type: where changed rows, the change ceiling, and the key
/// set come from, and which repository the local changes are replayed against.
/// </summary>
/// <remarks>
/// The engine never talks to the server directly, so a second implementation (over HTTP, say) can replace the direct
/// one without the engine changing. The generated direct implementation reads through the server's raw SQL surface and
/// writes through the server's ordinary repository.
/// </remarks>
/// <typeparam name="TEntity">The entity type.</typeparam>
/// <typeparam name="TKey">The primary key type.</typeparam>
public interface ISyncServerSource<TEntity, TKey>
    where TEntity : EntityBaseCore, new()
{
    /// <summary>
    /// Gets the exclusive upper bound for this pass: the lowest version of any transaction still in flight.
    /// </summary>
    /// <remarks>
    /// A row committed later can carry a lower version than one committed earlier, so reading up to "the current
    /// maximum" would step over rows that are still uncommitted and never come back for them. Stopping below the
    /// oldest active transaction is what makes the derived anchor (the local mirror's maximum) safe to resume from.
    /// </remarks>
    Task<byte[]?> GetChangeCeilingAsync(CancellationToken cancellationToken = default);

    /// <summary>Gets the rows whose version is above <paramref name="anchor"/> and below <paramref name="ceiling"/>, in ascending version order.</summary>
    /// <param name="anchor">The resume point (null on the first pass, which takes everything below the ceiling).</param>
    /// <param name="ceiling">The exclusive upper bound from <see cref="GetChangeCeilingAsync"/>.</param>
    /// <param name="batchSize">The maximum number of rows to return.</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    Task<SyncChangeBatch<TEntity>> GetChangesAsync(
        byte[]? anchor,
        byte[]? ceiling,
        int batchSize,
        CancellationToken cancellationToken = default
    );

    /// <summary>Gets the first batch of rows in ascending primary-key order (the versionless full scan).</summary>
    /// <remarks>
    /// A table without a version column has no change stream to resume, so its download reads every row, paged by the
    /// primary key. The default refuses rather than answers: a source written for a versioned table has no key-ordered
    /// SQL to serve it with, and only the generated versionless sources override it.
    /// </remarks>
    /// <param name="batchSize">The maximum number of rows to return.</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    Task<SyncChangeBatch<TEntity>> GetFirstPageAsync(
        int batchSize,
        CancellationToken cancellationToken = default
    ) =>
        throw new NotSupportedException(
            "This source does not page by primary key; it serves a versioned table."
        );

    /// <summary>Gets the next batch of rows whose primary key is above <paramref name="afterKey"/>, in ascending key order.</summary>
    /// <param name="afterKey">The last key of the previous batch (the exclusive lower bound).</param>
    /// <param name="batchSize">The maximum number of rows to return.</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    Task<SyncChangeBatch<TEntity>> GetPageAfterAsync(
        TKey afterKey,
        int batchSize,
        CancellationToken cancellationToken = default
    ) =>
        throw new NotSupportedException(
            "This source does not page by primary key; it serves a versioned table."
        );

    /// <summary>Gets every primary key the server holds for this table (the input to delete propagation).</summary>
    Task<IReadOnlyList<TKey>> GetAllKeysAsync(CancellationToken cancellationToken = default);

    /// <summary>The repository the local changes are replayed against.</summary>
    /// <remarks>
    /// The remote surface rather than the full one: replaying a journal entry only ever reads a row by key, inserts,
    /// updates, saves, or deletes it, and those are exactly the operations that can cross a network boundary. Asking for
    /// no more than that is what lets an HTTP client stand here beside a direct repository, which satisfies the narrower
    /// contract as well.
    /// </remarks>
    IRemoteRepositoryCore<TEntity, TKey> Writer { get; }

    /// <summary>The server's unbounded binary columns, or null when the table has none to copy.</summary>
    /// <remarks>
    /// Null is the answer for every table generated without the unbounded binary columns excluded, which is why it is
    /// the default: a source written before there was anything to copy still satisfies the contract, and a run that asks
    /// for the columns simply finds none.
    /// </remarks>
    ISyncBinaryColumns<TKey>? BinaryColumns => null;
}

/// <summary>What one table's download knows about the local changes of the run it belongs to.</summary>
/// <remarks>
/// <para>
/// Both halves are about the same thing: a download must not undo what the run's own upload has just done, and must not
/// undo what the upload could not do either.
/// </para>
/// <para>
/// <see cref="PendingKeyTexts"/> holds the keys whose local change is still in the journal - a collected conflict, or an
/// entry a failure left behind. The row behind such a key carries local content nobody has agreed to give up, so the
/// download stops there rather than overwriting it.
/// </para>
/// <para>
/// <see cref="AcknowledgedRowVersions"/> holds the version the server stamped on each row this device has uploaded and
/// not yet seen come back. Such a row comes back down as a change like any other, and applying it would be writing the
/// row's own content over itself; only the version is worth keeping, and that is all the download writes for it.
/// </para>
/// </remarks>
public sealed record SyncDownloadContext
{
    /// <summary>A download that knows of no unsent local change and of no outstanding acknowledgement.</summary>
    public static SyncDownloadContext Empty { get; } = new();

    /// <summary>The keys of this table that still hold an unsent journal entry.</summary>
    public IReadOnlySet<string> PendingKeyTexts { get; init; } =
        new HashSet<string>(StringComparer.Ordinal);

    /// <summary>The acknowledged server version of each uploaded row awaiting its echo, by the key's journal text form.</summary>
    public IReadOnlyDictionary<string, byte[]> AcknowledgedRowVersions { get; init; } =
        new Dictionary<string, byte[]>(StringComparer.Ordinal);
}

/// <summary>What one table's download did.</summary>
/// <param name="Applied">The number of server rows applied locally (a row recognised as this device's own echo is not one of them).</param>
/// <param name="TruncatedAtKeyText">The key the download stopped at because its local change is still unsent, or null when the table was drained.</param>
/// <param name="SettledAckKeyTexts">The acknowledged keys whose mirrored version this download has brought up to date, so their receipts can go.</param>
/// <remarks>
/// The settled keys are handed back rather than cleared here because the clearing has to follow the local commit that
/// wrote the versions: a receipt dropped before the commit that replaces it, and a commit that then fails, is the
/// "no receipt, stale mirror" state all over again. The opposite order leaves a receipt behind for a row that no longer
/// needs one, which the next run recognises as an echo, writes the same version for, and clears - a state that repairs
/// itself.
/// </remarks>
public readonly record struct SyncDownloadOutcome(
    int Applied,
    string? TruncatedAtKeyText,
    IReadOnlyList<string> SettledAckKeyTexts
)
{
    /// <summary>An outcome with no receipt to settle (what a table that carries no acknowledgements returns).</summary>
    /// <param name="applied">The number of server rows applied locally.</param>
    /// <param name="truncatedAtKeyText">The key the download stopped at, or null when the table was drained.</param>
    public SyncDownloadOutcome(int applied, string? truncatedAtKeyText)
        : this(applied, truncatedAtKeyText, []) { }
}

/// <summary>One row a <see cref="SyncConflictPolicy.ServerWins"/> upload wrote the server's copy over.</summary>
/// <param name="KeyText">The primary key in the text form the table's descriptor produces.</param>
/// <param name="ServerRowVersion">The version the server's copy carried when it was read, or null when it had none.</param>
/// <remarks>
/// The version reported is the server's own, not the one written onto the local row - that one is deliberately left
/// where it was. So nothing about the row itself says that its local content is the server's content at that version,
/// and the run records the pair as an acknowledgement instead.
/// </remarks>
public readonly record struct SyncAppliedServerRow(string KeyText, byte[]? ServerRowVersion);

/// <summary>The engine's view of one synchronised table, with the entity's own types erased.</summary>
public interface ISyncTable
{
    /// <summary>The table name, as it appears in the journal.</summary>
    string TableName { get; }

    /// <summary>The CLR entity type the table synchronises (what the exclusion lists are matched against).</summary>
    Type EntityType { get; }

    /// <summary>
    /// Whether the table has no version column - synchronised only by <see cref="SyncMode.LastWriteWins"/> runs,
    /// downloaded as a full key-ordered scan, and uploaded without version guards.
    /// </summary>
    bool IsVersionless { get; }

    /// <summary>The unbounded binary columns the ordinary row transfer leaves out (empty when the table has none).</summary>
    /// <remarks>
    /// The engine reads this to decide whether a refresh has local blobs to lose, and callers can read it to see which
    /// columns <c>SyncOptions.IncludeUnboundedBinary</c> would carry.
    /// </remarks>
    IReadOnlyList<string> UnboundedBinaryColumnNames { get; }

    /// <summary>Gets the server's change ceiling (the engine asks one table and uses the answer for all of them).</summary>
    Task<byte[]?> GetChangeCeilingAsync(CancellationToken cancellationToken = default);

    /// <summary>Pulls every server change below the ceiling into the local database and returns the number of rows applied.</summary>
    /// <remarks>
    /// A download that knows nothing of the run's local changes: it applies every row it is given. Inside a run the
    /// engine calls the overload that takes a <see cref="SyncDownloadContext"/> instead.
    /// </remarks>
    Task<int> DownloadAsync(
        byte[]? ceiling,
        int batchSize,
        bool includeUnboundedBinary,
        CancellationToken cancellationToken = default
    );

    /// <summary>Pulls the server's changes down under what the run knows about its own local changes.</summary>
    /// <param name="ceiling">The exclusive upper bound of the pass.</param>
    /// <param name="batchSize">How many rows one batch fetches and applies in a single local transaction.</param>
    /// <param name="includeUnboundedBinary">Whether the excluded unbounded binary columns are carried as well.</param>
    /// <param name="context">The table's unsent local changes and its outstanding acknowledgements.</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    /// <remarks>
    /// The default answers as the context-free overload does, applying every row and never stopping early - the only
    /// sound answer for an implementation that has no way to tell a row with an unsent local change from any other.
    /// </remarks>
    async Task<SyncDownloadOutcome> DownloadAsync(
        byte[]? ceiling,
        int batchSize,
        bool includeUnboundedBinary,
        SyncDownloadContext context,
        CancellationToken cancellationToken = default
    ) =>
        new(
            await DownloadAsync(ceiling, batchSize, includeUnboundedBinary, cancellationToken)
                .ConfigureAwait(false),
            null
        );

    /// <summary>Overwrites the named local rows with the server's copies.</summary>
    /// <param name="keyTexts">The keys, in the journal's text form, whose local content is to give way to the server's.</param>
    /// <param name="includeUnboundedBinary">Whether the excluded unbounded binary columns are carried down as well.</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    /// <remarks>
    /// <para>
    /// What <see cref="SyncConflictPolicy.ServerWins"/> is made of. Dropping the journal entry only stops the local
    /// change from being sent; the row keeps the content the entry was about, and the download brings nothing down for
    /// a row the server has not changed since it was last mirrored. The server's row is therefore read back and
    /// written over the local one, which is what "the server wins" says. A key the server no longer holds has nothing
    /// to apply, and is left to the delete propagation - so with propagation turned off that row stays as it is.
    /// </para>
    /// <para>
    /// <b>The mirrored version is left exactly where it was.</b> The row read from the server carries the server's
    /// current version, and writing that onto the local row would raise the derived resume point to it - past every
    /// row of the ordered stream this device has not seen, none of which any later run would ask for again. The
    /// content is applied and the version is not, so the next download reaches the row in its proper order and writes
    /// the version then; applying the same content a second time costs nothing.
    /// </para>
    /// <para>
    /// <b>Which is why the applied rows are reported back.</b> With the mirrored version left behind, nothing on the
    /// device records that the row's local content is the server's content at the version just read - and no download
    /// need ever supply it: a row restored under a server version at or below the derived resume point is one the
    /// ordered stream has already passed. Replaying a later edit to such a row would then find no version to guard it
    /// with and take it for a row that has never been on the server, which the server answers by already having it.
    /// The caller records the pairs as acknowledgements, and the replay reads its original from those too.
    /// </para>
    /// <para>
    /// The default applies nothing, the only sound answer for an implementation with no server of its own to read.
    /// </para>
    /// </remarks>
    /// <returns>The key and the server's version of every row applied, in the order they were applied.</returns>
    Task<IReadOnlyList<SyncAppliedServerRow>> ApplyServerRowsAsync(
        IReadOnlyList<string> keyTexts,
        bool includeUnboundedBinary,
        CancellationToken cancellationToken = default
    ) => Task.FromResult<IReadOnlyList<SyncAppliedServerRow>>([]);

    /// <summary>Deletes the local rows whose key the server no longer has, and returns the keys that went.</summary>
    /// <param name="pendingKeyTexts">The keys of this table that still hold an unsent journal entry; they are left alone.</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    /// <remarks>
    /// <para>
    /// A key the journal still holds an entry for is not treated as one the server dropped. The entry is a local
    /// intention this run has not settled - a conflict it collected, or a change it never reached - and deleting the row
    /// underneath it would resolve that in the server's favour without saying so, which is exactly what
    /// <see cref="SyncConflictPolicy.Collect"/> promises not to do. Once the entry is settled - uploaded, discarded as a
    /// stale intent, or dropped by <see cref="SyncConflictPolicy.ServerWins"/> - the next run propagates the deletion as
    /// usual.
    /// </para>
    /// <para>
    /// The protection reaches exactly as far as the journal does. A row written without going through the generated
    /// repositories - raw SQL, most of all - has no entry to hold it back and is deleted like any other row the server
    /// does not have (see <see cref="SyncOptions.PropagateDeletes"/>).
    /// </para>
    /// <para>
    /// The keys are returned rather than counted because a row the server has dropped invalidates whatever else was
    /// recorded about it - its acknowledgement most of all, which would otherwise send the next replay of that key
    /// against a version of a row that is gone.
    /// </para>
    /// </remarks>
    Task<IReadOnlyList<string>> PropagateDeletesAsync(
        IReadOnlySet<string> pendingKeyTexts,
        CancellationToken cancellationToken = default
    );

    /// <summary>Removes every local row of this table and returns how many went (the first half of a refresh).</summary>
    Task<int> DeleteAllLocalAsync(CancellationToken cancellationToken = default);

    /// <summary>Writes every server row below the ceiling into the emptied local table and returns how many arrived.</summary>
    Task<int> RefreshAsync(
        byte[]? ceiling,
        int batchSize,
        bool includeUnboundedBinary,
        CancellationToken cancellationToken = default
    );

    /// <summary>Replays one journal entry against the server.</summary>
    /// <param name="entry">The journal entry to replay.</param>
    /// <param name="mode">The run's mode; <see cref="SyncMode.LastWriteWins"/> replays without version guards and ignores <paramref name="policy"/>.</param>
    /// <param name="policy">How a collision with the server is treated (versioned mode only).</param>
    /// <param name="includeUnboundedBinary">Whether the excluded unbounded binary columns are carried as well.</param>
    /// <param name="acknowledgedRowVersion">The version the server last acknowledged for this key, or null when there is no receipt.</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    /// <remarks>
    /// A version-guarded replay guards against the later of the mirrored version and the acknowledged one. The mirror
    /// is the row's version as of the last download that reached it, the receipt is its version as of the last upload
    /// the server took, and either can be the more recent - the mirror when the receipt has already been cleared, the
    /// receipt when the echo has not come down yet.
    /// </remarks>
    Task<SyncUploadOutcome> UploadAsync(
        SyncJournalRow entry,
        SyncMode mode,
        SyncConflictPolicy policy,
        bool includeUnboundedBinary,
        byte[]? acknowledgedRowVersion,
        CancellationToken cancellationToken = default
    );
}

/// <summary>
/// The shared half of one synchronised table: the pieces that do not depend on whether the table carries a version
/// column - batch application, delete propagation, the local wipe of a refresh, the unbounded-binary column copy,
/// and the last-write-wins replay of a journal entry.
/// </summary>
/// <remarks>
/// The two shapes a table can take derive from this: <see cref="SyncTable{TEntity, TKey}"/> for a table with a
/// version column (incremental download, version-guarded replay) and <see cref="VersionlessSyncTable{TEntity, TKey}"/>
/// for one without (full key-ordered download, last-write-wins replay). They are classes rather than a flag because
/// the two differ in what they are able to promise, not in how they are configured.
/// </remarks>
/// <typeparam name="TEntity">The entity type.</typeparam>
/// <typeparam name="TKey">The primary key type.</typeparam>
public abstract class SyncTableBase<TEntity, TKey> : ISyncTable
    where TEntity : EntityBaseCore, new()
{
    /// <summary>The local repository, reached through the journaling decorator (engine writes suppress the recording).</summary>
    protected readonly IRepositoryCore<TEntity, TKey> _local;

    /// <summary>The local raw SQL surface (key sets, the derived anchor, the wipe of a refresh).</summary>
    protected readonly ISqlExecutor _localSqlExecutor;

    /// <summary>The server side: where changed rows and key sets come from, and where local changes are replayed to.</summary>
    protected readonly ISyncServerSource<TEntity, TKey> _server;

    /// <summary>The table's generated descriptor (its name, its SQL, and how a key and a version are read and written).</summary>
    protected readonly SyncTableDescriptor<TEntity, TKey> _descriptor;

    /// <summary>The local side's unbounded binary columns, built once because a copy asks for them per row.</summary>
    private readonly ISyncBinaryColumns<TKey>? _localBinaryColumns;

    /// <summary>Creates the table with its local repository, the local raw SQL surface, the server source, and its descriptor.</summary>
    protected SyncTableBase(
        IRepositoryCore<TEntity, TKey> local,
        ISqlExecutor localSqlExecutor,
        ISyncServerSource<TEntity, TKey> server,
        SyncTableDescriptor<TEntity, TKey> descriptor
    )
    {
        ArgumentNullException.ThrowIfNull(local);
        ArgumentNullException.ThrowIfNull(localSqlExecutor);
        ArgumentNullException.ThrowIfNull(server);
        ArgumentNullException.ThrowIfNull(descriptor);
        _local = local;
        _localSqlExecutor = localSqlExecutor;
        _server = server;
        _descriptor = descriptor;
        _localBinaryColumns =
            descriptor.UnboundedBinaryColumnNames.Count == 0
                ? null
                : new SyncRepositoryBinaryColumns<TEntity, TKey>(descriptor, local);
    }

    /// <inheritdoc />
    public string TableName => _descriptor.TableName;

    /// <inheritdoc />
    public Type EntityType => typeof(TEntity);

    /// <inheritdoc />
    public bool IsVersionless => _descriptor.IsVersionless;

    /// <summary>The local side's unbounded binary columns, or null when the table has none.</summary>
    /// <remarks>
    /// Null exactly when the descriptor names no such column; the two sides are asked separately because either one can
    /// be absent, and a copy needs both.
    /// </remarks>
    protected ISyncBinaryColumns<TKey>? LocalBinaryColumns => _localBinaryColumns;

    /// <inheritdoc />
    /// <remarks>
    /// The descriptor's own list, which is also what the local copy iterates, so the names the engine reads and the
    /// names the copy walks cannot come apart.
    /// </remarks>
    public IReadOnlyList<string> UnboundedBinaryColumnNames =>
        _descriptor.UnboundedBinaryColumnNames;

    /// <summary>SELECT that returns every local primary key.</summary>
    protected string LocalKeysSql => _descriptor.LocalKeysSql;

    /// <summary>SELECT that returns the local primary keys within a given set (bound as the collection parameter <c>@keys</c>).</summary>
    protected string LocalExistingKeysSql => _descriptor.LocalExistingKeysSql;

    /// <summary>DELETE that empties the local table (the first half of a refresh).</summary>
    protected string LocalDeleteAllSql => _descriptor.LocalDeleteAllSql;

    /// <summary>Reads the entity's primary key.</summary>
    protected TKey ReadKey(TEntity entity) => _descriptor.ReadKey(entity);

    /// <summary>Writes the entity's primary key (used to build the stub a version-guarded delete is sent as).</summary>
    protected void WriteKey(TEntity entity, TKey key) => _descriptor.WriteKey(entity, key);

    /// <summary>Renders a primary key into the text form the journal stores.</summary>
    public string FormatKey(TKey key) => _descriptor.FormatKey(key);

    /// <summary>Parses a primary key back out of the journal's text form.</summary>
    public TKey ParseKey(string keyText) => _descriptor.ParseKey(keyText);

    /// <inheritdoc />
    public virtual Task<byte[]?> GetChangeCeilingAsync(
        CancellationToken cancellationToken = default
    ) => _server.GetChangeCeilingAsync(cancellationToken);

    /// <inheritdoc />
    public abstract Task<int> DownloadAsync(
        byte[]? ceiling,
        int batchSize,
        bool includeUnboundedBinary,
        CancellationToken cancellationToken = default
    );

    /// <inheritdoc />
    public abstract Task<SyncDownloadOutcome> DownloadAsync(
        byte[]? ceiling,
        int batchSize,
        bool includeUnboundedBinary,
        SyncDownloadContext context,
        CancellationToken cancellationToken = default
    );

    /// <inheritdoc />
    public abstract Task<int> RefreshAsync(
        byte[]? ceiling,
        int batchSize,
        bool includeUnboundedBinary,
        CancellationToken cancellationToken = default
    );

    /// <inheritdoc />
    public abstract Task<SyncUploadOutcome> UploadAsync(
        SyncJournalRow entry,
        SyncMode mode,
        SyncConflictPolicy policy,
        bool includeUnboundedBinary,
        byte[]? acknowledgedRowVersion,
        CancellationToken cancellationToken = default
    );

    /// <summary>The later of two server versions (null and empty both mean "no version at all").</summary>
    /// <remarks>
    /// A version is an unsigned big-endian integer, so the comparison is the lexicographic one over the significant
    /// bytes, with a longer significant run standing for the larger number. Taking the maximum rather than preferring
    /// one side is what keeps the choice safe in both directions: a receipt already cleared leaves the mirror ahead,
    /// and an echo that has not come down leaves the receipt ahead.
    /// </remarks>
    /// <param name="left">One version, or null.</param>
    /// <param name="right">The other version, or null.</param>
    private protected static byte[]? MaxRowVersion(byte[]? left, byte[]? right)
    {
        if (left is not { Length: > 0 })
        {
            return right is { Length: > 0 } ? right : null;
        }

        if (right is not { Length: > 0 })
        {
            return left;
        }

        return CompareRowVersions(left, right) >= 0 ? left : right;
    }

    /// <summary>Compares two non-empty versions as unsigned big-endian integers.</summary>
    private static int CompareRowVersions(byte[] left, byte[] right)
    {
        var leftStart = FirstSignificantByte(left);
        var rightStart = FirstSignificantByte(right);
        var leftLength = left.Length - leftStart;
        var rightLength = right.Length - rightStart;

        if (leftLength != rightLength)
        {
            return leftLength < rightLength ? -1 : 1;
        }

        for (var index = 0; index < leftLength; index++)
        {
            var difference = left[leftStart + index].CompareTo(right[rightStart + index]);

            if (difference != 0)
            {
                return difference;
            }
        }

        return 0;
    }

    /// <summary>The offset of the first non-zero byte (the length itself when every byte is zero).</summary>
    private static int FirstSignificantByte(byte[] value)
    {
        var index = 0;

        while (index < value.Length && value[index] == 0)
        {
            index++;
        }

        return index;
    }

    /// <summary>
    /// Replays one journal entry without version guards: the local change overwrites whatever the server holds.
    /// </summary>
    /// <remarks>
    /// One code path for every table. An upsert re-reads the current local row (nothing to send is a stale intent,
    /// discarded), overwrites the server's row with <see cref="ConcurrencyMode.ForceOverwrite"/>, and inserts it when
    /// the update finds no row - which also means a row deleted on the server is resurrected by a local edit, exactly
    /// what last-write-wins promises. A delete needs no version, but it does re-read the local row for the reason an
    /// upsert does: a row that is still there says the business delete never landed, which makes the entry a stale
    /// intent rather than something to carry out on the server. A delete of a row the server no longer has is a no-op.
    /// Nothing can conflict, so nothing is ever collected.
    /// </remarks>
    protected async Task<SyncUploadOutcome> UploadLastWriteWinsAsync(
        SyncJournalRow entry,
        bool includeUnboundedBinary,
        CancellationToken cancellationToken
    )
    {
        var key = ParseKey(entry.KeyText);

        if (
            string.Equals(
                entry.Operation,
                nameof(SyncJournalOperation.Delete),
                StringComparison.Ordinal
            )
        )
        {
            if (await LocalRowSurvivedDeleteAsync(key, cancellationToken).ConfigureAwait(false))
            {
                return SyncUploadOutcome.Discarded;
            }

            await _server.Writer.DeleteAsync(key, cancellationToken).ConfigureAwait(false);

            return SyncUploadOutcome.Uploaded;
        }

        var local = await _local.GetByIdAsync(key, cancellationToken).ConfigureAwait(false);

        if (local is null)
        {
            // A journal-first entry whose business write never landed, or a row deleted afterwards. Nothing to send.
            return SyncUploadOutcome.Discarded;
        }

        await ForceOverwriteOrInsertAsync(local, cancellationToken).ConfigureAwait(false);

        if (includeUnboundedBinary)
        {
            await CopyBinaryColumnsUpAsync(key, cancellationToken).ConfigureAwait(false);
        }

        return SyncUploadOutcome.UploadedWith(
            await ReadServerRowVersionAsync(local, includeUnboundedBinary, cancellationToken)
                .ConfigureAwait(false)
        );
    }

    /// <summary>Reads the version the server now holds for a row an upsert has just sent.</summary>
    /// <remarks>
    /// The writer stamps the row it accepted, so the entity in hand already carries the new version. Writing a blob is
    /// another write to the same row, so where the excluded columns were carried the stamp in hand is behind by one and
    /// the server row is read once more. A table without a version column has nothing to report.
    /// </remarks>
    /// <param name="local">The row that was sent, as the writer left it.</param>
    /// <param name="includeUnboundedBinary">Whether the excluded unbounded binary columns were carried as well.</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    private protected async Task<byte[]?> ReadServerRowVersionAsync(
        TEntity local,
        bool includeUnboundedBinary,
        CancellationToken cancellationToken
    )
    {
        if (IsVersionless)
        {
            return null;
        }

        if (includeUnboundedBinary && UnboundedBinaryColumnNames.Count > 0)
        {
            var refreshed = await _server
                .Writer.GetByIdAsync(ReadKey(local), cancellationToken)
                .ConfigureAwait(false);

            if (refreshed is not null)
            {
                return _descriptor.ReadRowVersion(refreshed);
            }
        }

        return _descriptor.ReadRowVersion(local);
    }

    /// <summary>Overwrites the server's row without a version guard, inserting it when the update finds no row.</summary>
    /// <remarks>
    /// The two halves belong together: an update that matches nothing means the server no longer holds the row, and
    /// putting it back is what "the local change wins" amounts to. Shared by the last-write-wins replay and by the
    /// <see cref="SyncConflictPolicy.LocalWins"/> resolution of a version-guarded one, so the two say the same thing.
    /// </remarks>
    /// <param name="local">The current local row, which becomes the server's.</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    private protected async Task ForceOverwriteOrInsertAsync(
        TEntity local,
        CancellationToken cancellationToken
    )
    {
        local.MarkUpdated();
        var updated = await _server
            .Writer.UpdateAsync(local, ConcurrencyMode.ForceOverwrite, cancellationToken)
            .ConfigureAwait(false);

        if (!updated)
        {
            local.MarkAdded();
            await _server.Writer.InsertAsync(local, cancellationToken).ConfigureAwait(false);
        }
    }

    /// <summary>Whether the local row a delete entry speaks for is still there (the delete never landed).</summary>
    /// <remarks>
    /// The journal records the intent before the business delete runs, so an entry can outlive a delete a foreign key
    /// or a lock refused. Removing the server's row on the strength of such an entry would let a failed local
    /// operation finish itself on the server - and the delete propagation of the same run would then take the
    /// surviving local row with it. An upsert is already protected by re-reading the row it sends; this is the same
    /// guard for the one operation that has nothing to re-read.
    /// </remarks>
    /// <param name="key">The key the entry names.</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    private protected async Task<bool> LocalRowSurvivedDeleteAsync(
        TKey key,
        CancellationToken cancellationToken
    ) => await _local.GetByIdAsync(key, cancellationToken).ConfigureAwait(false) is not null;

    /// <summary>Copies every unbounded binary column of the given rows from the server down to the local database.</summary>
    /// <remarks>
    /// Suppressed as a whole: the local write goes through the journaling decorator like any other, and a downloaded
    /// blob recorded as a local change would be uploaded straight back on the next run.
    /// </remarks>
    protected async Task CopyBinaryColumnsDownAsync(
        IReadOnlyList<TEntity> rows,
        CancellationToken cancellationToken
    )
    {
        if (_server.BinaryColumns is not { } server || LocalBinaryColumns is not { } local)
        {
            return;
        }

        using (SyncSession.Suppress())
        {
            foreach (var row in rows)
            {
                var key = ReadKey(row);

                foreach (var column in local.UnboundedBinaryColumnNames)
                {
                    await CopyBinaryColumnAsync(server, local, column, key, cancellationToken)
                        .ConfigureAwait(false);
                }
            }
        }
    }

    /// <summary>Copies every unbounded binary column of one row from the local database up to the server.</summary>
    protected async Task CopyBinaryColumnsUpAsync(TKey key, CancellationToken cancellationToken)
    {
        if (_server.BinaryColumns is not { } server || LocalBinaryColumns is not { } local)
        {
            return;
        }

        using (SyncSession.Suppress())
        {
            foreach (var column in local.UnboundedBinaryColumnNames)
            {
                await CopyBinaryColumnAsync(local, server, column, key, cancellationToken)
                    .ConfigureAwait(false);
            }
        }
    }

    /// <summary>Copies one column of one row from one side to the other.</summary>
    /// <remarks>
    /// <para>
    /// The two accessors meet in the middle rather than end to end: reading pushes the bytes into a stream that is
    /// handed to it, writing pulls them out of a stream that is handed to it, and a stream cannot be both. A temporary
    /// file is what joins them without either side holding the blob in memory - and it answers the other question the
    /// write asks, since a length has to be known up front and the finished file reports its own. It lives in the
    /// operating system's temporary folder and is removed once the column has been written.
    /// </para>
    /// <para>
    /// A source column that is NULL (or a row the source no longer has) clears the destination rather than leaving what
    /// was there: the point of carrying these columns is that the two sides end up alike, and a stale blob under a row
    /// whose server copy has none is exactly the disagreement this is here to remove.
    /// </para>
    /// </remarks>
    private static async Task CopyBinaryColumnAsync(
        ISyncBinaryColumns<TKey> from,
        ISyncBinaryColumns<TKey> to,
        string columnName,
        TKey key,
        CancellationToken cancellationToken
    )
    {
        var path = Path.Combine(
            Path.GetTempPath(),
            "quicker-sync-" + Guid.NewGuid().ToString("n") + ".tmp"
        );

        try
        {
            bool present;

            await using (
                var destination = new FileStream(
                    path,
                    FileMode.Create,
                    FileAccess.Write,
                    FileShare.None,
                    bufferSize: 81920,
                    useAsync: true
                )
            )
            {
                present = await from.ReadUnboundedBinaryAsync(
                    columnName,
                    key,
                    destination,
                    cancellationToken
                )
                    .ConfigureAwait(false);
            }

            if (!present)
            {
                await to.WriteUnboundedBinaryAsync(columnName, key, null, null, cancellationToken)
                    .ConfigureAwait(false);

                return;
            }

            await using var source = new FileStream(
                path,
                FileMode.Open,
                FileAccess.Read,
                FileShare.Read,
                bufferSize: 81920,
                useAsync: true
            );
            await to.WriteUnboundedBinaryAsync(
                columnName,
                key,
                source,
                source.Length,
                cancellationToken
            )
                .ConfigureAwait(false);
        }
        finally
        {
            // Swallowed on purpose: this runs while an exception from the copy itself may be in flight, and letting a
            // failure to delete replace it would erase why the copy failed. What is lost by ignoring it is one
            // temporary file left in the operating system's temporary folder.
            try
            {
                File.Delete(path);
            }
            catch
            {
                // Nothing to do here - see above.
            }
        }
    }

    /// <summary>Applies one ordered batch of server rows to the local database inside a single transaction.</summary>
    /// <remarks>
    /// The lookup that decides insert from update is chunked to <see cref="SyncInClause.ChunkSize"/> keys per
    /// statement; the batch size is the caller's to choose, so the list of keys is not bounded on its own.
    /// </remarks>
    protected async Task ApplyBatchAsync(
        IReadOnlyList<TEntity> rows,
        bool includeUnboundedBinary,
        CancellationToken cancellationToken
    )
    {
        var keys = rows.Select(ReadKey).ToList();
        var existingKeys = new HashSet<string>(StringComparer.Ordinal);

        for (var offset = 0; offset < keys.Count; offset += SyncInClause.ChunkSize)
        {
            var count = Math.Min(SyncInClause.ChunkSize, keys.Count - offset);
            var chunk = new List<TKey>(count);

            for (var index = 0; index < count; index++)
            {
                chunk.Add(keys[offset + index]);
            }

            var existing = await _localSqlExecutor
                .QueryProjectionBySqlAsync<TKey>(
                    LocalExistingKeysSql,
                    new { keys = chunk },
                    cancellationToken
                )
                .ConfigureAwait(false);

            foreach (var key in existing)
            {
                existingKeys.Add(FormatKey(key));
            }
        }

        foreach (var row in rows)
        {
            if (existingKeys.Contains(FormatKey(ReadKey(row))))
            {
                row.MarkUpdated();
            }
            else
            {
                row.MarkAdded();
            }
        }

        // One graph save per batch is what makes the batch atomic; the applied rows are flat, so no cascade is wanted.
        // ForceOverwrite is deliberate: the server's row is the truth here, and the local engine has no version to guard.
        using (SyncSession.Suppress())
        {
            await _local
                .SaveAsync(
                    rows,
                    cascadeSave: false,
                    cascadeDelete: false,
                    insertWhenUpdateMissing: false,
                    ConcurrencyMode.ForceOverwrite,
                    cancellationToken
                )
                .ConfigureAwait(false);
        }

        // After the rows, not with them: an excluded column is not part of the row, and the copy needs the row to be
        // there to write into.
        if (includeUnboundedBinary)
        {
            await CopyBinaryColumnsDownAsync(rows, cancellationToken).ConfigureAwait(false);
        }
    }

    /// <inheritdoc />
    /// <remarks>
    /// The rows go through the same batch application a download uses, so a key the local database does not have is
    /// put back rather than skipped - a row deleted locally and still held by the server returns, which is the
    /// server winning over a delete exactly as it wins over an edit. A restored row carries no mirrored version until
    /// a download reaches it in order: it may not have one to keep, and the server's own is the one version that must
    /// not be written here.
    /// </remarks>
    public async Task<IReadOnlyList<SyncAppliedServerRow>> ApplyServerRowsAsync(
        IReadOnlyList<string> keyTexts,
        bool includeUnboundedBinary,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(keyTexts);

        var rows = new List<TEntity>(keyTexts.Count);
        var applied = new List<SyncAppliedServerRow>(keyTexts.Count);

        foreach (var keyText in keyTexts)
        {
            cancellationToken.ThrowIfCancellationRequested();

            var key = ParseKey(keyText);
            var server = await _server
                .Writer.GetByIdAsync(key, cancellationToken)
                .ConfigureAwait(false);

            if (server is null)
            {
                continue;
            }

            // Read before it is replaced: this is the version the content about to be applied belongs to, and the
            // only place it survives the write below.
            var serverRowVersion = _descriptor.ReadRowVersion(server);

            // The version has to keep saying how far this device's ordered stream reached, so the local row's own is
            // put back onto the server's copy before it is applied - see the interface for what writing the server's
            // would cost. A row the local database does not have keeps whatever the descriptor makes of "no version",
            // which is the same thing a row created locally starts with.
            var local = await _local.GetByIdAsync(key, cancellationToken).ConfigureAwait(false);
            _descriptor.WriteRowVersion(
                server,
                local is null ? null : _descriptor.ReadRowVersion(local)
            );
            rows.Add(server);
            applied.Add(new SyncAppliedServerRow(keyText, serverRowVersion));
        }

        if (rows.Count == 0)
        {
            return applied;
        }

        await ApplyBatchAsync(rows, includeUnboundedBinary, cancellationToken)
            .ConfigureAwait(false);

        // Reported only once the batch is in: a row whose application never committed is not one anything should be
        // recorded about.
        return applied;
    }

    /// <inheritdoc />
    public async Task<IReadOnlyList<string>> PropagateDeletesAsync(
        IReadOnlySet<string> pendingKeyTexts,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(pendingKeyTexts);

        var serverKeys = await _server.GetAllKeysAsync(cancellationToken).ConfigureAwait(false);
        var serverKeyTexts = serverKeys.Select(FormatKey).ToHashSet(StringComparer.Ordinal);
        var localKeys = await _localSqlExecutor
            .QueryProjectionBySqlAsync<TKey>(LocalKeysSql, null, cancellationToken)
            .ConfigureAwait(false);

        var removed = new List<string>();

        using (SyncSession.Suppress())
        {
            foreach (var key in localKeys)
            {
                var keyText = FormatKey(key);

                if (serverKeyTexts.Contains(keyText))
                {
                    continue;
                }

                // An unsent journal entry outranks the server's key set: the row is the subject of a local intention
                // this run has not settled, and removing it here would settle it silently against the local side.
                if (pendingKeyTexts.Contains(keyText))
                {
                    continue;
                }

                if (await _local.DeleteAsync(key, cancellationToken).ConfigureAwait(false))
                {
                    removed.Add(keyText);
                }
            }
        }

        return removed;
    }

    /// <inheritdoc />
    /// <remarks>
    /// Raw SQL is never journaled, so the suppression here is not what keeps this write out of the journal. It is
    /// there because a refresh is one engine-driven write from beginning to end, and a table whose local repository
    /// happens to be reached some other way inside it should be treated the same as the rest.
    /// </remarks>
    public async Task<int> DeleteAllLocalAsync(CancellationToken cancellationToken = default)
    {
        using (SyncSession.Suppress())
        {
            return await _localSqlExecutor
                .ExecuteSqlAsync(LocalDeleteAllSql, null, cancellationToken)
                .ConfigureAwait(false);
        }
    }
}

/// <summary>
/// The fixed half of one synchronised table that carries a version column: batching, anchor derivation, and the
/// version-guarded journal replay.
/// </summary>
/// <remarks>
/// <para>
/// The descriptor supplies everything that depends on the diagram - the table name, the SQL that reads the local anchor
/// and key set, how to read and write the key and the mirrored version on the entity, and how a key turns into the
/// journal's text form and back.
/// </para>
/// <para>
/// <b>The resume point is derived, never stored.</b> The anchor is the maximum mirrored version among the local rows,
/// so it is a fact about the data rather than a separate bookkeeping row that could disagree with it. Three things make
/// that derivation correct, and all three are load-bearing: rows are fetched in ascending version order, each batch is
/// applied in a single local transaction, and <b>the download is the only thing that writes a mirrored version</b>. A
/// run interrupted anywhere leaves the local database holding a prefix of the ordered stream, and the maximum of that
/// prefix is exactly where the next run must start. Rows created locally and not yet uploaded have no mirrored version,
/// so they drop out of the maximum on their own.
/// </para>
/// <para>
/// The third point is what keeps the first two worth anything. A version written from anywhere but the ordered stream -
/// an upload mirroring the stamp the server just gave its row, say - can stand above rows of that stream the local
/// database has not seen, and every one of them then sits below the anchor for good: no later run asks for them again.
/// The version an upload earns is therefore reported to the run rather than mirrored, and the download writes it when
/// the row reaches it in order.
/// </para>
/// </remarks>
/// <typeparam name="TEntity">The entity type.</typeparam>
/// <typeparam name="TKey">The primary key type.</typeparam>
public sealed class SyncTable<TEntity, TKey> : SyncTableBase<TEntity, TKey>
    where TEntity : EntityBaseCore, new()
{
    /// <summary>Creates the table with its local repository, the local raw SQL surface, the server source, and its descriptor.</summary>
    public SyncTable(
        IRepositoryCore<TEntity, TKey> local,
        ISqlExecutor localSqlExecutor,
        ISyncServerSource<TEntity, TKey> server,
        SyncTableDescriptor<TEntity, TKey> descriptor
    )
        : base(local, localSqlExecutor, server, descriptor) { }

    /// <summary>SELECT that returns the highest mirrored version among the local rows (the derived resume point).</summary>
    private string LocalAnchorSql => _descriptor.LocalAnchorSql;

    /// <summary>Reads the mirrored server version off the entity (null when the row has never been uploaded).</summary>
    private byte[]? ReadRowVersion(TEntity entity) => _descriptor.ReadRowVersion(entity);

    /// <summary>Writes the mirrored server version onto the entity.</summary>
    private void WriteRowVersion(TEntity entity, byte[]? rowVersion) =>
        _descriptor.WriteRowVersion(entity, rowVersion);

    /// <inheritdoc />
    public override async Task<int> DownloadAsync(
        byte[]? ceiling,
        int batchSize,
        bool includeUnboundedBinary,
        CancellationToken cancellationToken = default
    ) =>
        (
            await DownloadAsync(
                ceiling,
                batchSize,
                includeUnboundedBinary,
                SyncDownloadContext.Empty,
                cancellationToken
            )
                .ConfigureAwait(false)
        ).Applied;

    /// <inheritdoc />
    /// <remarks>
    /// <para>
    /// The rows of a batch arrive in ascending version order and are dealt with in that order, so whatever the run
    /// commits is a prefix of the stream and the anchor derived from it is where the next pass must resume.
    /// </para>
    /// <para>
    /// A row whose key still holds an unsent local change ends the table's download at that row. The rows behind it are
    /// left on the server rather than applied out of order: applying them would move the anchor past the stopping point,
    /// and the change that stopped it would then never be seen again.
    /// </para>
    /// </remarks>
    public override async Task<SyncDownloadOutcome> DownloadAsync(
        byte[]? ceiling,
        int batchSize,
        bool includeUnboundedBinary,
        SyncDownloadContext context,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(context);

        if (batchSize <= 0)
        {
            throw new ArgumentOutOfRangeException(
                nameof(batchSize),
                "The download batch size must be greater than zero."
            );
        }

        var applied = 0;
        byte[]? previousAnchor = null;
        var appliedAnyBatch = false;

        // The receipts this download makes redundant. Collected rather than cleared as they are met, because the
        // clearing has to follow the local commit that wrote the version - and the caller clears them once this
        // returns, by which time every batch has committed.
        var settledAcks = new List<string>();

        while (true)
        {
            cancellationToken.ThrowIfCancellationRequested();

            // The anchor is re-derived for every batch: the previous batch committed, so the maximum has moved on.
            var anchor = await _localSqlExecutor
                .ExecuteScalarSqlAsync<byte[]>(LocalAnchorSql, null, cancellationToken)
                .ConfigureAwait(false);

            if (appliedAnyBatch && SameAnchor(anchor, previousAnchor))
            {
                // A batch was applied and yet the resume point did not move, so asking again would hand back the same
                // rows for ever. Every reason for it is a defect rather than a state to wait out - a source that
                // ignores the anchor it is given, or rows whose version column is empty and cannot raise the maximum -
                // so it is reported instead of spun on. Without this the download has no way to end.
                throw new InvalidOperationException(
                    $"The download of '{TableName}' is not making progress: a batch was applied but the resume point "
                        + "derived from the local rows did not move. The server source is returning rows that do not "
                        + "advance past the anchor it was given."
                );
            }

            previousAnchor = anchor;

            var batch = await _server
                .GetChangesAsync(anchor, ceiling, batchSize, cancellationToken)
                .ConfigureAwait(false);

            if (batch.Rows.Count == 0)
            {
                return new SyncDownloadOutcome(applied, null, settledAcks);
            }

            var stopAt = FindPendingRow(batch.Rows, context.PendingKeyTexts);
            var rows = stopAt < 0 ? batch.Rows : batch.Rows.Take(stopAt).ToList();

            if (rows.Count > 0)
            {
                applied += await ApplyDownloadedRowsAsync(
                        rows,
                        context,
                        settledAcks,
                        includeUnboundedBinary,
                        cancellationToken
                    )
                    .ConfigureAwait(false);

                // Set even when every row of the batch was this device's own echo: those write a version too, so the
                // resume point did move and the progress guard has nothing to report.
                appliedAnyBatch = true;
            }

            if (stopAt >= 0)
            {
                // Stopping is a normal end of this table's download, not a stall: the caller settles the change that
                // stopped it and the next run carries on from the prefix this one left.
                return new SyncDownloadOutcome(
                    applied,
                    FormatKey(ReadKey(batch.Rows[stopAt])),
                    settledAcks
                );
            }

            // The source itself says whether the stream is drained; what is left over is above the ceiling either way
            // and waits for the next run. Asking again is safe but pointless, so the flag is what ends the loop.
            if (!batch.HasMore)
            {
                return new SyncDownloadOutcome(applied, null, settledAcks);
            }
        }
    }

    /// <summary>Finds the first row whose key still holds an unsent local change, or -1 when none does.</summary>
    private int FindPendingRow(IReadOnlyList<TEntity> rows, IReadOnlySet<string> pendingKeyTexts)
    {
        if (pendingKeyTexts.Count == 0)
        {
            return -1;
        }

        for (var index = 0; index < rows.Count; index++)
        {
            if (pendingKeyTexts.Contains(FormatKey(ReadKey(rows[index]))))
            {
                return index;
            }
        }

        return -1;
    }

    /// <summary>Applies the rows of one batch in order and returns how many of them were applied as content.</summary>
    /// <remarks>
    /// <para>
    /// A row this device uploaded comes back carrying the version the server stamped on it, which is the version the
    /// receipt holds. Such a row holds the local content it was made from, so writing it back would be writing the
    /// row over itself - and, where the excluded columns are carried, copying a blob down that was just copied up. Only
    /// the version is worth taking, and it is taken on its own.
    /// </para>
    /// <para>
    /// Every row that gets this far has its mirrored version written, one way or the other, so a row whose key holds a
    /// receipt leaves that receipt with nothing left to say: the mirror now carries at least what the receipt did. Both
    /// paths therefore add to <paramref name="settledAcks"/> - including a row someone else changed after this device
    /// uploaded it, whose receipt is not merely redundant but stale.
    /// </para>
    /// </remarks>
    /// <param name="rows">The batch's rows, in ascending version order.</param>
    /// <param name="context">The table's unsent local changes and its outstanding acknowledgements.</param>
    /// <param name="settledAcks">The keys whose receipt this download has made redundant; added to as rows are applied.</param>
    /// <param name="includeUnboundedBinary">Whether the excluded unbounded binary columns are carried as well.</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    private async Task<int> ApplyDownloadedRowsAsync(
        IReadOnlyList<TEntity> rows,
        SyncDownloadContext context,
        List<string> settledAcks,
        bool includeUnboundedBinary,
        CancellationToken cancellationToken
    )
    {
        var applied = 0;
        var content = new List<TEntity>();

        foreach (var row in rows)
        {
            var keyText = FormatKey(ReadKey(row));

            if (context.AcknowledgedRowVersions.ContainsKey(keyText))
            {
                settledAcks.Add(keyText);
            }

            if (!IsEchoOfThisDevicesUpload(row, context))
            {
                content.Add(row);

                continue;
            }

            // Flushed before the version-only write so the rows are committed in the order they arrived: every commit
            // boundary then leaves the local database holding a prefix of the ordered stream.
            applied += await FlushContentAsync(content, includeUnboundedBinary, cancellationToken)
                .ConfigureAwait(false);

            if (!await MirrorRowVersionAsync(row, cancellationToken).ConfigureAwait(false))
            {
                // The local row is gone - removed outside the generated repositories since the upload read it - so
                // there is no version to write onto it and the server's row is applied like any other.
                content.Add(row);
            }
        }

        return applied
            + await FlushContentAsync(content, includeUnboundedBinary, cancellationToken)
                .ConfigureAwait(false);
    }

    /// <summary>Applies the rows accumulated so far, empties the buffer, and returns how many went.</summary>
    private async Task<int> FlushContentAsync(
        List<TEntity> content,
        bool includeUnboundedBinary,
        CancellationToken cancellationToken
    )
    {
        if (content.Count == 0)
        {
            return 0;
        }

        await ApplyBatchAsync(content, includeUnboundedBinary, cancellationToken)
            .ConfigureAwait(false);
        var applied = content.Count;
        content.Clear();

        return applied;
    }

    /// <summary>Whether the downloaded row is the row this device uploaded, still carrying the version the server gave it.</summary>
    /// <remarks>
    /// The version has to match, not just the key: a row someone else changed after this device uploaded it carries a
    /// different version, and that change is a server-side change like any other and has to be applied.
    /// </remarks>
    private bool IsEchoOfThisDevicesUpload(TEntity row, SyncDownloadContext context) =>
        context.AcknowledgedRowVersions.TryGetValue(FormatKey(ReadKey(row)), out var acknowledged)
        && ReadRowVersion(row) is { } current
        && acknowledged.SequenceEqual(current);

    /// <summary>Writes one downloaded row's version onto the local row without touching its content (false = no local row).</summary>
    private async Task<bool> MirrorRowVersionAsync(
        TEntity row,
        CancellationToken cancellationToken
    )
    {
        using (SyncSession.Suppress())
        {
            var local = await _local
                .GetByIdAsync(ReadKey(row), cancellationToken)
                .ConfigureAwait(false);

            if (local is null)
            {
                return false;
            }

            WriteRowVersion(local, ReadRowVersion(row));
            local.MarkUpdated();
            await _local
                .UpdateAsync(local, ConcurrencyMode.ForceOverwrite, cancellationToken)
                .ConfigureAwait(false);

            return true;
        }
    }

    /// <summary>Compares two derived anchors (null means "no local row carries a version yet").</summary>
    private static bool SameAnchor(byte[]? left, byte[]? right) =>
        left is null || right is null ? left is null && right is null : left.SequenceEqual(right);

    /// <inheritdoc />
    /// <remarks>
    /// <para>
    /// The rows come from the same differential source an ordinary run reads, asked from the very beginning: a refresh
    /// is the degenerate case of a download whose resume point starts at nothing, so no second server surface and no
    /// extra endpoint is involved. The ceiling still applies, and it has to - a row still in flight beneath it must
    /// stay out of the reload, or the anchor the reloaded table yields would sit above a row that never arrived and no
    /// later run would look below it again.
    /// </para>
    /// <para>
    /// The cursor advances by the version of the batch's last row rather than by re-deriving the local maximum. Both
    /// give the same value while the source keeps its promise to return rows in ascending version order, and the row
    /// is already in hand. As in a download, a batch that fails to move the cursor is reported rather than spun on.
    /// </para>
    /// <para>
    /// Rows are inserted rather than saved: the table was emptied first, so there is nothing to compare against and
    /// nothing to update. That - together with the absent anchor query, key set, and journal - is where the speed of a
    /// refresh comes from.
    /// </para>
    /// </remarks>
    public override async Task<int> RefreshAsync(
        byte[]? ceiling,
        int batchSize,
        bool includeUnboundedBinary,
        CancellationToken cancellationToken = default
    )
    {
        if (batchSize <= 0)
        {
            throw new ArgumentOutOfRangeException(
                nameof(batchSize),
                "The refresh batch size must be greater than zero."
            );
        }

        var inserted = 0;
        byte[]? anchor = null;

        while (true)
        {
            cancellationToken.ThrowIfCancellationRequested();

            var batch = await _server
                .GetChangesAsync(anchor, ceiling, batchSize, cancellationToken)
                .ConfigureAwait(false);

            if (batch.Rows.Count == 0)
            {
                return inserted;
            }

            using (SyncSession.Suppress())
            {
                inserted += await _local
                    .BulkInsertAsync(batch.Rows, cancellationToken)
                    .ConfigureAwait(false);
            }

            if (includeUnboundedBinary)
            {
                await CopyBinaryColumnsDownAsync(batch.Rows, cancellationToken)
                    .ConfigureAwait(false);
            }

            var next = ReadRowVersion(batch.Rows[^1]);

            if (next is null || next.Length == 0 || SameAnchor(next, anchor))
            {
                throw new InvalidOperationException(
                    $"The refresh of '{TableName}' is not making progress: the last row of a batch carries no "
                        + "version, or one that does not advance past the anchor the batch was asked for. The server "
                        + "source is not returning rows in ascending version order above the anchor it was given."
                );
            }

            // The source itself says whether the stream is drained; what is left over is above the ceiling either way
            // and belongs to the next ordinary run, which resumes from the anchor this reload leaves behind.
            if (!batch.HasMore)
            {
                return inserted;
            }

            anchor = next;
        }
    }

    /// <inheritdoc />
    public override async Task<SyncUploadOutcome> UploadAsync(
        SyncJournalRow entry,
        SyncMode mode,
        SyncConflictPolicy policy,
        bool includeUnboundedBinary,
        byte[]? acknowledgedRowVersion,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(entry);

        if (mode == SyncMode.LastWriteWins)
        {
            // The run asked for overwrites, so the version guards - and the receipt they would be read against, and
            // the policy that decides what happens when they fire - have nothing to do.
            return await UploadLastWriteWinsAsync(entry, includeUnboundedBinary, cancellationToken)
                .ConfigureAwait(false);
        }

        var key = ParseKey(entry.KeyText);

        // A delete carries nothing extra: the excluded columns go with the row it removes.
        return string.Equals(
            entry.Operation,
            nameof(SyncJournalOperation.Delete),
            StringComparison.Ordinal
        )
            ? await UploadDeleteAsync(
                entry,
                key,
                policy,
                acknowledgedRowVersion,
                cancellationToken
            )
                .ConfigureAwait(false)
            : await UploadUpsertAsync(
                entry,
                key,
                policy,
                includeUnboundedBinary,
                acknowledgedRowVersion,
                cancellationToken
            )
                .ConfigureAwait(false);
    }

    /// <summary>Replays an insert or an update by sending the row's <i>current</i> local content.</summary>
    /// <remarks>
    /// The original the update guards against is the later of the mirrored version and the acknowledged one. Reading
    /// the mirror alone makes a row whose echo has not come down look older than the server's copy of itself, and the
    /// guard then fires against a version this very device wrote - a conflict with nobody. It is also what tells an
    /// offline insert apart from a row already accepted but not yet echoed: both have an empty mirror, and only the
    /// second has a receipt.
    /// </remarks>
    private async Task<SyncUploadOutcome> UploadUpsertAsync(
        SyncJournalRow entry,
        TKey key,
        SyncConflictPolicy policy,
        bool includeUnboundedBinary,
        byte[]? acknowledgedRowVersion,
        CancellationToken cancellationToken
    )
    {
        var local = await _local.GetByIdAsync(key, cancellationToken).ConfigureAwait(false);

        if (local is null)
        {
            // A journal-first entry whose business write never landed, or a row deleted afterwards. Nothing to send.
            return SyncUploadOutcome.Discarded;
        }

        var mirror = MaxRowVersion(ReadRowVersion(local), acknowledgedRowVersion);

        if (mirror is null)
        {
            // Neither a mirrored version nor a receipt means the row was created locally and has never been on the
            // server.
            var alreadyThere = await _server
                .Writer.GetByIdAsync(key, cancellationToken)
                .ConfigureAwait(false);

            if (alreadyThere is not null && policy != SyncConflictPolicy.LocalWins)
            {
                return SyncUploadOutcome.Conflicted(
                    new SyncConflict(
                        TableName,
                        entry.KeyText,
                        SyncJournalOperation.Upsert,
                        SyncConflictReason.DuplicateOnServer,
                        local,
                        alreadyThere
                    )
                );
            }

            if (alreadyThere is null)
            {
                local.MarkAdded();
                await _server.Writer.InsertAsync(local, cancellationToken).ConfigureAwait(false);
            }
            else
            {
                // LocalWins: the offline insert overwrites the row the server already holds under that key. The
                // insert the overwrite falls back to covers that row disappearing between the probe and the update.
                await ForceOverwriteOrInsertAsync(local, cancellationToken).ConfigureAwait(false);
            }
        }
        else
        {
            // The guard reads the version off the entity, so the one that is actually going to be guarded against is
            // written onto it first - which matters exactly when the receipt is the later of the two.
            WriteRowVersion(local, mirror);
            local.MarkUpdated();

            try
            {
                var updated = await _server
                    .Writer.UpdateAsync(
                        local,
                        policy == SyncConflictPolicy.LocalWins
                            ? ConcurrencyMode.ForceOverwrite
                            : ConcurrencyMode.Optimistic,
                        cancellationToken
                    )
                    .ConfigureAwait(false);

                if (!updated)
                {
                    if (policy != SyncConflictPolicy.LocalWins)
                    {
                        return SyncUploadOutcome.Conflicted(
                            new SyncConflict(
                                TableName,
                                entry.KeyText,
                                SyncJournalOperation.Upsert,
                                SyncConflictReason.MissingOnServer,
                                local,
                                null
                            )
                        );
                    }

                    // LocalWins: the server no longer has the row, so the local edit puts it back - the same
                    // resurrection last-write-wins performs, here as the resolution of a collected conflict.
                    local.MarkAdded();
                    await _server.Writer.InsertAsync(local, cancellationToken).ConfigureAwait(false);
                }
            }
            catch (SaveConflictException)
            {
                var current = await _server
                    .Writer.GetByIdAsync(key, cancellationToken)
                    .ConfigureAwait(false);

                return SyncUploadOutcome.Conflicted(
                    new SyncConflict(
                        TableName,
                        entry.KeyText,
                        SyncJournalOperation.Upsert,
                        SyncConflictReason.ModifiedOnServer,
                        local,
                        current
                    )
                );
            }
        }

        if (includeUnboundedBinary)
        {
            await CopyBinaryColumnsUpAsync(key, cancellationToken).ConfigureAwait(false);
        }

        // The server stamped the row with a new version. It is reported to the run rather than written onto the local
        // row: the mirrored version is the resume point of the download, and only the download may move it.
        return SyncUploadOutcome.UploadedWith(
            await ReadServerRowVersionAsync(local, includeUnboundedBinary, cancellationToken)
                .ConfigureAwait(false)
        );
    }

    /// <summary>Replays a delete under the protection of the version the row carried when it was deleted.</summary>
    /// <remarks>
    /// The key alone would delete unconditionally, so the delete goes through the graph save instead: a stub carrying
    /// the key, the recorded version, and <c>RowState.Removed</c> is exactly the shape the existing version guard
    /// already covers. A row the server no longer has is a no-op rather than a conflict - the delete's intent is
    /// already satisfied. A row that is still there locally means the opposite, and the entry is discarded unsent.
    /// <para>
    /// The recorded version is the mirror as the row carried it when it was deleted, so it is behind the server's
    /// whenever the row's echo had not come down - and the stub is guarded against the later of it and the receipt for
    /// the same reason an update is.
    /// </para>
    /// </remarks>
    private async Task<SyncUploadOutcome> UploadDeleteAsync(
        SyncJournalRow entry,
        TKey key,
        SyncConflictPolicy policy,
        byte[]? acknowledgedRowVersion,
        CancellationToken cancellationToken
    )
    {
        if (await LocalRowSurvivedDeleteAsync(key, cancellationToken).ConfigureAwait(false))
        {
            return SyncUploadOutcome.Discarded;
        }

        if (policy == SyncConflictPolicy.LocalWins)
        {
            await _server.Writer.DeleteAsync(key, cancellationToken).ConfigureAwait(false);

            return SyncUploadOutcome.Uploaded;
        }

        var stub = new TEntity();
        WriteKey(stub, key);
        WriteRowVersion(stub, MaxRowVersion(entry.OriginalRowVersion, acknowledgedRowVersion));
        stub.MarkRemoved();

        try
        {
            await _server
                .Writer.SaveAsync(
                    stub,
                    cascadeSave: false,
                    cascadeDelete: false,
                    insertWhenUpdateMissing: false,
                    ConcurrencyMode.Optimistic,
                    cancellationToken
                )
                .ConfigureAwait(false);
        }
        catch (SaveConflictException)
        {
            var current = await _server
                .Writer.GetByIdAsync(key, cancellationToken)
                .ConfigureAwait(false);

            return SyncUploadOutcome.Conflicted(
                new SyncConflict(
                    TableName,
                    entry.KeyText,
                    SyncJournalOperation.Delete,
                    current is null
                        ? SyncConflictReason.MissingOnServer
                        : SyncConflictReason.ModifiedOnServer,
                    null,
                    current
                )
            );
        }

        return SyncUploadOutcome.Uploaded;
    }
}

/// <summary>
/// The fixed half of one synchronised table without a version column: a full key-ordered download and a
/// last-write-wins replay.
/// </summary>
/// <remarks>
/// <para>
/// No version column means no change stream: there is nothing to derive a resume point from and nothing to bound a
/// pass with, so every download reads the whole table in ascending primary-key order and applies each batch as an
/// upsert. The cost is O(table) per run, which is why these tables are meant to be the small, rarely changing kind -
/// a large or busy table is better served by a rowversion column and the incremental download it buys.
/// </para>
/// <para>
/// Uploads carry no version either, so a replay can only overwrite. These tables therefore take part exclusively in
/// <see cref="SyncMode.LastWriteWins"/> runs; a <see cref="SyncMode.Versioned"/> run leaves them - and their journal
/// entries - untouched.
/// </para>
/// </remarks>
/// <typeparam name="TEntity">The entity type.</typeparam>
/// <typeparam name="TKey">The primary key type.</typeparam>
public sealed class VersionlessSyncTable<TEntity, TKey> : SyncTableBase<TEntity, TKey>
    where TEntity : EntityBaseCore, new()
{
    /// <summary>Creates the table with its local repository, the local raw SQL surface, the server source, and its descriptor.</summary>
    public VersionlessSyncTable(
        IRepositoryCore<TEntity, TKey> local,
        ISqlExecutor localSqlExecutor,
        ISyncServerSource<TEntity, TKey> server,
        SyncTableDescriptor<TEntity, TKey> descriptor
    )
        : base(local, localSqlExecutor, server, descriptor) { }

    /// <inheritdoc />
    /// <remarks>A key-ordered scan has no version to bound, so the answer is always null and the engine never asks.</remarks>
    public override Task<byte[]?> GetChangeCeilingAsync(
        CancellationToken cancellationToken = default
    ) => Task.FromResult<byte[]?>(null);

    /// <inheritdoc />
    /// <remarks>
    /// The ceiling is ignored - there is no version to bound by. Every row comes down and is applied as an upsert
    /// through the same batch application a versioned download uses (one local transaction per batch, journaling
    /// suppressed), so a row that did not change is overwritten with itself; the delete propagation that follows a
    /// download is what removes the rows the server dropped. A source whose last key fails to advance while it still
    /// claims more is reported rather than spun on, exactly like a versioned source that ignores its anchor.
    /// </remarks>
    public override async Task<int> DownloadAsync(
        byte[]? ceiling,
        int batchSize,
        bool includeUnboundedBinary,
        CancellationToken cancellationToken = default
    ) =>
        (
            await DownloadAsync(
                ceiling,
                batchSize,
                includeUnboundedBinary,
                SyncDownloadContext.Empty,
                cancellationToken
            )
                .ConfigureAwait(false)
        ).Applied;

    /// <inheritdoc />
    /// <remarks>
    /// A row whose key still holds an unsent local change is skipped and the scan carries on. There is no resume point
    /// to protect here - every run reads the whole table - so leaving one row alone costs nothing, and this table never
    /// stops a download of its own accord.
    /// </remarks>
    public override async Task<SyncDownloadOutcome> DownloadAsync(
        byte[]? ceiling,
        int batchSize,
        bool includeUnboundedBinary,
        SyncDownloadContext context,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(context);

        if (batchSize <= 0)
        {
            throw new ArgumentOutOfRangeException(
                nameof(batchSize),
                "The download batch size must be greater than zero."
            );
        }

        var applied = 0;
        string? previousKeyText = null;
        var batch = await _server
            .GetFirstPageAsync(batchSize, cancellationToken)
            .ConfigureAwait(false);

        while (true)
        {
            cancellationToken.ThrowIfCancellationRequested();

            if (batch.Rows.Count == 0)
            {
                return new SyncDownloadOutcome(applied, null);
            }

            var rows = WithoutPendingRows(batch.Rows, context.PendingKeyTexts);

            if (rows.Count > 0)
            {
                await ApplyBatchAsync(rows, includeUnboundedBinary, cancellationToken)
                    .ConfigureAwait(false);
                applied += rows.Count;
            }

            if (!batch.HasMore)
            {
                return new SyncDownloadOutcome(applied, null);
            }

            var lastKey = ReadKey(batch.Rows[^1]);
            var lastKeyText = FormatKey(lastKey);

            if (string.Equals(lastKeyText, previousKeyText, StringComparison.Ordinal))
            {
                throw new InvalidOperationException(
                    $"The download of '{TableName}' is not making progress: the last key of a batch did not advance "
                        + "past the one the batch was asked for. The server source is not returning rows in ascending "
                        + "primary-key order above the key it was given."
                );
            }

            previousKeyText = lastKeyText;
            batch = await _server
                .GetPageAfterAsync(lastKey, batchSize, cancellationToken)
                .ConfigureAwait(false);
        }
    }

    /// <summary>Drops the rows whose key still holds an unsent local change (the batch itself when there are none).</summary>
    private IReadOnlyList<TEntity> WithoutPendingRows(
        IReadOnlyList<TEntity> rows,
        IReadOnlySet<string> pendingKeyTexts
    ) =>
        pendingKeyTexts.Count == 0
            ? rows
            : rows.Where(row => !pendingKeyTexts.Contains(FormatKey(ReadKey(row)))).ToList();

    /// <inheritdoc />
    /// <remarks>
    /// Rows are inserted rather than saved - the table was emptied first, so there is nothing to compare against -
    /// and the scan is paged by key like a download, with the same progress guard. The ceiling is ignored for the
    /// same reason it is during a download.
    /// </remarks>
    public override async Task<int> RefreshAsync(
        byte[]? ceiling,
        int batchSize,
        bool includeUnboundedBinary,
        CancellationToken cancellationToken = default
    )
    {
        if (batchSize <= 0)
        {
            throw new ArgumentOutOfRangeException(
                nameof(batchSize),
                "The refresh batch size must be greater than zero."
            );
        }

        var inserted = 0;
        string? previousKeyText = null;
        var batch = await _server
            .GetFirstPageAsync(batchSize, cancellationToken)
            .ConfigureAwait(false);

        while (true)
        {
            cancellationToken.ThrowIfCancellationRequested();

            if (batch.Rows.Count == 0)
            {
                return inserted;
            }

            using (SyncSession.Suppress())
            {
                inserted += await _local
                    .BulkInsertAsync(batch.Rows, cancellationToken)
                    .ConfigureAwait(false);
            }

            if (includeUnboundedBinary)
            {
                await CopyBinaryColumnsDownAsync(batch.Rows, cancellationToken)
                    .ConfigureAwait(false);
            }

            if (!batch.HasMore)
            {
                return inserted;
            }

            var lastKey = ReadKey(batch.Rows[^1]);
            var lastKeyText = FormatKey(lastKey);

            if (string.Equals(lastKeyText, previousKeyText, StringComparison.Ordinal))
            {
                throw new InvalidOperationException(
                    $"The refresh of '{TableName}' is not making progress: the last key of a batch did not advance "
                        + "past the one the batch was asked for. The server source is not returning rows in ascending "
                        + "primary-key order above the key it was given."
                );
            }

            previousKeyText = lastKeyText;
            batch = await _server
                .GetPageAfterAsync(lastKey, batchSize, cancellationToken)
                .ConfigureAwait(false);
        }
    }

    /// <inheritdoc />
    /// <remarks>
    /// Only <see cref="SyncMode.LastWriteWins"/> runs include this table, and without a version the replay can only
    /// overwrite, so neither the mode nor the policy nor an acknowledged version has anything left to choose. Nothing
    /// ever records a receipt for such a table either: an upload with no version to report leaves none behind.
    /// </remarks>
    public override async Task<SyncUploadOutcome> UploadAsync(
        SyncJournalRow entry,
        SyncMode mode,
        SyncConflictPolicy policy,
        bool includeUnboundedBinary,
        byte[]? acknowledgedRowVersion,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(entry);

        return await UploadLastWriteWinsAsync(entry, includeUnboundedBinary, cancellationToken)
            .ConfigureAwait(false);
    }
}

/// <summary>
/// Bidirectional differential sync between the server database and the local one, with the server as the source of truth.
/// </summary>
/// <remarks>
/// <para>
/// A run uploads first and downloads second. Uploading first means a local change reaches the server before the server's
/// rows come back down, so a change accepted by the server is not immediately overwritten by its own pre-upload state.
/// It is also where <see cref="SyncConflictPolicy.ServerWins"/> settles the rows it discards: each one takes the
/// server's content in place of the local change, and a row the server does not have is left to the delete propagation
/// that follows the download.
/// </para>
/// <para>
/// Tables are visited in foreign-key order - parents before children when rows are written, children before parents when
/// rows are deleted - and each table is drained completely before the next one starts, so a child row is never applied
/// before the parent it points at.
/// </para>
/// <para>
/// Nothing here resolves a conflict silently. Under the default policy a local change that collides with the server stays
/// in the journal and comes back in <see cref="SyncResult.Conflicts"/> with both sides of the disagreement attached - and
/// the row it describes stays where it is, because both halves of the download leave every key the journal still holds an
/// entry for alone: the row itself is not overwritten, and the delete propagation does not remove it.
/// </para>
/// <para>
/// Leaving such a row alone has a price, and the run says so rather than paying it quietly. A table's download stops at
/// the first row whose local change is still unsent, and the tables after it in foreign-key order stop with it; what was
/// left unread is reported in <see cref="SyncResult.Truncations"/> and comes down once the change that stopped it has
/// been settled - which is the caller's to decide and re-run.
/// </para>
/// </remarks>
public sealed class SyncEngine
{
    /// <summary>The answer for a table with nothing left in the journal (shared rather than allocated per table).</summary>
    private static readonly IReadOnlySet<string> NoPendingKeyTexts = new HashSet<string>(
        StringComparer.Ordinal
    );

    private readonly IReadOnlyList<ISyncTable> _tables;
    private readonly SyncJournal _journal;

    /// <summary>Creates the engine over the synchronised tables, ordered parents first.</summary>
    /// <param name="tables">The synchronised tables in foreign-key order (a parent always precedes its children).</param>
    /// <param name="journal">The local journal of offline edits.</param>
    public SyncEngine(IEnumerable<ISyncTable> tables, SyncJournal journal)
    {
        ArgumentNullException.ThrowIfNull(tables);
        ArgumentNullException.ThrowIfNull(journal);
        _tables = tables.ToList();
        _journal = journal;
    }

    /// <summary>Runs one full sync: replays the local journal, then pulls the server's changes down.</summary>
    /// <remarks>
    /// What the upload learns is carried into the download through the acknowledgement table rather than through the
    /// run: the version the server stamped on each row that went up is written down as it goes, so the download can
    /// tell an echo from a change worth applying. Calling <see cref="UploadAsync"/> and <see cref="DownloadAsync"/>
    /// separately is therefore not a lesser arrangement - the receipts outlive the call that wrote them, and a
    /// download run on its own recognises the echoes of every upload whose row has yet to come back down.
    /// </remarks>
    /// <param name="options">The knobs for this run (null takes the defaults).</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    public async Task<SyncResult> SyncAsync(
        SyncOptions? options = null,
        CancellationToken cancellationToken = default
    )
    {
        options ??= new SyncOptions();
        await _journal.EnsureCreatedAsync(cancellationToken).ConfigureAwait(false);

        var conflicts = new List<SyncConflict>();
        var upload = await UploadAsync(options, conflicts, cancellationToken)
            .ConfigureAwait(false);
        var download = await DownloadCoreAsync(options, cancellationToken).ConfigureAwait(false);

        return new SyncResult(
            upload.Uploaded,
            download.Downloaded,
            download.DeletedLocally,
            upload.Discarded,
            conflicts
        )
        {
            Truncations = download.Truncations,
        };
    }

    /// <summary>Rebuilds the local database from the server's rows: every synchronised table is emptied and reloaded.</summary>
    /// <remarks>
    /// <para>
    /// This is for building the local database the first time, for recovering one that was lost or corrupted, and for
    /// starting over when a database has fallen so far behind that catching up row by row is not worth it. It is not a
    /// faster <see cref="SyncAsync"/> and does not replace one: it transfers every row of every synchronised table, so
    /// over a slow link and a large table the transfer is what dominates and an ordinary run - which carries only what
    /// changed - is the cheaper one from the second run onwards.
    /// </para>
    /// <para>
    /// What makes it fast is what it leaves out. Nothing is compared with the row it replaces, no anchor is derived
    /// per batch, no key set is fetched to find the rows the server dropped (they are gone by construction), and no
    /// journal is replayed. All of it is skipped because the answer is known in advance: the local side ends up as a
    /// copy of the server's.
    /// </para>
    /// <para>
    /// It touches the synchronised tables and nothing else. A table the local database keeps for itself - a settings
    /// table, a cache, anything excluded where the engine was put together - is not part of this and is left
    /// exactly as it was; and <see cref="SyncRefreshOptions.Mode"/> can narrow a run further.
    /// </para>
    /// <para>
    /// Unsent local changes are refused rather than lost. When the journal is not empty the run throws
    /// <see cref="SyncPendingChangesException"/> before deleting anything;
    /// <see cref="SyncRefreshOptions.Force"/> is the explicit request to drop them instead.
    /// </para>
    /// <para>
    /// Local blobs are refused on the same terms. When a synchronised table has unbounded binary columns - which the
    /// row transfer leaves out, so the reload does not bring them back - the run throws
    /// <see cref="SyncUnboundedBinaryLossException"/> before deleting anything, until
    /// <see cref="SyncRefreshOptions.IncludeUnboundedBinary"/> says to reload them too or
    /// <see cref="SyncRefreshOptions.DiscardLocalUnboundedBinaries"/> says the loss is intended. A generated setup
    /// without such columns never sees this.
    /// </para>
    /// <para>
    /// <b>Crash safety.</b> The run is not one transaction - the generated repositories manage their own connections,
    /// so nothing here can enlist in a transaction of its own making - but every point at which it commits is a state
    /// a later run can start from, which is the property that actually matters. The deletes go children first and the
    /// reloads parents first, so no foreign key ever points at a row that is not there; and each table's rows arrive
    /// in ascending version order, so a table interrupted part way holds exactly the rows below the version it
    /// stopped at - precisely the resume point that the local maximum yields. A refresh cut short anywhere is
    /// therefore repaired by running it again, and an ordinary <see cref="SyncAsync"/> in the meantime picks up from
    /// where it stopped rather than mistaking the gap for a server-side deletion.
    /// </para>
    /// <para>
    /// The one state this leaves that a single transaction would not is a partly rebuilt local database: between the
    /// first delete and the last row of the last table, a reader of the local database sees fewer rows than either
    /// side holds. Nothing is lost by it - the server still has everything - but a refresh is not something to run
    /// underneath a live screen.
    /// </para>
    /// </remarks>
    /// <param name="options">The knobs for this run (null takes the defaults).</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    /// <exception cref="SyncPendingChangesException">The journal holds unsent local changes and <see cref="SyncRefreshOptions.Force"/> was not set.</exception>
    /// <exception cref="SyncUnboundedBinaryLossException">A synchronised table has unbounded binary columns and neither <see cref="SyncRefreshOptions.IncludeUnboundedBinary"/> nor <see cref="SyncRefreshOptions.DiscardLocalUnboundedBinaries"/> was set.</exception>
    public async Task<SyncRefreshResult> RefreshAsync(
        SyncRefreshOptions? options = null,
        CancellationToken cancellationToken = default
    )
    {
        options ??= new SyncRefreshOptions();

        // Checked here rather than left to the per-table call: by then the local tables have already been emptied, and
        // a run that wipes the local database and only then reports a bad argument is not one anybody asked for.
        if (options.BatchSize <= 0)
        {
            throw new ArgumentOutOfRangeException(
                nameof(options),
                options.BatchSize,
                "The refresh batch size must be greater than zero."
            );
        }

        var scope = ResolveScope(options.Mode, options.ExcludedEntityTypes);

        // Also before anything is deleted, and before the journal is even read: a local blob that only exists here is
        // gone for good once its row is, and neither answer to that is one the engine may pick on the caller's behalf.
        if (!options.IncludeUnboundedBinary && !options.DiscardLocalUnboundedBinaries)
        {
            var atStake = scope
                .Where(table => table.UnboundedBinaryColumnNames.Count > 0)
                .Select(table => new SyncUnboundedBinaryColumns(
                    table.TableName,
                    table.UnboundedBinaryColumnNames
                ))
                .ToList();

            if (atStake.Count > 0)
            {
                throw new SyncUnboundedBinaryLossException(atStake);
            }
        }

        var startedAt = Stopwatch.GetTimestamp();

        await _journal.EnsureCreatedAsync(cancellationToken).ConfigureAwait(false);

        // Only the entries of the tables this refresh covers count as being at stake: an entry of a table outside
        // the scope describes rows the run will not touch, so it neither blocks the run nor is dropped by Force.
        var scopeTableNames = scope.Select(table => table.TableName).ToHashSet(StringComparer.Ordinal);
        var pending = (await _journal.ReadAllAsync(cancellationToken).ConfigureAwait(false))
            .Where(entry => scopeTableNames.Contains(entry.TableName))
            .ToList();

        if (pending.Count > 0 && !options.Force)
        {
            throw new SyncPendingChangesException(
                pending
                    .GroupBy(entry => entry.TableName, StringComparer.Ordinal)
                    .Select(group => new SyncPendingChange(group.Key, group.Count()))
                    .ToList()
            );
        }

        if (pending.Count > 0)
        {
            // Dropped before anything is deleted, so an interrupted forced run does not leave entries describing rows
            // that the reload has already replaced.
            await RemoveAsync(pending.Select(entry => entry.Id).ToList(), cancellationToken)
                .ConfigureAwait(false);
        }

        if (scope.Count == 0)
        {
            return new SyncRefreshResult([], pending.Count, Stopwatch.GetElapsedTime(startedAt));
        }

        // The receipts go with the entries, and for the same reason: a refresh replaces every row of these tables
        // along with its mirrored version, so a per-row record of what the server once acknowledged has nothing left
        // to be about. Dropped before anything is deleted, so an interrupted run leaves none behind either.
        foreach (var table in scope)
        {
            await _journal
                .RemoveTableAcksAsync(table.TableName, cancellationToken)
                .ConfigureAwait(false);
        }

        // One ceiling for the whole run, for the same reason an ordinary run uses one (and from a versioned table,
        // for the same reason as well).
        var ceilingTable = scope.FirstOrDefault(table => !table.IsVersionless);
        var ceiling = ceilingTable is null
            ? null
            : await ceilingTable.GetChangeCeilingAsync(cancellationToken).ConfigureAwait(false);
        var deleted = new int[scope.Count];

        // Children first: emptying a parent while its children are still there is what a foreign key forbids.
        for (var index = scope.Count - 1; index >= 0; index--)
        {
            deleted[index] = await scope[index]
                .DeleteAllLocalAsync(cancellationToken)
                .ConfigureAwait(false);
        }

        var tables = new List<SyncRefreshTableResult>(scope.Count);

        // Parents first, for the same reason in reverse.
        for (var index = 0; index < scope.Count; index++)
        {
            var table = scope[index];
            var inserted = await table
                .RefreshAsync(
                    ceiling,
                    options.BatchSize,
                    options.IncludeUnboundedBinary,
                    cancellationToken
                )
                .ConfigureAwait(false);
            tables.Add(new SyncRefreshTableResult(table.TableName, deleted[index], inserted));
        }

        return new SyncRefreshResult(tables, pending.Count, Stopwatch.GetElapsedTime(startedAt));
    }

    /// <summary>Replays the journal against the server and returns how many entries went and how many were dropped.</summary>
    /// <remarks>
    /// Each entry is settled - its receipt written, then the entry removed - the moment the server has taken it,
    /// rather than all of them at the end of the run. An upload interrupted part way then leaves behind entries for
    /// exactly the changes that did not reach the server; the whole-run alternative leaves entries for changes that
    /// did, and the next run resends them, reports a conflict against the row it wrote itself, or overwrites a newer
    /// server row with a stale local one.
    /// </remarks>
    /// <param name="options">The knobs for this run.</param>
    /// <param name="conflicts">The collection the collected conflicts are added to.</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    public async Task<(int Uploaded, int Discarded)> UploadAsync(
        SyncOptions options,
        ICollection<SyncConflict> conflicts,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(options);
        ArgumentNullException.ThrowIfNull(conflicts);

        var entries = await _journal.ReadAllAsync(cancellationToken).ConfigureAwait(false);

        if (entries.Count == 0)
        {
            return (0, 0);
        }

        // The journal is append-only, so a row edited several times has several entries. Only the last one describes
        // what to do now; the earlier ones are superseded and go with it once the last one has been dealt with.
        // A tuple key needs no separator, so two rows can never collide the way a concatenated string key can
        // when one table name is a prefix of another.
        var latestByRow = new Dictionary<(string TableName, string KeyText), SyncJournalRow>();
        var idsByRow = new Dictionary<(string TableName, string KeyText), List<long>>();

        foreach (var entry in entries)
        {
            var rowId = (entry.TableName, entry.KeyText);
            latestByRow[rowId] = entry;

            if (!idsByRow.TryGetValue(rowId, out var ids))
            {
                ids = [];
                idsByRow.Add(rowId, ids);
            }

            ids.Add(entry.Id);
        }

        var scope = ResolveScope(options.Mode, options.ExcludedEntityTypes);

        if (options.Mode == SyncMode.Versioned && options.ConflictPolicy == SyncConflictPolicy.ServerWins)
        {
            // Nothing local is worth sending, so each row this run holds an entry for takes the server's content
            // instead. Scoped to the tables the run covers - an entry of an excluded or out-of-mode table is not this
            // run's to decide about, so it stays for the run that does cover it. (In a last-write-wins run the
            // policy has nothing to decide at all, so it is not consulted.)
            //
            // The download alone cannot stand in for this: it only carries rows the server has changed since they
            // were last mirrored, and a local edit to a row nobody else has touched would survive the run that was
            // told to discard it - with its entry gone, for good.
            var scopeTableNames = scope.Select(table => table.TableName)
                .ToHashSet(StringComparer.Ordinal);
            var dropRows = idsByRow
                .Where(pair => scopeTableNames.Contains(pair.Key.TableName))
                .OrderBy(pair => pair.Value[0])
                .ToList();

            // Parents first, for the reason an upsert replay runs that way: a row put back may be the one another
            // row points at.
            foreach (var table in scope)
            {
                var keyTexts = dropRows
                    .Where(pair =>
                        string.Equals(pair.Key.TableName, table.TableName, StringComparison.Ordinal)
                    )
                    .Select(pair => pair.Key.KeyText)
                    .ToList();

                if (keyTexts.Count == 0)
                {
                    continue;
                }

                var applied = await table
                    .ApplyServerRowsAsync(
                        keyTexts,
                        options.IncludeUnboundedBinary,
                        cancellationToken
                    )
                    .ConfigureAwait(false);

                // After the rows are in and before the entries go, for the same reason the replay records its
                // receipts in that order. The applied row's local content is the server's content at the version
                // just read, and the mirrored version deliberately does not say so; the receipt is the only thing
                // that does, and a row restored under a version the ordered stream has already passed will never be
                // told otherwise by a download. Interrupted either side of this the run is still sound: before it,
                // the entries stay and the next run applies the same rows and records them then; after it but before
                // the entries go, the next run applies the same rows again - which changes nothing - and writes the
                // same receipts over themselves.
                foreach (var row in applied)
                {
                    // A table with no version has nothing to acknowledge (and no versioned run to reach it here).
                    if (row.ServerRowVersion is not { Length: > 0 } serverRowVersion)
                    {
                        continue;
                    }

                    await _journal
                        .RecordAckAsync(
                            table.TableName,
                            row.KeyText,
                            serverRowVersion,
                            cancellationToken
                        )
                        .ConfigureAwait(false);
                }
            }

            // Dropped afterwards: a run interrupted in the middle leaves the entries behind, and the next one applies
            // the same server content again and drops them then. The other order would leave a local edit standing
            // with nothing left to say it is there.
            var dropIds = dropRows.SelectMany(pair => pair.Value).ToList();
            await RemoveAsync(dropIds, cancellationToken).ConfigureAwait(false);

            return (0, dropIds.Count);
        }

        var uploaded = 0;
        var discarded = 0;

        // Upserts run parents first so a child never reaches the server before the row it points at.
        foreach (var table in scope)
        {
            var (sent, dropped) = await ReplayAsync(
                    table,
                    latestByRow,
                    idsByRow,
                    conflicts,
                    options.Mode,
                    options.ConflictPolicy,
                    options.IncludeUnboundedBinary,
                    SyncJournalOperation.Upsert,
                    cancellationToken
                )
                .ConfigureAwait(false);
            uploaded += sent;
            discarded += dropped;
        }

        // Deletes run the other way round, children first, for the same reason in reverse.
        for (var index = scope.Count - 1; index >= 0; index--)
        {
            var (sent, dropped) = await ReplayAsync(
                    scope[index],
                    latestByRow,
                    idsByRow,
                    conflicts,
                    options.Mode,
                    options.ConflictPolicy,
                    options.IncludeUnboundedBinary,
                    SyncJournalOperation.Delete,
                    cancellationToken
                )
                .ConfigureAwait(false);
            uploaded += sent;
            discarded += dropped;
        }

        return (uploaded, discarded);
    }

    /// <summary>Replays every entry of one operation kind for one table.</summary>
    /// <remarks>
    /// <para>
    /// The receipt is written <i>before</i> the entry is removed, which is what a crash between the two is measured
    /// against: both records survive, the next run replays the same local content with the acknowledged version as its
    /// original, and the server takes it again. The other order leaves the row with a stale mirror and no receipt to
    /// correct it, and the next version-guarded replay of that key reports a conflict with nobody.
    /// </para>
    /// <para>
    /// A delete that reached the server goes the other way: the row is gone, so its receipt is dropped rather than
    /// written, and dropping it first means a crash in between leaves an entry whose replay deletes a row the server
    /// no longer has - a no-op.
    /// </para>
    /// </remarks>
    private async Task<(int Uploaded, int Discarded)> ReplayAsync(
        ISyncTable table,
        Dictionary<(string TableName, string KeyText), SyncJournalRow> latestByRow,
        Dictionary<(string TableName, string KeyText), List<long>> idsByRow,
        ICollection<SyncConflict> conflicts,
        SyncMode mode,
        SyncConflictPolicy policy,
        bool includeUnboundedBinary,
        SyncJournalOperation operation,
        CancellationToken cancellationToken
    )
    {
        var operationName = operation.ToString();
        var entries = latestByRow
            .Values.Where(entry =>
                string.Equals(entry.TableName, table.TableName, StringComparison.Ordinal)
                && string.Equals(entry.Operation, operationName, StringComparison.Ordinal)
            )
            .OrderBy(entry => entry.Id)
            .ToList();

        if (entries.Count == 0)
        {
            return (0, 0);
        }

        // Read once for this table's pass: the receipts of the keys about to be replayed are what their version
        // guards are read against.
        var acknowledged = await _journal
            .ReadAcksAsync(table.TableName, cancellationToken)
            .ConfigureAwait(false);
        var uploaded = 0;
        var discarded = 0;

        foreach (var entry in entries)
        {
            var outcome = await table
                .UploadAsync(
                    entry,
                    mode,
                    policy,
                    includeUnboundedBinary,
                    acknowledged.TryGetValue(entry.KeyText, out var acknowledgedRowVersion)
                        ? acknowledgedRowVersion
                        : null,
                    cancellationToken
                )
                .ConfigureAwait(false);

            if (outcome.Conflict is { } conflict)
            {
                // The entry stays in the journal so the caller can decide and re-run.
                conflicts.Add(conflict);
                continue;
            }

            if (operation == SyncJournalOperation.Delete)
            {
                if (outcome.Sent)
                {
                    await _journal
                        .RemoveAcksAsync(table.TableName, [entry.KeyText], cancellationToken)
                        .ConfigureAwait(false);
                }
            }
            else if (outcome.ServerRowVersion is { Length: > 0 } serverRowVersion)
            {
                await _journal
                    .RecordAckAsync(
                        table.TableName,
                        entry.KeyText,
                        serverRowVersion,
                        cancellationToken
                    )
                    .ConfigureAwait(false);
            }

            await RemoveAsync(
                    idsByRow[(entry.TableName, entry.KeyText)],
                    cancellationToken
                )
                .ConfigureAwait(false);

            // A settled entry that never reached the server (a stale intent) is a discard, not an upload:
            // counting it as one would report a change as delivered when nothing was sent.
            if (outcome.Sent)
            {
                uploaded++;
            }
            else
            {
                discarded++;
            }
        }

        return (uploaded, discarded);
    }

    /// <summary>Removes settled journal entries without letting the removal itself be journaled.</summary>
    private async Task RemoveAsync(IReadOnlyList<long> ids, CancellationToken cancellationToken)
    {
        using (SyncSession.Suppress())
        {
            await _journal.RemoveAsync(ids, cancellationToken).ConfigureAwait(false);
        }
    }

    /// <summary>Pulls the server's changes down and, unless it is turned off, removes the local rows the server dropped.</summary>
    /// <remarks>
    /// A table whose journal still holds an unsent change stops at the row that change belongs to, and the tables
    /// after it stop with it. <see cref="SyncAsync"/> reports where that happened in
    /// <see cref="SyncResult.Truncations"/>; called on its own, this returns only what it applied.
    /// </remarks>
    /// <param name="options">The knobs for this run.</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    public async Task<(int Downloaded, int DeletedLocally)> DownloadAsync(
        SyncOptions options,
        CancellationToken cancellationToken = default
    )
    {
        var download = await DownloadCoreAsync(options, cancellationToken).ConfigureAwait(false);

        return (download.Downloaded, download.DeletedLocally);
    }

    /// <summary>Pulls the server's changes down, knowing what is still unsent and what the server has acknowledged.</summary>
    /// <param name="options">The knobs for this run.</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    private async Task<(
        int Downloaded,
        int DeletedLocally,
        IReadOnlyList<SyncDownloadTruncation> Truncations
    )> DownloadCoreAsync(SyncOptions options, CancellationToken cancellationToken)
    {
        ArgumentNullException.ThrowIfNull(options);

        var scope = ResolveScope(options.Mode, options.ExcludedEntityTypes);
        var truncations = new List<SyncDownloadTruncation>();

        if (scope.Count == 0)
        {
            return (0, 0, truncations);
        }

        // One ceiling for the whole pass: asking per table would let a row committed between two tables slip through
        // the gap between their bounds. Only a versioned table can answer - a key-ordered scan has no bound to apply -
        // so an all-versionless scope runs without one.
        var ceilingTable = scope.FirstOrDefault(table => !table.IsVersionless);
        var ceiling = ceilingTable is null
            ? null
            : await ceilingTable.GetChangeCeilingAsync(cancellationToken).ConfigureAwait(false);

        // Read once for the whole pass, after the upload has settled what it could: what is left is genuinely unsent.
        // The same set answers both questions asked of it - which rows a download must not overwrite, and which rows
        // the delete propagation must not remove - so the two cannot disagree about what is still pending.
        var pendingKeyTexts = await ReadPendingKeyTextsAsync(cancellationToken)
            .ConfigureAwait(false);
        var downloaded = 0;
        string? truncatedBy = null;

        foreach (var table in scope)
        {
            if (truncatedBy is not null)
            {
                // A table earlier in foreign-key order stopped part way, so rows this table would bring down may point
                // at parents that were not downloaded. Which ones cannot be known without reading the batches that
                // were left unread, so the whole table waits for the run that gets past the change that stopped it.
                truncations.Add(new SyncDownloadTruncation(table.TableName, null, truncatedBy));

                continue;
            }

            // Read per table alongside the pending keys: the receipts say which of the rows about to come down are
            // this device's own echoes, and - once they have come down - which receipts have served their purpose.
            var acknowledged = await _journal
                .ReadAcksAsync(table.TableName, cancellationToken)
                .ConfigureAwait(false);
            var outcome = await table
                .DownloadAsync(
                    ceiling,
                    options.DownloadBatchSize,
                    options.IncludeUnboundedBinary,
                    new SyncDownloadContext
                    {
                        PendingKeyTexts = pendingKeyTexts.TryGetValue(
                            table.TableName,
                            out var keyTexts
                        )
                            ? keyTexts
                            : NoPendingKeyTexts,
                        AcknowledgedRowVersions = acknowledged,
                    },
                    cancellationToken
                )
                .ConfigureAwait(false);
            downloaded += outcome.Applied;

            // After the download, so every batch that wrote one of these versions has committed: a receipt dropped
            // ahead of the commit that replaces it would be gone for a commit that then failed.
            if (outcome.SettledAckKeyTexts is { Count: > 0 } settledAcks)
            {
                await _journal
                    .RemoveAcksAsync(table.TableName, settledAcks, cancellationToken)
                    .ConfigureAwait(false);
            }

            if (outcome.TruncatedAtKeyText is { } stoppedAt)
            {
                truncations.Add(
                    new SyncDownloadTruncation(table.TableName, stoppedAt, null)
                );
                truncatedBy = table.TableName;
            }
        }

        if (!options.PropagateDeletes)
        {
            return (downloaded, 0, truncations);
        }

        var deleted = 0;

        for (var index = scope.Count - 1; index >= 0; index--)
        {
            var table = scope[index];
            var removedKeyTexts = await table
                .PropagateDeletesAsync(
                    pendingKeyTexts.TryGetValue(table.TableName, out var keyTexts)
                        ? keyTexts
                        : NoPendingKeyTexts,
                    cancellationToken
                )
                .ConfigureAwait(false);
            deleted += removedKeyTexts.Count;

            // A key the server has dropped takes its receipt with it. Left behind, it would be the original of the
            // next replay of that key - a version-guarded update against a row that is gone, reported as a conflict
            // with a row nobody can produce - which is exactly what a local row recreated under the same key runs into.
            if (removedKeyTexts.Count > 0)
            {
                await _journal
                    .RemoveAcksAsync(table.TableName, removedKeyTexts, cancellationToken)
                    .ConfigureAwait(false);
            }
        }

        return (downloaded, deleted, truncations);
    }

    /// <summary>Resolves which tables one run covers: the mode keeps the versionless ones out of a versioned run, and the exclusions take named types away.</summary>
    /// <remarks>
    /// A type the engine does not synchronise is rejected rather than skipped: the caller either mistyped, or named a
    /// table that was already excluded where the engine was put together - and a silently ignored exclusion would read
    /// as if it had worked. The order of the remaining tables is the foreign-key order the engine was built with.
    /// </remarks>
    private IReadOnlyList<ISyncTable> ResolveScope(
        SyncMode mode,
        IReadOnlyCollection<Type> excludedEntityTypes
    )
    {
        ArgumentNullException.ThrowIfNull(excludedEntityTypes);

        foreach (var type in excludedEntityTypes)
        {
            if (_tables.All(table => table.EntityType != type))
            {
                throw new ArgumentException(
                    $"The type '{type}' is not an entity type this engine synchronises - a typo, or a table that was "
                        + "already excluded where the engine was put together.",
                    nameof(excludedEntityTypes)
                );
            }
        }

        return _tables
            .Where(table =>
                (mode == SyncMode.LastWriteWins || !table.IsVersionless)
                && !excludedEntityTypes.Contains(table.EntityType)
            )
            .ToList();
    }

    /// <summary>Groups the keys of the still-unsent journal entries by table: the rows a download and a delete propagation both leave alone.</summary>
    private async Task<Dictionary<string, HashSet<string>>> ReadPendingKeyTextsAsync(
        CancellationToken cancellationToken
    )
    {
        var entries = await _journal.ReadAllAsync(cancellationToken).ConfigureAwait(false);
        var byTable = new Dictionary<string, HashSet<string>>(StringComparer.Ordinal);

        foreach (var entry in entries)
        {
            if (!byTable.TryGetValue(entry.TableName, out var keyTexts))
            {
                keyTexts = new HashSet<string>(StringComparer.Ordinal);
                byTable.Add(entry.TableName, keyTexts);
            }

            keyTexts.Add(entry.KeyText);
        }

        return byTable;
    }
}

/// <summary>
/// Records the journal entries a graph save is about to need, before the save itself runs ("journal-first").
/// </summary>
/// <remarks>
/// <para>
/// The traversal mirrors the decision procedure of the graph saver: a removed node has its cascade subtree recorded as
/// deletes (children first, each regardless of its own state) followed by the node itself, an added or updated node is
/// recorded as an upsert, and an unchanged node contributes nothing of its own - but its children are still visited
/// while the save cascades, because a changed child under an unchanged root is written all the same.
/// </para>
/// <para>
/// It is one traversal rather than one per entity type: the children come from
/// <see cref="EntityBaseCore.EnumerateCascadeChildren"/>, which yields the same cascade navigations the saver's own walk
/// enumerates (the saver reads them from its EntitySaveMetadata.CascadeNavigations rather than calling this method), and
/// a node is recorded only when its CLR type has a descriptor. A table on the path that is not synchronised is therefore
/// walked through without an entry of its own, and a subtree holding no synchronised table records nothing.
/// </para>
/// <para>
/// Recording the whole graph first keeps the journal-first safety order for every row the save is going to touch: an
/// entry whose write then fails or is rolled back describes a row the upload re-reads and settles without a round trip.
/// </para>
/// </remarks>
public sealed class SyncGraphRecorder
{
    private readonly Dictionary<Type, ISyncTableDescriptor> _descriptors;

    /// <summary>Creates the recorder over the descriptors of every synchronised table.</summary>
    /// <remarks>
    /// Every table the diagram synchronises belongs here, including one a particular engine was built without: the
    /// journal is shared, and a graph save reaching such a table records it exactly as it did before the exclusion.
    /// </remarks>
    /// <param name="descriptors">The descriptors, one per synchronised table.</param>
    public SyncGraphRecorder(IEnumerable<ISyncTableDescriptor> descriptors)
    {
        ArgumentNullException.ThrowIfNull(descriptors);
        _descriptors = descriptors.ToDictionary(descriptor => descriptor.EntityType);
    }

    /// <summary>Records the entries for a graph save rooted at the given entity (the cascade children included).</summary>
    /// <param name="journal">The journal the entries are recorded to.</param>
    /// <param name="entity">The root of the graph the save was asked for.</param>
    /// <param name="cascadeSave">Whether the save cascades into the children.</param>
    /// <param name="cascadeDelete">Whether removing the root removes its subtree.</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    public async Task RecordSaveAsync(
        SyncJournal journal,
        EntityBaseCore entity,
        bool cascadeSave,
        bool cascadeDelete,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(journal);
        ArgumentNullException.ThrowIfNull(entity);

        if (entity.RowState == RowState.Removed)
        {
            if (cascadeDelete)
            {
                await RecordDeleteGraphAsync(journal, entity, cancellationToken)
                    .ConfigureAwait(false);
            }
            else
            {
                await RecordDeleteAsync(journal, entity, cancellationToken).ConfigureAwait(false);
            }

            return;
        }

        if (entity.RowState != RowState.Unchanged && Find(entity) is { } descriptor)
        {
            await journal
                .RecordAsync(
                    descriptor.TableName,
                    descriptor.FormatEntityKey(entity),
                    SyncJournalOperation.Upsert,
                    null,
                    cancellationToken
                )
                .ConfigureAwait(false);
        }

        if (!cascadeSave)
        {
            return;
        }

        foreach (var child in entity.EnumerateCascadeChildren())
        {
            await RecordSaveAsync(journal, child, cascadeSave, cascadeDelete, cancellationToken)
                .ConfigureAwait(false);
        }
    }

    /// <summary>Records the whole subtree as deletes, children first (the saver removes them regardless of their own state).</summary>
    private async Task RecordDeleteGraphAsync(
        SyncJournal journal,
        EntityBaseCore entity,
        CancellationToken cancellationToken
    )
    {
        foreach (var child in entity.EnumerateCascadeChildren())
        {
            await RecordDeleteGraphAsync(journal, child, cancellationToken).ConfigureAwait(false);
        }

        await RecordDeleteAsync(journal, entity, cancellationToken).ConfigureAwait(false);
    }

    /// <summary>Records the delete of one node, carrying the mirrored version the row holds (nothing for an unsynchronised table).</summary>
    private Task RecordDeleteAsync(
        SyncJournal journal,
        EntityBaseCore entity,
        CancellationToken cancellationToken
    ) =>
        Find(entity) is { } descriptor
            ? journal.RecordAsync(
                descriptor.TableName,
                descriptor.FormatEntityKey(entity),
                SyncJournalOperation.Delete,
                descriptor.ReadEntityRowVersion(entity),
                cancellationToken
            )
            : Task.CompletedTask;

    /// <summary>Finds the descriptor of the node's table, or null when the table is not synchronised.</summary>
    private ISyncTableDescriptor? Find(EntityBaseCore entity) =>
        _descriptors.GetValueOrDefault(entity.GetType());
}

/// <summary>
/// Generic core of the journaling repository decorator: every write entry point on the repository contract records
/// its intent to the journal before the write is performed, and everything else is forwarded untouched.
/// </summary>
/// <remarks>
/// <para>
/// It wraps the repository rather than hooking into the save pipeline because a save hook only fires for a graph save -
/// a direct Insert, Update, Delete, or BulkInsert passes it by. Offline editing has to be caught at every write, so
/// every write entry point on the contract records here. What stays with the generated derived class is only what the
/// generic core cannot reach: the members the concrete interface adds - named queries and the binary column accessors -
/// which the derived class forwards itself.
/// </para>
/// <para>
/// Raw SQL (<c>ExecuteSqlAsync</c>) is forwarded untouched and is <b>not</b> recorded: the statement's shape is opaque
/// to the decorator, so there is no key to journal. The same holds for the bulk delete behind
/// <c>Query().ExecuteDeleteAsync</c>, whose rows are chosen by a predicate the decorator never sees. Rows changed
/// either way reach the server only if something else records them.
/// </para>
/// </remarks>
/// <typeparam name="TEntity">The entity type.</typeparam>
/// <typeparam name="TKey">The primary key type.</typeparam>
public abstract class JournalingRepositoryBase<TEntity, TKey> : IRepositoryCore<TEntity, TKey>
    where TEntity : EntityBaseCore, new()
{
    /// <summary>Creates the decorator over the repository it wraps, the journal, the table's descriptor, and the graph recorder.</summary>
    protected JournalingRepositoryBase(
        IRepositoryCore<TEntity, TKey> inner,
        SyncJournal journal,
        SyncTableDescriptor<TEntity, TKey> descriptor,
        SyncGraphRecorder graphRecorder
    )
    {
        ArgumentNullException.ThrowIfNull(descriptor);
        ArgumentNullException.ThrowIfNull(graphRecorder);
        Inner = inner;
        Journal = journal;
        Descriptor = descriptor;
        GraphRecorder = graphRecorder;
    }

    /// <summary>Gets the wrapped repository every call is forwarded to.</summary>
    protected IRepositoryCore<TEntity, TKey> Inner { get; }

    /// <summary>Gets the journal the write intents are recorded to.</summary>
    protected SyncJournal Journal { get; }

    /// <summary>Gets the table's descriptor (its journal name, and how its key and mirrored version are read).</summary>
    protected SyncTableDescriptor<TEntity, TKey> Descriptor { get; }

    /// <summary>Gets the recorder that journals the whole cascade a graph save is about to write.</summary>
    protected SyncGraphRecorder GraphRecorder { get; }

    /// <summary>Gets the server-side table name the journal entries are recorded under.</summary>
    protected string TableName => Descriptor.TableName;

    /// <summary>Reads the primary key of the given entity.</summary>
    protected TKey ReadKey(TEntity entity) => Descriptor.ReadKey(entity);

    /// <summary>Formats a key into the journal's key text (the same serialization the sync engine reads back).</summary>
    protected string FormatKey(TKey key) => Descriptor.FormatKey(key);

    /// <summary>Records a delete intent for the given key (the versioned and versionless subclasses differ here).</summary>
    protected abstract Task RecordDeleteAsync(TKey id, CancellationToken cancellationToken);

    /// <summary>Records the whole cascade a graph save is about to write, before the save itself runs.</summary>
    /// <remarks>
    /// The decorator sees only the root, while the saver walks the cascade navigations and writes the descendants too.
    /// The recorder walks the same navigations, so the children a save writes or deletes are journaled exactly like the
    /// root - and a table on the path that is not synchronised is walked through without an entry of its own.
    /// </remarks>
    protected Task RecordGraphSaveAsync(
        TEntity entity,
        bool cascadeSave,
        bool cascadeDelete,
        CancellationToken cancellationToken
    ) =>
        GraphRecorder.RecordSaveAsync(
            Journal,
            entity,
            cascadeSave,
            cascadeDelete,
            cancellationToken
        );

    /// <summary>Records the intent to write the given row, unless the sync engine is the one writing.</summary>
    protected Task RecordUpsertAsync(TEntity entity, CancellationToken cancellationToken) =>
        Journal.RecordAsync(
            TableName,
            FormatKey(ReadKey(entity)),
            SyncJournalOperation.Upsert,
            null,
            cancellationToken
        );

    /// <inheritdoc />
    public Task<TEntity?> GetByIdAsync(TKey id, CancellationToken cancellationToken = default) =>
        Inner.GetByIdAsync(id, cancellationToken);

    /// <inheritdoc />
    public Task<IReadOnlyList<TEntity>> GetAllAsync(CancellationToken cancellationToken = default) =>
        Inner.GetAllAsync(cancellationToken);

    /// <inheritdoc />
    /// <remarks>A read-only check: it writes nothing, so there is nothing to journal.</remarks>
    public Task<IReadOnlyList<UniquenessViolation>> CheckUniquenessAsync(
        TEntity entity,
        CancellationToken cancellationToken = default
    ) => Inner.CheckUniquenessAsync(entity, cancellationToken);

    /// <inheritdoc />
    public async Task InsertAsync(TEntity entity, CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(entity);
        await RecordUpsertAsync(entity, cancellationToken).ConfigureAwait(false);
        await Inner.InsertAsync(entity, cancellationToken).ConfigureAwait(false);
    }

    /// <inheritdoc />
    public async Task<bool> UpdateAsync(
        TEntity entity,
        ConcurrencyMode mode = ConcurrencyMode.Optimistic,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(entity);
        await RecordUpsertAsync(entity, cancellationToken).ConfigureAwait(false);

        return await Inner.UpdateAsync(entity, mode, cancellationToken).ConfigureAwait(false);
    }

    /// <inheritdoc />
    public async Task<bool> DeleteAsync(TKey id, CancellationToken cancellationToken = default)
    {
        await RecordDeleteAsync(id, cancellationToken).ConfigureAwait(false);

        return await Inner.DeleteAsync(id, cancellationToken).ConfigureAwait(false);
    }

    /// <inheritdoc />
    public async Task<int> BulkInsertAsync(
        IEnumerable<TEntity> entities,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(entities);
        var materialized = entities.ToList();

        foreach (var entity in materialized)
        {
            if (entity is not null)
            {
                await RecordUpsertAsync(entity, cancellationToken).ConfigureAwait(false);
            }
        }

        return await Inner.BulkInsertAsync(materialized, cancellationToken)
            .ConfigureAwait(false);
    }

    /// <inheritdoc />
    public async Task<int> SaveAsync(
        TEntity entity,
        bool cascadeSave = true,
        bool cascadeDelete = true,
        bool insertWhenUpdateMissing = false,
        ConcurrencyMode mode = ConcurrencyMode.Optimistic,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(entity);
        await RecordGraphSaveAsync(entity, cascadeSave, cascadeDelete, cancellationToken)
            .ConfigureAwait(false);

        return await Inner.SaveAsync(
            entity,
            cascadeSave,
            cascadeDelete,
            insertWhenUpdateMissing,
            mode,
            cancellationToken
        )
            .ConfigureAwait(false);
    }

    /// <inheritdoc />
    public async Task<int> SaveAsync(
        IEnumerable<TEntity> entities,
        bool cascadeSave = true,
        bool cascadeDelete = true,
        bool insertWhenUpdateMissing = false,
        ConcurrencyMode mode = ConcurrencyMode.Optimistic,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(entities);
        var materialized = entities.ToList();

        foreach (var entity in materialized)
        {
            if (entity is not null)
            {
                await RecordGraphSaveAsync(entity, cascadeSave, cascadeDelete, cancellationToken)
                    .ConfigureAwait(false);
            }
        }

        return await Inner.SaveAsync(
            materialized,
            cascadeSave,
            cascadeDelete,
            insertWhenUpdateMissing,
            mode,
            cancellationToken
        )
            .ConfigureAwait(false);
    }

    /// <inheritdoc />
    public SqlQuery<TEntity> Query() => Inner.Query();

    /// <inheritdoc />
    public Task<IReadOnlyList<TEntity>> QueryBySqlAsync(
        string sql,
        object? parameters = null,
        CancellationToken cancellationToken = default
    ) => Inner.QueryBySqlAsync(sql, parameters, cancellationToken);

    /// <inheritdoc />
    public Task<int> ExecuteSqlAsync(
        string sql,
        object? parameters = null,
        CancellationToken cancellationToken = default
    ) => Inner.ExecuteSqlAsync(sql, parameters, cancellationToken);

    /// <inheritdoc />
    public Task<TResult?> ExecuteScalarSqlAsync<TResult>(
        string sql,
        object? parameters = null,
        CancellationToken cancellationToken = default
    ) => Inner.ExecuteScalarSqlAsync<TResult>(sql, parameters, cancellationToken);
}

/// <summary>Journaling decorator core for a table with a row-version column (a delete intent carries the mirrored version).</summary>
/// <typeparam name="TEntity">The entity type.</typeparam>
/// <typeparam name="TKey">The primary key type.</typeparam>
public abstract class JournalingRepository<TEntity, TKey> : JournalingRepositoryBase<TEntity, TKey>
    where TEntity : EntityBaseCore, new()
{
    /// <summary>Creates the decorator over the repository it wraps, the journal, the table's descriptor, and the graph recorder.</summary>
    protected JournalingRepository(
        IRepositoryCore<TEntity, TKey> inner,
        SyncJournal journal,
        SyncTableDescriptor<TEntity, TKey> descriptor,
        SyncGraphRecorder graphRecorder
    )
        : base(inner, journal, descriptor, graphRecorder) { }

    /// <summary>Reads the mirrored row version of the given entity.</summary>
    private byte[]? ReadRowVersion(TEntity entity) => Descriptor.ReadRowVersion(entity);

    /// <inheritdoc />
    protected sealed override async Task RecordDeleteAsync(
        TKey id,
        CancellationToken cancellationToken
    )
    {
        // The row has to be read before it goes: its mirrored version is the only thing that lets the delete be
        // replayed under a version guard, and once the row is gone there is nowhere left to read it from.
        if (!SyncSession.IsSuppressed)
        {
            var existing = await Inner.GetByIdAsync(id, cancellationToken).ConfigureAwait(false);
            await Journal.RecordAsync(
                TableName,
                FormatKey(id),
                SyncJournalOperation.Delete,
                existing is null ? null : ReadRowVersion(existing),
                cancellationToken
            )
                .ConfigureAwait(false);
        }
    }
}

/// <summary>Journaling decorator core for a table without a row-version column (a delete intent carries no version and replays unguarded).</summary>
/// <typeparam name="TEntity">The entity type.</typeparam>
/// <typeparam name="TKey">The primary key type.</typeparam>
public abstract class VersionlessJournalingRepository<TEntity, TKey>
    : JournalingRepositoryBase<TEntity, TKey>
    where TEntity : EntityBaseCore, new()
{
    /// <summary>Creates the decorator over the repository it wraps, the journal, the table's descriptor, and the graph recorder.</summary>
    protected VersionlessJournalingRepository(
        IRepositoryCore<TEntity, TKey> inner,
        SyncJournal journal,
        SyncTableDescriptor<TEntity, TKey> descriptor,
        SyncGraphRecorder graphRecorder
    )
        : base(inner, journal, descriptor, graphRecorder) { }

    /// <inheritdoc />
    protected sealed override Task RecordDeleteAsync(TKey id, CancellationToken cancellationToken) =>
        // No version column means there is no mirrored version to capture before the row goes; the delete replays
        // without a guard, which is all a last-write-wins table can promise anyway.
        Journal.RecordAsync(
            TableName,
            FormatKey(id),
            SyncJournalOperation.Delete,
            null,
            cancellationToken
        );
}

/// <summary>
/// Generic core of the direct (same-process database connection) server source: the key set and the change stream
/// come through the server's raw SQL surface, and the local changes are replayed through the server's ordinary
/// repository. What stays with the generated derived class is only the SQL text, which carries the table's identity.
/// </summary>
/// <remarks>
/// The paging members are virtual here rather than left to the interface's default implementations on purpose:
/// interface mapping is fixed at the class that lists the interface - this one - so a member a derived class adds later
/// would never be reached through the interface. A virtual with the same default keeps the dispatch open for the
/// versionless subclass, which does override them.
/// </remarks>
/// <typeparam name="TEntity">The entity type.</typeparam>
/// <typeparam name="TKey">The primary key type.</typeparam>
public abstract class DirectSyncSourceBase<TEntity, TKey> : ISyncServerSource<TEntity, TKey>
    where TEntity : EntityBaseCore, new()
{
    /// <summary>Creates the source over the server's raw SQL surface, the repository local changes replay against, and the table's descriptor.</summary>
    protected DirectSyncSourceBase(
        ISqlExecutor serverSqlExecutor,
        IRemoteRepositoryCore<TEntity, TKey> writer,
        SyncTableDescriptor<TEntity, TKey> descriptor
    )
    {
        ArgumentNullException.ThrowIfNull(serverSqlExecutor);
        ArgumentNullException.ThrowIfNull(writer);
        ArgumentNullException.ThrowIfNull(descriptor);
        ServerSqlExecutor = serverSqlExecutor;
        Writer = writer;
        Descriptor = descriptor;
        BinaryColumns =
            descriptor.UnboundedBinaryColumnNames.Count == 0
                ? null
                : new SyncRepositoryBinaryColumns<TEntity, TKey>(descriptor, writer);
    }

    /// <summary>Gets the server's raw SQL surface the scans read through.</summary>
    protected ISqlExecutor ServerSqlExecutor { get; }

    /// <summary>Gets the table's descriptor (the SQL text that carries the table's identity).</summary>
    protected SyncTableDescriptor<TEntity, TKey> Descriptor { get; }

    /// <inheritdoc />
    public IRemoteRepositoryCore<TEntity, TKey> Writer { get; }

    /// <inheritdoc />
    /// <remarks>
    /// Null exactly when the descriptor names no unbounded binary column. The accessors are invoked on
    /// <see cref="Writer"/>, which is the generated server repository the direct registration hands in.
    /// </remarks>
    public ISyncBinaryColumns<TKey>? BinaryColumns { get; }

    /// <summary>SELECT that returns every primary key of the table (SQL Server quoting).</summary>
    protected string ServerKeysSql => Descriptor.ServerKeysSql;

    /// <inheritdoc />
    public abstract Task<byte[]?> GetChangeCeilingAsync(
        CancellationToken cancellationToken = default
    );

    /// <inheritdoc />
    public abstract Task<SyncChangeBatch<TEntity>> GetChangesAsync(
        byte[]? anchor,
        byte[]? ceiling,
        int batchSize,
        CancellationToken cancellationToken = default
    );

    /// <inheritdoc />
    public virtual Task<SyncChangeBatch<TEntity>> GetFirstPageAsync(
        int batchSize,
        CancellationToken cancellationToken = default
    ) =>
        throw new NotSupportedException(
            "This source does not page by primary key; it serves a versioned table."
        );

    /// <inheritdoc />
    public virtual Task<SyncChangeBatch<TEntity>> GetPageAfterAsync(
        TKey afterKey,
        int batchSize,
        CancellationToken cancellationToken = default
    ) =>
        throw new NotSupportedException(
            "This source does not page by primary key; it serves a versioned table."
        );

    /// <inheritdoc />
    public async Task<IReadOnlyList<TKey>> GetAllKeysAsync(
        CancellationToken cancellationToken = default
    ) =>
        await ServerSqlExecutor.QueryProjectionBySqlAsync<TKey>(
            ServerKeysSql,
            null,
            cancellationToken
        )
            .ConfigureAwait(false);
}

/// <summary>Direct server source for a table with a row-version column (an ascending, anchored change scan).</summary>
/// <typeparam name="TEntity">The entity type.</typeparam>
/// <typeparam name="TKey">The primary key type.</typeparam>
public sealed class DirectSyncSource<TEntity, TKey> : DirectSyncSourceBase<TEntity, TKey>
    where TEntity : EntityBaseCore, new()
{
    /// <summary>Creates the source over the server's raw SQL surface, the repository local changes replay against, and the table's descriptor.</summary>
    public DirectSyncSource(
        ISqlExecutor serverSqlExecutor,
        IRemoteRepositoryCore<TEntity, TKey> writer,
        SyncTableDescriptor<TEntity, TKey> descriptor
    )
        : base(serverSqlExecutor, writer, descriptor) { }

    /// <summary>SELECT that returns one ascending batch of rows above the anchor and below the ceiling (SQL Server quoting).</summary>
    private string ServerChangesSql => Descriptor.ServerChangesSql;

    /// <inheritdoc />
    public override async Task<byte[]?> GetChangeCeilingAsync(
        CancellationToken cancellationToken = default
    ) =>
        await ServerSqlExecutor.ExecuteScalarSqlAsync<byte[]>(
            "SELECT MIN_ACTIVE_ROWVERSION()",
            null,
            cancellationToken
        )
            .ConfigureAwait(false);

    /// <inheritdoc />
    /// <remarks>
    /// A full batch is reported as "there is more", which the next call settles: it either returns the rest or comes
    /// back empty when the batch happened to end exactly on the boundary. The extra round trip in that case is the
    /// price of not fetching a row beyond the batch to peek with, and it costs one empty query per drained table.
    /// </remarks>
    public override async Task<SyncChangeBatch<TEntity>> GetChangesAsync(
        byte[]? anchor,
        byte[]? ceiling,
        int batchSize,
        CancellationToken cancellationToken = default
    )
    {
        var rows = await ServerSqlExecutor.QueryBySqlAsync<TEntity>(
            ServerChangesSql,
            new
            {
                anchor,
                ceiling,
                batchSize,
            },
            cancellationToken
        )
            .ConfigureAwait(false);

        return new SyncChangeBatch<TEntity>(rows, rows.Count >= batchSize);
    }
}

/// <summary>Direct server source for a table without a row-version column (a key-ordered full scan, paged by primary key).</summary>
/// <typeparam name="TEntity">The entity type.</typeparam>
/// <typeparam name="TKey">The primary key type.</typeparam>
public sealed class VersionlessDirectSyncSource<TEntity, TKey>
    : DirectSyncSourceBase<TEntity, TKey>
    where TEntity : EntityBaseCore, new()
{
    /// <summary>Creates the source over the server's raw SQL surface, the repository local changes replay against, and the table's descriptor.</summary>
    public VersionlessDirectSyncSource(
        ISqlExecutor serverSqlExecutor,
        IRemoteRepositoryCore<TEntity, TKey> writer,
        SyncTableDescriptor<TEntity, TKey> descriptor
    )
        : base(serverSqlExecutor, writer, descriptor) { }

    /// <summary>SELECT that returns the first ascending batch of rows by primary key (SQL Server quoting).</summary>
    private string ServerPageFirstSql => Descriptor.ServerPageFirstSql;

    /// <summary>SELECT that returns the next ascending batch of rows above a key (SQL Server quoting).</summary>
    private string ServerPageAfterSql => Descriptor.ServerPageAfterSql;

    /// <inheritdoc />
    /// <remarks>A key-ordered scan has no version to bound, so there is no ceiling to read.</remarks>
    public override Task<byte[]?> GetChangeCeilingAsync(
        CancellationToken cancellationToken = default
    ) => Task.FromResult<byte[]?>(null);

    /// <inheritdoc />
    /// <remarks>Never called for a table without a version column; the download pages by key instead.</remarks>
    public override Task<SyncChangeBatch<TEntity>> GetChangesAsync(
        byte[]? anchor,
        byte[]? ceiling,
        int batchSize,
        CancellationToken cancellationToken = default
    ) =>
        throw new NotSupportedException(
            "The table has no version column; its download pages by primary key."
        );

    /// <inheritdoc />
    /// <remarks>
    /// A full batch is reported as "there is more", which the next call settles: it either returns the rest or comes
    /// back empty when the batch happened to end exactly on the boundary - the same trade the versioned change scan
    /// makes.
    /// </remarks>
    public override async Task<SyncChangeBatch<TEntity>> GetFirstPageAsync(
        int batchSize,
        CancellationToken cancellationToken = default
    )
    {
        var rows = await ServerSqlExecutor.QueryBySqlAsync<TEntity>(
            ServerPageFirstSql,
            new { batchSize },
            cancellationToken
        )
            .ConfigureAwait(false);

        return new SyncChangeBatch<TEntity>(rows, rows.Count >= batchSize);
    }

    /// <inheritdoc />
    public override async Task<SyncChangeBatch<TEntity>> GetPageAfterAsync(
        TKey afterKey,
        int batchSize,
        CancellationToken cancellationToken = default
    )
    {
        var rows = await ServerSqlExecutor.QueryBySqlAsync<TEntity>(
            ServerPageAfterSql,
            new { afterKey, batchSize },
            cancellationToken
        )
            .ConfigureAwait(false);

        return new SyncChangeBatch<TEntity>(rows, rows.Count >= batchSize);
    }
}

/// <summary>The descriptors of the synchronised tables, and the graph recorder that reads them.</summary>
/// <remarks>
/// <para>
/// This is the whole of what a table contributes to the sync support: its name, the SQL that carries its identity, and
/// the accessors that read a key, a mirrored version, and an unbounded binary column off it. The behaviour lives once in
/// the fixed engine, which takes a descriptor rather than being subclassed per table.
/// </para>
/// <para>
/// <see cref="All"/> holds every synchronised table, in foreign-key order (parents first), whatever a particular engine
/// was built to exclude: the journal is shared, and the recorder has to be able to name any table a graph save reaches.
/// </para>
/// </remarks>
public static class GeneratedSyncTables
{
    /// <summary>The descriptor of syncvo_orders.</summary>
    public static SyncTableDescriptor<SyncvoOrderEntity, OrderIdValue> SyncvoOrder { get; } =
        new()
        {
            TableName = "syncvo_orders",
            RemoteRouteName = "SyncvoOrder",
            IsVersionless = false,
            ReadKey = entity => entity.OrderId,
            WriteKey = (entity, key) => entity.OrderId = key,
            FormatKey = key => key.Value.ToString(CultureInfo.InvariantCulture),
            ParseKey = keyText => OrderIdValue.Create(int.Parse(keyText, CultureInfo.InvariantCulture)),
            ReadRowVersion = entity => entity.RowVer?.Value,
            WriteRowVersion = (entity, rowVersion) => entity.RowVer = RowVerValue.Create(rowVersion ?? []),
            ServerKeysSql = "SELECT [order_id] FROM [syncvo_orders]",
            ServerChangesSql = "SELECT TOP (@batchSize) * FROM [syncvo_orders] WHERE (@anchor IS NULL OR [row_ver] > CAST(@anchor AS binary(8))) AND (@ceiling IS NULL OR [row_ver] < CAST(@ceiling AS binary(8))) ORDER BY [row_ver]",
            LocalAnchorSql = "SELECT MAX(\"row_ver\") FROM \"syncvo_orders\"",
            LocalKeysSql = "SELECT \"order_id\" FROM \"syncvo_orders\"",
            LocalExistingKeysSql = "SELECT \"order_id\" FROM \"syncvo_orders\" WHERE \"order_id\" IN (@keys)",
            LocalDeleteAllSql = "DELETE FROM \"syncvo_orders\"",
        };

    /// <summary>The descriptor of syncvo_lines.</summary>
    public static SyncTableDescriptor<SyncvoLineEntity, LineIdValue> SyncvoLine { get; } =
        new()
        {
            TableName = "syncvo_lines",
            RemoteRouteName = "SyncvoLine",
            IsVersionless = false,
            ReadKey = entity => entity.LineId,
            WriteKey = (entity, key) => entity.LineId = key,
            FormatKey = key => key.Value.ToString(CultureInfo.InvariantCulture),
            ParseKey = keyText => LineIdValue.Create(int.Parse(keyText, CultureInfo.InvariantCulture)),
            ReadRowVersion = entity => entity.RowVer?.Value,
            WriteRowVersion = (entity, rowVersion) => entity.RowVer = RowVerValue.Create(rowVersion ?? []),
            ServerKeysSql = "SELECT [line_id] FROM [syncvo_lines]",
            ServerChangesSql = "SELECT TOP (@batchSize) * FROM [syncvo_lines] WHERE (@anchor IS NULL OR [row_ver] > CAST(@anchor AS binary(8))) AND (@ceiling IS NULL OR [row_ver] < CAST(@ceiling AS binary(8))) ORDER BY [row_ver]",
            LocalAnchorSql = "SELECT MAX(\"row_ver\") FROM \"syncvo_lines\"",
            LocalKeysSql = "SELECT \"line_id\" FROM \"syncvo_lines\"",
            LocalExistingKeysSql = "SELECT \"line_id\" FROM \"syncvo_lines\" WHERE \"line_id\" IN (@keys)",
            LocalDeleteAllSql = "DELETE FROM \"syncvo_lines\"",
        };

    /// <summary>Every synchronised table's descriptor, in foreign-key order (parents first).</summary>
    public static IReadOnlyList<ISyncTableDescriptor> All { get; } =
    [
        SyncvoOrder,
        SyncvoLine,
    ];

    /// <summary>The recorder the journaling decorators journal a graph save through.</summary>
    /// <remarks>
    /// One instance for the whole application: it holds nothing but the lookup from entity type to descriptor, and the
    /// journal it writes to is handed to it per call.
    /// </remarks>
    public static SyncGraphRecorder GraphRecorder { get; } = new(All);
}

/// <summary>
/// The local SyncvoOrderEntity repository with journaling: every write is recorded before it is performed.
/// </summary>
/// <remarks>
/// The recording and forwarding semantics live on the generic core (see
/// <see cref="JournalingRepositoryBase{TEntity, TKey}"/>), which reads the table's identity and key handling off the
/// descriptor and journals a graph save through <see cref="SyncGraphRecorder"/> (which walks the same cascade
/// navigations the saver walks, so the children the save writes or deletes are journaled exactly like the root). What
/// remains here is forwarding the members the concrete contract adds.
/// </remarks>
public sealed class JournalingSyncvoOrderRepository
    : JournalingRepository<SyncvoOrderEntity, OrderIdValue>, ISyncvoOrderRepository
{
    /// <summary>Creates the decorator over the repository it wraps and the journal it records to.</summary>
    public JournalingSyncvoOrderRepository(ISyncvoOrderRepository inner, SyncJournal journal)
        : base(
            inner,
            journal,
            GeneratedSyncTables.SyncvoOrder,
            GeneratedSyncTables.GraphRecorder
        ) { }
}

/// <summary>
/// The local SyncvoLineEntity repository with journaling: every write is recorded before it is performed.
/// </summary>
/// <remarks>
/// The recording and forwarding semantics live on the generic core (see
/// <see cref="JournalingRepositoryBase{TEntity, TKey}"/>), which reads the table's identity and key handling off the
/// descriptor and journals a graph save through <see cref="SyncGraphRecorder"/> (which walks the same cascade
/// navigations the saver walks, so the children the save writes or deletes are journaled exactly like the root). What
/// remains here is forwarding the members the concrete contract adds.
/// </remarks>
public sealed class JournalingSyncvoLineRepository
    : JournalingRepository<SyncvoLineEntity, LineIdValue>, ISyncvoLineRepository
{
    /// <summary>Creates the decorator over the repository it wraps and the journal it records to.</summary>
    public JournalingSyncvoLineRepository(ISyncvoLineRepository inner, SyncJournal journal)
        : base(
            inner,
            journal,
            GeneratedSyncTables.SyncvoLine,
            GeneratedSyncTables.GraphRecorder
        ) { }
}

/// <summary>DI registration for the bidirectional sync support.</summary>
/// <remarks>
/// <para>
/// The registration comes in two halves, and which half is combined with which is the only thing that decides how the
/// server is reached. The local half - <c>AddGeneratedSyncEngine</c> - registers the journal, the per-table descriptors,
/// and the engine, and wraps the local repositories with their journaling decorators so every local write is recorded no
/// matter which entry point the application uses. The server half registers the differential sources, either
/// <c>AddGeneratedDirectSyncSources</c> (a database connection this process holds). Swapping direct for remote is a change of that
/// one line and of nothing else: the engine resolves <c>ISyncServerSource&lt;,&gt;</c> either way.
/// </para>
/// <para>
/// <c>AddGeneratedSyncSupport</c> is the two halves together for the all-direct setup, which is the common case when both
/// databases are reachable from the same process.
/// </para>
/// <para>
/// Every key argument accepts <c>null</c>, which means the ordinary non-keyed registration rather than a key whose value
/// is null - the two never collide, because a keyed registration cannot be made with a null key. A server process that
/// registers its repositories plainly therefore passes <c>null</c>, while a hybrid client that holds two engines at once
/// passes the keys it registered them under.
/// </para>
/// <para>
/// The decoration keeps the original registration's factory and calls it for the inner instance, so the local
/// repositories are still built exactly as their own registration built them.
/// </para>
/// </remarks>
public static class GeneratedSyncServiceCollectionExtensions
{
    /// <summary>Registers the sync engine and the direct server sources together (the all-direct setup).</summary>
    /// <param name="services">The service collection.</param>
    /// <param name="serverServiceKey">The key the server (SQL Server) repositories were registered under (null for the non-keyed registration).</param>
    /// <param name="localServiceKey">The key the local (SQLite) repositories were registered under (null for the non-keyed registration).</param>
    /// <param name="excludeFromSync">Entity types this engine never synchronises (see <c>AddGeneratedSyncEngine</c>).</param>
    public static IServiceCollection AddGeneratedSyncSupport(
        this IServiceCollection services,
        object? serverServiceKey,
        object? localServiceKey,
        IReadOnlyCollection<Type>? excludeFromSync = null
    )
    {
        ArgumentNullException.ThrowIfNull(services);
        AddGeneratedDirectSyncSources(services, serverServiceKey);

        return AddGeneratedSyncEngine(services, localServiceKey, excludeFromSync);
    }

    /// <summary>Registers the differential sources that read the server over a direct database connection.</summary>
    /// <remarks>
    /// This is also what a server process registers before mapping the sync endpoints: those endpoints are a thin
    /// remoting of this very interface, so the server answers them from the same source a co-located client would use.
    /// </remarks>
    /// <param name="services">The service collection.</param>
    /// <param name="serverServiceKey">The key the server (SQL Server) repositories were registered under (null for the non-keyed registration).</param>
    public static IServiceCollection AddGeneratedDirectSyncSources(
        this IServiceCollection services,
        object? serverServiceKey
    )
    {
        ArgumentNullException.ThrowIfNull(services);

        AddDirectSource<SyncvoOrderEntity, OrderIdValue, ISyncvoOrderRepository>(
            services,
            serverServiceKey,
            GeneratedSyncTables.SyncvoOrder
        );

        AddDirectSource<SyncvoLineEntity, LineIdValue, ISyncvoLineRepository>(
            services,
            serverServiceKey,
            GeneratedSyncTables.SyncvoLine
        );

        return services;
    }

    /// <summary>Registers one table's differential source over a direct database connection.</summary>
    /// <remarks>
    /// The server repository stands in two places at once: it is the writer local changes are replayed against, and -
    /// for a table with unbounded binary columns - the surface those columns are copied through.
    /// </remarks>
    /// <typeparam name="TEntity">The entity type.</typeparam>
    /// <typeparam name="TKey">The primary key type.</typeparam>
    /// <typeparam name="TRepository">The generated repository contract of the entity.</typeparam>
    /// <param name="services">The service collection.</param>
    /// <param name="serverServiceKey">The key the server repositories were registered under (null for the non-keyed registration).</param>
    /// <param name="descriptor">The table's descriptor.</param>
    private static void AddDirectSource<TEntity, TKey, TRepository>(
        IServiceCollection services,
        object? serverServiceKey,
        SyncTableDescriptor<TEntity, TKey> descriptor
    )
        where TEntity : EntityBaseCore, new()
        where TRepository : class, IRepository<TEntity, TKey> =>
        services.AddScoped<ISyncServerSource<TEntity, TKey>>(provider =>
        {
            var serverSqlExecutor = Resolve<ISqlExecutor>(provider, serverServiceKey);
            var serverRepository = Resolve<TRepository>(provider, serverServiceKey);

            if (descriptor.IsVersionless)
            {
                return new VersionlessDirectSyncSource<TEntity, TKey>(
                    serverSqlExecutor,
                    serverRepository,
                    descriptor
                );
            }

            return new DirectSyncSource<TEntity, TKey>(
                serverSqlExecutor,
                serverRepository,
                descriptor
            );
        });

    /// <summary>Registers the local half: the journal, the journaling decorators, the table descriptors, and the engine.</summary>
    /// <remarks>
    /// <para>
    /// The differential sources are resolved rather than registered here, so exactly one of
    /// <c>AddGeneratedDirectSyncSources</c> has to be
    /// called as well. Leaving that out is not a silent failure: resolving the engine then fails on the missing source.
    /// </para>
    /// <para>
    /// <c>excludeFromSync</c> is the local-only declaration: an excluded table gets no journaling decorator (its
    /// writes are not recorded, and cost nothing extra) and no descriptor (no run downloads it, propagates deletes
    /// into it, or wipes it in a refresh). It is not a per-run scope - that is
    /// <see cref="SyncOptions.ExcludedEntityTypes"/> - and entries recorded before a table was excluded are never
    /// replayed; <see cref="SyncJournal.RemoveTableAsync"/> is how they are cleaned up. A type that is not a
    /// synchronised entity type, or an exclusion that leaves no table at all, is rejected here rather than
    /// discovered at the first run.
    /// </para>
    /// </remarks>
    /// <param name="services">The service collection.</param>
    /// <param name="localServiceKey">The key the local (SQLite) repositories were registered under (null for the non-keyed registration).</param>
    /// <param name="excludeFromSync">Entity types this engine never synchronises (null or empty keeps every table).</param>
    public static IServiceCollection AddGeneratedSyncEngine(
        this IServiceCollection services,
        object? localServiceKey,
        IReadOnlyCollection<Type>? excludeFromSync = null
    )
    {
        ArgumentNullException.ThrowIfNull(services);
        var excluded = ValidatedSyncExclusions(excludeFromSync);

        services.AddScoped(provider => new SyncJournal(
            Resolve<ISqlExecutor>(provider, localServiceKey)
        ));

        if (!excluded.Contains(typeof(SyncvoOrderEntity)))
        {
            Decorate<ISyncvoOrderRepository>(
                services,
                localServiceKey,
                (inner, provider) => new JournalingSyncvoOrderRepository(
                    inner,
                    provider.GetRequiredService<SyncJournal>()
                )
            );
            AddSyncTable<SyncvoOrderEntity, OrderIdValue, ISyncvoOrderRepository>(
                services,
                localServiceKey,
                GeneratedSyncTables.SyncvoOrder
            );
        }

        if (!excluded.Contains(typeof(SyncvoLineEntity)))
        {
            Decorate<ISyncvoLineRepository>(
                services,
                localServiceKey,
                (inner, provider) => new JournalingSyncvoLineRepository(
                    inner,
                    provider.GetRequiredService<SyncJournal>()
                )
            );
            AddSyncTable<SyncvoLineEntity, LineIdValue, ISyncvoLineRepository>(
                services,
                localServiceKey,
                GeneratedSyncTables.SyncvoLine
            );
        }

        services.AddScoped(provider => new SyncEngine(
            provider.GetServices<ISyncTable>(),
            provider.GetRequiredService<SyncJournal>()
        ));

        return services;
    }

    /// <summary>Registers one table with the engine, over the local repository the journaling decorator now wraps.</summary>
    /// <remarks>
    /// The local repository stands in two places here as well: the engine writes rows through it, and - for a table with
    /// unbounded binary columns - the copy reaches those columns through the same instance.
    /// </remarks>
    /// <typeparam name="TEntity">The entity type.</typeparam>
    /// <typeparam name="TKey">The primary key type.</typeparam>
    /// <typeparam name="TRepository">The generated repository contract of the entity.</typeparam>
    /// <param name="services">The service collection.</param>
    /// <param name="localServiceKey">The key the local repositories were registered under (null for the non-keyed registration).</param>
    /// <param name="descriptor">The table's descriptor.</param>
    private static void AddSyncTable<TEntity, TKey, TRepository>(
        IServiceCollection services,
        object? localServiceKey,
        SyncTableDescriptor<TEntity, TKey> descriptor
    )
        where TEntity : EntityBaseCore, new()
        where TRepository : class, IRepository<TEntity, TKey> =>
        services.AddScoped<ISyncTable>(provider =>
        {
            var local = Resolve<TRepository>(provider, localServiceKey);
            var localSqlExecutor = Resolve<ISqlExecutor>(provider, localServiceKey);
            var server = provider.GetRequiredService<ISyncServerSource<TEntity, TKey>>();

            if (descriptor.IsVersionless)
            {
                return new VersionlessSyncTable<TEntity, TKey>(
                    local,
                    localSqlExecutor,
                    server,
                    descriptor
                );
            }

            return new SyncTable<TEntity, TKey>(local, localSqlExecutor, server, descriptor);
        });

    /// <summary>Validates the construction-time exclusions: every named type must be synchronised, and at least one table must remain.</summary>
    /// <remarks>
    /// A name outside the synchronised set is rejected rather than skipped - a silently ignored exclusion would read
    /// as if it had worked - and excluding everything is rejected because an engine with no table is a configuration
    /// error wearing a valid registration.
    /// </remarks>
    private static HashSet<Type> ValidatedSyncExclusions(
        IReadOnlyCollection<Type>? excludeFromSync
    )
    {
        Type[] synchronised =
        [
            .. GeneratedSyncTables.All.Select(descriptor => descriptor.EntityType),
        ];
        var excluded = new HashSet<Type>(excludeFromSync ?? []);
        var unknown = excluded.Where(type => !synchronised.Contains(type)).ToList();

        if (unknown.Count > 0)
        {
            throw new ArgumentException(
                "excludeFromSync names types that are not synchronised entity types: "
                    + string.Join(", ", unknown.Select(type => type.Name))
                    + ".",
                nameof(excludeFromSync)
            );
        }

        if (excluded.Count >= synchronised.Length)
        {
            throw new ArgumentException(
                "excludeFromSync excludes every synchronised table, which leaves the engine nothing to do. "
                    + "Generate without sync support instead of excluding everything.",
                nameof(excludeFromSync)
            );
        }

        return excluded;
    }

    /// <summary>Resolves a service that was registered either under a key or plainly (<c>null</c> means the plain one).</summary>
    private static TService Resolve<TService>(IServiceProvider provider, object? serviceKey)
        where TService : notnull =>
        serviceKey is null
            ? provider.GetRequiredService<TService>()
            : provider.GetRequiredKeyedService<TService>(serviceKey);

    /// <summary>
    /// Replaces an existing registration with one that wraps the original instance, keeping the original factory.
    /// </summary>
    /// <remarks>
    /// The registration this decorates is a factory registration, so the inner instance can be produced by calling that
    /// same factory - the decorated repository is built exactly the way its own registration builds it. A non-keyed
    /// registration is found by the same predicate as a keyed one, because a plain descriptor carries a null service key
    /// and a keyed one can never be made with a null key.
    /// </remarks>
    private static void Decorate<TService>(
        IServiceCollection services,
        object? serviceKey,
        Func<TService, IServiceProvider, TService> decorate
    )
        where TService : class
    {
        var descriptor =
            services.LastOrDefault(candidate =>
                candidate.ServiceType == typeof(TService)
                && Equals(candidate.ServiceKey, serviceKey)
            )
            ?? throw new InvalidOperationException(
                $"No registration of {typeof(TService).Name} was found for the service key "
                    + $"'{serviceKey}'. Register the local repositories before calling AddGeneratedSyncEngine."
            );

        if (serviceKey is null)
        {
            var plainFactory =
                descriptor.ImplementationFactory ?? throw NotAFactoryRegistration<TService>(null);

            services.Remove(descriptor);
            services.Add(
                new ServiceDescriptor(
                    typeof(TService),
                    provider => decorate((TService)plainFactory(provider), provider),
                    descriptor.Lifetime
                )
            );

            return;
        }

        var keyedFactory =
            descriptor.KeyedImplementationFactory
            ?? throw NotAFactoryRegistration<TService>(serviceKey);

        services.Remove(descriptor);
        services.Add(
            new ServiceDescriptor(
                typeof(TService),
                serviceKey,
                (provider, key) => decorate((TService)keyedFactory(provider, key), provider),
                descriptor.Lifetime
            )
        );
    }

    /// <summary>Builds the failure for a registration the decorator cannot rebuild (an instance or a type registration).</summary>
    private static InvalidOperationException NotAFactoryRegistration<TService>(object? serviceKey) =>
        new(
            $"The registration of {typeof(TService).Name} for the service key '{serviceKey}' is not a "
                + "factory registration, so the journaling decorator cannot build the instance it wraps."
        );
}
}

namespace QuickER.Tests.GeneratedSyncVoFixture.Repositories.SqlServer
{

/// <summary>A factory that creates SQL Server connections.</summary>
public interface ISqlConnectionFactory
{
    /// <summary>Creates a new SQL connection.</summary>
    SqlConnection CreateConnection();
}

/// <summary>The default implementation that creates SQL connections from a connection string.</summary>
public sealed class SqlConnectionFactory(string connectionString) : ISqlConnectionFactory
{
    /// <summary>Creates a new SQL connection.</summary>
    public SqlConnection CreateConnection() => new(connectionString);
}

/// <summary>Creates a schema by running a DDL script against a SQL Server database.</summary>
/// <remarks>
/// A bootstrap convenience for development, tests, and samples - it turns the DDL QuickER generates into a usable
/// database in one call. It is not schema management: it knows nothing about versions, about what already exists,
/// or about rolling back, so anything that outlives a throwaway database wants a migration tool instead.
/// </remarks>
public static class SqlServerSchemaBootstrap
{
    /// <summary>Opens a connection and runs the whole DDL script.</summary>
    /// <remarks>
    /// <para>
    /// The script is sent as a single command. The DDL QuickER generates is one batch - it emits no <c>GO</c>
    /// separators and no statement that must start a batch of its own - so it needs no batch splitting.
    /// A hand-edited script that does contain <c>GO</c> has to be split by the caller.
    /// </para>
    /// <para>
    /// Pass the optional arguments by name (<c>commandTimeout:</c>, <c>cancellationToken:</c>). The optional parameter
    /// list is where later versions add their knobs, and a positional call would then quietly bind to a different one.
    /// </para>
    /// </remarks>
    /// <param name="connectionString">The connection string of the database to create the schema in.</param>
    /// <param name="ddl">The DDL script to run.</param>
    /// <param name="commandTimeout">How long the DDL command may run. Null keeps the provider's default; a large script on a slow machine may need more than that.</param>
    /// <param name="cancellationToken">A token that cancels the operation.</param>
    public static async Task ApplyDdlAsync(
        string connectionString,
        string ddl,
        TimeSpan? commandTimeout = null,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(connectionString);
        ArgumentException.ThrowIfNullOrWhiteSpace(ddl);

        await using var connection = new SqlConnectionFactory(connectionString).CreateConnection();
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        await using var command = connection.CreateCommand();
        command.CommandText = ddl;

        // The ADO command exposes its timeout in whole seconds, so a requested duration is rounded up (null keeps the provider default)
        if (commandTimeout is { } timeout)
        {
            ArgumentOutOfRangeException.ThrowIfLessThan(timeout, TimeSpan.Zero);
            command.CommandTimeout = (int)Math.Ceiling(timeout.TotalSeconds);
        }

        await command.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);
    }
}

/// <summary>The default implementation of the entity-agnostic raw SQL executor (the single implementation of binding, scalar conversion, and projection mapping).</summary>
/// <remarks>Stateless (holds only the connection factory), so it can be registered as a Singleton in DI. The repository's raw SQL methods delegate to this implementation.</remarks>
public sealed partial class SqlExecutor(ISqlConnectionFactory connectionFactory) : ISqlExecutor
{
    /// <summary>The source of SQL connections.</summary>
    private readonly ISqlConnectionFactory _connectionFactory = connectionFactory;

    /// <summary>Executes a raw SQL SELECT and maps the result rows strictly (all columns required) to {TEntity}.</summary>
    public async Task<IReadOnlyList<TEntity>> QueryBySqlAsync<TEntity>(
        string sql,
        object? parameters = null,
        CancellationToken cancellationToken = default
    )
        where TEntity : EntityBaseCore, new()
    {
        ArgumentNullException.ThrowIfNull(sql);

        var metadata = EntitySaveMetadata.For(typeof(TEntity));
        var items = new List<TEntity>();

        await using var connection = _connectionFactory.CreateConnection();
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        await using var command = new SqlCommand(sql, connection);
        BindParameters(command, parameters);

        await using var reader = await command.ExecuteReaderAsync(cancellationToken).ConfigureAwait(false);

        // The column ordinals are resolved once for the result set (on the first row, because some providers only
        // expose the result schema after a successful Read) and reused for every row
        EntitySaveMetadata.RawSqlRowPlan? plan = null;

        while (await reader.ReadAsync(cancellationToken).ConfigureAwait(false))
        {
            plan ??= metadata.CreateRawSqlRowPlan(reader);
            items.Add(metadata.MapEntityFromRawSql<TEntity>(reader, plan));
        }

        return items;
    }

    /// <summary>Executes a raw SQL SELECT and leniently projects the result rows onto an arbitrary <typeparamref name="TResult"/>.</summary>
    public async Task<IReadOnlyList<TResult>> QueryProjectionBySqlAsync<TResult>(
        string sql,
        object? parameters = null,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(sql);

        await using var connection = _connectionFactory.CreateConnection();
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        await using var command = new SqlCommand(sql, connection);
        BindParameters(command, parameters);

        await using var reader = await command.ExecuteReaderAsync(cancellationToken).ConfigureAwait(false);
        // Projection mapping (single-value mode and DTO mode) uses the shared helper's single implementation
        return await RawSqlMapper.ReadProjectionRowsAsync<TResult>(reader, cancellationToken).ConfigureAwait(false);
    }

    /// <summary>Executes raw SQL (UPDATE/DELETE/any DML) and returns the number of affected rows.</summary>
    public async Task<int> ExecuteSqlAsync(
        string sql,
        object? parameters = null,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(sql);

        await using var connection = _connectionFactory.CreateConnection();
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        await using var command = new SqlCommand(sql, connection);
        BindParameters(command, parameters);

        return await command.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);
    }

    /// <summary>Executes raw SQL and returns a single scalar value (<c>default</c> when there is no match or DBNull).</summary>
    public async Task<TResult?> ExecuteScalarSqlAsync<TResult>(
        string sql,
        object? parameters = null,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(sql);

        await using var connection = _connectionFactory.CreateConnection();
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        await using var command = new SqlCommand(sql, connection);
        BindParameters(command, parameters);

        var scalar = await command.ExecuteScalarAsync(cancellationToken).ConfigureAwait(false);
        return RawSqlMapper.ConvertSingleValue<TResult>(scalar is DBNull ? null : scalar);
    }

    /// <summary>
    /// Enumerates the public instance properties of an anonymous object (or similar) and binds property name <c>Foo</c> as
    /// SQL parameter <c>@Foo</c> via <c>AddWithValue</c> (raw SQL has no column context, so no explicit type). Does nothing
    /// when null. Bindable property resolution shares the single implementation in the shared helper
    /// <see cref="RawSqlMapper.GetBindableProperties"/>.
    /// </summary>
    internal static void BindParameters(SqlCommand command, object? parameters)
    {
        if (parameters is null)
        {
            return;
        }

        foreach (var property in RawSqlMapper.GetBindableProperties(parameters.GetType()))
        {
            var value =
                SqlParameterValue.Unwrap(property.GetValue(parameters));

            // Collection values (for IN) are expanded via the shared helper into @name0, @name1, ... (the @name in the SQL is rewritten too)
            if (RawSqlMapper.IsCollectionParameter(value))
            {
                RawSqlMapper.BindCollectionParameter(
                    command,
                    property.Name,
                    (System.Collections.IEnumerable)value!
                );
                continue;
            }

            command.Parameters.AddWithValue($"@{property.Name}", value ?? DBNull.Value);
        }
    }
}

/// <summary>Repository base class for SQL Server that implements CRUD using metadata.</summary>
public abstract class SqlServerRepositoryCore<TEntity, TKey>(
    ISqlConnectionFactory connectionFactory,
    ISaveHookRegistry? saveHooks = null,
    ISqlExecutor? sqlExecutor = null
) : IRepositoryCore<TEntity, TKey>
    where TEntity : EntityBaseCore, new()
{
    /// <summary>Metadata built exactly once per entity type (reused via a static field).</summary>
    private static readonly EntitySaveMetadata _metadata = EntitySaveMetadata.For(typeof(TEntity));

    /// <summary>The source of SQL connections.</summary>
    private readonly ISqlConnectionFactory _connectionFactory = connectionFactory;

    /// <summary>
    /// The delegate target of the raw SQL methods (consolidates binding and mapping into a single implementation).
    /// Unspecified = null builds the default implementation over the same connection factory, which keeps
    /// hand-constructed repositories working; the DI registrations pass the registered implementation instead.
    /// </summary>
    private readonly ISqlExecutor _sqlExecutor = sqlExecutor ?? new SqlExecutor(connectionFactory);

    /// <summary>The save hook registry (unspecified = null = no hooks, a complete no-op).</summary>
    private readonly ISaveHookRegistry? _saveHooks = saveHooks;

    /// <summary>Gets a single entity by primary key (null when not found).</summary>
    public async Task<TEntity?> GetByIdAsync(TKey id, CancellationToken cancellationToken = default)
    {
        await using var connection = _connectionFactory.CreateConnection();
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        await using var command = new SqlCommand(_metadata.SelectByIdSql, connection);
        _metadata.BindKeyParameter(command, id);

        await using var reader = await command.ExecuteReaderAsync(cancellationToken).ConfigureAwait(false);

        if (!await reader.ReadAsync(cancellationToken).ConfigureAwait(false))
        {
            return null;
        }

        return _metadata.MapEntity<TEntity>(reader);
    }

    /// <summary>Gets all entities.</summary>
    public async Task<IReadOnlyList<TEntity>> GetAllAsync(
        CancellationToken cancellationToken = default
    )
    {
        var items = new List<TEntity>();

        await using var connection = _connectionFactory.CreateConnection();
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        await using var command = new SqlCommand(_metadata.SelectAllSql, connection);
        await using var reader = await command.ExecuteReaderAsync(cancellationToken).ConfigureAwait(false);

        // Resolve column-name-to-ordinal once per result set instead of looking it up per row
        var ordinals = _metadata.SelectOrdinals(reader);

        while (await reader.ReadAsync(cancellationToken).ConfigureAwait(false))
        {
            items.Add(_metadata.MapEntity<TEntity>(reader, ordinals));
        }

        return items;
    }

    /// <summary>Inserts an entity.</summary>
    /// <remarks>When the table has a rowversion column, the version the database assigned is written back to <paramref name="entity"/>.</remarks>
    public async Task InsertAsync(TEntity entity, CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(entity);

        await using var connection = _connectionFactory.CreateConnection();
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        if (_metadata.RowVersionProperty is not null)
        {
            await using var returningCommand = new SqlCommand(
                _metadata.InsertReturningSql!,
                connection
            );
            _metadata.BindInsertParameters(returningCommand, entity);

            if (await returningCommand.ExecuteScalarAsync(cancellationToken).ConfigureAwait(false) is byte[] version)
            {
                _metadata.RowVersionProperty.SetValue(
                    entity,
                    SqlValueObjectActivator.Wrap(version, _metadata.RowVersionProperty.PropertyType)
                );
            }

            return;
        }

        await using var command = new SqlCommand(_metadata.InsertSql, connection);
        _metadata.BindInsertParameters(command, entity);
        await command.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);
    }

    /// <summary>Bulk inserts a collection of entities using SqlBulkCopy.</summary>
    /// <remarks>
    /// <para>
    /// Constraints are checked: SqlBulkCopy skips foreign key and CHECK constraints unless asked to honour them, which would
    /// let a bulk insert write rows the row-at-a-time INSERT path rejects. <c>CheckConstraints</c> is therefore always on, so
    /// a violating row fails the copy exactly as it would fail an INSERT. Triggers are still not fired
    /// (<c>FireTriggers</c> is deliberately left off - QuickER's DDL generates no triggers).
    /// </para>
    /// <para>
    /// Known limitation: SqlBulkCopy cannot return generated values, so for a table with a rowversion column the entities
    /// keep whatever version they had. Re-read them when the version is needed for a later update.
    /// </para>
    /// </remarks>
    public async Task<int> BulkInsertAsync(
        IEnumerable<TEntity> entities,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(entities);
        cancellationToken.ThrowIfCancellationRequested();

        // If a collection with a known count is empty, return without opening a connection
        if (entities is ICollection<TEntity> { Count: 0 })
        {
            return 0;
        }

        await using var connection = _connectionFactory.CreateConnection();
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        using var bulkCopy = new SqlBulkCopy(
            connection,
            SqlBulkCopyOptions.CheckConstraints,
            externalTransaction: null
        )
        {
            DestinationTableName = _metadata.TableName,
        };

        // Null elements are dropped before the reader sees them, so they are skipped rather than failing the whole copy
        using var reader = _metadata.CreateDataReader(
            entities.Where(entity => entity is not null)
        );

        // Map explicitly by column name (the DB column name) to avoid depending on column order
        for (var i = 0; i < reader.FieldCount; i++)
        {
            var columnName = reader.GetName(i);
            bulkCopy.ColumnMappings.Add(columnName, columnName);
        }

        await bulkCopy.WriteToServerAsync(reader, cancellationToken).ConfigureAwait(false);
        return bulkCopy.RowsCopied;
    }

    /// <summary>Updates an entity (true when a matching row was updated).</summary>
    /// <remarks>
    /// When the table has a rowversion column, <paramref name="mode"/> decides whether the update is guarded by the version
    /// the entity was read with. A guarded update that finds the row changed by someone else throws a
    /// <see cref="SaveConflictException"/>; a row that no longer exists still returns <c>false</c>. On success the new
    /// version is written back to <paramref name="entity"/>.
    /// </remarks>
    public async Task<bool> UpdateAsync(
        TEntity entity,
        ConcurrencyMode mode = ConcurrencyMode.Optimistic,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(entity);
        mode = ConcurrencyModes.Validated(mode);

        await using var connection = _connectionFactory.CreateConnection();
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        if (_metadata.RowVersionProperty is not null)
        {
            await using var guardedCommand = new SqlCommand(
                RowVersionConcurrency.UpdateSql(_metadata, mode),
                connection
            );
            RowVersionConcurrency.BindUpdate(_metadata, guardedCommand, entity, mode);

            if (await guardedCommand.ExecuteScalarAsync(cancellationToken).ConfigureAwait(false) is byte[] version)
            {
                _metadata.RowVersionProperty.SetValue(
                    entity,
                    SqlValueObjectActivator.Wrap(version, _metadata.RowVersionProperty.PropertyType)
                );
                return true;
            }

            // Nothing matched: a row that is simply gone keeps the pre-existing "false" contract, while a row that is
            // still there means someone else changed it after this entity was read
            if (
                await RowVersionConcurrency.RowExistsAsync(
                    _metadata,
                    entity,
                    connection,
                    transaction: null,
                    cancellationToken
                ).ConfigureAwait(false)
            )
            {
                throw RowVersionConcurrency.Conflict(_metadata, entity, "update");
            }

            return false;
        }

        await using var command = new SqlCommand(_metadata.UpdateSql, connection);
        _metadata.BindUpdateParameters(command, entity);

        var affected = await command.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);
        return affected > 0;
    }

    /// <inheritdoc />
    public async Task<bool> DeleteAsync(TKey id, CancellationToken cancellationToken = default)
    {
        await using var connection = _connectionFactory.CreateConnection();
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        await using var command = new SqlCommand(_metadata.DeleteSql, connection);
        _metadata.BindKeyParameter(command, id);

        var affected = await command.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);
        return affected > 0;
    }

    /// <summary>Starts a query where filters, ordering, and Include can be specified via a fluent chain.</summary>
    public SqlQuery<TEntity> Query() => new(new SqlServerSqlQueryExecutor<TEntity>(_connectionFactory));

    /// <summary>Gets the UNIQUE constraints the pre-check walks (the generated repository overrides this with its own table; empty here).</summary>
    protected virtual UniquenessConstraintSet<TEntity> UniquenessConstraints =>
        UniquenessConstraintSet<TEntity>.Empty;

    /// <summary>Collects the user-defined uniqueness checks (the generated repository overrides this to reach its own partial hook).</summary>
    /// <param name="checks">The list to add the checks to (null until the first one is added).</param>
    protected virtual void CollectUniquenessChecks(ref List<UniquenessCheck<TEntity>>? checks) { }

    /// <inheritdoc />
    public async Task<IReadOnlyList<UniquenessViolation>> CheckUniquenessAsync(
        TEntity entity,
        CancellationToken cancellationToken = default
    )
    {
        var constraints = UniquenessConstraints;
        var violations = await UniquenessChecker
            .CheckAsync(
                entity,
                Query,
                constraints.ExcludeSelf,
                constraints.Constraints,
                cancellationToken
            )
            .ConfigureAwait(false);

        List<UniquenessCheck<TEntity>>? customChecks = null;
        CollectUniquenessChecks(ref customChecks);
        await UniquenessChecker
            .RunCustomChecksAsync(entity, customChecks, violations, cancellationToken)
            .ConfigureAwait(false);

        return violations;
    }

    /// <summary>Saves inserts, updates, and deletes in a single transaction according to RowState (children cascade by default).</summary>
    /// <remarks>
    /// Entities whose table has a rowversion column take part in optimistic concurrency: their updates and deletes are
    /// guarded by the version they were read with unless <paramref name="mode"/> says otherwise, and the versions the
    /// database assigns are written back to the entities once the transaction commits.
    /// </remarks>
    public async Task<int> SaveAsync(
        TEntity entity,
        bool cascadeSave = true,
        bool cascadeDelete = true,
        bool insertWhenUpdateMissing = false,
        ConcurrencyMode mode = ConcurrencyMode.Optimistic,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(entity);
        mode = ConcurrencyModes.Validated(mode);

        // If the entire graph has no changes, return without even opening a connection
        if (!EntityGraphSaver.HasChanges(entity, cascadeSave))
        {
            return 0;
        }

        await using var connection = _connectionFactory.CreateConnection();
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        // Save the entire graph, cascades included, over a single connection and transaction (avoids MSDTC promotion)
        await using var transaction = (SqlTransaction)
            await connection.BeginTransactionAsync(cancellationToken).ConfigureAwait(false);

        // If hooks are registered, build a session that supplies a context participating in the in-progress (connection, transaction)
        var hooks =
            _saveHooks is null
                ? null
                : new SaveHookSession(
                    _saveHooks,
                    e => new SqlSaveHookContext(connection, transaction, e.GetType())
                );

        // Row versions the database assigns are collected during the transaction and applied only after it commits
        var versions = new RowVersionCollector();

        int rows;

        try
        {
            // HasChanges was already checked before this call, so skip the redundant internal graph traversal
            rows = await EntityGraphSaver.SaveAsync(
                entity,
                connection,
                transaction,
                cascadeSave,
                cascadeDelete,
                insertWhenUpdateMissing,
                cancellationToken,
                hooks,
                changesAlreadyVerified: true,
                mode: mode,
                versions: versions
            ).ConfigureAwait(false);
            await transaction.CommitAsync(cancellationToken).ConfigureAwait(false);
        }
        catch
        {
            await SqlTransactions.RollbackQuietlyAsync(transaction).ConfigureAwait(false);
            throw;
        }

        // What follows is settled state, not database work, and it is kept outside the try on purpose: the transaction
        // has already committed, so there is nothing left to roll back, and routing a failure here through the catch
        // would trade the real exception for a rollback error.

        // The commit made the new row versions visible, so settle them on the entities
        versions.Apply();

        // After a successful commit, settle the state (Added/Updated → Unchanged) to prevent double-processing on a re-save.
        // Skipped rows (where a hook's Before returned false) are left as they are
        EntityGraphSaver.AcceptChanges(entity, cascadeSave, hooks?.Skipped);
        return rows;
    }

    /// <summary>Saves multiple aggregate roots together in a single transaction (an atomic all-succeed-or-all-rollback operation).</summary>
    /// <remarks>
    /// Entities whose table has a rowversion column take part in optimistic concurrency: their updates and deletes are
    /// guarded by the version they were read with unless <paramref name="mode"/> says otherwise, and the versions the
    /// database assigns are written back to the entities once the transaction commits.
    /// </remarks>
    public async Task<int> SaveAsync(
        IEnumerable<TEntity> entities,
        bool cascadeSave = true,
        bool cascadeDelete = true,
        bool insertWhenUpdateMissing = false,
        ConcurrencyMode mode = ConcurrencyMode.Optimistic,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(entities);
        mode = ConcurrencyModes.Validated(mode);

        // Target only graphs with changes (filter before opening the connection and transaction)
        var targets = entities
            .Where(entity => entity is not null && EntityGraphSaver.HasChanges(entity, cascadeSave))
            .ToList();
        if (targets.Count == 0)
        {
            return 0;
        }

        await using var connection = _connectionFactory.CreateConnection();
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        // Save the graphs of all entities over a single connection and transaction (a mid-way failure rolls back everything)
        await using var transaction = (SqlTransaction)
            await connection.BeginTransactionAsync(cancellationToken).ConfigureAwait(false);

        // If hooks are registered, build a session that supplies a context participating in the in-progress (connection, transaction)
        var hooks =
            _saveHooks is null
                ? null
                : new SaveHookSession(
                    _saveHooks,
                    e => new SqlSaveHookContext(connection, transaction, e.GetType())
                );

        // Row versions the database assigns are collected during the transaction and applied only after it commits
        var versions = new RowVersionCollector();

        var rows = 0;

        try
        {
            foreach (var entity in targets)
            {
                // targets is already filtered by HasChanges, so skip the redundant internal graph traversal
                rows += await EntityGraphSaver.SaveAsync(
                    entity,
                    connection,
                    transaction,
                    cascadeSave,
                    cascadeDelete,
                    insertWhenUpdateMissing,
                    cancellationToken,
                    hooks,
                    changesAlreadyVerified: true,
                    mode: mode,
                    versions: versions
                ).ConfigureAwait(false);
            }

            await transaction.CommitAsync(cancellationToken).ConfigureAwait(false);
        }
        catch
        {
            await SqlTransactions.RollbackQuietlyAsync(transaction).ConfigureAwait(false);
            throw;
        }

        // What follows is settled state, not database work, and it is kept outside the try on purpose: the transaction
        // has already committed, so there is nothing left to roll back, and routing a failure here through the catch
        // would trade the real exception for a rollback error.

        // The commit made the new row versions visible, so settle them on the entities
        versions.Apply();

        // After a successful commit, settle the state of every graph (Added/Updated → Unchanged) to prevent double-processing on a re-save.
        // Skipped rows (where a hook's Before returned false) are left as they are
        foreach (var entity in targets)
        {
            EntityGraphSaver.AcceptChanges(entity, cascadeSave, hooks?.Skipped);
        }

        return rows;
    }

    /// <summary>Executes a raw SQL SELECT and maps the result rows to {TEntity}.</summary>
    /// <remarks>
    /// The SELECT must return all columns of {TEntity} (<c>SELECT *</c> or all columns listed). A partial SELECT (missing
    /// columns) is not allowed. Parameters bind the public property names of an anonymous object as <c>@name</c> without an
    /// explicit type (<b>always pass values as parameters; string concatenation risks injection</b>).
    /// The implementation delegates to <see cref="ISqlExecutor"/> (a single implementation of binding and mapping).
    /// </remarks>
    public Task<IReadOnlyList<TEntity>> QueryBySqlAsync(
        string sql,
        object? parameters = null,
        CancellationToken cancellationToken = default
    ) => _sqlExecutor.QueryBySqlAsync<TEntity>(sql, parameters, cancellationToken);

    /// <summary>Executes raw SQL (UPDATE/DELETE/any DML) and returns the number of affected rows.</summary>
    /// <remarks>
    /// The connection is opened and closed per call (no transaction argument). To execute multiple statements atomically,
    /// write <c>BEGIN TRAN ... COMMIT</c> in the SQL within a single call.
    /// Parameter binding is the same as <see cref="QueryBySqlAsync"/>
    /// (<b>always pass values as parameters; string concatenation risks injection</b>).
    /// The implementation delegates to <see cref="ISqlExecutor"/>.
    /// </remarks>
    public Task<int> ExecuteSqlAsync(
        string sql,
        object? parameters = null,
        CancellationToken cancellationToken = default
    ) => _sqlExecutor.ExecuteSqlAsync(sql, parameters, cancellationToken);

    /// <summary>Executes raw SQL and returns a single scalar value (<c>default</c> when there is no match or DBNull).</summary>
    /// <remarks>
    /// When the result is <c>null</c> / <see cref="DBNull"/>, returns <c>default(TResult)</c>. When the type does not match,
    /// it performs a best-effort conversion with <see cref="Convert.ChangeType(object, Type, IFormatProvider)"/>
    /// (InvariantCulture), throwing a descriptive exception when it cannot convert. Parameter binding is the same as
    /// <see cref="QueryBySqlAsync"/> (<b>always pass values as parameters; string concatenation risks injection</b>).
    /// The implementation delegates to <see cref="ISqlExecutor"/>.
    /// </remarks>
    public Task<TResult?> ExecuteScalarSqlAsync<TResult>(
        string sql,
        object? parameters = null,
        CancellationToken cancellationToken = default
    ) => _sqlExecutor.ExecuteScalarSqlAsync<TResult>(sql, parameters, cancellationToken);

    /// <summary>Executes a raw SQL SELECT and leniently projects the result rows onto an arbitrary <typeparamref name="TResult"/> (for raw SQL projections of named queries).</summary>
    /// <remarks>
    /// Parameter binding is the same as <see cref="QueryBySqlAsync"/>
    /// (<b>always pass values as parameters; string concatenation risks injection</b>).
    /// The implementation delegates to <see cref="ISqlExecutor"/>.
    /// </remarks>
    protected Task<IReadOnlyList<TResult>> QueryProjectionBySqlAsync<TResult>(
        string sql,
        object? parameters = null,
        CancellationToken cancellationToken = default
    ) => _sqlExecutor.QueryProjectionBySqlAsync<TResult>(sql, parameters, cancellationToken);
}

/// <summary>The SQL Server context passed to a save hook's After, participating in the in-progress (connection, transaction).</summary>
/// <remarks>Created bound to an entity type (<see cref="WriteBinaryColumnAsync"/> resolves that type's excluded columns). Raw SQL reuses <c>SqlExecutor.BindParameters</c>.</remarks>
internal sealed class SqlSaveHookContext(
    SqlConnection connection,
    SqlTransaction transaction,
    Type entityType
) : ISaveHookContext
{
    private readonly SqlConnection _connection = connection;
    private readonly SqlTransaction _transaction = transaction;
    private readonly EntitySaveMetadata _metadata = EntitySaveMetadata.For(entityType);

    /// <summary>Executes raw SQL (any DML) within the same transaction and returns the number of affected rows (binding shares the single implementation with SqlExecutor).</summary>
    public async Task<int> ExecuteSqlAsync(
        string sql,
        object? parameters = null,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(sql);

        await using var command = new SqlCommand(sql, _connection, _transaction);
        SqlExecutor.BindParameters(command, parameters);
        return await command.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);
    }

    /// <summary>Stream-writes an unbounded binary (excluded) column within the same transaction (unsupported for diagrams without exclusions).</summary>
    public Task<bool> WriteBinaryColumnAsync(
        string propertyName,
        object key,
        Stream? source,
        long? length = null,
        CancellationToken cancellationToken = default
    ) =>
        throw new NotSupportedException(
            "Writing an unbounded binary column requires code generated with ExcludeUnboundedBinaryColumns enabled. "
                + "Enable the option, or update the column with raw SQL (ExecuteSqlAsync)."
        );
}

/// <summary>A query WHERE clause parameter (name, value, target column name). The column name is set only when known and is used for explicit typing.</summary>
/// <param name="Name">The parameter name (for example, @p0).</param>
/// <param name="Value">The value to bind (may include a value object; unwrapping to the raw value happens on the binding side).</param>
/// <param name="ColumnName">The target column name without brackets; null when the column cannot be identified.</param>
internal readonly record struct SqlQueryParameter(string Name, object? Value, string? ColumnName);

/// <summary>
/// The SQL Server ADO executor for <see cref="SqlQuery{TEntity}"/>.
/// It translates the plan's predicates and orderings to SQL via <see cref="SqlExpressionTranslator"/>, and
/// fetches the graph as nested JSON in a single query with FOR JSON, then restores it with System.Text.Json.
/// </summary>
/// <remarks>
/// Dialect SQL (identifier quoting, SELECT syntax, paging clauses) is confined to this executor.
/// SqlQuery merely passes the dialect-neutral <see cref="SqlQueryPlan{TEntity}"/>, and dialect differences are absorbed only here.
/// </remarks>
internal sealed class SqlServerSqlQueryExecutor<TEntity>(ISqlConnectionFactory connectionFactory)
    : ISqlQueryExecutor<TEntity>
    where TEntity : EntityBaseCore
{
    /// <summary>The source that creates SQL connections.</summary>
    private readonly ISqlConnectionFactory _connectionFactory = connectionFactory;

    private static string TableName => EntitySaveMetadata.For(typeof(TEntity)).TableName;

    // Navigations may carry [JsonIgnore] (to break parent-reference cycles), but loading with Include
    // needs to restore them too, so a resolver modifier adds navigation properties back to the read set.
    private static readonly JsonSerializerOptions JsonOptions = new()
    {
        PropertyNameCaseInsensitive = true,
        TypeInfoResolver = new DefaultJsonTypeInfoResolver
        {
            Modifiers = { IncludeNavigationProperties },
        },
        Converters = { new ValueObjectJsonConverterFactory() },
    };

    /// <summary>Re-registers navigation properties dropped from the contract by [JsonIgnore] and the like as deserialization targets.</summary>
    private static void IncludeNavigationProperties(JsonTypeInfo typeInfo)
    {
        if (typeInfo.Kind != JsonTypeInfoKind.Object)
        {
            return;
        }

        foreach (
            var property in typeInfo.Type.GetProperties(BindingFlags.Public | BindingFlags.Instance)
        )
        {
            if (
                !property.CanRead
                || !property.CanWrite
                || property.GetCustomAttribute<NavigationReferenceAttribute>() is null
            )
            {
                continue;
            }

            var existing = typeInfo.Properties.FirstOrDefault(item =>
                string.Equals(item.Name, property.Name, StringComparison.OrdinalIgnoreCase)
            );
            if (existing is not null)
            {
                // When disabled by [JsonIgnore] (Get/Set are null), revive it so Include can read it in
                existing.Get ??= property.GetValue;
                existing.Set ??= property.SetValue;
            }
            else
            {
                var jsonProperty = typeInfo.CreateJsonPropertyInfo(
                    property.PropertyType,
                    property.Name
                );
                jsonProperty.Get = property.GetValue;
                jsonProperty.Set = property.SetValue;
                typeInfo.Properties.Add(jsonProperty);
            }
        }
    }

    /// <summary>Fetches the entities matching the conditions (together with the requested Includes) as a list.</summary>
    public async Task<IReadOnlyList<TEntity>> ToListAsync(
        SqlQueryPlan<TEntity> plan,
        CancellationToken cancellationToken
    )
    {
        var parameters = new List<SqlQueryParameter>();
        var whereClause = BuildWhereClause(plan, parameters);

        if (plan.WithUnboundedBinary)
        {
            // Unbounded binary columns requested: materialize with an all-column plain SELECT regardless of dialect (no-Include is already guarded at the terminal)
            return await MaterializeWithUnboundedBinaryAsync(
                plan,
                whereClause,
                parameters,
                plan.Take,
                plan.Skip,
                cancellationToken
            ).ConfigureAwait(false);
        }
        var json = await ReadJsonAsync(
            BuildJsonSelect(plan, whereClause, plan.Take, plan.Skip),
            parameters,
            cancellationToken
        ).ConfigureAwait(false);
        if (string.IsNullOrWhiteSpace(json))
        {
            return new List<TEntity>();
        }

        return JsonSerializer.Deserialize<List<TEntity>>(json, JsonOptions) ?? new List<TEntity>();
    }

    /// <summary>Fetches the entities matching the conditions with a projection (when the selector references only columns and there is no Include, only the referenced columns are plain-SELECTed).</summary>
    /// <remarks>
    /// When there is an Include, or column references cannot be safely extracted from the selector alone, falls back to
    /// fetching all columns and projecting in memory. When pruning is possible, only the referenced columns
    /// are issued as a plain SELECT (no JSON), partially materialized, then projected.
    /// </remarks>
    public async Task<IReadOnlyList<TResult>> ToProjectionListAsync<TResult>(
        SqlQueryPlan<TEntity> plan,
        Expression<Func<TEntity, TResult>> selector,
        CancellationToken cancellationToken
    )
    {
        var metadata = EntitySaveMetadata.For(typeof(TEntity));

        // Prune columns server-side only when there is no Include and the selector references columns only (all column properties)
        var projectionColumns =
            plan.Includes.Count == 0
            && ProjectionColumnCollector.TryCollect(selector, out var referenced)
                ? metadata.ResolveProjectionColumns(referenced)
                : null;

        var project = selector.Compile();

        if (projectionColumns is null)
        {
            // Fallback: materialize all columns, then project in memory
            var entities = await ToListAsync(plan, cancellationToken).ConfigureAwait(false);
            return entities.Select(project).ToList();
        }

        // Server-side column pruning: plain-SELECT only the referenced columns, partially materialize, then project
        var parameters = new List<SqlQueryParameter>();
        var whereClause = BuildWhereClause(plan, parameters);
        var sql =
            $"SELECT {metadata.BuildColumnList(projectionColumns)} FROM {TableName}{whereClause}{BuildOrderAndPaging(plan, plan.Take, plan.Skip)};";

        await using var connection = _connectionFactory.CreateConnection();
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        await using var command = CreateCommand(connection, sql, parameters);
        await using var reader = await command.ExecuteReaderAsync(cancellationToken).ConfigureAwait(false);

        // Column-name-to-ordinal mapping is resolved only once per result set
        var ordinals = metadata.ColumnOrdinals(reader, projectionColumns);

        var results = new List<TResult>();

        while (await reader.ReadAsync(cancellationToken).ConfigureAwait(false))
        {
            // Apply the projection to a partial entity with only the referenced columns populated (RowState is irrelevant; the entity is discarded after projection)
            var entity = metadata.MapEntityColumns<TEntity>(reader, projectionColumns, ordinals);
            results.Add(project(entity));
        }

        return results;
    }

    /// <summary>Fetches the first entity matching the conditions (together with the requested Includes); returns null when there is no match.</summary>
    public async Task<TEntity?> FirstOrDefaultAsync(
        SqlQueryPlan<TEntity> plan,
        CancellationToken cancellationToken
    )
    {
        var parameters = new List<SqlQueryParameter>();
        var whereClause = BuildWhereClause(plan, parameters);

        if (plan.WithUnboundedBinary)
        {
            // Unbounded binary columns requested: materialize the first row with an all-column plain SELECT (no-Include is already guarded at the terminal)
            var withBinary = await MaterializeWithUnboundedBinaryAsync(
                plan,
                whereClause,
                parameters,
                take: 1,
                plan.Skip,
                cancellationToken
            ).ConfigureAwait(false);
            return withBinary.Count > 0 ? withBinary[0] : null;
        }
        var json = await ReadJsonAsync(
            BuildJsonSelect(plan, whereClause, 1, plan.Skip),
            parameters,
            cancellationToken
        ).ConfigureAwait(false);
        if (string.IsNullOrWhiteSpace(json))
        {
            return null;
        }

        var list = JsonSerializer.Deserialize<List<TEntity>>(json, JsonOptions);
        return list is { Count: > 0 } ? list[0] : null;
    }

    /// <summary>Returns the count of rows matching the conditions (orderings, paging, and Include are not involved).</summary>
    public async Task<int> CountAsync(SqlQueryPlan<TEntity> plan, CancellationToken cancellationToken)
    {
        var parameters = new List<SqlQueryParameter>();
        var whereClause = BuildWhereClause(plan, parameters);

        await using var connection = _connectionFactory.CreateConnection();
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        await using var command = CreateCommand(
            connection,
            $"SELECT COUNT(*) FROM {TableName}{whereClause};",
            parameters
        );
        var result = await command.ExecuteScalarAsync(cancellationToken).ConfigureAwait(false);
        return Convert.ToInt32(result);
    }

    /// <summary>Returns whether any record matching the conditions exists (orderings, paging, and Include are not involved).</summary>
    public async Task<bool> AnyAsync(SqlQueryPlan<TEntity> plan, CancellationToken cancellationToken)
    {
        var parameters = new List<SqlQueryParameter>();
        var whereClause = BuildWhereClause(plan, parameters);

        await using var connection = _connectionFactory.CreateConnection();
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        await using var command = CreateCommand(
            connection,
            $"SELECT CASE WHEN EXISTS (SELECT 1 FROM {TableName}{whereClause}) THEN 1 ELSE 0 END;",
            parameters
        );
        var result = await command.ExecuteScalarAsync(cancellationToken).ConfigureAwait(false);
        return Convert.ToInt32(result) != 0;
    }

    /// <summary>Bulk-deletes the rows matching the conditions. When cascadeDelete=true, descendants are also deleted along FK chains.</summary>
    public async Task<int> ExecuteDeleteAsync(
        SqlQueryPlan<TEntity> plan,
        bool cascadeDelete,
        CancellationToken cancellationToken
    )
    {
        var parameters = new List<SqlQueryParameter>();
        var whereClause = BuildWhereClause(plan, parameters);

        await using var connection = _connectionFactory.CreateConnection();
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        if (!cascadeDelete)
        {
            await using var command = CreateCommand(
                connection,
                $"DELETE FROM {TableName}{whereClause};",
                parameters
            );
            return await command.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);
        }

        // Cascade: execute the DELETE statements ordered descendants-first, then the target, in a single transaction
        await using var transaction = (SqlTransaction)
            await connection.BeginTransactionAsync(cancellationToken).ConfigureAwait(false);

        try
        {
            var rows = 0;

            foreach (
                var sql in CascadeDeletePlanner.BuildDeleteStatements(
                    typeof(TEntity),
                    TableName,
                    whereClause
                )
            )
            {
                await using var command = new SqlCommand(sql, connection, transaction);
                AddParameters(command, parameters);
                rows += await command.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);
            }

            await transaction.CommitAsync(cancellationToken).ConfigureAwait(false);
            return rows;
        }
        catch
        {
            await SqlTransactions.RollbackQuietlyAsync(transaction).ConfigureAwait(false);
            throw;
        }
    }

    /// <summary>
    /// Materialization for WithUnboundedBinary. Plain-SELECTs all columns (including unbounded binary columns)
    /// without Include, materializing legitimate entities with RowState=Unchanged (shared across dialects).
    /// On SQL Server this avoids the default JSON path (Base64) and prevents memory inflation. No-Include only (guarded at the terminal).
    /// </summary>
    private async Task<IReadOnlyList<TEntity>> MaterializeWithUnboundedBinaryAsync(
        SqlQueryPlan<TEntity> plan,
        string whereClause,
        IReadOnlyList<SqlQueryParameter> parameters,
        int? take,
        int? skip,
        CancellationToken cancellationToken
    )
    {
        var metadata = EntitySaveMetadata.For(typeof(TEntity));
        // Plain-SELECT all columns (including the excluded ones, i.e. unbounded binary columns)
        var sql =
            $"SELECT {metadata.BuildColumnList(metadata.AllProperties)} FROM {TableName}{whereClause}{BuildOrderAndPaging(plan, take, skip)};";

        await using var connection = _connectionFactory.CreateConnection();
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        await using var command = CreateCommand(connection, sql, parameters);
        await using var reader = await command.ExecuteReaderAsync(cancellationToken).ConfigureAwait(false);

        // Column-name-to-ordinal mapping is resolved only once per result set
        var ordinals = metadata.ColumnOrdinals(reader, metadata.AllProperties);

        var results = new List<TEntity>();

        while (await reader.ReadAsync(cancellationToken).ConfigureAwait(false))
        {
            // Materialize as a legitimate entity (RowState=Unchanged) with all columns bound
            results.Add(
                metadata.MapEntityColumns<TEntity>(
                    reader,
                    metadata.AllProperties,
                    ordinals,
                    markUnchanged: true
                )
            );
        }

        return results;
    }

    /// <summary>Concatenates the FOR JSON result (returned as multiple rows of roughly 2KB each) into a single JSON string.</summary>
    private async Task<string> ReadJsonAsync(
        string sql,
        IReadOnlyList<SqlQueryParameter> parameters,
        CancellationToken cancellationToken
    )
    {
        await using var connection = _connectionFactory.CreateConnection();
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        await using var command = CreateCommand(connection, sql, parameters);
        await using var reader = await command.ExecuteReaderAsync(cancellationToken).ConfigureAwait(false);

        var chunks = new List<string>();
        while (await reader.ReadAsync(cancellationToken).ConfigureAwait(false))
        {
            chunks.Add(reader.GetString(0));
        }

        return string.Concat(chunks);
    }

    /// <summary>Builds the FOR JSON SELECT statement from the root's WHERE, ordering, paging, and the Include tree.</summary>
    private static string BuildJsonSelect(
        SqlQueryPlan<TEntity> plan,
        string whereClause,
        int? take,
        int? skip
    ) =>
        JsonQueryPlanner.BuildSelect(
            typeof(TEntity),
            whereClause,
            BuildOrderAndPaging(plan, take, skip),
            plan.Includes
        );

    /// <summary>Builds the ORDER BY / OFFSET-FETCH clauses (when take/skip is specified, a dummy ordering is supplied because ORDER BY is mandatory).</summary>
    private static string BuildOrderAndPaging(SqlQueryPlan<TEntity> plan, int? take, int? skip)
    {
        var orderings = BuildOrderings(plan);

        if (take.HasValue || skip.HasValue)
        {
            var ordering =
                orderings.Count == 0
                    ? " ORDER BY (SELECT NULL)"
                    : " ORDER BY " + string.Join(", ", orderings);
            return take.HasValue
                ? $"{ordering} OFFSET {skip ?? 0} ROWS FETCH NEXT {take.Value} ROWS ONLY"
                : $"{ordering} OFFSET {skip ?? 0} ROWS";
        }

        return orderings.Count == 0 ? string.Empty : " ORDER BY " + string.Join(", ", orderings);
    }

    /// <summary>Translates the plan's orderings (expression trees) into SQL ORDER BY elements ("[col] ASC", etc.).</summary>
    private static List<string> BuildOrderings(SqlQueryPlan<TEntity> plan)
    {
        var orderings = new List<string>(plan.Orderings.Count);
        foreach (var ordering in plan.Orderings)
        {
            orderings.Add(
                SqlExpressionTranslator.ToColumn(ordering.KeySelector)
                    + (ordering.Descending ? " DESC" : " ASC")
            );
        }

        return orderings;
    }

    /// <summary>Translates the plan's predicates (expression trees) into a WHERE clause, accumulating value parameters into parameters (empty string when there are no conditions).</summary>
    private static string BuildWhereClause(
        SqlQueryPlan<TEntity> plan,
        List<SqlQueryParameter> parameters
    )
    {
        if (plan.Predicates.Count == 0)
        {
            return string.Empty;
        }

        var conditions = new List<string>(plan.Predicates.Count);
        foreach (var predicate in plan.Predicates)
        {
            conditions.Add(SqlExpressionTranslator.ToCondition(predicate.Body, parameters));
        }

        return " WHERE " + string.Join(" AND ", conditions);
    }

    /// <summary>Creates a command with the accumulated parameters applied.</summary>
    private SqlCommand CreateCommand(
        SqlConnection connection,
        string sql,
        IReadOnlyList<SqlQueryParameter> parameters
    )
    {
        var command = new SqlCommand(sql, connection);
        AddParameters(command, parameters);
        return command;
    }

    /// <summary>Applies the translated condition parameters to the command.</summary>
    /// <remarks>
    /// Parameters whose column is known are built as explicit SqlParameters using that column's [SqlColumnType]
    /// (harmless even through functions such as LOWER-wrapped comparisons, since both sides share the same type).
    /// When the column cannot be identified, falls back to AddWithValue.
    /// </remarks>
    private static void AddParameters(
        SqlCommand command,
        IReadOnlyList<SqlQueryParameter> parameters
    )
    {
        var metadata = EntitySaveMetadata.For(typeof(TEntity));
        foreach (var parameter in parameters)
        {
            var value =
                SqlParameterValue.Unwrap(parameter.Value);
            metadata.AddQueryParameter(command, parameter.Name, parameter.ColumnName, value);
        }
    }
}

/// <summary>A planner that builds the FOR JSON SELECT statement from the Include tree and FK metadata (database-independent and pure).</summary>
internal static class JsonQueryPlanner
{
    /// <summary>Caches the root column projection for Include-less roots (pure text fixed per type, with the root alias always a0).</summary>
    private static readonly ConcurrentDictionary<Type, string> _rootProjectionCache = new();

    /// <summary>Builds a SELECT statement returning nested JSON from the root type, WHERE clause, ordering/paging clause, and Include tree.</summary>
    public static string BuildSelect(
        Type rootType,
        string whereClause,
        string orderAndPaging,
        IReadOnlyList<IncludeNode> includes
    )
    {
        var aliasCounter = new int[1];
        var rootAlias = NextAlias(aliasCounter);
        // Without Include, the root projection is pure text determined by the type ("a0.[col] AS Prop, ..."), so pull it from the cache
        // (the root alias is always a0 on the first NextAlias call; with Include, child aliases vary so it is rebuilt every time)
        var projection =
            includes.Count == 0
                ? _rootProjectionCache.GetOrAdd(
                    rootType,
                    static t => BuildProjection(t, "a0", Array.Empty<IncludeNode>(), new int[1])
                )
                : BuildProjection(rootType, rootAlias, includes, aliasCounter);
        var tableName = EntitySaveMetadata.For(rootType).TableName;
        return $"SELECT {projection} FROM {tableName} AS {rootAlias}{whereClause}{orderAndPaging} FOR JSON PATH;";
    }

    private static string BuildProjection(
        Type type,
        string alias,
        IReadOnlyList<IncludeNode> includes,
        int[] aliasCounter
    )
    {
        var metadata = EntitySaveMetadata.For(type);
        var parts = new List<string>();

        // Columns are aliased to property names ([col] AS Prop) so System.Text.Json can restore them directly
        foreach (var (propertyName, columnName) in metadata.Columns)
        {
            parts.Add($"{alias}.[{columnName}] AS {propertyName}");
        }

        // Included children are embedded as correlated subqueries (FOR JSON)
        foreach (var node in includes)
        {
            parts.Add(BuildIncludeProjection(node, alias, aliasCounter));
        }

        return string.Join(", ", parts);
    }

    private static string BuildIncludeProjection(
        IncludeNode node,
        string parentAlias,
        int[] aliasCounter
    )
    {
        var attribute =
            EntitySaveMetadata.NavigationAttribute(node.Property)
            ?? throw new InvalidOperationException(
                $"{node.Property.Name} is not a navigation marked with [NavigationReference]."
            );
        var childType = attribute.IsCollection
            ? node.Property.PropertyType.GetGenericArguments()[0]
            : node.Property.PropertyType;
        var childAlias = NextAlias(aliasCounter);
        var childTable = EntitySaveMetadata.For(childType).TableName;

        // Correlation: child direction is child.[Dependent] = parent.[Principal]; parent reference is parent.[Principal] = self.[Dependent]
        var correlation = attribute.IsParentReference
            ? $"{childAlias}.[{attribute.PrincipalColumn}] = {parentAlias}.[{attribute.DependentColumn}]"
            : $"{childAlias}.[{attribute.DependentColumn}] = {parentAlias}.[{attribute.PrincipalColumn}]";

        var childProjection = BuildProjection(childType, childAlias, node.Children, aliasCounter);

        // Collections are emitted as arrays; single references as objects via WITHOUT_ARRAY_WRAPPER.
        // Nested FOR JSON results get string-escaped by the outer query, so wrap them in JSON_QUERY to embed them as raw JSON.
        var arrayMode = attribute.IsCollection ? string.Empty : ", WITHOUT_ARRAY_WRAPPER";
        return $"JSON_QUERY((SELECT {childProjection} FROM {childTable} AS {childAlias} WHERE {correlation} FOR JSON PATH{arrayMode})) AS {node.Property.Name}";
    }

    private static string NextAlias(int[] aliasCounter) => "a" + aliasCounter[0]++;
}

/// <summary>Translates lambda expressions (expression trees) into SQL conditions and column references.</summary>
/// <remarks>
/// Supported constructs are limited to comparisons (== != &lt; &lt;= &gt; &gt;=), logical combinations (&amp;&amp; ||), negation, null checks, bool columns, and string Contains/StartsWith/EndsWith; anything outside this set throws.
/// An <c>==</c> / <c>!=</c> comparison whose value side is null is compensated to <c>IS NULL</c> / <c>IS NOT NULL</c> (the same meaning C# and EF Core give it), whether the null is written as a literal or comes from a variable.
/// </remarks>
internal static class SqlExpressionTranslator
{
    /// <summary>Translates the body of a predicate lambda into a SQL condition, parameterizing values and appending them to parameters.</summary>
    public static string ToCondition(
        Expression expression,
        List<SqlQueryParameter> parameters
    ) => Visit(expression, parameters);

    /// <summary>Extracts the bracketed column name from a key-selecting lambda.</summary>
    public static string ToColumn(LambdaExpression keySelector)
    {
        var member = Unwrap(keySelector.Body) as MemberExpression;

        if (member is null || !IsColumn(member))
        {
            throw new NotSupportedException(
                $"Only entity properties can be specified as an ordering: {keySelector}"
            );
        }

        return ColumnName(member.Member);
    }

    private static string Visit(
        Expression expression,
        List<SqlQueryParameter> parameters
    )
    {
        switch (expression)
        {
            case BinaryExpression { NodeType: ExpressionType.AndAlso } binary:
                return $"({Visit(binary.Left, parameters)} AND {Visit(binary.Right, parameters)})";

            case BinaryExpression { NodeType: ExpressionType.OrElse } binary:
                return $"({Visit(binary.Left, parameters)} OR {Visit(binary.Right, parameters)})";

            case BinaryExpression binary:
                return VisitComparison(binary, parameters);

            case UnaryExpression { NodeType: ExpressionType.Not } unary:
            {
                var operand = Unwrap(unary.Operand);

                // A negation of a negation cancels out here rather than being passed on. The equality case below only fires
                // when the operand is the comparison itself, so an inner Not would fall through to the NOT (...) wrapper and
                // take the comparison's null compensation out of reach: !(!(col != v)) would come out as NOT ([col] = @p),
                // which drops the NULL rows that C# and EF Core keep. Cancelling is recursive, so any stack of negations
                // collapses to whatever the expression underneath translates to.
                if (operand is UnaryExpression { NodeType: ExpressionType.Not } innerNegation)
                {
                    return Visit(Unwrap(innerNegation.Operand), parameters);
                }

                if (operand is MemberExpression boolMember && IsColumn(boolMember))
                {
                    return $"{ColumnName(boolMember.Member)} = 0";
                }

                // A negated equality is translated as the opposite comparison rather than wrapped in NOT, so that it gets
                // the same null compensation the opposite operator would get on its own: NOT ([col] <> @p) leaves out every
                // row whose column is NULL, while C# and EF Core read !(col != v) as including them.
                if (
                    operand
                    is BinaryExpression
                    {
                        NodeType: ExpressionType.Equal or ExpressionType.NotEqual
                    } equality
                )
                {
                    return VisitComparison(equality, parameters, negate: true);
                }

                // A negated IN gets the same treatment: NOT ([col] IN (...)) is UNKNOWN - and therefore excluded - for
                // every row whose column is NULL, while C# and EF Core include such rows (null is not contained in a
                // list of non-null values). Folding the negation into the clause lets it emit the compensated form.
                if (
                    operand is MethodCallExpression inCall
                    && TryGetIn(inCall, out var notInColumn, out var notInCollection)
                )
                {
                    return BuildInClause(notInColumn, notInCollection, parameters, negate: true);
                }

                // Anything else keeps the NOT wrapper, and a negated composite condition - !(a == b && c) - lands here: the
                // negation is not pushed inward, so the comparisons inside are compensated but then read through NOT, and
                // NOT (UNKNOWN) is still UNKNOWN. A row a NULL made UNKNOWN inside therefore stays excluded where C# and
                // EF Core would have kept it. Writing the negation on the comparison itself (a != b || !c) goes through the
                // flips above and matches them (documented as a known limitation)
                return $"NOT ({Visit(unary.Operand, parameters)})";
            }

            case MethodCallExpression call
                when TryGetLike(call, out var likeColumn, out var likeKind):

                // When the argument is a column, this is a column-to-column LIKE (the pattern is escaped and assembled on the SQL side; rows where the argument column is NULL do not match)
                if (TryColumnName(call.Arguments[0]) is { } patternColumn)
                {
                    return $"{likeColumn} LIKE {BuildLikePatternFromColumn(patternColumn, likeKind)} ESCAPE '\\'";
                }

                // The argument may be a string or a value object (the TSelf overload). Value objects are unwrapped to the raw value (string)
                // A null pattern is unreachable when the query was built through SqlQuery.Where (the guard rejects it up front); kept as defense in depth
                var raw =
                    SqlParameterValue.Unwrap(Evaluate(call.Arguments[0])) as string
                    ?? throw new ArgumentNullException(
                        "value",
                        "The pattern argument of Contains/StartsWith/EndsWith in a query predicate must not be null."
                    );
                var pattern = likeKind switch
                {
                    LikeKind.Contains => "%" + EscapeLike(raw) + "%",
                    LikeKind.StartsWith => EscapeLike(raw) + "%",
                    _ => "%" + EscapeLike(raw),
                };
                return $"{likeColumn} LIKE {AddParameter(pattern, parameters, RawColumnName(likeColumn))} ESCAPE '\\'";

            case MethodCallExpression call
                when TryGetIn(call, out var inColumn, out var inCollection):
                return BuildInClause(inColumn, inCollection, parameters);

            case MethodCallExpression call
                when TryGetNullOrEmpty(call, out var neColumn, out var neWhitespace):
                // Empty-string check. IsNullOrWhiteSpace also treats surrounding whitespace as empty
                return neWhitespace
                    ? $"({neColumn} IS NULL OR LTRIM(RTRIM({neColumn})) = '')"
                    : $"({neColumn} IS NULL OR {neColumn} = '')";

            case MethodCallExpression call
                when TryGetEquals(call, out var eqColumn, out var eqArg, out var eqIgnoreCase):

                // When the argument is a column, this is a column-to-column equality (IgnoreCase variants fold both sides with LOWER, same rule as the value path)
                if (TryColumnName(eqArg) is { } eqArgColumn)
                {
                    return eqIgnoreCase
                        ? $"LOWER({eqColumn}) = LOWER({eqArgColumn})"
                        : $"{eqColumn} = {eqArgColumn}";
                }

                // The value is unwrapped to the raw value on the AddParameters side (value-object support)
                var eqParameter = AddParameter(Evaluate(eqArg), parameters, RawColumnName(eqColumn));
                // Case-insensitive comparisons fold both sides with LOWER
                return eqIgnoreCase
                    ? $"LOWER({eqColumn}) = LOWER({eqParameter})"
                    : $"{eqColumn} = {eqParameter}";

            case MemberExpression member when member.Type == typeof(bool) && IsColumn(member):
                return $"{ColumnName(member.Member)} = 1";

            default:
                throw new NotSupportedException($"This expression cannot be translated to SQL: {expression}");
        }
    }

    /// <summary>Translates a binary comparison, compensating for nulls on both the value side and the column side.</summary>
    /// <remarks>
    /// <para>
    /// Each side is resolved once: an operand that stays on the SQL side (a column reference or a date component) is rendered as SQL,
    /// and every other operand is evaluated to its actual value. When an <c>==</c> / <c>!=</c> comparison has a value operand that turns
    /// out to be null (a literal null, or a variable / expression that evaluates to null), it becomes <c>IS NULL</c> / <c>IS NOT NULL</c>,
    /// which is what C# and EF Core mean by it. Binding the null as an ordinary parameter would instead leave <c>col = @p</c>, and SQL's
    /// three-valued logic makes that UNKNOWN for every row.
    /// </para>
    /// <para>
    /// The other half of the same mismatch sits on the column side: <c>col &lt;&gt; @p</c> is UNKNOWN - and therefore excluded - for
    /// every row whose column is NULL, while C# and EF Core both consider NULL different from a non-null value. A <c>!=</c> against a
    /// non-null value is therefore emitted as <c>(col &lt;&gt; @p OR col IS NULL)</c>, the same shape EF Core's relational provider
    /// produces. It is applied without asking whether the column allows NULL, because that cannot be decided reliably from the
    /// expression tree; on a column that is never NULL the added disjunct simply never holds, so the result is unchanged.
    /// </para>
    /// <para>
    /// Comparing two columns is the same mismatch once more, with a NULL possible on either side, so both operators are spelled out
    /// in full: <c>!=</c> becomes <c>(a &lt;&gt; b OR (a IS NULL AND b IS NOT NULL) OR (a IS NOT NULL AND b IS NULL))</c> and <c>==</c>
    /// becomes <c>(a = b OR (a IS NULL AND b IS NULL))</c>, the shapes EF Core's relational provider produces. Both follow from C#
    /// counting one NULL side as different and two NULL sides as the same, which plain <c>=</c> / <c>&lt;&gt;</c> get wrong in
    /// opposite directions. A column compared against a value needs no such treatment on the <c>==</c> side, where SQL and C# already
    /// agree that a NULL column does not match a non-null value.
    /// </para>
    /// <para>
    /// The compensations are deliberately limited to equality: the relational operators (&lt; &lt;= &gt; &gt;=) are left alone,
    /// because they have no null-aware SQL counterpart.
    /// </para>
    /// <para>
    /// They are also limited to the operators themselves. The method form of an equality is translated elsewhere and is
    /// emitted as a plain <c>a = b</c>, so <c>!x.A.Equals(x.B)</c> drops every row whose argument column is NULL, where C#
    /// (and the in-memory backend, which runs the compiled lambda) counts that row as a match. Where a NULL is possible,
    /// write it as <c>x.A != x.B</c>, which takes the compensation.
    /// </para>
    /// <para>
    /// They also only reach a negation that sits directly on a comparison, which is why <c>!</c> flips the operator instead of
    /// wrapping the result. A <c>!</c> applied to a composite condition - <c>!(a == b &amp;&amp; c)</c> - is not pushed inward by
    /// De Morgan's laws: it comes out as <c>NOT (...)</c> around operands that are compensated individually, and NOT of an
    /// UNKNOWN is still UNKNOWN, so a row a NULL made UNKNOWN inside the parentheses stays excluded where C# and EF Core would
    /// have kept it. Where a NULL is possible, write the negation on the comparison itself (<c>a != b || !c</c>), which takes
    /// the flip and matches them.
    /// </para>
    /// </remarks>
    /// <param name="binary">The comparison to translate.</param>
    /// <param name="parameters">The parameter list the value operands are appended to.</param>
    /// <param name="negate">
    /// Whether the comparison is being translated under a <c>!</c>, in which case equality and inequality swap places here instead of
    /// the result being wrapped in NOT (which would bypass the null compensation above).
    /// </param>
    private static string VisitComparison(
        BinaryExpression binary,
        List<SqlQueryParameter> parameters,
        bool negate = false
    )
    {
        // A negation is folded in by flipping the operator (only == / != reach here negated, so nothing else can be flipped)
        var nodeType = negate
            ? binary.NodeType == ExpressionType.Equal
                ? ExpressionType.NotEqual
                : ExpressionType.Equal
            : binary.NodeType;

        var left = Unwrap(binary.Left);
        var right = Unwrap(binary.Right);

        // Resolve both sides once: SQL-side operands keep their SQL text, value-side operands are evaluated here (and reused below)
        var leftSql = OperandSql(left);
        var rightSql = OperandSql(right);
        var leftValue = leftSql is null ? Evaluate(left) : null;
        var rightValue = rightSql is null ? Evaluate(right) : null;

        if (nodeType is ExpressionType.Equal or ExpressionType.NotEqual)
        {
            var suffix = nodeType == ExpressionType.NotEqual ? "NOT " : string.Empty;

            if (leftSql is not null && rightSql is null && IsNullValue(rightValue))
            {
                return $"{leftSql} IS {suffix}NULL";
            }

            if (rightSql is not null && leftSql is null && IsNullValue(leftValue))
            {
                return $"{rightSql} IS {suffix}NULL";
            }
        }

        // "not equal to a non-null value" also has to admit the rows whose column is NULL (see the remarks); the null
        // value cases have already returned above, so what reaches here is exactly the non-null comparison
        if (nodeType == ExpressionType.NotEqual)
        {
            if (leftSql is not null && rightSql is null)
            {
                return $"({leftSql} <> {AddParameter(rightValue, parameters, RawColumnName(leftSql))} OR {leftSql} IS NULL)";
            }

            if (rightSql is not null && leftSql is null)
            {
                return $"({rightSql} <> {AddParameter(leftValue, parameters, RawColumnName(rightSql))} OR {rightSql} IS NULL)";
            }

            // Both sides stay on the SQL side: a NULL on either side has to be spelled out, since <> alone drops those rows
            if (leftSql is not null && rightSql is not null)
            {
                return $"({leftSql} <> {rightSql} OR ({leftSql} IS NULL AND {rightSql} IS NOT NULL) OR ({leftSql} IS NOT NULL AND {rightSql} IS NULL))";
            }
        }

        // The mirror image on the equality side: plain = makes two NULL columns UNKNOWN and drops the row, while C# and
        // EF Core both count two nulls as equal (see the remarks). Only column-to-column needs it - a NULL column against a
        // non-null value is a non-match to C# just as it is to SQL
        if (nodeType == ExpressionType.Equal && leftSql is not null && rightSql is not null)
        {
            return $"({leftSql} = {rightSql} OR ({leftSql} IS NULL AND {rightSql} IS NULL))";
        }

        var op = nodeType switch
        {
            ExpressionType.Equal => "=",
            ExpressionType.NotEqual => "<>",
            ExpressionType.GreaterThan => ">",
            ExpressionType.GreaterThanOrEqual => ">=",
            ExpressionType.LessThan => "<",
            ExpressionType.LessThanOrEqual => "<=",
            _ => throw new NotSupportedException($"Unsupported operator: {binary.NodeType}"),
        };

        // In a column-versus-value comparison, the value parameter carries the opposing column name for explicit typing (omitted when both sides are columns or both are values)
        return $"{leftSql ?? AddParameter(leftValue, parameters, RawColumnName(rightSql))} {op} {rightSql ?? AddParameter(rightValue, parameters, RawColumnName(leftSql))}";
    }

    /// <summary>Renders an operand that stays on the SQL side (a column reference, or a date component of a date-time column). Returns null for a value operand.</summary>
    private static string? OperandSql(Expression expression) =>
        TryColumnName(expression) is { } column ? column
        : TryGetDatePart(expression, out var datePart) ? datePart
        : null;

    /// <summary>Whether an evaluated value operand is null (a value object is unwrapped first, so one wrapping a null underlying value counts as null too).</summary>
    private static bool IsNullValue(object? value) => SqlParameterValue.Unwrap(value) is null;

    private enum LikeKind
    {
        Contains,
        StartsWith,
        EndsWith,
    }

    private static bool TryGetLike(MethodCallExpression call, out string column, out LikeKind kind)
    {
        column = string.Empty;
        kind = LikeKind.Contains;

        if (
            call.Object is null
            || call.Arguments.Count != 1
            || (
                call.Method.DeclaringType != typeof(string)
                && !IsValueObjectStringMethod(call.Method)
            )
        )
        {
            return false;
        }

        if (Unwrap(call.Object) is not MemberExpression member || !IsColumn(member))
        {
            return false;
        }

        switch (call.Method.Name)
        {
            case "Contains":
                kind = LikeKind.Contains;
                break;
            case "StartsWith":
                kind = LikeKind.StartsWith;
                break;
            case "EndsWith":
                kind = LikeKind.EndsWith;
                break;
            default:
                return false;
        }

        column = ColumnName(member.Member);
        return true;
    }

    /// <summary>Determines whether a collection Contains (arrays = static Enumerable.Contains; List/HashSet = instance Contains) is a target for IN translation.</summary>
    /// <remarks>Only calls where the column is on the argument side are targeted (string.Contains with the column as the receiver is already handled by the LIKE path).</remarks>
    private static bool TryGetIn(
        MethodCallExpression call,
        out string column,
        out Expression collection
    )
    {
        column = string.Empty;
        collection = null!;

        if (call.Method.Name != "Contains")
        {
            return false;
        }

        // Arrays etc.: static Enumerable.Contains / MemoryExtensions.Contains(collection, item) (two arguments, no receiver).
        // With C# 14 first-class spans, array.Contains(x) resolves to MemoryExtensions.Contains(span, item, comparer),
        // so the three-argument form is also accepted when the comparer is null (= default equality, same IN semantics).
        // A non-null comparer cannot be translated to SQL and falls through to the unsupported-expression error.
        if (call.Object is null && call.Arguments.Count is 2 or 3)
        {
            if (
                call.Arguments.Count == 3
                && Unwrap(call.Arguments[2]) is not ConstantExpression { Value: null }
            )
            {
                return false;
            }

            if (Unwrap(call.Arguments[1]) is MemberExpression staticItem && IsColumn(staticItem))
            {
                column = ColumnName(staticItem.Member);
                collection = UnwrapCollection(call.Arguments[0]);
                return true;
            }

            return false;
        }

        // List<T> / HashSet<T> etc.: instance Contains(item) (one argument, the receiver is the collection)
        // Arrays resolve to .NET's span-based Contains, where the receiver becomes op_Implicit(array) (UnwrapCollection restores the raw array)
        if (call.Object is not null && call.Arguments.Count == 1)
        {
            if (Unwrap(call.Arguments[0]) is MemberExpression instanceItem && IsColumn(instanceItem))
            {
                column = ColumnName(instanceItem.Member);
                collection = UnwrapCollection(call.Object);
                return true;
            }
        }

        return false;
    }

    /// <summary>Strips implicit conversions attached to a collection expression (op_Implicit / Convert such as array-to-ReadOnlySpan), restoring the raw enumerable collection expression.</summary>
    private static Expression UnwrapCollection(Expression expression)
    {
        while (true)
        {
            expression = Unwrap(expression);
            if (
                expression
                is MethodCallExpression
                {
                    Method.Name: "op_Implicit",
                    Object: null,
                    Arguments.Count: 1
                } conversion
            )
            {
                expression = conversion.Arguments[0];
                continue;
            }

            return expression;
        }
    }

    /// <summary>Builds an IN clause - or, when <paramref name="negate"/> is set, a NOT IN clause - from the elements of a collection, with the null semantics C# and EF Core give to Contains.</summary>
    /// <remarks>
    /// <para>Null elements are not parameterized. IN never matches a value against NULL in SQL, so they are folded into an IS NULL test on the column instead:
    /// a row whose column is NULL is a match for a list that contains null, and only for such a list.</para>
    /// <para>NOT IN compensates the column side unconditionally, for the same reason <c>!=</c> does: <c>[col] NOT IN (...)</c> is UNKNOWN - and the row therefore
    /// excluded - whenever the column is NULL, while C# and EF Core keep that row (null is not contained in a list of non-null values). Whether the column is
    /// nullable cannot be decided from the expression tree, and on a NOT NULL column the added clause simply never holds, so the meaning is unchanged.</para>
    /// <para>An empty collection - or one that holds nothing but nulls, once the nulls are folded out - has no values left to compare against, so the clause
    /// reduces to the null test alone, or to a constant condition when there was no null either: IN () is invalid SQL, so an empty IN means "no match"
    /// (always false) and an empty NOT IN means "every row" (always true).</para>
    /// </remarks>
    private static string BuildInClause(
        string column,
        Expression collection,
        List<SqlQueryParameter> parameters,
        bool negate = false
    )
    {
        // Strings are IEnumerable themselves but are not treated as enumerable collections here
        if (Evaluate(collection) is not IEnumerable enumerable || enumerable is string)
        {
            throw new NotSupportedException(
                $"IN searches require an enumerable collection (array, List, etc.): {collection}"
            );
        }

        var placeholders = new List<string>();
        var rawColumn = RawColumnName(column);
        var hasNull = false;
        foreach (var item in enumerable)
        {
            // Null elements carry no parameter of their own; they are represented by the IS NULL branch below
            if (IsNullValue(item))
            {
                hasNull = true;
                continue;
            }

            placeholders.Add(AddParameter(item, parameters, rawColumn));
        }

        if (placeholders.Count == 0)
        {
            return (hasNull, negate) switch
            {
                (true, false) => $"{column} IS NULL",
                (true, true) => $"{column} IS NOT NULL",
                (false, false) => "1 = 0",
                (false, true) => "1 = 1",
            };
        }

        var values = string.Join(", ", placeholders);

        return (hasNull, negate) switch
        {
            (true, false) => $"({column} IN ({values}) OR {column} IS NULL)",
            (true, true) => $"({column} NOT IN ({values}) AND {column} IS NOT NULL)",
            (false, false) => $"{column} IN ({values})",
            (false, true) => $"({column} NOT IN ({values}) OR {column} IS NULL)",
        };
    }

    /// <summary>Determines whether x.Col.Equals(value) is a target for equality translation. When the second argument is a *IgnoreCase StringComparison, case is ignored.</summary>
    /// <remarks>The column may be a plain column or a value object. Any column type (string, numeric, etc.) can be translated to equality.</remarks>
    private static bool TryGetEquals(
        MethodCallExpression call,
        out string column,
        out Expression argument,
        out bool ignoreCase
    )
    {
        column = string.Empty;
        argument = null!;
        ignoreCase = false;

        if (
            call.Object is null
            || call.Method.Name != "Equals"
            || TryColumnName(call.Object) is not { } resolvedColumn
        )
        {
            return false;
        }

        // Only the two forms Equals(value) / Equals(value, StringComparison) are supported
        if (call.Arguments.Count == 1)
        {
            column = resolvedColumn;
            argument = call.Arguments[0];
            return true;
        }

        if (call.Arguments.Count == 2 && call.Method.DeclaringType == typeof(string))
        {
            ignoreCase = Evaluate(call.Arguments[1]) is StringComparison.OrdinalIgnoreCase
                or StringComparison.InvariantCultureIgnoreCase
                or StringComparison.CurrentCultureIgnoreCase;
            column = resolvedColumn;
            argument = call.Arguments[0];
            return true;
        }

        return false;
    }

    /// <summary>Detects string.IsNullOrEmpty(x.Col) / IsNullOrWhiteSpace(x.Col) (the column may be a plain column or a value object's .Value).</summary>
    private static bool TryGetNullOrEmpty(
        MethodCallExpression call,
        out string column,
        out bool whitespace
    )
    {
        column = string.Empty;
        whitespace = call.Method.Name == "IsNullOrWhiteSpace";

        if (
            call.Object is not null
            || call.Method.DeclaringType != typeof(string)
            || call.Arguments.Count != 1
            || !(call.Method.Name == "IsNullOrEmpty" || whitespace)
            || TryColumnName(call.Arguments[0]) is not { } resolvedColumn
        )
        {
            return false;
        }

        column = resolvedColumn;
        return true;
    }

    /// <summary>Whether the method is one of the substring matches a string value object declares.</summary>
    /// <remarks>
    /// The judgement goes through the interface map of <see cref="IStringMatchValueObject{TSelf}"/>, so only the type that
    /// actually implements those members qualifies. Testing the name against a type that merely implements the interface
    /// would also claim a <c>Contains</c> a concrete value object declares for itself, which is an ordinary method call
    /// rather than a column-side match.
    /// </remarks>
    private static bool IsValueObjectStringMethod(MethodInfo method) =>
        StringMatchMethodCache.GetOrAdd(
            method,
            static m =>
            {
                if (m.DeclaringType is not { IsInterface: false } declaring)
                {
                    return false;
                }

                var contract = Array.Find(
                    declaring.GetInterfaces(),
                    i =>
                        i.IsGenericType
                        && i.GetGenericTypeDefinition() == typeof(IStringMatchValueObject<>)
                );

                return contract is not null
                    && Array.IndexOf(declaring.GetInterfaceMap(contract).TargetMethods, m) >= 0;
            }
        );

    /// <summary>Cache of the judgement per method: the interface probe allocates, and expression translation asks for the same methods repeatedly.</summary>
    private static readonly ConcurrentDictionary<MethodInfo, bool> StringMatchMethodCache = new();

    /// <summary>Removes Convert nodes such as boxing to object.</summary>
    private static Expression Unwrap(Expression expression)
    {
        while (
            expression
                is UnaryExpression
                {
                    NodeType: ExpressionType.Convert or ExpressionType.ConvertChecked
                } unary
        )
        {
            expression = unary.Operand;
        }

        return expression;
    }

    /// <summary>Whether the member is a property reference on the lambda parameter (i.e. a column). A navigation property, and a property without a [Column] mapping, are not columns and are rejected outright.</summary>
    /// <remarks>
    /// A navigation carries no column of its own, so treating one as a column would emit its property name as a column
    /// name and produce SQL the database rejects (<c>x.Parent == null</c> became <c>[Parent] IS NULL</c>). The in-memory
    /// store and EF Core both translate such a predicate happily, which made this the one place where the three backends
    /// disagreed. Failing here states the limitation instead, and the fix is always the same: filter on the foreign-key column.
    /// On a type that uses <c>[Column]</c> mapping (a generated entity), a property without the mapping — one added
    /// through an extension partial, or base-class state such as RowState — is refused for the same reason: it has no
    /// column behind it, so the only translations available are wrong ones. A type with no <c>[Column]</c> at all
    /// (a hand-written query type) keeps the name-as-column-name convention the raw-SQL mapping uses.
    /// </remarks>
    private static bool IsColumn(MemberExpression member)
    {
        if (
            member is not
            {
                Expression: ParameterExpression parameter,
                Member: PropertyInfo property
            }
        )
        {
            return false;
        }

        if (IsNavigation(property))
        {
            throw new NotSupportedException(
                $"'{property.DeclaringType?.Name}.{property.Name}' is a navigation property and cannot be translated to SQL; "
                    + "filter on the foreign-key column instead."
            );
        }

        if (!IsMappedColumn(property) && TypeUsesColumnMapping(parameter.Type))
        {
            throw new NotSupportedException(
                $"'{property.DeclaringType?.Name}.{property.Name}' has no [Column] mapping and cannot be translated to SQL; "
                    + "map it with [Column(\"...\")] or evaluate it outside the query."
            );
        }

        return true;
    }

    /// <summary>Caches the [NavigationReference] lookup per property (the column check runs for every column reference in every predicate).</summary>
    private static readonly ConcurrentDictionary<PropertyInfo, bool> _navigationCache = new();

    /// <summary>Whether the property is a navigation (annotated with <see cref="NavigationReferenceAttribute"/>) rather than a column.</summary>
    private static bool IsNavigation(PropertyInfo property) =>
        _navigationCache.GetOrAdd(
            property,
            static p => p.GetCustomAttribute<NavigationReferenceAttribute>() is not null
        );

    /// <summary>Caches the [Column] lookup per property (the same allow-list the save metadata uses: a property is a column exactly when it carries the mapping).</summary>
    private static readonly ConcurrentDictionary<PropertyInfo, bool> _mappedColumnCache = new();

    /// <summary>Whether the property carries the <c>[Column]</c> mapping that makes it a translatable column.</summary>
    private static bool IsMappedColumn(PropertyInfo property) =>
        _mappedColumnCache.GetOrAdd(
            property,
            static p => p.GetCustomAttribute<ColumnAttribute>() is not null
        );

    /// <summary>Caches, per queried type, whether it participates in [Column] mapping at all. A type with no mapped property keeps the name-as-column-name convention for hand-written query types.</summary>
    private static readonly ConcurrentDictionary<Type, bool> _columnMappedTypeCache = new();

    /// <summary>Whether the queried type declares at least one <c>[Column]</c>-mapped property (making unmapped properties non-columns on it).</summary>
    private static bool TypeUsesColumnMapping(Type type) =>
        _columnMappedTypeCache.GetOrAdd(
            type,
            static t =>
                Array.Exists(
                    t.GetProperties(BindingFlags.Public | BindingFlags.Instance),
                    property => property.GetCustomAttribute<ColumnAttribute>() is not null
                )
        );

    /// <summary>Caches member-to-bracketed-column-name resolution per type member (avoiding [Column] reflection for every column reference).</summary>
    private static readonly ConcurrentDictionary<MemberInfo, string> _columnNameCache = new();

    private static string ColumnName(MemberInfo member) =>
        _columnNameCache.GetOrAdd(
            member,
            static m => EntitySaveMetadata.QuoteIdentifier(m.GetCustomAttribute<ColumnAttribute>()?.Name ?? m.Name)
        );

    /// <summary>Extracts the bracketed column name from a column reference (a plain column x.Col, or a value object's x.Col.Value). Returns null when it is not a column.</summary>
    private static string? TryColumnName(Expression expression)
    {
        if (Unwrap(expression) is not MemberExpression member)
        {
            return null;
        }

        if (IsColumn(member))
        {
            return ColumnName(member.Member);
        }

        // Strip the value object's .Value and resolve to the inner column ([col]) (x.Col.Value -> [col])
        if (
            member.Member.Name == "Value"
            && typeof(IValueObjectCore).IsAssignableFrom(member.Member.DeclaringType)
            && member.Expression is { } inner
            && Unwrap(inner) is MemberExpression valueObjectColumn
            && IsColumn(valueObjectColumn)
        )
        {
            return ColumnName(valueObjectColumn.Member);
        }

        return null;
    }

    /// <summary>Translates date-component references on DateTime columns (x.Col.Year / x.Col.Value.Month, etc.) into SQL date functions.</summary>
    /// <remarks>
    /// The member name alone does not make something a date component, so the type the member is read from has to be a date/time
    /// type as well. Without that check a property named <c>Year</c> added to any other column's type - a partial member on a value
    /// object, say - would silently become <c>YEAR([col])</c>, computing a date component of a column that holds no date.
    /// </remarks>
    private static bool TryGetDatePart(Expression expression, out string sql)
    {
        sql = string.Empty;

        if (
            Unwrap(expression) is not MemberExpression member
            || member.Expression is not { } source
            || TryColumnName(source) is not { } column
            || !IsDateTimeType(Unwrap(source).Type)
        )
        {
            return false;
        }

        sql = member.Member.Name switch
        {
            "Year" => $"YEAR({column})",
            "Month" => $"MONTH({column})",
            "Day" => $"DAY({column})",
            "Hour" => $"DATEPART(HOUR, {column})",
            "Minute" => $"DATEPART(MINUTE, {column})",
            "Second" => $"DATEPART(SECOND, {column})",
            "DayOfYear" => $"DATEPART(DAYOFYEAR, {column})",
            "Date" => $"CAST({column} AS date)",
            _ => string.Empty,
        };

        return sql.Length != 0;
    }

    /// <summary>Whether the type is one whose members can be date components (the nullable forms included).</summary>
    private static bool IsDateTimeType(Type type)
    {
        var underlying = Nullable.GetUnderlyingType(type) ?? type;

        return underlying == typeof(DateTime)
            || underlying == typeof(DateOnly)
            || underlying == typeof(DateTimeOffset);
    }

    /// <summary>
    /// Evaluates constants, closure variables, and the like to obtain the actual value. Most cases are constants or
    /// field/property references on a closure capturing local variables, so they are read directly via reflection,
    /// avoiding (expensive) expression-tree compilation. Only other expressions such as method calls are evaluated
    /// with <see cref="Expression.Lambda(Expression, ParameterExpression[])"/>.
    /// </summary>
    private static object? Evaluate(Expression expression)
    {
        // Entity column references (the lambda parameter) cannot be evaluated as values. Reject explicitly before expression-tree compilation fails with an internal error
        if (ReferencesLambdaParameter(expression))
        {
            throw new NotSupportedException(
                $"This expression cannot be translated to SQL (entity columns cannot appear in a value position): {expression}"
            );
        }

        switch (expression)
        {
            // Constants return their value as-is
            case ConstantExpression constant:
                return constant.Value;

            // For field/property references, recursively evaluate the target instance (null for static members), then read via reflection
            case MemberExpression member:
                var instance = member.Expression is null ? null : Evaluate(member.Expression);

                return member.Member switch
                {
                    FieldInfo field => field.GetValue(instance),
                    PropertyInfo property => property.GetValue(instance),
                    _ => CompileAndInvoke(expression),
                };

            // Everything else (method calls, arithmetic, etc.) is evaluated by compiling the expression tree (compatibility-first fallback)
            default:
                return CompileAndInvoke(expression);
        }
    }

    /// <summary>Wraps an arbitrary expression tree in a lambda, compiles and invokes it to obtain the actual value (fallback for expressions that cannot be read directly via reflection).</summary>
    /// <remarks>
    /// The lambda is typed as <c>Func&lt;object&gt;</c> (boxing the result with a Convert node) so that it can be invoked
    /// directly. The untyped <c>Compile().DynamicInvoke()</c> pair goes through reflection on every call and wraps any
    /// exception the expression throws in a <see cref="System.Reflection.TargetInvocationException"/>.
    /// </remarks>
    private static object? CompileAndInvoke(Expression expression) =>
        Expression.Lambda<Func<object?>>(Expression.Convert(expression, typeof(object)))
            .Compile()();

    /// <param name="value">The actual value to parameterize (may be null).</param>
    /// <param name="parameters">The list that receives the generated parameter.</param>
    /// <param name="columnName">The target column name (without brackets). Passed only when the column can be identified, and used for explicit typing.</param>
    private static string AddParameter(
        object? value,
        List<SqlQueryParameter> parameters,
        string? columnName = null
    )
    {
        var name = "@p" + parameters.Count;
        parameters.Add(new SqlQueryParameter(name, value, columnName));
        return name;
    }

    /// <summary>Extracts the raw column name from a bracketed column name "[col]". Returns null when it is not a simple column (null, wrapped in a function, etc.).</summary>
    /// <remarks>The doubled closing quote that EntitySaveMetadata.QuoteIdentifier writes is folded back, so a name that contains the quote character resolves to the name the diagram actually holds.</remarks>
    private static string? RawColumnName(string? bracketedColumn) =>
        bracketedColumn is { Length: >= 2 } && bracketedColumn[0] == '[' && bracketedColumn[^1] == ']'
            ? bracketedColumn[1..^1].Replace("]]", "]")
            : null;

    /// <summary>Escapes the LIKE wildcards (% _ [ \).</summary>
    private static string EscapeLike(string value) =>
        value.Replace("\\", "\\\\").Replace("%", "\\%").Replace("_", "\\_").Replace("[", "\\[");

    /// <summary>Builds, on the SQL side, a LIKE pattern that treats the column value as a literal (the same 4 characters as EscapeLike, escaped via REPLACE).</summary>
    /// <remarks>Rows where the argument column is NULL yield a NULL concatenation, then LIKE NULL, and thus no match. This is the column-argument case only: a null value argument never reaches SQL because SqlQuery.Where rejects it up front.</remarks>
    private static string BuildLikePatternFromColumn(string column, LikeKind kind)
    {
        var escaped =
            $"REPLACE(REPLACE(REPLACE(REPLACE({column}, '\\', '\\\\'), '%', '\\%'), '_', '\\_'), '[', '\\[')";

        return kind switch
        {
            LikeKind.Contains => $"'%' + {escaped} + '%'",
            LikeKind.StartsWith => $"{escaped} + '%'",
            _ => $"'%' + {escaped}",
        };
    }

    /// <summary>Walks the expression tree to determine whether it contains a lambda parameter (i.e. an entity column reference).</summary>
    private static bool ReferencesLambdaParameter(Expression expression)
    {
        var finder = new LambdaParameterFinder();
        finder.Visit(expression);
        return finder.Found;
    }

    /// <summary>A lightweight visitor that merely raises a flag when it finds a lambda-parameter reference.</summary>
    private sealed class LambdaParameterFinder : ExpressionVisitor
    {
        public bool Found { get; private set; }

        protected override Expression VisitParameter(ParameterExpression node)
        {
            Found = true;
            return node;
        }
    }
}

/// <summary>Metadata built from the entity type's attributes that holds table/column information, CRUD SQL, and cascade child navigations, and provides row mapping and parameter binding.</summary>
/// <remarks>Built once per type and cached by type key (reduces reflection cost). Shared by the repository's CRUD, graph save, JSON query planner, and cascade delete planner.</remarks>
internal sealed class EntitySaveMetadata
{
    private static readonly ConcurrentDictionary<Type, EntitySaveMetadata> _cache = new();

    /// <summary>Gets the table name wrapped in quoting brackets (a schema-qualified name is quoted part by part).</summary>
    public required string TableName { get; init; }

    /// <summary>Quotes a table name, splitting a schema-qualified name on its first '.' so that each part is quoted on its own (sales.orders becomes [sales].[orders]).</summary>
    /// <remarks>Quoting the whole name in one go would name a single table that literally contains a dot, so every statement against a table outside the default schema would fail at run time. The DDL generator splits the same way.</remarks>
    internal static string QuoteTableName(string name)
    {
        var separator = name.IndexOf('.');

        return separator < 0
            ? QuoteIdentifier(name)
            : $"{QuoteIdentifier(name[..separator])}.{QuoteIdentifier(name[(separator + 1)..])}";
    }

    /// <summary>Quotes a single SQL identifier, doubling the closing quote character so that a name containing it cannot escape the quotes.</summary>
    /// <remarks>Table and column names come from the diagram, which accepts free text, so a name may well contain the quote character itself. This mirrors the escaping the DDL generator applies.</remarks>
    internal static string QuoteIdentifier(string name)
    {
        const string close = "]";

        return "[" + name.Replace(close, close + close) + close;
    }

    /// <summary>Gets the property that corresponds to the primary key.</summary>
    public required PropertyInfo KeyProperty { get; init; }

    /// <summary>Gets the column name of the primary key.</summary>
    public required string KeyColumnName { get; init; }

    /// <summary>Gets all column properties subject to mapping (excluding navigations and base-class properties). INSERT / BulkInsert always use this.</summary>
    public required IReadOnlyList<PropertyInfo> AllProperties { get; init; }

    /// <summary>Gets the column properties targeted by SELECT / UPDATE (all columns minus unbounded binary columns; identical to all columns when there are no excluded columns). Used by row mapping.</summary>
    public required IReadOnlyList<PropertyInfo> SelectProperties { get; init; }

    /// <summary>Gets the unbounded binary columns excluded from SELECT / UPDATE (marked with <see cref="UnboundedBinaryColumnAttribute"/>). Empty when there are no excluded columns.</summary>
    public required IReadOnlyList<PropertyInfo> ExcludedProperties { get; init; }

    /// <summary>Gets the rowversion (concurrency token) property, or <c>null</c> when the table has no such column.</summary>
    /// <remarks>Resolved from <see cref="StoreGeneratedColumnAttribute"/>. A table carries at most one rowversion column, so the first match is used.</remarks>
    public PropertyInfo? RowVersionProperty { get; init; }

    /// <summary>Gets the (property, column name) pairs of the SELECT columns, resolved at build time. Row mapping enumerates this instead of reflecting for column names per row.</summary>
    public required IReadOnlyList<(PropertyInfo Property, string ColumnName)> SelectColumns { get; init; }

    /// <summary>Gets the pre-resolved column property to column name map (used to resolve column names for arbitrary property sets such as projections and excluded columns).</summary>
    public required IReadOnlyDictionary<PropertyInfo, string> ColumnNameByProperty { get; init; }

    /// <summary>Gets the column properties targeted by INSERT / BulkInsert (all columns minus store-generated columns; identical to all columns when there are no store-generated columns).</summary>
    public required IReadOnlyList<PropertyInfo> InsertProperties { get; init; }

    /// <summary>Gets the column properties excluding the primary key.</summary>
    public required IReadOnlyList<PropertyInfo> NonKeyProperties { get; init; }

    /// <summary>Gets the (property name, column name) pairs of the columns. Used for aliasing in JSON projections ([col] AS Prop).</summary>
    public required IReadOnlyList<(string PropertyName, string ColumnName)> Columns { get; init; }

    /// <summary>Gets the column name to column property map (used to look up column types when explicitly typing query WHERE-clause parameters).</summary>
    public required IReadOnlyDictionary<string, PropertyInfo> PropertyByColumn { get; init; }

    /// <summary>Gets the quoted column list for SELECT (for example: [id], [name]).</summary>
    public required string ColumnList { get; init; }

    /// <summary>Gets the SELECT statement that fetches all rows.</summary>
    public required string SelectAllSql { get; init; }

    /// <summary>Gets the SELECT statement that fetches a row by primary key.</summary>
    public required string SelectByIdSql { get; init; }

    /// <summary>Gets the statement that answers whether a row with the given primary key exists (1 or 0), without fetching any column data.</summary>
    public required string ExistsByIdSql { get; init; }

    /// <summary>Gets the INSERT statement.</summary>
    public required string InsertSql { get; init; }

    /// <summary>Gets the UPDATE statement.</summary>
    public required string UpdateSql { get; init; }

    /// <summary>Gets the DELETE statement.</summary>
    public required string DeleteSql { get; init; }

    /// <summary>Gets the INSERT statement that returns the row version the database assigned (<c>null</c> when the table has no rowversion column).</summary>
    public string? InsertReturningSql { get; init; }

    /// <summary>Gets the UPDATE statement guarded by the row version the entity was read with, returning the new row version (<c>null</c> when the table has no rowversion column).</summary>
    public string? UpdateVersionedSql { get; init; }

    /// <summary>Gets the UPDATE statement without the row version guard, returning the new row version (<c>null</c> when the table has no rowversion column). Used by <see cref="ConcurrencyMode.ForceOverwrite"/>.</summary>
    public string? UpdateForcedSql { get; init; }

    /// <summary>Gets the DELETE statement guarded by the row version the entity was read with (<c>null</c> when the table has no rowversion column).</summary>
    public string? DeleteVersionedSql { get; init; }

    /// <summary>Gets the cascade-target child navigations.</summary>
    public required IReadOnlyList<CascadeNavigation> CascadeNavigations { get; init; }

    /// <summary>Gets the metadata for the specified type (built once per type and cached).</summary>
    public static EntitySaveMetadata For(Type entityType) => _cache.GetOrAdd(entityType, Build);

    /// <summary>Caches the navigation property to <see cref="NavigationReferenceAttribute"/> resolution per property.</summary>
    private static readonly ConcurrentDictionary<
        PropertyInfo,
        NavigationReferenceAttribute?
    > _navigationAttributeCache = new();

    /// <summary>Gets the <see cref="NavigationReferenceAttribute"/> of a navigation property (cached so Include resolution does not reflect per node).</summary>
    public static NavigationReferenceAttribute? NavigationAttribute(PropertyInfo property) =>
        _navigationAttributeCache.GetOrAdd(
            property,
            static p => p.GetCustomAttribute<NavigationReferenceAttribute>()
        );

    private static EntitySaveMetadata Build(Type entityType)
    {
        var tableAttribute =
            entityType.GetCustomAttribute<TableAttribute>()
            ?? throw new InvalidOperationException(
                $"{entityType.Name} requires a [Table] attribute."
            );
        var allProperties = entityType
            .GetProperties(BindingFlags.Public | BindingFlags.Instance)
            .ToList();
        // A property is a column only when it carries [Column], which the generator puts on every column property.
        // Anything else a partial declaration adds - navigations, RowState, and members added to the extension surface -
        // is therefore never part of a SQL statement. A handwritten property opts in by carrying [Column] with the name
        // of a real column
        var columns = allProperties
            .Where(property =>
                property.CanRead
                && property.CanWrite
                && property.GetCustomAttribute<ColumnAttribute>() is not null
            )
            .ToList();
        var keyProperties = columns
            .Where(property => property.GetCustomAttribute<KeyAttribute>() is not null)
            .ToList();
        var keyProperty = keyProperties.Count switch
        {
            0 => throw new InvalidOperationException(
                $"{entityType.Name} requires a property with a [Key] attribute."
            ),
            1 => keyProperties[0],
            _ => throw new InvalidOperationException(
                $"{entityType.Name} may have only one property with a [Key] attribute (composite keys are not supported by the repository; found: {string.Join(", ", keyProperties.Select(property => property.Name))})."
            ),
        };
        // Exclude unbounded binary columns (UnboundedBinaryColumnAttribute) from SELECT / UPDATE. The full column set
        // (AllProperties) is kept for INSERT / BulkInsert; only the SELECT column set (selectProperties) is reduced.
        // With no excluded columns it matches the full set
        var excludedColumns = columns
            .Where(property =>
                property.GetCustomAttribute<UnboundedBinaryColumnAttribute>() is not null
            )
            .ToList();
        var selectProperties =
            excludedColumns.Count == 0
                ? columns
                : columns.Where(property => !excludedColumns.Contains(property)).ToList();
        // Columns whose values are generated by the database (rowversion / timestamp etc., StoreGeneratedColumnAttribute)
        // are excluded from INSERT / UPDATE. The database assigns them, so an explicit write fails at runtime
        // (e.g. SQL Server timestamp columns). They are still fetched by SELECT
        var storeGeneratedColumns = columns
            .Where(property =>
                property.GetCustomAttribute<StoreGeneratedColumnAttribute>() is not null
            )
            .ToList();
        // A store-generated column doubles as the table's concurrency token; a table carries at most one of them
        var rowVersionProperty =
            storeGeneratedColumns.Count == 0 ? null : storeGeneratedColumns[0];
        // INSERT / BulkInsert targets are all columns minus store-generated columns (identical to all columns when there are none)
        var insertProperties =
            storeGeneratedColumns.Count == 0
                ? columns
                : columns.Where(property => !storeGeneratedColumns.Contains(property)).ToList();
        var nonKeyProperties = selectProperties
            .Where(property =>
                property != keyProperty && !storeGeneratedColumns.Contains(property)
            )
            .ToList();
        var tableName = EntitySaveMetadata.QuoteTableName(tableAttribute.Name);
        var keyColumnName = GetColumnName(keyProperty);
        var columnList = string.Join(", ", selectProperties.Select(property => EntitySaveMetadata.QuoteIdentifier(GetColumnName(property))));
        var updateAssignments = nonKeyProperties.Select(property =>
            $"{EntitySaveMetadata.QuoteIdentifier(GetColumnName(property))} = @{property.Name}"
        );
        var insertColumnList = string.Join(", ", insertProperties.Select(property => EntitySaveMetadata.QuoteIdentifier(GetColumnName(property))));
        var insertValueList = string.Join(", ", insertProperties.Select(property => $"@{property.Name}"));
        // Quoted rowversion column, non-null only for tables that carry one. The optimistic concurrency statements below
        // are built solely for those tables (every other table keeps exactly the statements it had before)
        var rowVersionColumn =
            rowVersionProperty is null
                ? null
                : EntitySaveMetadata.QuoteIdentifier(GetColumnName(rowVersionProperty));
        var cascades = allProperties
            .Select(property =>
                (property, attribute: property.GetCustomAttribute<NavigationReferenceAttribute>())
            )
            .Where(pair => pair.attribute is { Cascade: true })
            .Select(pair => new CascadeNavigation(
                pair.property,
                pair.attribute!.IsCollection,
                pair.attribute.IsCollection
                    ? pair.property.PropertyType.GetGenericArguments()[0]
                    : pair.property.PropertyType,
                pair.attribute.PrincipalColumn,
                pair.attribute.DependentColumn
            ))
            .ToList();

        return new EntitySaveMetadata
        {
            TableName = tableName,
            KeyProperty = keyProperty,
            KeyColumnName = keyColumnName,
            AllProperties = columns,
            SelectProperties = selectProperties,
            ExcludedProperties = excludedColumns,
            RowVersionProperty = rowVersionProperty,
            // Resolve column names for row mapping at build time to eliminate per-row [Column] reflection
            SelectColumns = selectProperties.Select(property => (property, GetColumnName(property))).ToList(),
            ColumnNameByProperty = columns.ToDictionary(property => property, GetColumnName),
            // Compile the expression-tree materializer for SelectColumns (the fixed SELECT set) once per type
            SelectMaterializer = BuildSelectMaterializer(entityType, selectProperties),
            InsertProperties = insertProperties,
            NonKeyProperties = nonKeyProperties,
            Columns = selectProperties.Select(property => (property.Name, GetColumnName(property))).ToList(),
            PropertyByColumn = columns.ToDictionary(
                GetColumnName,
                property => property,
                StringComparer.Ordinal
            ),
            ColumnList = columnList,
            SelectAllSql = $"SELECT {columnList} FROM {tableName};",
            SelectByIdSql = $"SELECT {columnList} FROM {tableName} WHERE {EntitySaveMetadata.QuoteIdentifier(keyColumnName)} = @id;",
            ExistsByIdSql =
                $"SELECT CASE WHEN EXISTS (SELECT 1 FROM {tableName} WHERE {EntitySaveMetadata.QuoteIdentifier(keyColumnName)} = @id) THEN 1 ELSE 0 END;",
            InsertSql =
                $"INSERT INTO {tableName} ({insertColumnList}) VALUES ({insertValueList});",
            UpdateSql =
                $"UPDATE {tableName} SET {string.Join(", ", updateAssignments)} WHERE {EntitySaveMetadata.QuoteIdentifier(keyColumnName)} = @id;",
            DeleteSql = $"DELETE FROM {tableName} WHERE {EntitySaveMetadata.QuoteIdentifier(keyColumnName)} = @id;",
            InsertReturningSql =
                rowVersionColumn is null
                    ? null
                    : $"INSERT INTO {tableName} ({insertColumnList}) OUTPUT INSERTED.{rowVersionColumn} VALUES ({insertValueList});",
            UpdateVersionedSql =
                rowVersionColumn is null
                    ? null
                    : $"UPDATE {tableName} SET {string.Join(", ", updateAssignments)} OUTPUT INSERTED.{rowVersionColumn} WHERE {EntitySaveMetadata.QuoteIdentifier(keyColumnName)} = @id AND {rowVersionColumn} = @originalRowVersion;",
            UpdateForcedSql =
                rowVersionColumn is null
                    ? null
                    : $"UPDATE {tableName} SET {string.Join(", ", updateAssignments)} OUTPUT INSERTED.{rowVersionColumn} WHERE {EntitySaveMetadata.QuoteIdentifier(keyColumnName)} = @id;",
            DeleteVersionedSql =
                rowVersionColumn is null
                    ? null
                    : $"DELETE FROM {tableName} WHERE {EntitySaveMetadata.QuoteIdentifier(keyColumnName)} = @id AND {rowVersionColumn} = @originalRowVersion;",
            CascadeNavigations = cascades,
        };
    }

    // ===== Row materializer (expression-tree compiled; removes reflection from the hot path) =====
    /// <summary>Type-specialized reader accessors that avoid boxing (<c>GetInt32</c> etc.). Only the fast-path CLR types are registered.</summary>
    private static readonly IReadOnlyDictionary<Type, MethodInfo> _typedReaders = BuildTypedReaders();

    /// <summary>Resolved <see cref="MethodInfo"/> of <see cref="DbDataReader.IsDBNull(int)"/>.</summary>
    private static readonly MethodInfo _isDbNullMethod = typeof(DbDataReader).GetMethod(
        nameof(DbDataReader.IsDBNull),
        new[] { typeof(int) }
    )!;

    /// <summary>Resolved <see cref="MethodInfo"/> of <see cref="DbDataReader.GetValue(int)"/> (used as the fallback for columns that cannot be type-specialized).</summary>
    private static readonly MethodInfo _getValueMethod = typeof(DbDataReader).GetMethod(
        nameof(DbDataReader.GetValue),
        new[] { typeof(int) }
    )!;

    /// <summary>Resolved <see cref="MethodInfo"/> of <see cref="SetColumnValue"/> (called as the fallback for columns that cannot be type-specialized).</summary>
    private static readonly MethodInfo _setColumnValueMethod = typeof(EntitySaveMetadata).GetMethod(
        nameof(SetColumnValue),
        BindingFlags.NonPublic | BindingFlags.Static
    )!;

    /// <summary>Resolved <see cref="PropertyInfo"/> of <see cref="EntityBaseCore.RowState"/>.</summary>
    private static readonly PropertyInfo _rowStateProperty = typeof(EntityBaseCore).GetProperty(
        nameof(EntityBaseCore.RowState)
    )!;

    /// <summary>Gets the expression-tree-compiled delegate that materializes one row of SelectColumns (the fixed SELECT set) (built once per type and cached).</summary>
    /// <remarks>The arguments are <c>(reader, ordinals)</c>. <c>ordinals</c> holds the column ordinals in SelectColumns order, resolved once before the row loop.</remarks>
    public required Func<DbDataReader, int[], EntityBaseCore> SelectMaterializer { get; init; }

    /// <summary>Builds the type-specialized reader accessor table (each value is a <see cref="DbDataReader"/> method taking an <c>int</c> and returning the corresponding CLR type).</summary>
    private static IReadOnlyDictionary<Type, MethodInfo> BuildTypedReaders()
    {
        static MethodInfo Getter(string name) =>
            typeof(DbDataReader).GetMethod(name, new[] { typeof(int) })!;

        // Type-specialized accessors for the declared column types the generated SELECT returns. On SQLite each GetXxx
        // coerces the storage type (long to int, TEXT to DateTime, etc.), equivalent to CoerceScalar; on SQL Server each
        // returns the column's CLR type directly, equivalent to the previous pass-through. Types not listed here
        // (byte[], enums, DateTimeOffset, TimeSpan, etc.) are converted via the fallback.
        return new Dictionary<Type, MethodInfo>
        {
            [typeof(bool)] = Getter(nameof(DbDataReader.GetBoolean)),
            [typeof(byte)] = Getter(nameof(DbDataReader.GetByte)),
            [typeof(short)] = Getter(nameof(DbDataReader.GetInt16)),
            [typeof(int)] = Getter(nameof(DbDataReader.GetInt32)),
            [typeof(long)] = Getter(nameof(DbDataReader.GetInt64)),
            [typeof(float)] = Getter(nameof(DbDataReader.GetFloat)),
            [typeof(double)] = Getter(nameof(DbDataReader.GetDouble)),
            [typeof(decimal)] = Getter(nameof(DbDataReader.GetDecimal)),
            [typeof(string)] = Getter(nameof(DbDataReader.GetString)),
            [typeof(DateTime)] = Getter(nameof(DbDataReader.GetDateTime)),
            [typeof(Guid)] = Getter(nameof(DbDataReader.GetGuid)),
        };
    }

    /// <summary>Caches the type-specialized pair resolved per value object property type (<c>null</c> when the type has no fast path).</summary>
    private static readonly ConcurrentDictionary<
        Type,
        (MethodInfo Getter, MethodInfo Create)?
    > _valueObjectReaderCache = new();

    /// <summary>
    /// Resolves the type-specialized pair for a value object property: the reader accessor for its underlying value and
    /// the static <c>Create</c> factory that wraps it.
    /// </summary>
    /// <remarks>
    /// Returns <c>null</c> when the property is not a value object, when its underlying type has no type-specialized
    /// accessor (<c>byte[]</c> and friends), or when no matching factory exists; those columns take the fallback.
    /// </remarks>
    private static (MethodInfo Getter, MethodInfo Create)? ResolveValueObjectReader(
        Type propertyType
    ) => _valueObjectReaderCache.GetOrAdd(propertyType, ResolveValueObjectReaderCore);

    /// <summary>Performs the uncached resolution behind <see cref="ResolveValueObjectReader"/>.</summary>
    private static (MethodInfo Getter, MethodInfo Create)? ResolveValueObjectReaderCore(
        Type propertyType
    )
    {
        var iface = Array.Find(
            propertyType.GetInterfaces(),
            i => i.IsGenericType && i.GetGenericTypeDefinition() == typeof(IValueObject<,>)
        );

        if (iface is null)
        {
            return null;
        }

        // The underlying value type is the second type argument of IValueObject<TSelf, TValue>
        if (!_typedReaders.TryGetValue(iface.GetGenericArguments()[1], out var getter))
        {
            return null;
        }

        // FlattenHierarchy: Create is declared on ValueObjectBaseCore, and without the flag reflection never returns a
        // static member declared on a base class - the resolution would quietly fail and every value object column
        // would take the SetColumnValue fallback instead of the fast path.
        var create = propertyType.GetMethod(
            "Create",
            BindingFlags.Public | BindingFlags.Static | BindingFlags.FlattenHierarchy,
            binder: null,
            new[] { getter.ReturnType },
            modifiers: null
        );

        return create is null ? null : (getter, create);
    }

    /// <summary>
    /// Builds the expression-tree-compiled delegate that materializes one row of SelectColumns (the fixed SELECT set)
    /// into an entity using a pre-resolved ordinal array (once per type).
    /// </summary>
    /// <remarks>
    /// Columns with a type-specialized accessor are read directly without boxing (<c>DBNull</c> becomes the default value,
    /// equivalent to the previous <c>SetValue(null)</c>);
    /// a value object column whose underlying value has such an accessor reads it the same way and calls the value object's
    /// static <c>Create</c> factory directly;
    /// all other columns fall back to the previous
    /// <see cref="SetColumnValue"/> (dialect-specific conversion / value object re-wrapping).
    /// The resulting final state (<c>RowState = Unchanged</c>) matches the previous row mapping.
    /// </remarks>
    private static Func<DbDataReader, int[], EntityBaseCore> BuildSelectMaterializer(
        Type entityType,
        IReadOnlyList<PropertyInfo> properties
    )
    {
        var readerParam = Expression.Parameter(typeof(DbDataReader), "reader");
        var ordinalsParam = Expression.Parameter(typeof(int[]), "ordinals");
        var entityVar = Expression.Variable(entityType, "entity");

        var body = new List<Expression>
        {
            Expression.Assign(entityVar, Expression.New(entityType)),
        };

        for (var i = 0; i < properties.Count; i++)
        {
            var ordinal = Expression.ArrayIndex(ordinalsParam, Expression.Constant(i));
            body.Add(BuildColumnAssign(entityVar, readerParam, ordinal, properties[i]));
        }

        // Rows read from the database are treated as unchanged (same post-state as the previous row mapping)
        body.Add(
            Expression.Assign(
                Expression.Property(entityVar, _rowStateProperty),
                Expression.Constant(RowState.Unchanged)
            )
        );
        body.Add(Expression.Convert(entityVar, typeof(EntityBaseCore)));

        var block = Expression.Block(typeof(EntityBaseCore), new[] { entityVar }, body);
        return Expression
            .Lambda<Func<DbDataReader, int[], EntityBaseCore>>(block, readerParam, ordinalsParam)
            .Compile();
    }

    /// <summary>Builds the assignment expression for one column. Type-specializable columns are read directly without boxing; anything else falls back to <see cref="SetColumnValue"/>.</summary>
    private static Expression BuildColumnAssign(
        Expression entityExpr,
        ParameterExpression readerParam,
        Expression ordinal,
        PropertyInfo property
    )
    {
        var propertyType = property.PropertyType;
        var underlying = Nullable.GetUnderlyingType(propertyType) ?? propertyType;

        // Columns with a type-specialized accessor are read directly without boxing
        // (DBNull becomes the default value, equivalent to the previous SetValue(null))
        if (_typedReaders.TryGetValue(underlying, out var getter))
        {
            Expression read = Expression.Call(readerParam, getter, ordinal);

            if (getter.ReturnType != propertyType)
            {
                read = Expression.Convert(read, propertyType);
            }

            var value = Expression.Condition(
                Expression.Call(readerParam, _isDbNullMethod, ordinal),
                Expression.Default(propertyType),
                read
            );
            return Expression.Assign(Expression.Property(entityExpr, property), value);
        }

        // A value object whose underlying value has a type-specialized accessor reads that value without boxing and
        // calls the static Create factory straight from the expression tree (no reflection Invoke, no Convert.ChangeType,
        // and DBNull becomes null, equivalent to the previous SetValue(null))
        if (ResolveValueObjectReader(propertyType) is (var voGetter, var voCreate))
        {
            Expression created = Expression.Call(
                voCreate,
                Expression.Call(readerParam, voGetter, ordinal)
            );

            if (created.Type != propertyType)
            {
                created = Expression.Convert(created, propertyType);
            }

            var wrapped = Expression.Condition(
                Expression.Call(readerParam, _isDbNullMethod, ordinal),
                Expression.Default(propertyType),
                created
            );
            return Expression.Assign(Expression.Property(entityExpr, property), wrapped);
        }

        // Fallback: call the previous SetColumnValue (DBNull to null / dialect-specific conversion / value object re-wrapping) via the ordinal
        return Expression.Call(
            _setColumnValueMethod,
            Expression.Convert(entityExpr, typeof(EntityBaseCore)),
            Expression.Constant(property, typeof(PropertyInfo)),
            Expression.Call(readerParam, _getValueMethod, ordinal)
        );
    }

    /// <summary>Resolves each SelectColumns column name to its ordinal on this reader once (call before the row loop).</summary>
    public int[] SelectOrdinals(DbDataReader reader)
    {
        var ordinals = new int[SelectColumns.Count];

        for (var i = 0; i < ordinals.Length; i++)
        {
            ordinals[i] = reader.GetOrdinal(SelectColumns[i].ColumnName);
        }

        return ordinals;
    }

    /// <summary>Maps one data reader row to an entity (pre-resolved ordinal variant, for hot loops).</summary>
    public TEntity MapEntity<TEntity>(
        SqlDataReader reader,
        int[] ordinals
    )
        where TEntity : EntityBaseCore => (TEntity)SelectMaterializer(reader, ordinals);

    /// <summary>Maps one data reader row to an entity (single-row variant that resolves the SelectColumns ordinals on each call).</summary>
    public TEntity MapEntity<TEntity>(SqlDataReader reader)
        where TEntity : EntityBaseCore, new() => (TEntity)SelectMaterializer(reader, SelectOrdinals(reader));

    /// <summary>
    /// The column resolution of one raw SQL result set: the ordinal of every SELECT column, plus the ordinals of the
    /// excluded (unbounded binary) columns the statement happened to include.
    /// </summary>
    /// <remarks>
    /// Built once per result set and reused for every row, so neither the name-to-ordinal lookup nor the reader's column
    /// name set is rebuilt per row. Resolve it after the first successful <c>Read</c>: some providers only expose the
    /// result schema once a row has been fetched.
    /// </remarks>
    public sealed class RawSqlRowPlan
    {
        /// <summary>Gets the ordinal of each <see cref="SelectColumns"/> column on this reader (same order as SelectColumns).</summary>
        public required int[] SelectOrdinals { get; init; }

        /// <summary>Gets the excluded columns this result set does contain, paired with their ordinal (empty in the usual case).</summary>
        public required (PropertyInfo Property, int Ordinal)[] ExcludedOrdinals { get; init; }
    }

    /// <summary>Resolves the raw SQL column plan for the current result set (call once, after the first <c>Read</c>).</summary>
    /// <exception cref="InvalidOperationException">A required SELECT column is missing from the result set.</exception>
    public RawSqlRowPlan CreateRawSqlRowPlan(SqlDataReader reader)
    {
        int[] selectOrdinals;

        // The exception thrown for an unknown column reference differs by data reader implementation
        // (IndexOutOfRangeException vs ArgumentOutOfRangeException), so both are caught
        try
        {
            selectOrdinals = SelectOrdinals(reader);
        }
        catch (Exception ex) when (ex is IndexOutOfRangeException or ArgumentOutOfRangeException)
        {
            throw new InvalidOperationException(
                $"The raw SQL SELECT must include the {KeyProperty.DeclaringType?.Name} columns ({ColumnList}); use SELECT * or list all columns. "
                    + $"The result set is missing a column: {ex.Message}",
                ex
            );
        }

        if (ExcludedProperties.Count == 0)
        {
            return new RawSqlRowPlan
            {
                SelectOrdinals = selectOrdinals,
                ExcludedOrdinals = Array.Empty<(PropertyInfo, int)>(),
            };
        }

        // Excluded (unbounded binary) columns are optional, so they are matched against the reader's own column names
        var ordinalsByName = RawReaderOrdinals(reader);
        var excluded = new List<(PropertyInfo Property, int Ordinal)>();

        foreach (var property in ExcludedProperties)
        {
            if (ordinalsByName.TryGetValue(ColumnNameByProperty[property], out var ordinal))
            {
                excluded.Add((property, ordinal));
            }
        }

        return new RawSqlRowPlan
        {
            SelectOrdinals = selectOrdinals,
            ExcludedOrdinals = excluded.ToArray(),
        };
    }

    /// <summary>
    /// Strict row mapping for raw SQL (the column set and column types are variable, so no type specialization;
    /// uses the previous lenient <see cref="SetColumnValue"/>). Reads through the plan's pre-resolved ordinals.
    /// </summary>
    private TEntity MapEntityStrict<TEntity>(
        SqlDataReader reader,
        RawSqlRowPlan plan
    )
        where TEntity : EntityBaseCore, new()
    {
        var entity = new TEntity();

        // Unbounded binary columns are excluded from SELECT by default, so only SelectColumns
        // (the pre-resolved pairs of SelectProperties) are mapped
        for (var i = 0; i < plan.SelectOrdinals.Length; i++)
        {
            SetColumnValue(entity, SelectColumns[i].Property, reader.GetValue(plan.SelectOrdinals[i]));
        }

        // Rows read from the database are treated as unchanged (later edits transition them to Updated)
        entity.RowState = RowState.Unchanged;
        return entity;
    }

    /// <summary>
    /// Sets a column value read from the reader onto the target property (the shared row-mapping step). <c>DBNull</c>
    /// assigns <c>null</c>; otherwise the value is re-wrapped for value objects, coerced from the SQLite storage type,
    /// or passed through for SQL Server, depending on the dialect.
    /// </summary>
    private static void SetColumnValue(EntityBaseCore entity, PropertyInfo property, object value)
    {
        if (value is DBNull)
        {
            property.SetValue(entity, null);
        }
        else
        {
            // Value objects are converted to the wrapped type and re-wrapped (Wrap already applies Convert.ChangeType).
            // A stored value the value object rejects surfaces as a validation failure with no hint of where it came from,
            // so the column is named here and the original exception is kept as the inner one
            try
            {
                property.SetValue(entity, SqlValueObjectActivator.Wrap(value, property.PropertyType));
            }
            catch (Exception ex) when (ex is not OperationCanceledException)
            {
                throw new InvalidOperationException(
                    $"The stored value of column '{GetColumnName(property)}' could not be mapped to {entity.GetType().Name}.{property.Name} ({property.PropertyType.Name}): {ex.Message}",
                    ex
                );
            }
        }
    }

    /// <summary>
    /// Maps a raw SQL result row to {TEntity} through a plan resolved for this result set. Same strict mapping as
    /// <see cref="MapEntityStrict"/> (the SELECT columns are required; a missing one is reported by
    /// <see cref="CreateRawSqlRowPlan"/> while the plan is built).
    /// Unbounded binary columns are not fetched by default, but if the raw SQL SELECT explicitly includes them they are mapped additionally (so a user who deliberately selected them gets the values).
    /// </summary>
    public TEntity MapEntityFromRawSql<TEntity>(
        SqlDataReader reader,
        RawSqlRowPlan plan
    )
        where TEntity : EntityBaseCore, new()
    {
        var entity = MapEntityStrict<TEntity>(reader, plan);

        // If excluded columns (unbounded binary) are present in the raw SQL result, take them opportunistically
        if (plan.ExcludedOrdinals.Length > 0)
        {
            foreach (var (property, ordinal) in plan.ExcludedOrdinals)
            {
                SetColumnValue(entity, property, reader.GetValue(ordinal));
            }

            // Re-finalize as unchanged so the opportunistic assignments do not shift state
            // (the column properties are plain auto-properties, but just in case)
            entity.RowState = RowState.Unchanged;
        }

        return entity;
    }

    /// <summary>Maps a single raw SQL result row, resolving the column plan on this call (convenience for one-row reads).</summary>
    /// <remarks>Resolve the plan yourself with <see cref="CreateRawSqlRowPlan"/> when reading many rows, so the ordinals are resolved once for the whole result set.</remarks>
    public TEntity MapEntityFromRawSql<TEntity>(SqlDataReader reader)
        where TEntity : EntityBaseCore, new() =>
        MapEntityFromRawSql<TEntity>(reader, CreateRawSqlRowPlan(reader));

    /// <summary>Enumerates the data reader's column name to ordinal map once, case-insensitively (used to detect excluded columns in raw SQL results).</summary>
    /// <remarks>A name that appears twice keeps its first ordinal, which is what <c>GetOrdinal</c> - and therefore the previous name-based lookup - resolves it to.</remarks>
    private static Dictionary<string, int> RawReaderOrdinals(SqlDataReader reader)
    {
        var ordinals = new Dictionary<string, int>(
            reader.FieldCount,
            StringComparer.OrdinalIgnoreCase
        );

        for (var i = 0; i < reader.FieldCount; i++)
        {
            ordinals.TryAdd(reader.GetName(i), i);
        }

        return ordinals;
    }

    /// <summary>
    /// Resolves the set of column property names referenced by a projection selector into the column properties
    /// (<see cref="PropertyInfo"/>) to SELECT. When every reference is a column property (including unbounded binary
    /// columns), returns the list in order; when even one non-column name (a navigation etc.) is present, or when there
    /// are zero references, returns <c>null</c> (= server-side column pruning is not possible; fall back to the previous path).
    /// </summary>
    public IReadOnlyList<PropertyInfo>? ResolveProjectionColumns(
        IReadOnlyCollection<string> propertyNames
    )
    {
        // With zero referenced columns there is nothing to SELECT, so a fallback is required (e.g. a constants-only projection)
        if (propertyNames.Count == 0)
        {
            return null;
        }

        var resolved = new List<PropertyInfo>(propertyNames.Count);

        foreach (var name in propertyNames)
        {
            // Look up by name in the full column set (AllProperties); excluded (unbounded binary) columns
            // are also fetched when the projection references them
            var property = AllProperties.FirstOrDefault(candidate => candidate.Name == name);

            if (property is null)
            {
                // A non-column (navigation etc.) is present = cannot prune safely
                return null;
            }

            resolved.Add(property);
        }

        return resolved;
    }

    /// <summary>Returns a SELECT column list joining the specified column properties as quoted column names with "," (for example: [id], [name]) (for projection pruning).</summary>
    public string BuildColumnList(IReadOnlyList<PropertyInfo> properties) =>
        string.Join(
            ", ",
            properties.Select(property => EntitySaveMetadata.QuoteIdentifier(GetColumnName(property)))
        );

    /// <summary>Per-column-property "reader+ordinal, set onto entity" binders (expression-tree compiled, cached per property).</summary>
    private static readonly ConcurrentDictionary<
        PropertyInfo,
        Action<EntityBaseCore, DbDataReader, int>
    > _columnBinderCache = new();

    /// <summary>Gets the type-specialized binder for one column (so the variable column sets of projections and full-column fetches bind without per-row reflection).</summary>
    private static Action<EntityBaseCore, DbDataReader, int> ColumnBinder(PropertyInfo property) =>
        _columnBinderCache.GetOrAdd(property, BuildColumnBinder);

    /// <summary>Compiles the single-column expression tree (<see cref="BuildColumnAssign"/>) into an <c>Action&lt;EntityBaseCore, DbDataReader, int&gt;</c>.</summary>
    private static Action<EntityBaseCore, DbDataReader, int> BuildColumnBinder(PropertyInfo property)
    {
        var entityParam = Expression.Parameter(typeof(EntityBaseCore), "entity");
        var readerParam = Expression.Parameter(typeof(DbDataReader), "reader");
        var ordinalParam = Expression.Parameter(typeof(int), "ordinal");

        // Properties are declared on the derived entity type, so downcast EntityBaseCore to the declaring type before accessing
        var assign = BuildColumnAssign(
            Expression.Convert(entityParam, property.DeclaringType!),
            readerParam,
            ordinalParam,
            property
        );

        return Expression
            .Lambda<Action<EntityBaseCore, DbDataReader, int>>(
                assign,
                entityParam,
                readerParam,
                ordinalParam
            )
            .Compile();
    }

    /// <summary>Resolves the column names of the specified column properties to their ordinals on this reader once (call before the row loop of projections and full-column fetches).</summary>
    public int[] ColumnOrdinals(DbDataReader reader, IReadOnlyList<PropertyInfo> properties)
    {
        var ordinals = new int[properties.Count];

        for (var i = 0; i < ordinals.Length; i++)
        {
            ordinals[i] = reader.GetOrdinal(ColumnNameByProperty[properties[i]]);
        }

        return ordinals;
    }

    /// <summary>
    /// Returns a {TEntity} with only the specified column properties mapped from one data reader row (shared by
    /// server-side column pruning for projections and the full-column fetch of WithUnboundedBinary).
    /// Only the columns included in the SELECT are bound; all other columns keep their default values. Projection use
    /// (<paramref name="markUnchanged"/> = false, the default) does not set RowState because the entity is discarded after
    /// the selector is applied, whereas the full-column fetch of WithUnboundedBinary (<paramref name="markUnchanged"/> = true)
    /// finalizes RowState=Unchanged because it returns a legitimate entity equivalent to a normal fetch. <paramref name="ordinals"/>
    /// holds the column ordinals in <paramref name="properties"/> order, resolved once before the row loop via <see cref="ColumnOrdinals"/>.
    /// </summary>
    public TEntity MapEntityColumns<TEntity>(
        SqlDataReader reader,
        IReadOnlyList<PropertyInfo> properties,
        int[] ordinals,
        bool markUnchanged = false
    )
        where TEntity : EntityBaseCore
    {
        // The query executor's TEntity has no new() constraint of its own, so the instance is created through Activator. The
        // parameterless constructor it needs is guaranteed by the contract types the entity has to satisfy to get here
        // (IRepositoryCore<TEntity, TKey> and IRemoteRepositoryCore<TEntity, TKey> both require "where TEntity : EntityBaseCore, new()"),
        // so a partial declaration that removed the default constructor would fail the build with CS0310 rather than reach
        // this line
        var entity = (TEntity)Activator.CreateInstance(typeof(TEntity))!;

        for (var i = 0; i < properties.Count; i++)
        {
            ColumnBinder(properties[i])(entity, reader, ordinals[i]);
        }

        if (markUnchanged)
        {
            // When returning a "legitimate entity" with all columns bound, finalize it as unchanged, like any row read from the database
            entity.RowState = RowState.Unchanged;
        }

        return entity;
    }

    /// <summary>Binds the INSERT parameters (the insert-target columns excluding store-generated columns) (shared by insert and graph insert).</summary>
    public void BindInsertParameters(SqlCommand command, EntityBaseCore entity)
    {
        foreach (var property in InsertProperties)
        {
            AddColumnParameter(
                command,
                $"@{property.Name}",
                property,
                SqlParameterValue.Unwrap(property.GetValue(entity))
            );
        }
    }

    /// <summary>Binds the UPDATE parameters (non-key columns plus the primary key) (shared by update and graph update).</summary>
    public void BindUpdateParameters(SqlCommand command, EntityBaseCore entity)
    {
        // Updates that still carry values in unbounded binary columns (excluded from UPDATE) would lose them silently,
        // so reject them up front. Both direct UpdateAsync and cascading graph updates pass through here,
        // so this single spot covers both
        UnboundedBinaryColumns.ThrowIfExcludedAssigned(entity);

        foreach (var property in NonKeyProperties)
        {
            AddColumnParameter(
                command,
                $"@{property.Name}",
                property,
                SqlParameterValue.Unwrap(property.GetValue(entity))
            );
        }

        AddColumnParameter(
            command,
            "@id",
            KeyProperty,
            SqlParameterValue.Unwrap(KeyProperty.GetValue(entity))
        );
    }

    /// <summary>Binds the entity's primary key value to the @id parameter (used by graph delete).</summary>
    public void BindEntityKeyParameter(SqlCommand command, EntityBaseCore entity)
    {
        AddColumnParameter(
            command,
            "@id",
            KeyProperty,
            SqlParameterValue.Unwrap(KeyProperty.GetValue(entity))
        );
    }

    /// <summary>Binds the row version the entity was read with to the @originalRowVersion parameter (the optimistic concurrency guard of UPDATE / DELETE).</summary>
    /// <remarks>
    /// Only called for tables that have a rowversion column. A <c>null</c> value (an entity that was never read from the
    /// database) binds as DBNull and matches no row, so the save is reported as a conflict rather than silently overwriting.
    /// </remarks>
    public void BindRowVersionParameter(SqlCommand command, EntityBaseCore entity)
    {
        var property = RowVersionProperty!;
        AddColumnParameter(
            command,
            "@originalRowVersion",
            property,
            SqlParameterValue.Unwrap(property.GetValue(entity))
        );
    }

    /// <summary>Binds an externally supplied primary key value to the @id parameter (used by GetById/Delete).</summary>
    public void BindKeyParameter(SqlCommand command, object? id)
    {
        var value =
            SqlParameterValue.Unwrap(id)
            ?? throw new InvalidOperationException("id cannot be null.");
        AddColumnParameter(command, "@id", KeyProperty, value);
    }

    /// <summary>Resolves the per-property [SqlColumnType] attribute once and caches it (null when absent).</summary>
    private static readonly ConcurrentDictionary<PropertyInfo, SqlColumnTypeAttribute?> _columnTypeCache =
        new();

    /// <summary>
    /// Builds and adds an explicitly typed <see cref="SqlParameter"/> from the column property's
    /// [SqlColumnType] attribute. When the attribute is absent (hand-written entities, unknown types), falls back to
    /// AddWithValue.
    /// </summary>
    /// <param name="command">The command to add the parameter to</param>
    /// <param name="name">The parameter name (with the @ prefix)</param>
    /// <param name="property">The property corresponding to the target column (the basis for typing)</param>
    /// <param name="rawValue">The value after value objects have already been unwrapped to their raw value; null is bound as DBNull.Value</param>
    private static void AddColumnParameter(
        SqlCommand command,
        string name,
        PropertyInfo property,
        object? rawValue
    )
    {
        var attribute = _columnTypeCache.GetOrAdd(
            property,
            static p => p.GetCustomAttribute<SqlColumnTypeAttribute>()
        );
        if (attribute is null)
        {
            command.Parameters.AddWithValue(name, rawValue ?? DBNull.Value);
            return;
        }

        var parameter = new SqlParameter(name, attribute.DbType);
        // String/binary Size safety guard: when the declared length is positive and the value length is within it,
        // use the declared length; when the value exceeds the declared length, use the value length as Size
        // (ADO.NET truncates input values client-side by Size, so a fixed Size would cause silent data corruption
        // instead of a server-side truncation error; sending the oversized value as-is preserves the server-side error).
        // (max) = -1 always stays -1.
        if (attribute.Size == -1)
        {
            parameter.Size = -1;
        }
        else if (attribute.Size > 0)
        {
            var valueLength = rawValue switch
            {
                string text => text.Length,
                byte[] bytes => bytes.Length,
                _ => 0,
            };
            parameter.Size = valueLength > attribute.Size ? valueLength : attribute.Size;
        }

        if (attribute.Precision > 0)
        {
            parameter.Precision = attribute.Precision;
            parameter.Scale = attribute.Scale;
        }

        parameter.Value = rawValue ?? DBNull.Value;
        command.Parameters.Add(parameter);
    }

    /// <summary>
    /// Binds a query WHERE-clause parameter. When the column name is known and its column property is found, the
    /// parameter is explicitly constructed with the column type; otherwise falls back to AddWithValue.
    /// </summary>
    /// <param name="command">The command to add the parameter to</param>
    /// <param name="name">The parameter name (with the @ prefix)</param>
    /// <param name="columnName">The unquoted column name; null when the column cannot be determined</param>
    /// <param name="rawValue">The value after value objects have already been unwrapped to their raw value; null is bound as DBNull.Value</param>
    public void AddQueryParameter(
        SqlCommand command,
        string name,
        string? columnName,
        object? rawValue
    )
    {
        if (columnName is not null && PropertyByColumn.TryGetValue(columnName, out var property))
        {
            AddColumnParameter(command, name, property, rawValue);
            return;
        }

        command.Parameters.AddWithValue(name, rawValue ?? DBNull.Value);
    }

    /// <summary>Creates an IDataReader for SqlBulkCopy that reads an entity collection one row at a time (store-generated columns are excluded from insertion).</summary>
    public IDataReader CreateDataReader(IEnumerable<EntityBaseCore> entities) =>
        new EntityDataReader(InsertProperties, entities);

    /// <summary>An IDataReader that reads entity columns one row at a time and feeds them to SqlBulkCopy (memory-efficient, no intermediate DataTable).</summary>
    /// <remarks>SqlBulkCopy uses only Read, GetValue, FieldCount, GetName, and GetOrdinal, so the other typed getters are left unsupported.</remarks>
    private sealed class EntityDataReader : IDataReader
    {
        private readonly IReadOnlyList<PropertyInfo> _properties;
        private readonly string[] _columnNames;
        private readonly IEnumerator<EntityBaseCore> _enumerator;

        public EntityDataReader(
            IReadOnlyList<PropertyInfo> properties,
            IEnumerable<EntityBaseCore> entities
        )
        {
            _properties = properties;
            _columnNames = properties.Select(GetColumnName).ToArray();
            _enumerator = entities.GetEnumerator();
        }

        public int FieldCount => _properties.Count;

        public bool Read() => _enumerator.MoveNext();

        public object GetValue(int i) =>
            SqlParameterValue.Unwrap(_properties[i].GetValue(_enumerator.Current)) ?? DBNull.Value;

        public string GetName(int i) => _columnNames[i];

        public int GetOrdinal(string name)
        {
            var index = Array.IndexOf(_columnNames, name);
            return index >= 0
                ? index
                : throw new IndexOutOfRangeException($"Column {name} does not exist.");
        }

        // Nullable<T> returns the underlying type (to align with SqlBulkCopy's column type resolution)
        public Type GetFieldType(int i) =>
            Nullable.GetUnderlyingType(_properties[i].PropertyType) ?? _properties[i].PropertyType;

        public bool IsDBNull(int i) => GetValue(i) is DBNull;

        public object this[int i] => GetValue(i);

        public object this[string name] => GetValue(GetOrdinal(name));

        public int GetValues(object[] values)
        {
            var count = Math.Min(values.Length, FieldCount);
            for (var i = 0; i < count; i++)
            {
                values[i] = GetValue(i);
            }

            return count;
        }

        public void Dispose() => _enumerator.Dispose();

        public int Depth => 0;

        public bool IsClosed => false;

        public int RecordsAffected => -1;

        public void Close() { }

        public bool NextResult() => false;

        public DataTable? GetSchemaTable() => null;

        // The members below are never called by SqlBulkCopy, so they are left unsupported
        public bool GetBoolean(int i) => throw new NotSupportedException();

        public byte GetByte(int i) => throw new NotSupportedException();

        public long GetBytes(
            int i,
            long fieldOffset,
            byte[]? buffer,
            int bufferOffset,
            int length
        ) => throw new NotSupportedException();

        public char GetChar(int i) => throw new NotSupportedException();

        public long GetChars(
            int i,
            long fieldOffset,
            char[]? buffer,
            int bufferOffset,
            int length
        ) => throw new NotSupportedException();

        public IDataReader GetData(int i) => throw new NotSupportedException();

        public string GetDataTypeName(int i) => throw new NotSupportedException();

        public DateTime GetDateTime(int i) => throw new NotSupportedException();

        public decimal GetDecimal(int i) => throw new NotSupportedException();

        public double GetDouble(int i) => throw new NotSupportedException();

        public float GetFloat(int i) => throw new NotSupportedException();

        public Guid GetGuid(int i) => throw new NotSupportedException();

        public short GetInt16(int i) => throw new NotSupportedException();

        public int GetInt32(int i) => throw new NotSupportedException();

        public long GetInt64(int i) => throw new NotSupportedException();

        public string GetString(int i) => throw new NotSupportedException();
    }

    private static string GetColumnName(PropertyInfo property) =>
        property.GetCustomAttribute<ColumnAttribute>()?.Name ?? property.Name;
}

/// <summary>Planner that builds the cascade-delete DELETE statements from FK metadata (database-independent, pure).</summary>
internal static class CascadeDeletePlanner
{
    /// <summary>Returns the DELETE statements that remove the rootType rows matching the condition and their descendants, in child-to-parent execution order.</summary>
    /// <param name="rootType">The entity type at which the delete starts</param>
    /// <param name="rootTable">The quoted root table name</param>
    /// <param name="whereClause">The root WHERE clause (" WHERE ..." or an empty string)</param>
    public static IReadOnlyList<string> BuildDeleteStatements(
        Type rootType,
        string rootTable,
        string whereClause
    )
    {
        var statements = new List<string>();
        AppendDescendantDeletes(
            rootType,
            rootTable,
            whereClause,
            new HashSet<Type> { rootType },
            statements
        );
        statements.Add($"DELETE FROM {rootTable}{whereClause};");
        return statements;
    }

    private static void AppendDescendantDeletes(
        Type parentType,
        string parentTable,
        string parentScopeWhere,
        HashSet<Type> visited,
        List<string> statements
    )
    {
        foreach (var navigation in EntitySaveMetadata.For(parentType).CascadeNavigations)
        {
            // Cyclic cascades (self-references etc.) cannot be expressed with fixed nesting, so they are unsupported
            if (!visited.Add(navigation.ChildType))
            {
                throw new NotSupportedException(
                    $"Cyclic cascades ({navigation.ChildType.Name}) are not supported by ExecuteDeleteAsync. Load the graph and use SaveAsync, or use ON DELETE CASCADE in the database."
                );
            }

            var childTable = EntitySaveMetadata.For(navigation.ChildType).TableName;
            var childScopeWhere =
                $" WHERE {EntitySaveMetadata.QuoteIdentifier(navigation.DependentColumn)} IN (SELECT {EntitySaveMetadata.QuoteIdentifier(navigation.PrincipalColumn)} FROM {parentTable}{parentScopeWhere})";

            // Delete grandchildren and below first, then the children (FK consistency)
            AppendDescendantDeletes(
                navigation.ChildType,
                childTable,
                childScopeWhere,
                visited,
                statements
            );
            statements.Add($"DELETE FROM {childTable}{childScopeWhere};");

            visited.Remove(navigation.ChildType);
        }
    }
}

/// <summary>A save hook session that lives only for the duration of a single Save call (carries the registry, context factory, and skip set).</summary>
/// <remarks>
/// The context factory is supplied by the backend (QuickER dialect, EF Core, InMemory) with the in-progress transaction
/// context captured inside. The skip set is tracked by reference equality (<see cref="ReferenceEqualityComparer"/>) and
/// used by the post-commit <c>AcceptChanges</c> to leave states untouched.
/// </remarks>
internal sealed class SaveHookSession(
    ISaveHookRegistry registry,
    Func<EntityBaseCore, ISaveHookContext> contextFactory
)
{
    private readonly ISaveHookRegistry _registry = registry;
    private readonly Func<EntityBaseCore, ISaveHookContext> _contextFactory = contextFactory;
    private readonly HashSet<EntityBaseCore> _skipped = new(ReferenceEqualityComparer.Instance);

    /// <summary>Gets the set of entities skipped by a Before returning <c>false</c> (reference equality). Used by AcceptChanges to leave states untouched.</summary>
    public IReadOnlySet<EntityBaseCore> Skipped => _skipped;

    /// <summary>Adds an entity to the skip set.</summary>
    public void Skip(EntityBaseCore entity) => _skipped.Add(entity);

    /// <summary>Calls Before in registration order and short-circuits at the first <c>false</c> (types with no hooks yield <c>true</c>).</summary>
    public Task<bool> InvokeBeforeAsync(
        EntityBaseCore entity,
        SaveOperation operation,
        CancellationToken cancellationToken
    )
    {
        var invoker = _registry.GetInvoker(entity.GetType());
        return invoker is null
            ? Task.FromResult(true)
            : invoker.InvokeBeforeAsync(entity, operation, cancellationToken);
    }

    /// <summary>Calls After in registration order (types with no hooks do nothing). The context is created bound to the entity type.</summary>
    public Task InvokeAfterAsync(
        EntityBaseCore entity,
        SaveOperation operation,
        CancellationToken cancellationToken
    )
    {
        var invoker = _registry.GetInvoker(entity.GetType());
        return invoker is null
            ? Task.CompletedTask
            : invoker.InvokeAfterAsync(
                entity,
                operation,
                _contextFactory(entity),
                cancellationToken
            );
    }
}

/// <summary>Collects the row versions the database assigned during a save so that they can be written back once the transaction commits.</summary>
/// <remarks>
/// A rowversion is assigned while the transaction is still open, so writing it straight back to the entity would leave it
/// carrying a version that never became visible if the transaction is rolled back afterwards. The saver records the pairs
/// here instead and <see cref="Apply"/> settles them after a successful commit.
/// </remarks>
internal sealed class RowVersionCollector
{
    private readonly List<(EntityBaseCore Entity, byte[] Version)> _versions = new();

    /// <summary>Records the raw row version bytes the database assigned to an entity (converting them to the property type is left to <see cref="Apply"/>).</summary>
    public void Record(EntityBaseCore entity, byte[] version) => _versions.Add((entity, version));

    /// <summary>Writes every recorded row version back to its entity (call only after the save transaction has committed).</summary>
    public void Apply()
    {
        foreach (var (entity, version) in _versions)
        {
            var property = EntitySaveMetadata.For(entity.GetType()).RowVersionProperty!;

            // The raw bytes are wrapped here when the property is a value object type. A value object that rejects the
            // bytes the database assigned would otherwise fail with no indication of which property was being written
            try
            {
                property.SetValue(
                    entity,
                    SqlValueObjectActivator.Wrap(version, property.PropertyType)
                );
            }
            catch (Exception ex) when (ex is not OperationCanceledException)
            {
                throw new InvalidOperationException(
                    $"The row version the database assigned could not be written back to {entity.GetType().Name}.{property.Name} ({property.PropertyType.Name}): {ex.Message}",
                    ex
                );
            }
        }
    }
}

/// <summary>Optimistic concurrency helpers shared by the direct CRUD methods and the graph saver, for tables that carry a rowversion (concurrency token) column.</summary>
internal static class RowVersionConcurrency
{
    /// <summary>Selects the UPDATE statement for the given mode (the version guard applies to <see cref="ConcurrencyMode.Optimistic"/> only).</summary>
    public static string UpdateSql(EntitySaveMetadata metadata, ConcurrencyMode mode) =>
        mode == ConcurrencyMode.Optimistic
            ? metadata.UpdateVersionedSql!
            : metadata.UpdateForcedSql!;

    /// <summary>Binds the UPDATE parameters, adding the version guard parameter for <see cref="ConcurrencyMode.Optimistic"/>.</summary>
    public static void BindUpdate(
        EntitySaveMetadata metadata,
        SqlCommand command,
        EntityBaseCore entity,
        ConcurrencyMode mode
    )
    {
        metadata.BindUpdateParameters(command, entity);

        if (mode == ConcurrencyMode.Optimistic)
        {
            metadata.BindRowVersionParameter(command, entity);
        }
    }

    /// <summary>
    /// Returns whether the row the entity's primary key points at currently exists. Used after a guarded statement affected
    /// no rows, to tell "the row is gone" (the pre-existing not-found contract) apart from "the row version is stale".
    /// </summary>
    /// <remarks>The question is existence only, so it runs the EXISTS statement rather than selecting every column of a row that is then discarded.</remarks>
    public static async Task<bool> RowExistsAsync(
        EntitySaveMetadata metadata,
        EntityBaseCore entity,
        SqlConnection connection,
        SqlTransaction? transaction,
        CancellationToken cancellationToken
    )
    {
        await using var command = new SqlCommand(metadata.ExistsByIdSql, connection);
        command.Transaction = transaction;
        metadata.BindEntityKeyParameter(command, entity);

        // The statement always yields a single row whose only column is the int 1 or 0 (the CASE never returns NULL)
        var exists = await command.ExecuteScalarAsync(cancellationToken).ConfigureAwait(false);
        return exists is int flag && flag != 0;
    }

    /// <summary>Builds the conflict reported when the row still exists but its version moved on since the entity was read.</summary>
    /// <param name="metadata">The metadata of the entity's type.</param>
    /// <param name="entity">The entity whose save was rejected.</param>
    /// <param name="operation">The lowercase verb of the rejected operation ("update" or "delete").</param>
    public static SaveConflictException Conflict(
        EntitySaveMetadata metadata,
        EntityBaseCore entity,
        string operation
    ) =>
        SaveConflictException.Modified(
            entity.GetType(),
            metadata.KeyProperty.GetValue(entity),
            operation
        );
}

/// <summary>Internal engine that saves an entity graph in a single transaction according to RowState.</summary>
internal static class EntityGraphSaver
{
    /// <summary>Returns whether the entity itself, or (when cascading) any child, has changes.</summary>
    public static bool HasChanges(EntityBaseCore entity, bool cascade) =>
        entity.HasChanges
        || (cascade && EnumerateCascadeChildren(entity).Any(child => HasChanges(child, true)));

    /// <summary>Saves the graph and returns the number of saved records (when <paramref name="hooks"/> is provided, fires the save hooks before and after each operation).</summary>
    /// <remarks>
    /// When <c>changesAlreadyVerified</c> is <c>true</c> (the caller has already checked <see cref="HasChanges"/>, i.e.
    /// changes are known to exist), the redundant graph traversal (change detection) at the start is skipped. Recursion
    /// into children passes the default <c>false</c>, so per-subtree change detection (pruning clean branches) is still
    /// performed.
    /// </remarks>
    public static async Task<int> SaveAsync(
        EntityBaseCore entity,
        SqlConnection connection,
        SqlTransaction transaction,
        bool cascadeSave,
        bool cascadeDelete,
        bool insertWhenUpdateMissing,
        CancellationToken cancellationToken,
        SaveHookSession? hooks = null,
        bool changesAlreadyVerified = false,
        ConcurrencyMode mode = ConcurrencyMode.Optimistic,
        RowVersionCollector? versions = null
    )
    {
        if (!changesAlreadyVerified && !HasChanges(entity, cascadeSave))
        {
            return 0;
        }

        var rows = 0;

        if (entity.IsRemoved)
        {
            // Deletion removes the children (subtree) first, then the entity itself (FK consistency)
            if (cascadeDelete)
            {
                foreach (var child in EnumerateCascadeChildren(entity))
                {
                    rows += await DeleteGraphAsync(
                        child,
                        connection,
                        transaction,
                        cancellationToken,
                        hooks,
                        mode
                    ).ConfigureAwait(false);
                }
            }

            // Before(Delete). On false, only this node's deletion is skipped (the children were deleted above, so this node remains)
            if (
                hooks is not null
                && !await hooks.InvokeBeforeAsync(
                    entity,
                    SaveOperation.Delete,
                    cancellationToken
                ).ConfigureAwait(false)
            )
            {
                hooks.Skip(entity);
                return rows;
            }

            rows += await DeleteEntityAsync(
                entity,
                connection,
                transaction,
                cancellationToken,
                mode
            ).ConfigureAwait(false);

            // After(Delete) fires immediately after the DML (before commit)
            if (hooks is not null)
            {
                await hooks.InvokeAfterAsync(entity, SaveOperation.Delete, cancellationToken).ConfigureAwait(false);
            }

            return rows;
        }

        // Inserts and updates save the entity itself first, then proceed to the children (child FKs reference the parent PK)
        if (entity.IsAdded)
        {
            if (
                hooks is null
                || await hooks.InvokeBeforeAsync(entity, SaveOperation.Insert, cancellationToken).ConfigureAwait(false)
            )
            {
                rows += await InsertEntityAsync(
                    entity,
                    connection,
                    transaction,
                    cancellationToken,
                    versions
                ).ConfigureAwait(false);

                if (hooks is not null)
                {
                    await hooks.InvokeAfterAsync(entity, SaveOperation.Insert, cancellationToken).ConfigureAwait(false);
                }
            }
            else
            {
                // Before returned false = only this one insert is skipped (the child cascade continues)
                hooks.Skip(entity);
            }
        }
        else if (entity.IsUpdated)
        {
            if (
                hooks is null
                || await hooks.InvokeBeforeAsync(entity, SaveOperation.Update, cancellationToken).ConfigureAwait(false)
            )
            {
                var (affected, performed) = await UpdateAsync(
                    entity,
                    connection,
                    transaction,
                    insertWhenUpdateMissing,
                    cancellationToken,
                    mode,
                    versions
                ).ConfigureAwait(false);
                rows += affected;

                // After fires with the operation actually performed (Insert when switched by insertWhenUpdateMissing)
                if (hooks is not null)
                {
                    await hooks.InvokeAfterAsync(entity, performed, cancellationToken).ConfigureAwait(false);
                }
            }
            else
            {
                hooks.Skip(entity);
            }
        }

        if (cascadeSave)
        {
            foreach (var child in EnumerateCascadeChildren(entity))
            {
                rows += await SaveAsync(
                    child,
                    connection,
                    transaction,
                    cascadeSave,
                    cascadeDelete,
                    insertWhenUpdateMissing,
                    cancellationToken,
                    hooks,
                    changesAlreadyVerified: false,
                    mode,
                    versions
                ).ConfigureAwait(false);
            }
        }

        return rows;
    }

    /// <summary>Finalizes saved entities to Unchanged after commit.</summary>
    public static void AcceptChanges(EntityBaseCore entity, bool cascade) =>
        AcceptChanges(entity, cascade, null);

    /// <summary>
    /// Finalizes saved entities to Unchanged after commit. Entities contained in <paramref name="skip"/> (rows skipped
    /// because a save hook's Before returned <c>false</c>) were not operated on, so their state is left untouched.
    /// </summary>
    public static void AcceptChanges(
        EntityBaseCore entity,
        bool cascade,
        IReadOnlySet<EntityBaseCore>? skip
    )
    {
        if (entity.IsRemoved)
        {
            return;
        }

        // Skipped entities had no INSERT / UPDATE performed, so their RowState is left untouched
        if (skip is null || !skip.Contains(entity))
        {
            entity.MarkUnchanged();
        }

        if (cascade)
        {
            foreach (var child in EnumerateCascadeChildren(entity))
            {
                AcceptChanges(child, true, skip);
            }
        }
    }

    /// <summary>Deletes the subtree starting from the children (deleted regardless of state; when <paramref name="hooks"/> is provided, fires Before/After(Delete) per child).</summary>
    private static async Task<int> DeleteGraphAsync(
        EntityBaseCore entity,
        SqlConnection connection,
        SqlTransaction transaction,
        CancellationToken cancellationToken,
        SaveHookSession? hooks = null,
        ConcurrencyMode mode = ConcurrencyMode.Optimistic
    )
    {
        var rows = 0;

        foreach (var child in EnumerateCascadeChildren(entity))
        {
            rows += await DeleteGraphAsync(
                child,
                connection,
                transaction,
                cancellationToken,
                hooks,
                mode
            ).ConfigureAwait(false);
        }

        // Before(Delete) fires from the subtree's children upward. On false, "the children are gone but this node remains" (the consequence of a standalone skip)
        if (
            hooks is not null
            && !await hooks.InvokeBeforeAsync(entity, SaveOperation.Delete, cancellationToken).ConfigureAwait(false)
        )
        {
            hooks.Skip(entity);
            return rows;
        }

        rows += await DeleteEntityAsync(
            entity,
            connection,
            transaction,
            cancellationToken,
            mode
        ).ConfigureAwait(false);

        if (hooks is not null)
        {
            await hooks.InvokeAfterAsync(entity, SaveOperation.Delete, cancellationToken).ConfigureAwait(false);
        }

        return rows;
    }

    /// <summary>Inserts a single row, capturing the row version the database assigned when the table carries one.</summary>
    private static async Task<int> InsertEntityAsync(
        EntityBaseCore entity,
        SqlConnection connection,
        SqlTransaction transaction,
        CancellationToken cancellationToken,
        RowVersionCollector? versions
    )
    {
        var metadata = EntitySaveMetadata.For(entity.GetType());

        if (metadata.RowVersionProperty is not null)
        {
            // The INSERT returns the version the database generated; it is written back to the entity after the commit
            var version = await ExecuteReturningAsync(
                entity,
                meta => meta.InsertReturningSql!,
                static (meta, command, e) => meta.BindInsertParameters(command, e),
                connection,
                transaction,
                cancellationToken
            ).ConfigureAwait(false);

            if (version is byte[] newVersion)
            {
                versions?.Record(entity, newVersion);
            }

            return 1;
        }

        return await ExecuteAsync(
            entity,
            meta => meta.InsertSql,
            static (meta, command, e) => meta.BindInsertParameters(command, e),
            connection,
            transaction,
            cancellationToken
        ).ConfigureAwait(false);
    }

    /// <summary>Deletes a single row, guarded by the row version the entity was read with when the table carries one.</summary>
    private static async Task<int> DeleteEntityAsync(
        EntityBaseCore entity,
        SqlConnection connection,
        SqlTransaction transaction,
        CancellationToken cancellationToken,
        ConcurrencyMode mode
    )
    {
        var metadata = EntitySaveMetadata.For(entity.GetType());

        if (metadata.RowVersionProperty is not null && mode == ConcurrencyMode.Optimistic)
        {
            var affected = await ExecuteAsync(
                entity,
                meta => meta.DeleteVersionedSql!,
                static (meta, command, e) =>
                {
                    meta.BindEntityKeyParameter(command, e);
                    meta.BindRowVersionParameter(command, e);
                },
                connection,
                transaction,
                cancellationToken
            ).ConfigureAwait(false);

            // Zero affected rows is ambiguous: either the row is already gone (deleting a row that is not there has always
            // been tolerated silently) or someone else changed it after it was read. Probing the row tells the two apart
            if (
                affected == 0
                && await RowVersionConcurrency.RowExistsAsync(
                    metadata,
                    entity,
                    connection,
                    transaction,
                    cancellationToken
                ).ConfigureAwait(false)
            )
            {
                throw RowVersionConcurrency.Conflict(metadata, entity, "delete");
            }

            return affected;
        }

        return await ExecuteAsync(
            entity,
            meta => meta.DeleteSql,
            static (meta, command, e) => meta.BindEntityKeyParameter(command, e),
            connection,
            transaction,
            cancellationToken
        ).ConfigureAwait(false);
    }

    /// <summary>Executes the update and returns the affected row count and the operation actually performed (Insert when switched).</summary>
    private static async Task<(int Rows, SaveOperation Performed)> UpdateAsync(
        EntityBaseCore entity,
        SqlConnection connection,
        SqlTransaction transaction,
        bool insertWhenUpdateMissing,
        CancellationToken cancellationToken,
        ConcurrencyMode mode,
        RowVersionCollector? versions
    )
    {
        var metadata = EntitySaveMetadata.For(entity.GetType());
        int affected;

        if (metadata.RowVersionProperty is not null)
        {
            // The guarded UPDATE returns the version the database generated; a null result means it matched no row
            var version = await ExecuteReturningAsync(
                entity,
                meta => RowVersionConcurrency.UpdateSql(meta, mode),
                (meta, command, e) => RowVersionConcurrency.BindUpdate(meta, command, e, mode),
                connection,
                transaction,
                cancellationToken
            ).ConfigureAwait(false);

            if (version is byte[] newVersion)
            {
                versions?.Record(entity, newVersion);
                return (1, SaveOperation.Update);
            }

            // Nothing matched: probing the row separates "the row is gone" (handled below like any missing record) from
            // "someone else changed it after it was read", which must never be silently switched to an INSERT
            if (
                await RowVersionConcurrency.RowExistsAsync(
                    metadata,
                    entity,
                    connection,
                    transaction,
                    cancellationToken
                ).ConfigureAwait(false)
            )
            {
                throw RowVersionConcurrency.Conflict(metadata, entity, "update");
            }

            affected = 0;
        }
        else
        {
            affected = await ExecuteAsync(
                entity,
                meta => meta.UpdateSql,
                static (meta, command, e) => meta.BindUpdateParameters(command, e),
                connection,
                transaction,
                cancellationToken
            ).ConfigureAwait(false);
        }

        if (affected != 0)
        {
            return (affected, SaveOperation.Update);
        }

        // The record to update does not exist (e.g. deleted by another user). Depending on the policy,
        // switch to INSERT or report it as a conflict
        if (insertWhenUpdateMissing)
        {
            var inserted = await InsertEntityAsync(
                entity,
                connection,
                transaction,
                cancellationToken,
                versions
            ).ConfigureAwait(false);
            return (inserted, SaveOperation.Insert);
        }

        throw SaveConflictException.NotFound(
            entity.GetType(),
            metadata.KeyProperty.GetValue(entity)
        );
    }

    /// <summary>Executes a statement whose OUTPUT clause returns a single value, yielding <c>null</c> when it matched no row.</summary>
    private static async Task<object?> ExecuteReturningAsync(
        EntityBaseCore entity,
        Func<EntitySaveMetadata, string> sqlSelector,
        Action<EntitySaveMetadata, SqlCommand, EntityBaseCore> bind,
        SqlConnection connection,
        SqlTransaction transaction,
        CancellationToken cancellationToken
    )
    {
        var metadata = EntitySaveMetadata.For(entity.GetType());

        await using var command = new SqlCommand(sqlSelector(metadata), connection, transaction);
        bind(metadata, command, entity);
        return await command.ExecuteScalarAsync(cancellationToken).ConfigureAwait(false);
    }

    private static async Task<int> ExecuteAsync(
        EntityBaseCore entity,
        Func<EntitySaveMetadata, string> sqlSelector,
        Action<EntitySaveMetadata, SqlCommand, EntityBaseCore> bind,
        SqlConnection connection,
        SqlTransaction transaction,
        CancellationToken cancellationToken
    )
    {
        var metadata = EntitySaveMetadata.For(entity.GetType());

        await using var command = new SqlCommand(sqlSelector(metadata), connection, transaction);
        bind(metadata, command, entity);
        return await command.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);
    }

    /// <summary>Enumerates the cascade-target child entities (nulls are excluded).</summary>
    private static IEnumerable<EntityBaseCore> EnumerateCascadeChildren(EntityBaseCore entity)
    {
        foreach (var navigation in EntitySaveMetadata.For(entity.GetType()).CascadeNavigations)
        {
            var value = navigation.Property.GetValue(entity);

            if (value is null)
            {
                continue;
            }

            if (navigation.IsCollection)
            {
                if (value is IEnumerable<EntityBaseCore> children)
                {
                    foreach (var child in children)
                    {
                        if (child is not null)
                        {
                            yield return child;
                        }
                    }
                }
            }
            else if (value is EntityBaseCore child)
            {
                yield return child;
            }
        }
    }
}

/// <summary>Extensions that register the generated repositories (SQL Server implementation) with the DI container.</summary>
/// <remarks>
/// DI registration is provided per engine under the name <c>AddGeneratedSqlServerRepositories</c>, registering
/// the same contracts (I{Entity}Repository / ISqlExecutor) with dialect-specific implementations. To use multiple dialects
/// (multi-targeting) in the same process, use the overloads with <c>object? serviceKey</c> (keyed DI) and resolve the
/// dialect-specific connection via <c>[FromKeyedServices("...")]</c>.
/// </remarks>
public static class GeneratedSqlServerRepositoryServiceCollectionExtensions
{
    /// <summary>Registers the SQL Server repositories with the DI container using a connection string (non-keyed, for standalone use).</summary>
    /// <remarks>
    /// <see cref="ISqlConnectionFactory"/> and <see cref="ISqlExecutor"/> go in with <c>AddSingleton</c>, so the last
    /// registration wins and this call overrides one you made earlier. To supply your own, register it <b>after</b> this
    /// call, or use the <c>serviceKey</c> overload and keep the two sets apart. (The save hook registry is added with
    /// <c>TryAddScoped</c> instead: an earlier registration of yours is left alone.)
    /// </remarks>
    public static IServiceCollection AddGeneratedSqlServerRepositories(
        this IServiceCollection services,
        string connectionString
    )
    {
        ArgumentNullException.ThrowIfNull(services);
        ArgumentException.ThrowIfNullOrWhiteSpace(connectionString);

        services.AddSingleton<ISqlConnectionFactory>(_ => new SqlConnectionFactory(
            connectionString
        ));
        services.AddSingleton<ISqlExecutor, SqlExecutor>();

        // Register the save hook registry by default (a complete no-op when no ISaveHook<T> is registered)
        services.TryAddScoped<ISaveHookRegistry>(provider => new ServiceProviderSaveHookRegistry(
            provider
        ));
        services.AddScoped<ISyncvoOrderRepository, SyncvoOrderRepository>();
        services.AddScoped<ISyncvoLineRepository, SyncvoLineRepository>();

        return services;
    }

    /// <summary>Registers the SQL Server repositories with a service key (keyed DI, for using multiple dialects simultaneously).</summary>
    /// <remarks>
    /// Registers I{Entity}Repository / ISqlExecutor keyed by <paramref name="serviceKey"/>. Consumers resolve the
    /// dialect-specific implementation like <c>[FromKeyedServices(serviceKey)] ICustomerRepository</c>.
    /// The connection factory is captured per key in a closure, so it causes no non-keyed registration collisions.
    /// </remarks>
    public static IServiceCollection AddGeneratedSqlServerRepositories(
        this IServiceCollection services,
        object? serviceKey,
        string connectionString
    )
    {
        ArgumentNullException.ThrowIfNull(services);
        ArgumentException.ThrowIfNullOrWhiteSpace(connectionString);

        var connectionFactory = new SqlConnectionFactory(connectionString);
        services.AddKeyedSingleton<ISqlConnectionFactory>(serviceKey, (_, _) => connectionFactory);
        services.AddKeyedSingleton<ISqlExecutor>(
            serviceKey,
            (_, _) => new SqlExecutor(connectionFactory)
        );

        // Register the save hook registry by default (non-keyed; a complete no-op when no ISaveHook<T> is registered)
        services.TryAddScoped<ISaveHookRegistry>(provider => new ServiceProviderSaveHookRegistry(
            provider
        ));

        // Every entity is wired the same way, so the local function holds what they share - the captured connection
        // factory, the key, and the keyed SQL executor - and each entity contributes only its contract and constructor
        void AddRepository<TContract>(
            Func<ISqlConnectionFactory, ISaveHookRegistry?, ISqlExecutor?, TContract> create
        )
            where TContract : class
        {
            services.AddKeyedScoped(
                serviceKey,
                (provider, key) => create(
                    connectionFactory,
                    provider.GetService<ISaveHookRegistry>(),
                    provider.GetKeyedService<ISqlExecutor>(key)
                )
            );
        }

        AddRepository<ISyncvoOrderRepository>(
            (factory, hooks, executor) => new SyncvoOrderRepository(factory, hooks, executor)
        );
        AddRepository<ISyncvoLineRepository>(
            (factory, hooks, executor) => new SyncvoLineRepository(factory, hooks, executor)
        );

        return services;
    }
}

/// <summary>Base of every generated SQL Server repository implementation, and the extension point for them. Members added to a partial declaration of this class are available to every entity repository built on this engine.</summary>
/// <typeparam name="TEntity">The entity type.</typeparam>
/// <typeparam name="TKey">The primary key type.</typeparam>
public abstract partial class SqlServerRepository<TEntity, TKey>(
    ISqlConnectionFactory connectionFactory,
    ISaveHookRegistry? saveHooks = null,
    ISqlExecutor? sqlExecutor = null
) : SqlServerRepositoryCore<TEntity, TKey>(connectionFactory, saveHooks, sqlExecutor)
    where TEntity : EntityBaseCore, new() { }

